/* כל השונה הלכות - תשפ"ז. נתוני ההלכות (385 ימים), מילה במילה לפי הקובץ שסופק. */
window.HALACHOT={start:[2026,9,12],days:[{"h":"א' תשרי א' ראש השנה יום שבת","s":"הלכות יום הכיפורים","d":["לרפואה שלמה אביטל לוריא פנינה בת יפה | בריאות ואריכות ימים אורה בת מיניס | לרפואה עידן נגר ומשפחתו | להצלחת מדינת היהודים מדינת ישראל וכוחות הבטחון ולומדי התורה"],"b":[["t","מהי הרחיצה האסורה ביום כיפור?"],["b","רחיצה אסורה בין בחמין בין בצונן. ואפילו להושיט אצבעו לתוך מים אסור. ודווקא רחיצה של תענוג, אבל שלא לתענוג, מותר. וצריך ליזהר שלא ירחץ יותר ממה שמוכרח לו. ואף לתפילה, מנחה נעילה וערבית לא ירחץ אצבעותיו (כשלא יודע בהם איזה שהוא טינוף)."],["s","(משנ\"ב ס\"ק ה' ו'. שע\"ה סי' קי\"ג ס\"ג)"],["t","אלו ברכות שאין מברכין בברכות השחר"],["b","בברכות השחר, צריך לדלג ברכת \"שעשה לי כל צרכי\", לפי שאסורים בנעילת הסנדל. וכן צריך לדלג ברכת \"המעביר שינה מעיני\" לפי שאין רוחצין העיניים במים להדיא. אבל ברכת על נטילת ידים מברכין, כיון שנוטלין עד פרקי האצבעות. ובשאמי נוהגים לברך גם \"שעשה לי כל צרכי\", ואף \"המעביר\" (וכ\"כ הגר\"י צוברי בס' פסקי הלכות עמ' ל\"ב)."],["s","(סימן ק\"ה ס\"ו, מועדי ה' בין המצרים סי' ד' ס\"ט. עיני יצחק אות ח\"י)"]]},{"h":"ב' תשרי ב' ראש השנה יום ראשון","s":"הלכות תפילות יום הכפורים וצום גדליה","d":["זיווג הגון למיכל בת רפאל"],"b":[["t","כיצד מקיימים ביום הכיפורים את חיוב \"מאה ברכות בכל יום\"?"],["b","אם יכוון לכל ברכות השליח צבור והקוראים בתורה והמפטירים, לא יחסרו לו, אלא רק שלוש ברכות לתשלום מאה. ולכן טוב להריח בבשמים ולברך עליהם, כדי להשלים מאה ברכות, וכן נוהגים. אמנם כל זמן שלא הסיח דעתו, אסור לברך שנית דהוי ברכה לבטלה. על כן צריך להפסיק בינתיים זמן גדול שיהא היסח הדעת: (שע\"ה סי' קי\"ד ס\"י)"],["t","ענייני צום גדליה"],["b","מצות עשה מדברי הנביאים בימים שאירעו צרות לאבותינו. ומתוכם, יום שלישי בתשרי, בו נהרג גדליה בן אחיקם. שלאחר שחרב בית המקדש, השאירו נבוכדנאצר הרשע, מלך בבל בארץ ישראל, וישמהו לראש על יתר ישראל. וע\"י שנהרג, גלו כולם ונהרגו מהם לאלפים, וכבתה גחלת ישראל הנשארת. ואומר עננו בג' תפילות; ערבית ליל התענית, שחרית, ומנחה. (שו\"ע תקס\"ד. שת\"ז, עריכת שולחן, שע\"ה קב' ב' י')"]]},{"h":"ג' תשרי יום שני. צום גדליה","s":"הלכות ערב יום הכיפורים","d":["לעילוי נשמת סעדה בת סעיד אשוואל ענאקי | לעילוי נשמת משה בן דוד"],"b":[["t","האם צריך להדליק נרות ולברך עליהם?"],["b","בהבדלה של מוצאי יום הכיפורים, צריכין לברך דוקא על נר \"שבת\" דהיינו שדלק כל משך יום הכיפורים, ולא על נר שמדליק במוצאי כיפור ע\"י גפרור, וכדו'. ולכן צריך שיכין נר אחד שיידלק מערב יום הכיפורים, עד שעת ההבדלה כדי שיברך עליו \"בורא מאורי האש\". (שע\"ה קי\"ד סעיף י\"ז)"],["t","איזה בגדים לובשים לכבוד יום הכיפורים?"],["b","נוהגין ללבוש הבגדים היקרים, ויש לובשים לבן דוגמת מלאכי השרת. ויש לובשים בגדי פשתן לבנים תכריכי יום האחרון, שעל ידי זה לב האדם נכנע ונשבר. גם הנשים לובשות בגדיהן היקרים לכבוד היום, וגם מתקשטות. (שע\"ה קי\"ב סט\"ז. עיני יצחק מ'. מועדי ה' סי' ד' סכ\"ד)"]]},{"h":"ד' תשרי יום שלישי","s":"הלכות יום הכיפורים","d":["ברכה והצלחה ליעקב בן ענת שרעבי"],"b":[["t","איזה סוג נעליים אסור לנעול ביום הכיפורים?"],["b","אסור לנעול סנדל או מנעל, מעור. ואפילו אם הסנדל של עץ, אלא שהוא מחופה בעור. אבל אם אינו מחופה בעור, אלא עשוי מבגד או מ\"גומי\", או קש, או לבדים, מותר. (שע\"ה סי' קי\"ג ס\"ו)"],["t","האם חולה או יולדת מותר בנעילת הסנדל?"],["b","כל חולה אף על פי שאין בו סכנה, או מי שיש לו מכה ברגלו, וכן היולדת כל שלושים יום, מותרין בנעילת הסנדל, לפי שהצינה קשה להם. (שם ס\"ט)"]]},{"h":"ה' תשרי יום רביעי","s":"הלכות יום הכיפורים","d":["לעילוי נשמת זהרה בת יחיא וסעדה עוזרי | ברכה והצלחה אילנה בת שלמה"],"b":[["t","האם יש דין חינוך לקטנים, להתענות ביום הכיפורים?"],["b","קטן וקטנה פחותים מגיל תשע שנים, אין מניחים אותם להתענות מחשש סכנה. קטן בן תשע שנים ובן עשר שנים, מחנכין אותו לשעות. כיצד; היה רגיל לאכול בשתי שעות ביום, מאכילין אותו בשלוש. היה רגיל בשלוש, מאכילין אותו בארבע. לפי כח הבן. בן אחת עשרה שנה, בין זכר בין נקבה, צריכים להתענות כל היום מדברי סופרים, כדי לחנכן במצוות. אלא אם כן הם חלשים, סומכים על דעת המקילים בזה: (שע\"ה סי' קי\"ג סי\"ט. ערי\"ש תרט\"ז ב' ד' ו'. רמב\"ם הלכות שביתת עשור פ\"ב ה\"י)"],["t","דיני החולים המותרים לאכול ביוה\"כ"],["b","יולדת או מפלת, וכן חולה שיש בו סכנה, לענין אכילה ושתייה. אם יכול לאכול בשיעורים דהיינו כשלושים גרם, וישהה קצת ושוב יאכל, יעשה כך. והשהייה בין אכילה לאכילה לכתחילה תשע דקות ואם זה קשה, יצמצם פחות פחות עד שתי דקות. ואם אומר שיסתכן אם לא יאכל די מחסורו, יאכל כרגיל עד שיבין שדי לו: קידוש, לא יעשה. ובברכת המזון יאמר יעלה ויבוא. (שע\"ה סי' קי\"ג סי\"ג. ערי\"ש תרי\"ז ז' ט'. תרי\"ח א' ב' ז' ח' ט')"]]},{"h":"ו' תשרי יום חמישי","s":"הלכות יום הכיפורים","d":["לעילוי נשמת שלום בן משה ותמר הלל ז\"ל | זיווג הגון לשני בת מאיר | להצלחת אביאל והודיה חדד וילדיהן","מארי יחיא גריידי זצוק\"ל תר\"ץ - אב\"ד דמאר"],"b":[["t","דיני הווידוי בתפילות יום הכיפורים"],["b","ערבית שחרית מוסף מנחה ונעילה, מתוודה היחיד בסיום תפילתו, והש\"צ גם באמצע החזרה. וצריכים לעמוד אז. ואין להישען אז על דבר שאם ינטל אותו דבר, יפול. ויש נוהגים לחזור ולהתוודות בפיהם עם הש\"צ ואין מסתפקים בשמיעה ממנו. מי שיודע בעצמו חטא, שלא נזכר בתוך סדר הוידוי, כיון שהוא אומר את הוידוי בלחש, נכון שיפרט את החטא ההוא, ויתוודה עליו במרירות הלב ובדמעות שליש: נכון שכל אשה תאמר הוידוי בעצמה ביום הכיפורים לכל הפחות פעם אחת."],["s","(שע\"ה סי' קי\"ד ס\"ו עיני יצחק י\"ב)"],["t","זמן תפילת נעילה"],["b","זמן תפילת נעילה כשהחמה בראש כל האילנות, (דהיינו חצי שעה קודם הזמן שהשמש נעלמת מעינינו), כדי שישלים אותה עם צאת הכוכבים. ולפעמים נמשכת קצת בתוך הלילה, ואפילו הכי אומרים \"חתמנו\". לפי שאין הדין מסתלק עד שיגמרו ישראל את סדריהם למטה."],["s","(שם. ומועדי ה' סי' ו' סכ\"ב)"]]},{"h":"ז' תשרי יום שישי","s":"הלכות יום הכיפורים","d":["לעילוי נשמת אבידן בן סעדיה מעטוף ז\"ל | לעילוי נשמת אהרון בן הרון"],"b":[["t","האם מברכים על הבשמים בהבדלה של יום הכיפורים?"],["b","בהבדלה על הכוס במוצאי יום הכיפורים אין מברכין על הבשמים, ואפילו כשחל יוהכ\"פ בשבת. ואומרים \"אל י\"י ויאר לנו\", כמו בשאר מוצאי שבת:"],["s","(שע\"ה סי' קי\"ד סעיף י\"ז חזו\"ע ס\"ו)"],["t","מעלת הימים שבין כיפור לסוכות?"],["b","בימים שבין יום הכפורים לסוכות, אין להתענות אפילו ביום שמת בו אביו ואמו, ולא ווידוי ונפילת אפים. לפי שהם ימי שמחה שהיו מחנכים בהם את המזבח בימי שלמה. (שע\"ה שם ס\"כ. וסי' כ\"א סי\"א. חזו\"ע ס\"י וס\"ק י'):"]]},{"h":"ח' תשרי יום שבת פרשת האזינו שבת שובה","s":"הלכות כשרות ארבעת המינים","d":["לעילוי נשמת סביחה בת לולו | שילת בת כפיר ברכה והצלחה | רפואה שלימה לאורלי בת מאיר"],"b":[["t","כשרות הלולב"],["b","עלי הלולב גדלים שניים שניים דבוקים מגבם וגב כל שני עלים נקרא \"תיומת\". אפילו נחלקה כל התיומת, אם לא נתרחקו הסדקים כל כך עד שנראית כשניים כשר. מיהו נוהגים להחמיר שלא ליטול אפילו נחלקה מקצת תיומת העליון: לכתחילה עדיף ליקח לולב שעליו אינם כפופים בראשן:"],["s","(שע\"ה קי\"ז א', ב'. ערי\"ש תרמ\"ה ו' ז')"],["t","מה הדין לולב עקום?"],["b","אם הלולב עקום שנעשתה השדרה כגב בעל חטוטרת (בלשוננו, גבן), אם לאחריו כשר, מפני שזוהי ברייתו. אבל אם נתעקם הלולב לפניו או לאחד מצדדיו, פסול. ואם הלולב בעיקום מעט כשר. מיהו למצווה מן המובחר יש להחמיר: (שע\"ה קי\"ז א', ב'. ערי\"ש תרמ\"ה ו' ז')"]]},{"h":"ט' תשרי יום ראשון ערב יום הכיפורים","s":"הלכות כשרות ארבעת המינים","d":["כמוהר\"ר יהודה חבשוש זצוק\"ל - תש\"ד"],"b":[["t","מהו הדס משולש?"],["b","ההדס צריך להיות משולש דהיינו שיוצאין בו מכל קן וקן שלושה עלים בשורה אחת בשווה, שלא יהא אחד גבוה או נמוך מחביריו. ולכתחילה צריך להיות משולש מלמטה עד למעלה, אך אין זה מעכב, אלא אף אם למטה המועט אינו משולש והרוב שלמעלה משולש, גם כן כשר. והוא הדין להיפך כשהרוב למטה משולש. (שע\"ה סי' קי\"ז ס\"ג)"],["t","האם השילוש בעלי ההדס צריך להיות מדוייק?"],["b","כל שיש קו הנפגש בשלושת שרשי העלים, נחשב משולש. רוצה לומר אפילו שבשורש אחד הוא נפגש מלמעלה, ואחד מלמטה: וצריך לדקדק שלא ינשרו העלין מן ההדס. (דאם נשר עלה אחד מכל שלשה ברוב שיעור ההדס, נחלקו הראשונים אם פסול או כשר):"],["s","(שם. ובחזו\"ע הלכות הדס ס\"ה)"]]},{"h":"י' תשרי יום שני יום הכיפורים","s":"הלכות כשרות ארבעת המינים","d":["לעילוי נשמת אריה בן חיים ענאקי | לעילוי נשמת יחיאל כהן בן יוסף"],"b":[["t","מה הדין אם נקטם ראש ההדס?"],["b","יש להחמיר לכתחילה שלא יהיו ראשי ההדסים קטומים דהיינו ראשי העצים. אבל בקטימת העלים (דהיינו עלים חתוכים) אין קפידא."],["s","(שע\"ה סי' קי\"ז ס\"ד ערי\"ש תרמ\"ו א' ועיין שם תרמ\"ז ב')"],["t","מה הדין ערבה שנקטם ראשה, או נשרו העלים שלה?"],["b","ערבה שיבשה או שנשרו רוב העלין שלה, או שנקטם ראש העץ שלה, פסולה. ורבינו הרמב\"ם מכשיר בנקטם ראשה. (שם ס\"ו)"]]},{"h":"יא תשרי יום שלישי","s":"הלכות כשרות האתרוג ועשיית סכך הסוכה","d":["לעילוי נשמת סעיד בן מוסא הלל ז\"ל | ברכה והצלחה ופרנסה בשפע לאלחנן בן יוסף | ברכה והצלחה לר' שבאל בן שולמית"],"b":[["t","כשרות האתרוג"],["b","אתרוג שניקב וחסר אפילו כל שהוא, פסול ואפילו כשאין הנקב ניכר אלא על ידי התבוננות. וחסרון שנעשה ע\"י הקוצים או שעלה עליו קרום כשר. נקודות שחורות וכיוצא, רובן לכלוך וכנימות שיכולים לירד, מיהו כל זמן שלא ירדו מסתברא דפסול. פיסולי חסר ושינוי מראה, אתרוג כחזזית וכיוצא בזה, היינו דווקא ביום טוב ראשון, אבל מיום שני ואילך כשרים ומברכים עליהם."],["s","(קי\"ז ז', י\"ב, והערה שם. ערי\"ש תרמ\"ח ב' ט' תרמ\"ט ט\"ו)"],["t","מהי כמות הסכך שמותר ליתן על הסוכה?"],["b","צריך להניח סכך עד שתהא צילתה מרובה מחמתה. ולכתחילה צריך שיהא אויר קצת בין הסכך, כדי שייראו הכוכבים. ומכל מקום אם הייתה מעובה שאין הכוכבים נראים, כשרה. (שע\"ה סי' קט\"ו ס\"ה)"]]},{"h":"יב תשרי יום רביעי","s":"הלכות כשרות ארבעת המינים","d":["רפואה שלימה וחז\"ב לאיתמר בן מאיר"],"b":[["t","כשאין הסיכוך מלא, ויש מקומות שיש בהם חלל אויר ריק, האם מותר לשבת תחתיו?"],["b","צריכין ליזהר שלא יהא במקום אחד אוויר ג' טפחים. ואם האויר לאורך כל הסוכה, או שיש בו כדי ראשו או רובו אפילו בפחות מג' טפחים, אין יושבין תחתיו. אבל אם אינו הולך באורך כל הסוכה, מותר לאכול ולישן תחתיו. (שם ס\"ה וחזו\"ע דיני הסכך סל\"ג)"]]},{"h":"יג תשרי יום חמישי","s":"הלכות עשיית הסכך","d":["רפואה שלימה לאבישי בן מיכל כמוהרר\"י עמרם קורח זצוק\"ל תשי\"ג - אב\"ד צנעא"],"b":[["t","האם מותר להעמיד את הסכך בדבר הראוי לקבל טומאה?"],["b","אין מסככים בכלים, כיון שראויים הם לקבל טומאה. ורק בעץ פשוט שאינו כלי מסככים. אבל אם אינו מסכך בכלים, אלא נותן אותם מעל הסכך להחזיקו, מעיקר הדין מותר. וראוי להחמיר. (חזו\"ע דיני הסכך ס\"ב. שע\"ה סי' קט\"ו ס\"ד)"],["t","האם מותר לתת הסכך קודם שעשה את הדפנות?"],["b","אסור להניח את הסכך קודם שיעשה את הדפנות. אלא אם כן עשה רוחב טפח לכל הפחות באורך כל הסוכה סמוך לסכך, ונתן עליו הסכך ואחר כך גמר המחיצות. (שע\"י הדפנות ברוחב טפח שם סכך עליו)."],["s","(שם ס\"י. טור סוף סימן תרל\"ה)"]]},{"h":"יד' תשרי יום שישי ערב חג סוכות","s":"הלכות סכך וישיבה בסוכה","d":[],"b":[["t","מה היא מצוות סוכה?"],["b","כתוב \"בסוכות תשבו שבעת ימים\". אמרה תורה; שידור אדם בסוכה שבעת ימים, כמו שהוא דר בביתו כל השנה. ותהא עיקר דירתו בסוכה, שיכניס לתוכה כליו הנאים ומצעותיו הנאות, ואוכל, ושותה, ולומד, וישן בסוכה. (שע\"ה סי' קט\"ז ס\"א):"],["t","סדר הקידוש בחג הסוכות"],["b","בליל יו\"ט ראשון כשבאים מבית הכנסת אחרי תפילת ערבית, נכנסים לסוכה, ואין יושבים אלא מביאים כוס יין, והגדול מקדש בעמידה, וכן כל השומעים עומדים. ובסוף מברך לישב בסוכה, ויושבים כולם, ואח\"כ מברך שהחיינו. ויכוון שהוא מברך שהחיינו על החג וגם על הסוכה, ושותים."],["b","וגם בשחרית מקדשין מעומד, ומסיים בברכת לישב בסוכה ויושבין ושותין. וכל זה גם כשחל בשבת, וכן בשבת חוה\"מ:"],["s","(שע\"ה סי' קט\"ז סי\"ג. ערי\"ש תרמ\"ג א')"]]},{"h":"טו תשרי יום שבת חג סוכות","s":"הלכות נטילת ארבעת המינים","d":["לזש\"ק איילה בת שאלתיאל | לזש\"ק יוסף חי בן יעקב"],"b":[["t","כיצד אחיזת ארבעת המינים"],["b","כשמסיים שליח ציבור חזרת תפילת שחרית נוטל הוא וכן כל אחד מהקהל את ארבעת המינים. ויהיה הלולב בימינו והאתרוג בשמאלו. ומנהג הבלדי שפני הלולב דהיינו צד העליון ששם הקליפה האדומה, יהיו לשמאלו כלפי האתרוג, והשדרה מצד ימינו. ומנהג השאמי שהשדרה כלפי פניו של אדם. ואז מברך הש\"צ על נטילת לולב. וביום הראשון מברך אח\"כ שהחיינו. והשנה שחל יום ראשון של סוכות בשבת, שאין נוטלין בו לולב, אזי מברך שהחיינו ביום שני של סוכות:"],["s","(שע\"ה סי' קי\"ח א'. ערי\"ש תרנ\"א ה' ו' ט\"ו)"],["t","מהו סדר הנענועים?"],["b","סדר הנענועים, מוליך ומביא מעלה ומוריד. דהיינו בתחלה לצד פניו ואח\"כ לאחוריו, ואח\"כ למעלה, ואח\"כ למטה, ואח\"כ משלימים שתי הרוחות הנוספות, דהיינו לצד ימינו ואח\"כ שמאלו. זהו מנהג הבלדי. ומנהג השאמי להקיף בסיבוב, דהיינו בתחלה לצד שמתפללין אליו וממשיכים דרך ימין, דהיינו מזרח דרום מערב צפון, ולבסוף למעלה ולמטה: (שע\"ה קי\"ח ד'. ערי\"ש תרנ\"א י\"ד)"]]},{"h":"טז תשרי יום ראשון ב' דסוכות","s":"הלכות נטילת ארבעת המינים","d":["לעילוי נשמת רפאל בן שלום"],"b":[["t","מנהג חלק מהשאמי שלא לברך על הסוכה אלא באכילת קבע"],["b","יש מהשאמי נוהגים כמו שכתוב בשולחן ערוך שלא לברך לישב בסוכה אלא באכילת קבע. ונוהגים הם לברך תחילה המוציא ואחר כך לישב בסוכה קודם שטועם. וכל מה שהוא יושב ועושה בסוכה ואפילו ישן שם, נפטר הכל בברכה שבירך בשעת אכילת קבע עד שיאכל שנית בקבע. ואם לא יצא מן הסוכה לעסקיו או לבית הכנסת בין סעודה לסעודה, אלא יצא יציאת עראי ודעתו היה לחזור מיד, לא הוי היסח הדעת, ואינו צריך לברך בסעודת קבע השניה: (קט\"ז י')"],["b","מנהג הבלדי והרבה מן השאמי לברך בכל פעם שמקיימים מצוות ישיבה בסוכה מנהג הבלדי וכן הרבה מהשאמי שאין הברכה תלויה בסעודה כלל, אלא מברכים בכל פעם שנכנסים ומקיימים ישיבה בסוכה, כדעת הגאונים והרמב\"ם. ואפילו נכנס לסוכת חבירו לבקרו, מברך אף על פי שאינו סועד ולא טועם כלום שם. ודווקא כשיצא מן הסוכה יציאה גמורה לעשות ענייניו, אבל יצא יציאת עראי ודעתו לחזור לא הוי היסח הדעת ואינו חוזר ומברך: (קט\"ז י\"א. ערי\"ש תרמ\"ט ב')"]]},{"h":"יז תשרי יום שני ג' דסוכות","s":"הלכות נטילת ארבעת המינים","d":["לעילוי נשמת רפאל חיים ז\"ל בן ארז ידעי הי\"ו | ברכה והצלחה מיכל בת מלכה | רפואה שלימה לסלמה בת סעיד"],"b":[["t","איזה אכילה מחייבת בסוכה?"],["b","אכילה בסוכה בלילה הראשונה היא חובה, שצריך לאכול בסוכה פת לכל הפחות כזית בכדי אכילת פרס. ובשאר הלילות והימים, דווקא אם רצונו לאכול אכילת קבע דהיינו פת, ואפילו היא פת כסנין, וכן תבשיל העשוי מחמת מיני דגן, אם אוכל יותר משיעור כביצה, חייב לאכול בסוכה. אבל אכילת עראי, דהיינו פת פחות מכביצה, וכן אם אכל פירות אפילו הרבה וקבע עליהם, וכן יין ושאר משקין, או בשר וגבינה, מותר לאכול ולשתות חוץ לסוכה, דאף בביתו מצוי שאוכל עראי חוץ לביתו: (שע\"ה קט\"ז ס\"ה. ערי\"ש תרמ\"ט ב')"],["t","מהי אכילת קבע כדי לברך לישב בסוכה?"],["b","לנוהגים שלא לברך אלא בשעת סעודה, אכילת קבע היינו פת יותר מכביצה אפילו לא קבע עליה, ואפילו היא פת כסנין. וכן תבשיל העשוי מחמשת מיני דגן יותר מכביצה וקבע עליו סעודה, חייב בסוכה ולברך לישב בסוכה. (ויש אומרים שעל פת כסנין ותבשיל מחמת מיני דגן אין מברכין על הסוכה אלא א\"כ אוכל מהן שיעור קביעת סעודה):"],["s","(קט\"ז ה')"]]},{"h":"יח תשרי יום שלישי ד' דסוכות","s":"הלכות איסור מלאכה בחול המועד","d":["רפואה שלימה לאיילה חן בת אודליה","כמוהר\"ר רפאל אלשיך זצוק\"ל - תש\"ח"],"b":[["t","האם מותר לתקן בחול המועד כסא או שולחן שנשברו?"],["b","ימי חול המועד נקראו בתורה בשם מקראי קודש. והם ימי חג ושמחה. ואסור לעשות בהם כל מלאכת אומן אף אם הם לצורך המועד. ואין מתקנים כסא או שולחן או ארון בגדים מעשה אומן. (לבוש ס\"א. מועדי ה' סי' תק\"מ ס\"ח)"],["b","האם מותר לתקן דברים שדרך להשתמש בהם במועד, אך אינם צורך אוכל נפש."],["b","אסור לתקן מנעליו או מלבושיו ע\"י אומן. ומי שצריך לו בגד במועד, אם היה הדיוט, ואינו מהיר באותה מלאכה, הרי זה עושה אותה כדרכו. ואם היה אומן מהיר, הרי זה עושה אותה מעשה הדיוט. [וישאל מורה הוראה]."],["s","(שו\"ע סי' תקמ\"א סעיפים ד' ה'. מועדי ה' שם סעיפים ג' ה')"]]},{"h":"יט תשרי יום רביעי ה' דסוכות","s":"הלכות איסור מלאכה בחול המועד","d":["לעילוי נשמת עובדיה בן יחיא מעטוף ז\"ל | רפואה שלימה לאליהו בן שלמה"],"b":[["t","האם מותרת מלאכת הדיוט שלא לצורך המועד?"],["b","כל מלאכה שאסורה ביו\"ט, אסור לעשותה בחול המועד. אפילו אם היא מלאכה פשוטה שלא צריכה אומנות. אבל אם הוא לצורך המועד, מותר. לפיכך מותר לנסוע באוטו לצורך המועד. ואפילו לשם טיול מותר. (ב\"י סי' תקל\"ו. מועדי ה' תקל\"ו ס\"א)"],["t","האם מותר לעשות סחורה בחול המועד?"],["b","כל סחורה אסורה בחול המועד אפילו כל שהוא, בין לקנות בין למכור, כדי שלא יהיו כשאר ימי החול שאין בהם קדושה כלל. אבל דברים הנצרכים למועד, כגון; תבלין או ירקות או חלב וכל דבר שאינו מתקיים, פותחים חנויותיהם ומוכרין כדרכן אפילו בפרהסיא, מפני שהכל יודעים שהן לצורך המועד. (שו\"ע תקל\"ט ס\"י שע\"ה סי' ק' ס\"א וס\"ה)"]]},{"h":"כ' תשרי יום חמישי ו' דסוכות","s":"הלכות יום שביעי של סוכות","d":["לעילוי נשמת יחיא זכריה בן שלום | מזל בת זוהרה רפואת הנפש והגוף"],"b":[["t","מדוע נתייחד ליל הושענא רבה משאר לילות החג?"],["b","בליל שביעי של סוכות שהוא הושענא רבה נוהגין להיות נעורים כל הלילה לעסוק בתורה. והטעם ללימוד, לפי שבחג נידונין על המים שכל חיי האדם תלויים במים, והיום הוא יום אחרון של-חג והכל הולך אחר החיתום. ועל פי הקבלה הטעם הוא לפי שהוא זמן גמר החיתום של ראש השנה ויום כיפור, שבליל הושענא רבה נחתמים פעם שנית חותם חיצון: (שע\"ה קי\"ט א'. ערי\"ש תרס\"ד ב')"],["t","דין לקיחת ערבה מיוחדת בהושענא רבה ודין החבטה"],["b","ביום הושענא רבה מנהג נביאים שכל אחד יטול ערבה מיוחדת לחבוט אותה, מלבד הערבה שבלולב (והמנהג לקחת חמש יחידות, ויש נוהגים ג' יחידות של ערבה). ואוגדין את הערבות בפני עצמן. בשעת ההלל יש לאחוז רק את הלולב והאתרוג, ולא את הערבה שמיועדת לחבטה, אבל בהקפות נוהגין לאחוז את כולן. ובסיום התפילה אחרי עלינו לשבח חובטין את הערבות בקרקע, ג' או חמש פעמים. (קי\"ט ג' ה' ו'. ערי\"ש תרס\"ד י\"א)"]]},{"h":"כא תשרי יום שישי ז' דסוכות הושענא רבה","s":"הלכות יום שביעי של סוכות ושמיני עצרת","d":["רפואה שלימה להדס בת משה לעילוי נשמת כמוהר\"ר יחיא בן יחיא אב\"ד מהאצר"],"b":[["t","ממתי יוכל לפנות הסוכה ביום השביעי לכבוד יו\"ט?"],["b","אע\"פ שגמר מלאכול ביום השביעי שחרית, לא יסתור הסוכה. אבל מזמן מנחה ולמעלה, מוציא את הכלים ממנה, ומכין את הבית לכבוד יום טוב: (שו\"ע תרס\"ו ס\"א. שע\"ה קי\"ט ס\"ח. ובערי\"ש תרס\"ו א' הוסיף משם השו\"ע והשת\"ז דאף בבין השמשות לא יפרק)"],["t","סדר התפילה ביום שמיני עצרת"],["b","יום שמיני עצרת רגל בפני עצמו הוא, ואין לו שייכות לחג הסוכות. ובקידוש של ליל החג צריך לברך שהחיינו. והתפילה כמו ביו\"ט ראשון זולת שאומרים \"את יום חג שמיני עצרת [ובשאמי, שמיני חג עצרת], הזה זמן שמחתנו באהבה\". ומי שטעה ואמר את יום חג הסוכות הזה, אפשר שיצא ידי חובתו ואינו צריך לחזור, ובפרט כשכבר סיים ברכת שים שלום: (שע\"ה סי' קי\"ט ס\"ט, ועיני יצחק שם)"]]},{"h":"כב תשרי יום שבת שמיני עצרת שמחת תורה","s":"הלכות יום שמיני עצרת","d":["לעילוי נשמת הנופלים והנרצחים הקדושים הי\"ד \"בחרבות ברזל\" כ\"ב בתשרי תשפ\"ד | לעילוי נשמת בנימין בן מאיר עזאני ז״ל | ברכה והצלחה לרענן בן ישעיה ידעי"],"b":[["t","חובת קיום שלוש סעודות בשבת שמחת תורה"],["b","יום שמחת תורה שחל להיות בשבת, צריך להקפיד לעשות סעודת שחרית קודם חצות היום שאז הוא זמנה. כי מצוות היום בשלוש סעודות, משא\"כ כשחל בחול דליכא קפידא בזה, מאחר שאין נוהגין אז לאכול סעודה שלישית. לפיכך כשחל בשבת ישכימו להתפלל, כדי שיוכלו לומר כל הפיוטים והתפילות, ויספיקו לקדש ולסעוד קודם חצות היום: (שע\"ה סי' קי\"ט י\"ז)"],["t","ממתי מתחילין לומר משיב הרוח ומוריד הגשם"],["b","מתפילת לחש של מוסף שמיני עצרת, מתחילין לומר משיב הרוח ומוריד הגשם. ואסור להזכיר הגשם עד שיכריז השליח ציבור משיב הרוח ומוריד הגשם. (ובדורות האחרונים המנהג לומר אז פיוטים שנכללת בהם הכרזה זו, ונקראים בשם תיקון הגשם)."],["b","אם טעה ולא אמר משיב הרוח ומוריד הגשם, אלא אמר מוריד הטל, אם נזכר קודם שסיים ברכת מחיה המתים אומרו במקום שנזכר. אבל אם לא נזכר עד לאחר"],["b","שאמר ברוך אתה ה', גומר ברכת מחיה המתים, ואינו צריך לחזור בשביל הזכרת הגשם, כיון שהזכיר טל."],["s","(סימן י\"ז א', ב', ג')"]]},{"h":"כג תשרי יום ראשון. אסרו חג","s":"הלכות אסרו חג, וניקיון המקום לדבר שבקדושה","d":["לעילוי נשמת חיים בן יחיא ענאקי | רפואה שלימה לאסתר בת משה","כמוהר\"ר דוד מזעקי זצוק\"ל - תקפ\"ה"],"b":[["t","מעלת יום אסרו חג"],["b","יש נוהגין להרבות קצת באכילה ושתייה ביום שלאחר החג בכל שלוש רגלים, והוא נקרא \"אסרו חג\". וטוב שלא להתענות בו, אפילו חתן וכלה ביום חופתם, ולא יארצייט. (שע\"ה סי' צ\"ח סי\"ח)"],["t","חובת נקיון המקום לקדושה"],["b","כתוב (דברים כ\"ג י\"ד-ט\"ו) \"וכסית את צאתך כי י\"י אלהיך מתהלך בקרב מחניך וגו' והיה מחניך קדוש\". מכאן למדו רבותינו ז\"ל, שבכל מקום אשר ה' אלהינו מתהלך עמנו, דהיינו כשאנו עוסקים בדבר שבקדושה, כגון קרית-שמע, תפילה, לימוד תורה וכדומה, צריך להיות המחנה קדוש, שהמקום יהיה נקי מכל דבר טינוף. (שע\"ה סי' ה' ס\"א)"]]},{"h":"כד תשרי יום שני","s":"הלכות נקיון המקום לדבר שבקדושה","d":["לעילוי נשמת החייל יותם בן אלדד הלל ז\"ל | רפואה שלימה לשושנה בת משה"],"b":[["t","מה הדין לדבר ולהרהר בדברי תורה במקומות שיש בהם טינוף?"],["b","בית המרחץ שמתרחצים בו בחמין, אסור לדבר ולהרהר בדברי קדושה, משום הזוהמא וההבל שיש בו. וכן במבואות המטונפות דהיינו מקומות ברחוב שיש שם טינופת, אסור בדברי קדושה. (שו\"ע סי' פ\"ד ס\"א מ\"ב סק\"ד. שע\"ה סי' ה' סי\"ג)"],["t","דין הזכרת שמות המיוחדים להקב\"ה במקומות המטונפים"],["b","במקומות המטונפים שהזכרנו לעיל שאסור בדברי קדושה. הוא הדין שאסור להזכיר שמות המיוחדים להקדוש ברוך הוא אפילו בלשון האומות (כגון \"אללה\" בלשון ערב, וכן \"גאד\" או \"גאט\" בלשון אשכנז, ו-\"דיו\" בלשון צרפת)."],["b","וכן אסור שם ליתן שלום לחבירו, כי שלום הוא שמו -הקדוש ברוך הוא, שנאמר (שופטים ו' כ\"ד) \"ויקרא לו של"],["b","י\"י שלום\". (שע\"ה סי' ה' סי\"ג)"]]},{"h":"כה תשרי יום שלישי","s":"הלכות נקיון המקום לדבר שבקדושה","d":["עלייה בתורה וירא\"ש ליוסף בן ר' דניאל | רפואה שלימה למאיר בן אליהו","הרה\"ג שמריהו ברזילי זצוק\"ל ר\"י משכן שמעון - תשס\"א"],"b":[["t","מה הדין לקרוא לאדם ששמו \"שלום\"?"],["b","אדם ששמו שלום, מותר לקרותו בשמו אף במקומות המטונפים, כיון שאינו מכוין על עניין השלום, אלא להזכרת שמו של אותו אדם. וירא-שמים צריך להחמיר, ויבלע את האות \"מ\"ם\" ויאמר רק \"שלו\" בלי מ\"ם. או יאמר \"שלון\" בנו\"ן. (שע\"ה סי' ה' סי\"ג)"],["t","האם מותר לדבר דברי קדושה כנגד ערוה?"],["b","אסור לדבר דברי תורה וקדושה כנגד ערוה, בין שלו בין של אחר, ואף של אשה כלפי אשה אחרת אסור. ואפילו של קטן או קטנה. שנאמר (דברים כ\"ג ט\"ו) \"ולא יראה בך ערוות דבר\". ויש אומרים שאפילו אם עוצם את עיניו שלא לראות את הערוה, לא מועיל, כיון שהיא כנגד פניו, אלא יטה פניו וגופו מכנגדה. (כה\"ח סי' ע\"ה סקי\"א. שע\"ה סי' ה' סי\"ד)"]]},{"h":"כו תשרי יום רביעי","s":"הלכות נקיון המקום לדבר שבקדושה","d":["לעילוי נשמת נח בנימין בן משה | לעילוי נשמת ציון בן שלום גחזן | לעילוי נשמת אודליה ידעי בת אברהם ז״ל"],"b":[["t","גוף של אשה במקום שדרכה לכסותו, ושיער, האם הוא ערוה?"],["b","טפח מגולה באשה במקום שדרכה לכסותו, וכן שערות של אשה נשואה, אסור לקרוא ק\"ש כנגדה, אפילו היא אשתו. ודבר זה אע\"פ שאינו ערווה ממש, אסרו אותו חכמים מפני שמביא לידי הרהור. ואם עוצם עיניו, אע\"פ שאינו מטה את גופו מותר, משום שלא יבוא להרהר. (כה\"ח סי' ע\"ה סקכ\"ז בשם נשמת אדם ופרי מגדים. שע\"ה סי' ה' סט\"ו)"],["t","מה הדין טפח מגולה באשה לגבי אשה אחרת?"],["b","ודווקא באיש, אסרו בדברי תורה. אבל לגבי אשה, כנגד טפח ושיער מגולים של אשה אחרת, אינם חשובים כמו ערוה, מפני שאין בה הרהור. ומותרת לברך ולקרוא ק\"ש כנגדה. וערווה ממש, אפילו של קטן או קטנה, אסורה גם אשה, לברך ולהתפלל, שנאמר \"ולא יראה בך ערוות דבר\". (ב\"י ריש סי' ע\"ה בשם הרשב\"א. א\"ר שם אות ג'. מאמר מרדכי שם אות ג'. שע\"ה סי' ה' סט\"ו)"]]},{"h":"כז תשרי יום חמישי","s":"הלכות נקיון המקום לדבר שבקדושה","d":["ברכה והצלחה ברו\"ג נחת מהילדים ופרנסה בשפע לאוהד בן ציון | מרים בת ר' סעדיה ברכה והצלחה ברו\"ג וברהגוה\"נ | לרפואה, הצלחה, פרנסה טובה, לעוזי בן רחל","הרה\"ג משומר צוברי זצוק\"ל רב העיר גן יבנה"],"b":[["t","מה הדין קול זמר של אשה?"],["b","קול זמר של אשה נחשב גם כן ערוה. וגם כשהוא מוקלט במכשיר, אסור. ומכל מקום בשעת הדוחק, שהוא שומע, ואי אפשר לו למחות, לא יתבטל משום זה מקרית שמע ותפילה ותורה, אלא יתאמץ לכוון כל לבבו, לענין הקדושה שהוא עוסק בה, ולא יתן לב עליה. (שע\"ה סי' ה' סט\"ז)"],["t","הלכות ברכות שאדם מברך בכל יום"],["b","האם חייב אדם לברך בכל יום מאה ברכות?"],["b","חייב אדם לברך בכל יום מאה ברכות לפחות, ודוד המלך תיקן זאת. וסמך מן התורה, ועתה ישראל מה י\"י אלהיך שואל מעמך, כי אם ליראה את י\"י וגו' אל תקרא \"מה\" אלא מאה, הן מאה ברכות, שהן ליראה את ה' ולאהבה אותו, ולזכרו תמיד על ידי הברכות שמברכין. (שע\"ה סי' ו' סי\"א)"]]},{"h":"כח תשרי יום שישי","s":"הלכות ברכות שאדם מברך בכל יום","d":["להצלחת מיכל בת אליהו"],"b":[["t","באיזה זמנים אנו צריכים לשים לב שלא יחסרו לנו מאה ברכות?"],["b","בכל ימי החול יש השלמה של כל מאה ברכות, מפני התשע עשרה ברכות שיש בתפילת העמידה שבשלוש תפילות. אבל בשבת ויום טוב שיש שבע ברכות בתפילת העמידה, חסרים מן המאה ברכות. ואותם משלימים בברכות הנהנין על פירות ובשמים. ובמה שמכוונים לברכות השליח צבור בחזרת התפילות, וברכות הקוראים בתורה והמפטיר, ועונין אחריהן אמן. (שע\"ה סי' ו' סי\"א)"],["t","האם צריך לכוון בשעת אמירת הברכות?"],["b","יכוון בברכות פרוש המילים; שלא יזרוק הברכה מפיו, אלא יכוון בעת האמירה ויברך בנחת. וראוי שירגיל את עצמו לברך בקול רם כי הקול מעורר הכוונה. ויש ליזהר מלהתעסק באיזה דבר בשעת אמירת הברכה, או להלך אז, כדי שיכוון פרוש המלות כראוי:"],["s","(שו\"ע סי' ה' ס\"א. מ\"ב שם סק\"א. שע\"ה סי' ו' ס\"ג)"]]},{"h":"כט תשרי יום שבת פרשת בראשית. ערב ראש חודש","s":"הלכות הזכרת השם","d":["לעילוי נשמת דניאל בן רפי ואביגיל אהרון ז\"ל"],"b":[["t","האם צריך לדעת קודם הברכה, מה היא הברכה שאותה הוא רוצה לברך?"],["b","קודם שיברך איזו ברכה, צריך שידע מה היא הברכה שהוא צריך לברך. כדי שבשעה שיזכיר את \"השם יתברך\" שהוא עיקר הברכה, ידע מה שיסיים. וכשהוא מברך, יהא פיו נקי מן הרוק, וגם שאר דבר לא איסור הוצאת שם שמים לבטלה יהא בתוך פיו, שנאמר ימלא פי תהלתך. (שע\"ה סי' ו' ס\"ב)"],["b","אסור להוציא שם שמים לבטלה. וכל המוציאו לבטלה, עובר על מצוות עשה דכתיב \"את י\"י אלהיך תירא\". וכתיב אם לא תשמור וגו' ליראה את השם הנכבד"],["b","והנורא. וזהו מכלל היראה, שלא להזכיר שמו הגדול, כי אם בדרך שבח וברכה במה שהוא מחוייב, או בדרך לימוד. (שע\"ה סי' ו' ס\"ד)"]]},{"h":"ל' תשרי יום ראשון א' דראש חודש","s":"הלכות הזכרת השם","d":["להצלחה בלימוד התורה ומידות טובות לישי בן דקל","כמוהר\"ר סאלם קלאזן זצוק\"ל תש\"מ - מרבני צנעא"],"b":[["t","איסור הוצאת שם שמים לבטלה"],["b","מה שהבאנו שאסור להוציא שם שמים לבטלה, אינו רק בשם הוי\"ה ואדנות בלבד, אלא כל השמות המיוחדים לו יתברך, אסור להוציא לבטלה. ואפילו בשמות שקורים האומות (כגון \"אללה\" בלשון ערב, וכן \"גאד\" או \"גאט\" בלשון אשכנז, ו\"דיו\" בלשון צרפת) טוב ליזהר."],["s","(שע\"ה סי' ו' ס\"ד)"],["t","האם מותר לכתוב אחד משמות הקב\"ה על מכתב?"],["b","אסור לכתוב בשום מכתב וכיוצא בזה את שמו יתברך בכל לשון, כי לאחר זמן יתגלגל המכתב באשפה. ודבר זה גורם עניות בישראל חס ושלום."],["b","אבל אות ה' בלבד, כגון ברוך ה', בעזרת ה', אין קפידא."],["s","(שע\"ה סי' ו' ס\"ד)"]]},{"h":"א' מרחשון יום שני ב' דראש חודש","s":"הלכות הזכרת השם","d":["לעילוי נשמת אבי מורי משה בן יחיא דהרי ז\"ל"],"b":[["t","מה הדין אם נזדמן לו רוק בתוך פיו, וגם צריך להזכיר את השם?"],["b","אסור להזכיר שם שמים ולירוק, משום שהוא בזיון ק, ואח\"כ כלפי מעלה. לפיכך אם נזדמן לו בתוך פיו, ירו יזכיר את השם. וכן כשמנשק את הספר, ירוק תחילה, ולא אח\"כ. (סנהדרין ק\"א ע\"א. שע\"ה סי' ו' ס\"ד)"],["t","כשרוצה להזכיר את שם ה' איך יאמר?"],["b","כשרוצה להזכיר את השם יאמר \"השם\" ולא כמו שיש טועים לומר \"אדושם\" או \"אמוני\" או \"אלוקים\", \"קלי\", \"שקי\", \"צבקות\", וכה\"ג שאין זה דרך כבוד כלפי מעלה."],["s","(שע\"ה ח\"א ס'י' ו' ס\"ד)"]]},{"h":"ב' מרחשון יום שלישי","s":"הלכות הזכרת השם","d":["ברכה והצלחה ארי דוד בן ליאל ועדיה בידני | ברכה והצלחה דניאל בן יוסף"],"b":[["t","הלומד גמ' ומדרשים אם יזכיר שם שמיים?"],["b","הלומד גמרא, ומדרשים, פוסקים, ומפרשים, וכיוצא ם פסוק, או מקצתו, אין איסור כלל בזה, והובא ש בקריאת השמות, ואפילו בשם אדנות, ואדרבה יש אומרים שמצווה להזכירם ככתבם. (שע\"ה ח\"א סי' ו' ס\"ה)"],["t","האם מותר להזכיר שמות הקדושים המוזכרים בתוך מאמרי התלמוד?"],["b","אם מוזכר שמות הקדושים בתוך מאמר בתלמוד או במדרשים, ואינו פסוק כלל, גם שם יוכל להזכיר את השמות הקדושים ככתבם, חוץ מבשם אדנות, ובשם יה, שראוי לומר באלף, דלת, נון, יוד. ביו\"ד ה\"א. (שע\"ה ח\"א סי' ו' ס\"ה)"]]},{"h":"ג' מרחשון יום רביעי","s":"הלכות הזכרת השם","d":["לעילוי נשמת הרב עובדיה יוסף זצ\"ל רב ראשי בישראל"],"b":[["t","האם מותר להזכיר שם שמים המוזכר בתוך נוסח ברכה בתלמוד?"],["b","נוסח ברכה המוזכר בתלמוד ובמדרשים, יאמר ברוך אתה \"השם\" במקום הוי\"ה. אבל שם אלהינו שבתוך נוסח הברכה, מנהגינו לקראו ככתיבתו, בלא שום שינוי. והוא הדין בכל זה, לדורש ברבים בדברי תורה. (שע\"ה ח\"א סי' ו' ס\"ה)"],["t","אם יזכיר שם שמיים בשירות ותושבחות?"],["b","אם אומרים שירות ותושבחות באימה וביראה, ולא בקלות ראש מותר להזכיר כל השמות כמות שהן, וגם לחזור הבית כפי דרך השירים, וכן הוא המנהג (שע\"ה ח\"א סי' ו' ס\"ו)"]]},{"h":"ד' מרחשון יום חמישי","s":"הלכות הזכרת השם","d":[],"b":[["t","אם הוציא שם שמיים לבטלה?"],["b","אסור לברך ברכה לבטלה חס ושלום, או לגרום לעצמו לברך ברכה שאינה צריכה. ואם נכשל ובירך ברכה לבטלה, יאמר אחרי כן ברוך שם כבוד מלכותו לעולם ועד. (שע\"ה ח\"א סי' ו' ס\"ז)"],["t","מה הדין אם כבר התחיל את הברכה, ואמר ברוך אתה ה'?"],["b","אם מיד לאחר שהזכיר את השם נזכר שאינו צריך לברך, כגון שבירך על השתיה ברוך אתה ה', ונזכר שכבר בירך על השתיה הקודמת, ואינו צריך לברך על השתיה הזאת, יסיים \"למדני חוקיך, שזהו פסוק שלם בתהילים (קיט יב) והוי כמו לימוד, ולא לבטלה. (שע\"ה ח\"א סי' ו' ס\"ז)"]]},{"h":"ה' מרחשון יום שישי","s":"הלכות הזכרת השם","d":[],"b":[["t","מה הדין אם נזכר רק אחרי שהתחיל תיבת אלהינו?"],["b","ואם התחיל תיבת \"אלהינו\" ונזכר מיד. כלומר בירך; \" יסיים הי....\" ולא גמר לומר \"נו ברוך אתה ה' \"אל \"ישראל, אבינו, מעולם ועד עולם\" שזהו גם כן לשון הפסוק בדברי הימים א', (כט י'). ומכל מקום יאמר גם בזה, \"ברוך שם כבוד מלכותו לעולם ועד\"."],["s","(שע\"ה ח\"א סי' ו' ס\"ז)"],["t","אם נסתפק אם בירך או לא?"],["b","כל הברכות אם נסתפק בהם אם בירך, או לא בירך, אינו חוזר ומברך. חוץ מברכת המזון שאם נסתפק אם בירך ברכת המזון, או לא בירך, חוזר ומברך. מפני שברכת המזון מן התורה, וספק דאורייתא לחומרא. (שע\"ה ח\"א סי' ו' ס\"ט)"]]},{"h":"ו' מרחשון יום שבת פרשת נח","s":"הלכות הזכרת השם","d":[],"b":[["t","שמות שאסור לקרותם"],["b","אסור להגות (להזכיר ככתבו) שם הוי\"ה ברוך הוא לם קמץ, באותיותיו, דהיינו לקרותו כניקודו שוא חו אלא בכינויו באדנות. גם לא יקרא אותיותיו כסדר, אלא בהפסק, וכך נוהגים שמוסיפים ווי\"ן בינתיים, וא\"ו וה\"א\"."],["b","\"יו\"ד וה\"א ו (וכ\"כ בשם הגר\"י צוברי בס' פסקי הלכות עמ' ל\"ב)"],["b","וכן יש ליזהר שלא לקרות שמות מלאכים שאין נמצאים בשמות בני אדם כמותם. ולכן במקום \"מטטרון\" - יאמר מי\"ם טי\"ת. \"סמאל\" – יאמר סמ\"ך מי\"ם."],["s","(שע\"ה ח\"א סי' ו' ס\"י)"],["t","הלכות עניית אמן"],["b","מה יכוון כשעונה \"אמן\"?"],["b","כל ברכה שאדם שומע מחבירו, כששומע שגומר את הברכה, צריך לומר אמן."],["b","ופירוש אמן, אמת. ויכוון בלבו, אמת היא הברכה שבירך המברך, ואני מאמין בזה. ובברכות שיש בהן גם בקשה, כגון בתוך תפילת שמונה עשרה, כגון אתה חונן וכדו' יכוון באמירת \"אמן\" לשני הדברים אמנו י דברים, אמת היא הברכה, ויהי רצון ש במהרה. ובקדיש שאינו אלא תפילה על העתיד יכוון רק לבקשה שיאמן הדבר במהרה. (שע\"ה ח\"א סי' ו' סי\"ב)"]]},{"h":"ז' מרחשון יום ראשון","s":"הלכות עניית אמן","d":[],"b":[["t","לזש\"ק שרה בת מיכאל"],["b","עניית אמן כתיקונה צריך ליזהר מאוד שיאמר תיבת אמן כתיקונה, שלא יחטוף האל\"ף, ולא יבליע הנו\"ן."],["b","וכן לא יגביה קולו יותר מן המברך, שנאמר \"גדלו לי\"י איתי, ונרוממה שמו יחדיו\"."],["b","גם יזהר מאוד שלא יענה אמן, קודם שסיים המברך כל הברכה. (שע\"ה סי' ו' סי\"ג)"],["t","האם מותר לאחר עניית אמן מסיום הברכה?"],["b","לא יאחר מלענות אמן. אלא תכף שסיים המברך את הברכה, יענה אמן. ותוך כדי דיבור (דהיינו כדי אמירת שלוש תיבות שלום עליך רבי), נחשב צמוד לברכה."],["b","וכל שלא כלה אמן מפי רוב הציבור, יכול כל אחד לענות עמהם. (שם)"]]},{"h":"ח' מרחשון יום שני","s":"הלכות עניית אמן","d":[],"b":[["t","האם מותר לאדם לענות אמן אחר ברכה של עצמו?"],["b","כל העונה אמן על ברכת עצמו, הרי זה מגונה. ואפילו סיים ברכה אחת בשווה עם שליח ציבור, לא יענה. אבל אם הוא בירך ברכה אחת, והשליח ציבור ברכה אחרת, וסיימו בשווה, עונה אמן על ברכת שליח ציבור."],["s","(שע\"ה סי' ו' סי\"ד)"],["t","באלו ברכות, יש מצווה לענות אמן אחר ברכת עצמו?"],["b","ואחר ברכה שהיא סוף ברכות אחרונות, העונה אמן על עצמו, הרי זה משובח. ולכן המנהג שעונה אמן בסיום ברכת השכיבנו אחרי קרית שמע דערבית, ובסיום ברכות ההפטרה. וכן אחר ברכת בונה ירושלים בברכת המזון, מפני ששם סיום שלוש הברכות שהן מן התורה. והטוב והמטיב מדרבנן, וכאילו היא תוספת. והוא הדין בסיום שמונה עשרה, שהוא המברך את עמו ישראל בשלום. (שם)"]]},{"h":"ט' מרחשון יום שלישי","s":"הלכות עניית אמן","d":["כמוהר\"ר יהודה חבשוש זצוק\"ל - תש\"ד"],"b":[["t","האם יכול לענות אמן אחר ברכת ישתבח שבירך בעצמו?"],["b","ברכת ישתבח אם היא נחשבת כברכה שהיא סוף ברכות, מפני שהיא סיום לברכת ברוך שאמר. או אינה נחשבת כברכה של סוף ברכות. תלוי במחלוקת."],["b","מנהג השאמי לענות אמן אחר ברכת ישתבח, לפי שמחשיבין אותה סמוכה לברוך שאמר. וכן אחר ברכת יהללוך, משום דהוי סיום לברכה ראשונה של ההלל."],["b","ומנהג הבלדי, שאין עונים באלו, אלא דווקא על ברכות סמוכות ממש. (שע\"ה סי' ו' סי\"ד)"],["t","אם מותר לענות אמן אחר ברכת קטן פחות מגיל שש, שהוא גיל חינוך?"],["b","עונים אמן אחרי קטן שמברך כדי לפטור את עצמו, כגון קודם אכילה ושתייה, או כשעולה לספר תורה. אע\"פ שהוא פחות מבן שש שנים, כיון שהוא בן חינוך לעניין זה, וכן הוא מנהגינו. (שע\"ה סי' ו' סט\"ו)"]]},{"h":"י' מרחשון יום רביעי","s":"הלכות עניית אמן","d":["ברכה והצלחה איתן סעדיה בן יעקב ועדי לרוס | ברכה והצלחה לאושרית ידעי"],"b":[["t","האם צריך לענות ברוך הוא וברוך שמו, כששומע הזכרת השם?"],["b","כששומע שמברכים ברוך אתה ה'... טוב לומר ברוך הוא וברוך שמו (אם יכוון בו כראוי), ויש הנוהגים כן. וזהו דווקא כשנמצא במקום שיכול להפסיק, וגם אינו יוצא באותה ברכה ידי חובה. כפי שיבואר בהלכה הבאה. (שע\"ה ח\"א סי' ו' סט\"ז)"],["t","באיזה זמנים לא יענה ברוך הוא וברוך שמו?"],["b","אם השומע עומד במקום שאסור להפסיק. כגון ששומע ברכה בתוך פסוקי דזמרה, אל יאמר ברוך הוא וברוך שמו, אלא רק יענה אמן. וכן אם שומע ברכה שגם הוא צריך לצאת בה ידי חובה, שתהא נחשבת לו כאילו אמרה בעצמו, כגון ברכות השופר וברכות המגילה, לא יאמר ברוך הוא וברוך שמו, משום דזה הוי הפסק באמצע הברכות. ודווקא כשנמצא במקום שיכול להפסיק וגם אינו יוצא באותה ברכה ידי חובה. (שם. ומ\"ב סי' קכ\"ד ס\"ק כ\"א)"]]},{"h":"יא מרחשון יום חמישי","s":"הלכות ברכות השחר","d":["לעילוי נשמת גזאל (איילה) בת יוסף | ברכה והצלחה לנועה ידעי"],"b":[["t","ברכות השחר מברכים בבית, או בבית הכנסת?"],["b","ברכות השחר וברכות התורה מברך אותן כל אחד בביתו, קודם שהולך לבית הכנסת."],["b","ורבים נוהגים שהש\"ץ מסדיר כל הברכות בבית הכנסת, כדי להוציא את עמי הארץ שאינם יודעים. וגם הבקיאים יוצאים בזה ידי חובתם אם הם מכוונים לצאת. ורק ברכת על נטילת ידים מברכים כולם בביתם תיכף אחרי הנטילה."],["b","ויש מברכים בביתם גם אשר יצר ומתחיל בבית הכנסת מאלהי נשמה. (שע\"ה סי' ז' ס\"א)"],["t","האם מברכין בברכות השחר, את ברכת הנותן ליעף כח?"],["b","ברכת הנותן ליעף כח, אין מנהגינו לומר. וכן שאר ברכות שלא נזכרו בתלמוד. ואשה המברכת ברכות השחר, במקום שלא עשני אשה, תאמר \"ברוך שעשני כרצונו\" בלא הזכרת השם"]]},{"h":"יב' מרחשון יום שישי","s":"הלכות ברכות השחר","d":["לעילוי נשמת סאלם בן סלימאן ימיני ז\"ל"],"b":[["t","האם עיוור או חרש מברכים ברכות השחר ככולם?"],["b","גם עיוור מברך ברכת פוקח עיוורים, משום שיש לו הנאה שאחרים מראים לו את הדרך. וכן חרש, אף על פי שאינו יכול לשמוע קול התורנגול, מברך הנותן לשכוי בינה, ככל אדם. (שע\"ה ח\"א סי' ז' ס\"ג)"],["t","אם קדם ובירך זוקף כפופים, קודם לברכת מתיר אסורים?"],["b","ברכת מתיר אסורים, קודמת לברכת זוקף כפופים. שברכת מתיר אסורים, היא הודאה על התרת האיברים. וברכת זוקף כפופים היא הודאה על זקיפת הקומה."],["b","אם קדם ובירך זוקף כפופים, קודם שבירך מתיר אסורים, שוב לא יברך מתיר אסורים. שבכלל זקיפת הקומה, היא התרת האיברים. (שע\"ה סי' ז' ס\"ג)"]]},{"h":"יג מרחשון יום שבת פרשת לך לך","s":"הלכות ברכות השחר","d":["ברכה והצלחה לרות בת ארז | פרנסה בשפע ובריאות איתנה מיכאל בן יוסף","הרה\"ג שלמה קרח זצוק\"ל רב ואב\"ד ב\"ב"],"b":[["t","האם ברכות התורה הם ב' ברכות או ג'?"],["b","המנהג שברכות התורה הם ג' ברכות, דהיינו שברכת \"הערב נא\" איננה המשך לברכה ראשונה. ולכן עונים אמן גם על ברכת \"על דברי תורה\" שהיא סיום הברכה הראשונה, וברכת \"הערב נא\", היא ברכה שנייה. (שע\"ה ח\"א סי' ז' ס\"ד)"],["t","הניעור כל הלילה, איזה ברכות צריך לברך בבוקר?"],["b","הניעור כל הלילה, מברך בבוקר כל ברכות השחר, וכן ברכות התורה. חוץ מברכת על נטילת ידים והמעביר שינה, שאינו מברך, וכן נוהגים."],["b","אמנם מפני שיש סוברים שהניעור בלילה אינו מברך ברכות התורה, נכון להדר לשמוע אותן מפי אדם שישן, ולכוון לצאת ידי חובה. (שם ס\"ה)"],["b","ומנהג השאמי לברך המעביר שינה."],["s","(פסקי הלכות לגר\"י צוברי עמוד ח')"]]},{"h":"יד מרחשון יום ראשון","s":"הלכות ברכות השחר","d":["לעילוי נשמת רבקה בת שרה | לעילוי נשמת אתי מיכל בת יחיא | רועי בן יגאל ברכה והצלחה"],"b":[["t","הקם משנתו קודם עלות השחר, אם יכול לברך ברכות השחר?"],["b","הקם מחצות הלילה ללמוד, מברך על נטילת ידיים וכל ברכות השחר, וברכת התורה. בין שדעתו לחזור לישון, ובין שאין דעתו לחזור לישון. ופרשת התמיד ראוי לדלג, ולאומרה לאחר עלות השחר. אם קם לאחר חצות ובירך על נטילת ידיים כדלעיל, וחזר לישון, כשיקום יטול ידיו ג' פעמים בלא ברכה. (שע\"ה ח\"א סי' ז' ס\"ו)"],["t","אם יכול לברך ברכות השחר לאחר התפילה?"],["b","כל ברכות השחר אם לא בירך קודם התפילה, יכול לברך לאחר התפילה. חוץ מברכת \"על נטילת ידיים\", (כיון שיש אומרים דנטילת ידים שחרית, נתקנה משום התפילה, א\"כ לאחר שהתפלל, אין עוד מקום לברכה זאת)."],["b","וחוץ מברכת \"אלהי הנשמה\", (שכבר יצא בברכת מחיה המתים). (שע\"ה ח\"א סי' ז' ס\"ז)"]]},{"h":"טו מרחשון יום שני","s":"הלכות ברכות התורה","d":["לעילוי נשמת שלום כבתי בן סעיד | לעילוי נשמת חנה בת רבקה | ברכה והצלחה להראל בן אברהם"],"b":[["t","האם יכול לברך ברכות התורה לאחר התפילה?"],["b","אם לא בירך ברכות התורה קודם התפילה, יש אומרים שלא יוכל לברך אחר התפילה, משום שכבר נפטר בברכת אהבת עולם, שיש בה גם מענין ברכת התורה. ויש אומרים שאין ברכת אהבת עולם פוטרת מברכות התורה, אלא אם לומד לאחר התפילה מיד בלי הפסק. לכן לכתחילה צריכין ליזהר לברך ברכות התורה קודם התפילה. ובדיעבד, אם לא בירך קודם התפילה, ילמד איזה דבר מיד אחר התפילה."],["b","וגם אם לא למד מיד לאחר התפילה, אפילו הכי לא יברך מספק. (שע\"ה ח\"א סי' ז' ס\"ז)"],["t","כיצד המנהג באמירת \"י\"י מלך\" קודם ברוך שאמר?"],["b","מנהג השאמי לעמוד ולומר \"י\"י מלך, י\"י מלך\" וכו' והציבור כופלין אותו, וכן פעם שנית, ואחר כך אומרים למנצח בנגינות, ואח\"כ ברוך שאמר. אך בבלדי המנהג לומר זאת מיושב, פעם אחת, סמוך לסיום פיסקת \"לעולם יהא אדם\" וכו', בין ביחיד בין בציבור. ואחר שמסיימים \"ברוך י\"י לעולם אמן ואמן\", עומדים לאמירת המהולל וברוך שאמר. (שם סי\"א)"]]},{"h":"טז מרחשון יום שלישי","s":"הלכות סדר התפילה וציצית","d":["ברכה והצלחה לאלדד בן יואב מהצרי הלוי"],"b":[["t","האם אמירת ה' מלך קודם ברוך שאמר הוי דבר שבקדושה?"],["b","פשוט לכולי עלמא שאמירת ה' מלך אינו נחשב דבר שבקדושה ולכן אין צריך שיהיו עשרה בשעת אמירתו. והיחיד העוסק בתפילתו, אפילו שהוא עומד בקרבנות שמותר להפסיק בהם, אינו צריך להפסיק לענות עמהם."],["b","מיהו אם אינו עוסק בתפילה, אלא שותק, נכון שגם הוא יתערב עם הציבור, ויענה עמהם."],["s","(שע\"ה ח\"א סי' ז' עיני יצחק הע' כב'. בא\"ח ש\"א פרשת ויגש ס\"א)"],["t","חשיבות מצוות ציצית"],["b","מצוות ציצית שקולה כנגד כל המצוות כולן, שנאמר \"וראיתם אותו וזכרתם את כל מצוות י\"י\". לכן אף על פי שאין אדם חייב בציצית אם אין בגדו בעל ארבע כנפות, מכל מקום טוב ונכון שיזהר ללבוש טלית קטן כל היום, מלבד מה שצריך שיהיה לו טלית גדול להתעטף בו בשעת התפילה. (שע\"ה ח\"א סי' ח' ס\"א)"]]},{"h":"יז מרחשון יום רביעי","s":"הלכות ציצית","d":["רפואה שלימה איתמר בן אליהו","כמוהר\"ר שלום אלשיך זצוק\"ל - תרנ\"ט","כמוהר\"ר צאלח נגאר זצוק\"ל - תש\"מ מרבני סוואדיה"],"b":[["t","זה אלי ואנוהו"],["b","יהדר שתהיה הטלית נאה, וכן כל המצוות צריך לעשותן בהידור בכל מה שאפשר, שנאמר \"זה אלי ואנוהו\", ודרשו חז\"ל, התנאה לפניו במצוות. (שע\"ה ח\"א סי' ח' ס\"ב)"],["t","האם חוטי הציצית חייבים להיעשות לשמה?"],["b","הטוויה, השזירה, והקשירה, של החוטים צריכים להיות לשם מצוות ציצית. ואם לא היו טווין לשם ציצית, פסולים."],["b","וטוב שיוציא בשפתיו בתחילה שעושה לשמה, ולא יסתפק במחשבה, וכן המנהג."],["s","(שו\"ע סי\"א ס\"א. שע\"ה ח\"א סי' ח' ס\"ב)"]]},{"h":"יח מרחשון יום חמישי","s":"הלכות ציצית","d":["לעילוי נשמת מנחם ישועה בן הרב שלום יצחק ז\"ל"],"b":[["t","האם ציציות שנעשו במכונה כשרות לציצית?"],["b","ידקדק לקנות הציצית מאיש נאמן (או בחנות, עם חותם הכשר על הפתילים) שיהיה בטוח שנעשו הטויה השזירה והקשירה עבודת יד לשמן, וציציות שנטוו על ידי מכונות דעת הרבה פוסקים שהן פסולות."],["s","(שע\"ה ח\"א סי' ח' ס\"ב)"],["t","האם אשה וקטן כשרים לעשות ציציות לציצית?"],["b","גם אשה כשרה לטוות, ולשזור, ולקשור, לשם מצוות ציצית."],["b","והוא הדין קטנה וקטנה, אם יודעים לעשות המצווה לשמה, וגדול העומד על גביו, המלמדו לעשות לשמה, כשר. (שם ועיני יצחק י\"א)"]]},{"h":"יט מרחשון יום שישי","s":"הלכות ציצית","d":[],"b":[["t","איזו טלית חייבת מן התורה בציצית?"],["b","לדעת הרי\"ף והרמב\"ם, אין חייב בציצית מן התורה, אלא בגד פשתים, או של צמר רחלים. אבל בגדי שאר מינים, אין חייבים בציצית, אלא מדרבנן. ודעת התוס' והרא\"ש ששאר מינים חייבים מן התורה. לפיכך ירא שמים יצא את כולם, ויעשה את הטלית מצמר רחלים, כדי שיוכל לקיים מצות ציצית מן התורה בלי פקפוק: (שו\"ע סי' ט' סעיפים א' ו'. שע\"ה סי' ח' ס\"ג)"],["t","האם אפשר לתת ציציות, שלא ממין הבגד?"],["b","ציצית של פשתים, או של צמר רחלים, מועיל לתת בכל מיני בגדים, לצאת ידי חובת מצוות ציצית. ומכל מקום לא יתן ציצית של פשתן – לצמר. או ציצית של צמר – לפשתן. מפני שהם כלאים: (דרק בזמן שהיה תכלת, שהוא מצמר, התירה התורה לתת על בגד פשתים. אבל בזמן הזה שאין תכלת, יש איסור כלאים.) (שו\"ע סי' ט' ס\"ב)"]]},{"h":"כ' מרחשון יום שבת פרשת וירא","s":"הלכות ציצית","d":["כמוהר\"ר מרדכי שרעבי זצוק\"ל ר\"י המקובלים נהר שלום","כמוהר\"ר חיים מוסא חג'בי זצוק\"ל - תש\"י אב\"ד כוולאן"],"b":[["t","האם אפשר לעשות הציציות משאר מיני בגדים?"],["b","ציצית של שאר מינים, אי אפשר לתת על בגד ממין אחר. אלא אם כן הבגד מאותו מין של הציציות. כגון משי, לבגד משי. וצמר גפן, לצמר גפן. אבל שלא במינם אין פוטרין: (שו\"ע סי' ט' ס\"ג)"],["t","איזה צבע ראויה להיות הטלית?"],["b","ראוי שתהיה הטלית בצבע לבן, וכן נוהגים, אלא שעושים בו פסים שחורים לנוי (או כחולים, זכר לתכלת)."],["b","וכן החוטים יהיו לבנים דווקא, אפילו אם גוון הטלית אינו לבן. (שע\"ה סי' ח' ס\"ג)"]]},{"h":"כא מרחשון יום ראשון","s":"הלכות ציצית","d":["לעילוי נשמת מזל (סעדה) בת רבי משה מליחי | ברכה והצלחה למיכל בת ארז","כמוהר\"ר הרב יחיא אלשיך זצוק\"ל - תשנ\"ז"],"b":[["t","אם ללבוש הציצית מעל הבגדים או תחת הבגדים?"],["b","יש נוהגים ללובשה מעל הבגדים כדעת מרן השו\"ע, כדי שתמיד יראהו ויזכור המצוות. ויש הנוהגים ללובשה תחת הבגדים כדעת האר\"י. ומכל מקום את הציציות עצמן, ראוי להוציא החוצה תמיד. (שע\"ה סי' ח' ס\"ד)"],["t","האם מברכים על טלית קטן (הנקראת בלשוננו ציצית)?"],["b","המנהג אצלנו דרך כלל, אותם שהיו לובשים טלית קטן (בלשוננו ציצית), מנהגם שלא לברך עליו כלל. לא רק בשחרית שיש מקום לפטרו ע\"י ברכת טלית גדול, אלא גם כשלובשים אותו באמצע היום אחרי הפסקה. אמנם יש שנוהגים לברך עליו. ולהלכה: הנוהגים לברך על טלית קטן יש להם על מה שיסמוכו, ויכולים להחזיק במנהגם. אבל אין הדברים מוסכמים ומבוררים לכל השיטות, לכן טוב לפטור הטלית קטן בבוקר בברכת הטלית גדול. ואף אם לובשו בתחילה בצהרים, לא יוציא בשפתיו הזכרת השם בברכה, רק יהרהר בלבו. (שע\"ה שם. שולי המעיל אות כ\"א)"]]},{"h":"כב מרחשון יום שני","s":"הלכות ציצית","d":[],"b":[["t","כיצד עשיית הציצית לפי מנהגינו?"],["b","אופן עשיית הציציות כפי מנהגינו, כך הוא; אומר תחילה הריני עושה לשם מצוות ציצית. ומכניס ארבע חוטים בנקב שבכנף הבגד, וכופלם לשמונה חוטים. לוקח ארבעה חוטים של צד אחד וארבעה חוטים של צד השני, וקושרם יחד ב' קשרים זה על גב זה."],["b","לאחר מכן כורך בחוט הארוך שלוש כריכות, והוא תחתיהם, ומהדקם. ושלוש כריכות אלו נקראים חוליא."],["b","ועושה שבע חוליות. ומרחיק בין חוליא לחוליא כשליש אגודל."],["b","כל אחת מהחוליות נחשבת קשר, כיון שהן מהודקות היטב."],["b","ומנהג זה מיוסד על פי התלמוד והזוהר, ורבינו הרמב\"ם. (שע\"ה סי' ח' ס\"ה)"],["t","מנהג נוסף בעשיית הציצית"],["b","יש נוהגים שלאחר שהכניס את החוטים וכפלם וקשר ב' קשרים זה על גב זה;"],["b","עושה ד' חוליות. חוליא ראשונה, עשר כריכות, ובשנייה חמש, ובשלישית שש, וברביעית חמש. כמנין \"הוי\"ה\". ובין כל חוליה לחוליה עושין שני קשרים."],["b","ויש נוהגים עוד כעין המנהג הזה, אלא שבמקום לעשות; \"עשר\", \"חמש\", \"שש\", \"חמש\": עושין; \"שבע\", \"שמונה\", \"אחת עשרה\", \"שלוש עשרה\", כמנין \"י\"י אחד\". (שם)"]]},{"h":"כג מרחשון יום שלישי","s":"הלכות ציצית","d":["ברכה והצלחה לבנימין בן גיא"],"b":[["t","מהו שיעור החוטים?"],["b","שיעור כל אורך החוטים, צריך להיות לכל הפחות \"עשרים וארבעה סנטימטר\" (י\"ב אגודלים), מן הקשר הראשון, עד קצה החוטים."],["b","ונוי הציצית \"שליש גדיל, ושני שלישי ענף\" (גמ' מנחות לט.) פירוש; שיהיו כל החוליות ביחד, שליש. והחוטין התלויים, שני שלישים."],["b","ועל כן ידקדק שיהיו כל החוליות \"שמונה סנטימטר (ד' אגודלים). והחוטים התלויים \"שש עשרה סנטימטר\" (ח' אגודלים). ואם הן ארוכים יותר, ירחיק יותר בין החוליות. (שע\"ה סי' ח' ס\"ו)"],["t","היאך יחתוך את החוטים כשצריך לכך (לקצרם וכדו')?"],["b","ראוי שלא לחתוך את ראשי החוטים בסכין או במספריים (של מתכת), משום שנאמר \"לא תניף עליהם ברזל\". אלא בשיניים שהן ל\"ב, יחתוך ל\"ב חוטים. והוא הדין לחתכם באבן חדה וכדו'. (שע\"ה ח\"א סי' ח' ס\"ח ובהערה)"],["b","[וכיום מוכרים מספריים מיוחדות שאינם עשויים מברזל]"]]},{"h":"כד מרחשון יום רביעי","s":"הלכות ציצית","d":["לעילוי נשמת ציפורה בת מנצור ומזל | לעילוי נשמת שלום בן שלמה"],"b":[["t","מה הדין אם נקב הטלית קרוב לשפת הטלית?"],["b","הנקב שמכניסים בו את הציצית, לא יהא רחוק משפת הבגד, הן באורך הן ברוחב, יותר משלושה אגודלים (שש סנטימטר). מפני שאינו נקרא כנף. ולא למטה מכשיעור שיש מקשר גודל עד סוף הציפורן (כשני אגודלים, ארבעה ס\"מ), משום שנאמר \"על כנפי בגדיהם\", ואם היה למטה ממלא קשר גודל, היה תחת הכנף. ומודדין זה ביושר, ולא באלכסון מן הקרן: [כיום מגיע מוכן בחנויות, הנקב במקומו הנכון.] ואם היה הנקב רחוק כשיעור, אלא שעל ידי משיכת הקשר, נקמט שפת הטלית ואין בו כשיעור, מכל מקום כשר. (שו\"ע סי' י\"א ס\"ט שע\"ה ס\"ט)"],["t","מה הדין אם נקרע הכנף ונתמעט מהשיעור לאחר שנעשה?"],["b","אם בשעת קשירת הציציות, היה הנקב רחוק כשיעור, ואחר כך נקרע קצת הנקב, או שפת הטלית, עד שהציצית היא בפחות משיעור הריחוק מהקצה, לא נפסלה בכך. כי לא הקפידה התורה שלא תהא הציצית תחת הכנף, אלא בשעת העשייה, שנאמר, \"ועשו להם ציצית על כנפי בגדיהם\". ומכל מקום לכתחילה טוב לעשות אמרא סביב הנקב, וכן בשפת הטלית, שלא יפחת משיעור קשר אגודל, וכן נוהגים. (שע\"ה סי' ח' סי\"ב)"]]},{"h":"כה מרחשון יום חמישי","s":"הלכות ציצית","d":["ברכה והצלחה לאחינעם בת פנינה ומשפחתה"],"b":[["t","האם צריך לעשות שני נקבים בכנף בכדי להכניס את הציציות?"],["b","יש אומרים שבטלית קטן, יעשה שני נקבים זה אצל זה כמו צירי, ויכניס בשניהם את הציצית, והן תלויות מבחוץ, ואין מנהגינו כן. (שם סי\"א)."],["t","האם יש מצווה לבדוק את כשרות הציצית?"],["b","מידת חסידות לבדוק את הציציות אם הן כשרות, קודם שמברך. ויבדוק גם את החוטין שהן בתוך הנקב. וכן יפריד את החוטין שלא יהיו מסובכים זה בזה. ומותר להפריד הציציות בשבת. אבל בפעם הראשונה אחר גמר עשייתן, אסור להפרידן בשבת, משום מכה בפטיש. (שע\"ה ח\"א סי' ח' סי\"ד)"]]},{"h":"כו מרחשון יום שישי","s":"הלכות ציצית","d":["לעילוי נשמת לאה בת יפת נגר ז\"ל","כמוהר\"ר אהרן מצרפי זצוק\"ל תשל\"א אב\"ד של אכמת בני מנצור"],"b":[["t","אם צריכות הציציות להיות נוטפים על הקרן?"],["b","יש מצריכים שהציציות יהיו נוטפים ותלויים על הקרן לאורך הטלית, ולא ישמטו לצד מטה ואם היה ברחבו, לא הוי נוטף שהרי כלפי הקרקע הוא תלוי. (ויש כנף שהוא תולה הציצית בארכו, ויש ברחבו, הכל לפי מה שמתעטפים בו.) ולא נהגו כן. ומכל מקום המחמיר תבוא עליו ברכה."],["b","ועל כל פנים אסור שיהיו תלויים באלכסון, על קרן זוית. (שו\"ע סי' י\"א סט\"ו. שע\"ה ח\"א סי' ח' סי\"ג עיני יצחק מ\"ב)"],["t","שלא יברך על הטלית בעודה מקופלת"],["b","כל המצוות מברך עליהן עובר לעשייתן (קודם לעשייתן)"],["b","ולאחר הברכה תיכף ומיד צריך לעשות את המצווה בלי הפסק ולכן יאחוז את הטלית בשתי ידיו כשהיא פרושה ופשוטה מקיפוליה. ויברך מעומד. (שע\"ה ח\"א סי' סט\"ו)"]]},{"h":"כז מרחשון יום שבת פרשת חיי שרה","s":"הלכות ציצית","d":["לעילוי נשמת אברהם בן ישורון הלל ז\"ל | לעילוי נשמת חנה בת אסתר ושמעון | בריאות הצלחה בזוגיות ופרנסה מיכל בת מירב"],"b":[["t","בנוסח הברכה \"בציצית\" האם \"הבית\" בפתח או בשווא?"],["b","נוסח הברכה \"להתעטף בציצית\", הבית בפתח, והצדי דגושה. ויש מהשאמי שגורסים \"להתעטף בציצית\" הבית בשווא. (שע\"ה ח\"א סי' ח' סט\"ו)"],["t","האם כיסוי הראש בטלית חובה?"],["b","מברך מעומד להתעטף בציצית, ומיד אחר כך, יעטוף את ראשו ומקצת גופו. ויעמוד מעוטף כך שיעור הילוך ארבע אמות לכל הפחות, ואחר כך יכול להסירו מעל ראשו. (שם)"]]},{"h":"כח מרחשון יום ראשון","s":"הלכות ציצית","d":["לעילוי נשמת רבי סעדיה בן משה עמר | לעילוי נשמת רסיה בת צדוק | לעילוי נשמת מאירה (רד'ה) בת סעיד סאלח ז\"ל","הרה\"ג ציון חוכיימה זצוק\"ל - תשע\"ו"],"b":[["t","האם יש עניין שהטלית תהיה על ראשו כל משך זמן התפילה?"],["b","נכון שיהא ראשו מכוסה בטלית כל שעת התפילה, כדי שיתפלל באימה. מפני שהכיסוי מכניע לב האדם, ומביאו לידי יראת שמיים. ועוד שמסתיר עיניו מלהביט לימינו ולשמאלו, ולא תתבלבל כוונתו. וכן הוא המנהג. ואפילו הילדים הקטנים מכסים ראשם בטלית. (שע\"ה ח\"א סי' ח' סט\"ו)"],["t","האם יש להקפיד שהציציות לא ייגררו על הרצפה?"],["b","נכון להיזהר שלא לגרור את הציציות על הארץ, משום ביזוי מצווה. לכן יגביהן. ואם הטלית ארוכה, יכול לתחבן תוך החגורה, או יעלה הטלית על כתיפו. (שע\"ה ח\"א סי' ח' סט\"ז)"]]},{"h":"כט מרחשון יום שני ערב ראש חודש","s":"הלכות ציצית","d":["ברכה והצלחה לעזריאל בן שלום","כמוהר\"ר סעדיה שאער זצוק\"ל - תשמ\"ה דיין במחוז ירים"],"b":[["t","צורת העטיפה"],["b","אין מנהגינו להתעטף בטלית כעטיפת הישמעאלים, וגם אין אנו מגביהין צדדי הטלית מזה ומזה על הכתפיים, אלא עוטפים הראש והכתפיים עד סוף הגב או כמחציתו, וכל ארבעת הכנפות והציציות משתלשלות לפנים. והעוטפים רק סביב ראשם וצווארם, בלא מקצת גופם, צריך למחות בהם. כי עיקר העטיפה, היא בגוף."],["s","(שע\"ה ח\"א סי' ח' סי\"ז)"],["t","כשכמה בני אדם מקיימים מצווה כאחד?"],["b","שניים או שלושה ויותר העומדים להתעטף כאחת, עדיף שאחד יברך בקול רם, ויכוון להוציאם ידי חובתם, וגם הם יתכוונו לצאת ידי חובה. משום \"ברוב עם הדרת מלך\". וכשמסיים הברכה, יענו אמן, ויתעטפו. וכן הוא המנהג."],["b","והוא הדין בכל כיוצא בזה, כגון ברכת הלל, לולב, ספירת העומר, וברכת הלבנה. (שם סי\"ח)"]]},{"h":"ל' מרחשון יום שלישי א' דראש חודש","s":"הלכות ציצית","d":["לעילוי נשמת בעלי היקר והאהוב רענן בן שלום | ברכה והצלחה לבנימין בן שלום"],"b":[["t","כיצד ננהג, אם יש שליחי ציבור שלא מכוונים להוציא ידי חובה?"],["b","בזמננו שיש שליחי ציבור שאינם בקיאים לכוון להוציא ידי חובה. או שבקיאים, אלא שבאותו רגע אינם נותנים לב לדבר. נראה שטוב שכל אחד יאמר עמו בלחש, ויסיים קודם לו שלוש תיבות, כדי שיוכל לענות אמן אחריו. (שע\"ה ח\"א סי' ח' סי\"ח)"],["t","האם חייבים בציצית בלילה?"],["b","ממתי שהגיע זמן של הלילה, פטור ממצוות ציצית (אף בבגד ד' כנפות המיוחד ליום), שנאמר \"וראיתם אותו\" דווקא בזמן ראייה. וביום שהוא זמן ראייה, חייב, גם בבגד המיוחד ללילה."],["b","ומכל מקום סדינים, אף על פי שאדם ישן בהם בבוקר, אין מטילין בהם ציצית דלא חייבה תורה רק דרך מלבוש, ולא דרך העלאה, או מצע מתחתיו."],["s","(שו\"ע סי' י\"ח סעיפים א' ב', כדעת הרמב\"ם. שע\"ה סי' ח' סי\"ט)"]]},{"h":"א כסלו יום רביעי ב' דראש חודש","s":"הלכות ציצית","d":["לעילוי נשמת שוקרי ידעי ז\"ל | לעילוי נשמת יוסף בן סאלם חג'בי"],"b":[["t","ממתי אפשר לברך על הציצית? ומה הדין לקשור הציציות בלילה?"],["b","לכתחילה יזהר שלא יברך עליו אף על פי שכבר עלה השחר, אלא עד שיהא כל כך יום, שיכיר בין תכלת ללבן. הלכך כשמתעטפים בטלית בלילה, כגון בלילי סליחות של חודש אלול, אין מברכין עליו, אלא עד שיגיע הזמן, שאז ממשמשין בידיהם בציציות ומברכין."],["b","ומכל מקום מותר לעשות בלילה חוטי ציצית ואף לקשרן. (שע\"ה סי' ח' סי\"ט)"],["t","האם מברכים שהחיינו על טלית חדשה?"],["b","מברכים שהחיינו על טלית או תפילין חדשים. ועל טלית קטן אין לברך שהחיינו. אלא אם כן עשאו מדבר חשוב שהוא שמח בו, יש מקום לברך שהחיינו. (שע\"ה סי' ח' סכ\"א)"]]},{"h":"ב' כסלו יום חמישי","s":"הלכות ציצית","d":["לעילוי נשמת דוד בן עובדיה ושושנה לוי ע\"ה"],"b":[["t","הפושט טליתו וחוזר ללובשה האם צריך לברך?"],["b","יש אומרים שהפושט טליתו ודעתו לחזור וללובשה מיד, עדיין ברכת הטלית שבירך בתחילה, חלה עליו, ולא צריך לחזור ולברך. ואפילו אם נכנס לבית הכסא, לא הוי הפסק, כיון שמצד הדין, מותר ליכנס בה לבית הכסא. אבל אם הסיר הטלית מעליו שלא על דעת להחזיר, צריך לחזור ולברך. ודעת השו\"ע שבכל אופן צריך לחזור ולברך. משום שמצווה הראשונה הלכה לה, ועכשיו מתחיל מצווה חדשה. וכן עיקר לדינא. ומי שרוצה להחמיר, יהרהר הברכה בלבו. (שו\"ע סי' ח' סי\"ד. שת\"ז בשם הלבוש. שע\"ה סי' ח' סכ\"ב. וכ\"כ בשם הגר\"י צוברי בס' פסקי הלכות עמ' כ')"],["t","נפלה טליתו שלא במתכוון האם יחזור לברך?"],["b","נפלה טליתו ממנו שלא במתכוון, אם מקצתה נשאר על גופו, אף על פי שרובה נפל, כיון שנשאר עליו קצת מן המצווה, אינו צריך לחזור ולברך כשמתקנה עליו. אבל אם לא נשאר כלום על גופו, הוי הפסקה ועיטוף חדש, ואינו המשך לעיטוף הראשון, וצריך לחזור ולברך (אף לדעה ראשונה שהבאנו בהלכה הקודמת, כיון שנפלה פתאום, בלא דעת להחזיר). (שו\"ע ס\"ח סט\"ו. מ\"ב שם ס\"ק מ\"א. שע\"ה ח\"א סי' ח' סכ\"ג)"]]},{"h":"ג' כסלו יום שישי","s":"הלכות ציצית","d":["לעילוי נשמת שולמית בת מנשה | זיווג הגון לאיילה בת שרונה"],"b":[["t","מה נחשב נפלה רובה, שלא חוזר ומברך?"],["b","מה שאמרנו שאם נפלה טליתו שלא במתכוון אם נפלה רובה, אינו צריך לחזור ולברך, הוא דווקא שאותו מקצת שלא נפל, נשאר מונח על גופו. אבל אם נשאר מונח על ידו, כיון שאין מצווה כלל בהנחתו על היד, שהרי עיקר העיטוף הוא בגוף, אם כן לא נשאר עליו מהמצווה כלום, ולכן כשחוזר ומתעטף בה, צריך לחזור ולברך. (מג\"א ס\"ק כ'. ר\"ז סכ\"ו. שע\"ה סי' ח' סכ\"ג)"],["t","מה הדין נפלה הטלית באמצע התפילה בזמן שאינו יכול להפסיק?"],["b","אם נפלה טליתו כולה מעל גופו כשהוא באמצע התפילה, במקום שאינו רשאי להפסיק, יתעטף בטלית בלא לברך, וכשיגיע למקום שיוכל לברך, ימשמש בידיו בציצית ויברך. (שע\"ה סי' ח' סכ\"ג)"]]},{"h":"ד' כסלו יום שבת פרשת תולדות","s":"הלכות ציצית","d":["לעילוי נשמת יהושע בן אהרון ושמעה גזי ז\"ל | רפואה שלימה והצלחה לפנינה בת רחמונה ג'מילה"],"b":[["t","האם מברך להתעטף בציצית מטלית הקהל שלוקח בבית הכנסת?"],["b","טלית הקהל הנמצאת בבית הכנסת, אפילו אינו נוטלה רק לעלות לתורה וכיוצא בזה, צריך לברך עליה, דהוי כשלו. (וטוב להתכוון בפירוש לשם מצוות ציצית, ולא מפני כבוד הציבור בלבד)."],["s","(שע\"ה סי' ח' סכ\"ה. וכ\"כ בשם הגר\"י צוברי בס' פסקי הלכות עמוד כ')"],["t","מה הדין אם נקרע אחד מהחוטים?"],["b","כתוב בתורה (דברים כב יב) \"גדילים תעשה לך על ארבע כנפות כסותך אשר תכסה בה\" ודרשינן בגמ' (מנחות ל\"ט:) גדיל, שניים (דאין גדיל פחות משניים). גדילים, ארבעה. פירוש; חייבה התורה ליתן בטלית ארבעה חוטים. כל חוט כפול לשנים, כל צד אחד של החוט נקרא ראש חוט. אם נפסק חוט אחד לגמרי, דהיינו משני ראשי החוט, פסול. (שו\"ע סי' יב ס\"א. שע\"ה סי' ח' סכ\"ו)"]]},{"h":"ה' כסלו יום ראשון","s":"הלכות ציצית","d":["לעילוי נשמת חממה בת גיאת ידעי ע\"ה | ברכה והצלחה בריאות איתי בן דורון"],"b":[["t","מה הדין אם לא נקרע החוט לגמרי?"],["b","מה שאמרנו שאם נפסק חוט אחד פסול, הוא דווקא שנחתך מעיקרו, דהיינו שנפסק משני ראשים שלו. אבל אם נשאר באחד הראשים כדי עניבה, והוא בערך אורך ארבעה סנטימטר של חוט משתלשל ויוצא מחוץ לקשרים והחוליות, כשר."],["s","(שע\"ה סי' ח' סכ\"ו. ועיני יצחק אות פ'. שכך המנהג כפי דעת רש\"י)"],["t","מה הדין נחתכו ארבעה ראשי חוטים?"],["b","מה שלמדנו, שצריך להיות ארבעה חוטין בכנף, נכפלים לשמונה ראשי חוטים, זהו דווקא שבא לכתחילה לעשות הציצית. אז חייב שיהיה ארבעה חוטין שלמים, אבל אם נחתכו לאחר מכן, אפילו אם נחתכו כל החוטין אם נשאר מכל חוט כדי עניבה, כשר. דהיינו אם ארבעה ראשים, נחתכו לגמרי עד הגדיל, וארבעה ראשים שכנגדם, נשאר כדי עניבה (ארבעה סנטימטר), כשר."],["s","(שו\"ע סי' יב ס\"א. שע\"ה סי' ח' סכ\"ו)"]]},{"h":"ו' כסלו יום שני","s":"הלכות ציצית","d":["לעילוי נשמת רפאל בן יהודה דנין ז\"ל"],"b":[["t","באיזה אופן בלבד אפשר להקל בזה?"],["b","כל ההיתר בנקרעו ארבעה חוטין, כשכנגדן הראש שני של החוט יש בו כדי עניבה, הוא דווקא אם דקדק בעת עשיית הציצית לתת סימן בארבעה ראשים, בענין שלעולם הארבעה ראשים הם מצד אחד של הקשר, והארבעה ראשים מצד האחר. רק אז, אם נפסקו מצד אחד, כשר. דוודאי נשתייר מכל אחד, הראש השני שהוא כדי עניבה. (שע\"ה סי' ח' סכ\"ו)"],["t","האם הדין הזה קיים גם לקשרים של מנהג התימנים?"],["b","אם לא דקדק שיהיו ראשי ארבעה החוטים מצד אחד, או לפי הנוהגים אצל התימנים שאין קשרים בין חוליא לחוליא, וכל ראשי החוטים מעורבים יחד, ולא ניתן להבחין על חוט, מה הם שני ראשים שלו. אפילו נחתך רק שני ראשי חוטים, פסול, שמא הוא מאותו חוט. וחוט שלם שנפסק פסול. אלא אם כן נשתייר באחד מהראשים כדי עניבה. (שו\"ע סי' יב ס\"א. שע\"ה סי' ח' סכ\"ו)"]]},{"h":"ז' כסלו יום שלישי","s":"הלכות ציצית","d":["רז בן אלדד ברכה והצלחה ברוחניות גשמיות ולימוד התורה"],"b":[["t","האם יש מקום להחמיר שלא להקל בארבעה ראשים חתוכים?"],["b","מה שאמרנו שאם נחתכו ארבעה ראשי חוטין מצד אחד, ונשאר מצד שני של החוט כדי עניבה, כך הוא עיקר הדין. אבל דעת רבינו תם, ששני חוטין שלמים (דהיינו ארבעה ראשים) בתוך כל כנף, חייבים לעולם להיות שלמים, דהיינו שכל אחד מהראשים ארוך י\"ב גודלים (24 סנטימטר), אז מכשירים כשנפסקו השני חוטין אחרים - אם נשתייר בהם כדי עניבה. וטוב לחוש לדעת רבינו תם במקום שאפשר. (שע\"ה סי' ח' סכ\"ו)"],["t","מה הדין נקרע החוט במקום הקשירה שלו בכנף?"],["b","אם נפסק חוט אחד במקום שהם תלויים בנקב, פסול. משום שחסר חוט אחד בשלמותו שאינו תלוי בכנף. (שע\"ה סי' ח' סכ\"ו)"]]},{"h":"ח' כסלו יום רביעי","s":"הלכות ציצית","d":["לעילוי נשמת שמחה בת שלום"],"b":[["t","האם לכתחילה אפשר להקל לקשור חוטים שאינם ארוכים י\"ב גודלים בכנף?"],["b","זה שאמרנו שאם נפסק חוט אחד ונשאר ממנו כדי עניבה כשר, זהו דווקא, אם בשעת עשייה היו כל החוטין ארוכים כשיעור, אלא שאחר כך נפסקו. אבל אם בשעת עשייה, היה אפילו רק חוט אחד קצר משהו מן השיעור, יש אומרים שפסול. ויש אומרים שרק לכתחילה אסור להניחו בבגד. (שע\"ה סי' ח' סכ\"ז)"],["t","מה הדין חוטין שנתפרדו משזירתם?"],["b","החוטים צריכים להיות שזורין משני חוטין לכל הפחות, ובדרך כלל עושים מארבעה, ויש מהדרין משמונה – למצווה מן המובחר. ואם איזה חוט נפרד משזירתו לגמרי (כלומר בלתי שזור אפילו לשניים), אזי כל הפרוד נחשב כאלו נחתך ואיננו. לפיכך נוהגים לעשות קשר בסוף כל חוט, כדי שיעמוד בשזירתו. (שע\"ה סי' ח' סכ\"ח)"]]},{"h":"ט' כסלו יום חמישי","s":"הלכות ציצית","d":[],"b":[["t","מה הדין אם נקרע הנקב שבכנף הטלית, ונפלה הציצית בשלמותה?"],["b","אם הייתה הציצית עשויה כתקנה על הנקב שבכנף הטלית, ונקרע הטלית מן הנקב ועד סופו, ונפלה הציצית, ורוצה להחזירה למקומה, ולתפור את הטלית עד הנקב, פסול משום שנאמר \"גדילים תעשה לך\" ודרשינן \"תעשה, ולא מן העשוי\". אלא יתיר את הציצית, ויחזור ויקשור כהלכה. (שע\"ה סי' ח' ס\"ז)"],["t","מה הדין אם נקרע ונפרד כל הכנף מהטלית?"],["b","אם נחתך או נקרע הכנף, ונפרד לגמרי מן הטלית, ואין בחתיכה זו שלוש אצבעות על שלוש אצבעות (שש על שש סנטימטר), יש אומרים שחתיכה זו אפילו לאחר שתפרה היטב אל הטלית, פסולה מלהטיל בה ציצית, דכיון שאין בה שלוש על שלוש אצבעות, אין עליה שם בגד, ואפילו אם נתחברה עם הטלית נחשבת כפרודה. וראוי להחמיר כן. (שע\"ה סי' ח' סכ\"ט)"]]},{"h":"י' כסלו יום שישי","s":"הלכות ציצית","d":["לעילוי נשמת שלום בן רנייה (רינה)"],"b":[["t","מה הדין אם לא נקרע לגמרי, אלא נשאר מעט מחובר?"],["b","אם לא נקרע ונפרד הכנף לגמרי, אלא נשאר מחובר מעט, מועילה התפירה שתהא נחשבת בכלל הטלית, והציצית שיטיל בה אחר התפירה, כשר."],["b","ונוהגין לתפור חתיכת בגד בכנפי הטלית כדי לחזקו. (שע\"ה סי' ח' סכ\"ט)"],["t","באיזה חוטים מותר לתפור במקום שטח כנף הטלית?"],["b","יש אומרים שבכל השטח של הכנף (בערך כ-שש סנטימטר משפת הבגד), לא יהיה שם חוט תפור (כגון באימרא שעושים סביב הנקב לחזקו, או שמחליפים עטרה). שהיה ראוי לעשות ממין החוט הזה ציצית. כגון אם הטלית של צמר, שלא יתפור שם בחוטי צמר, רק בחוטי משי וכדומה. ואם הטלית מכותנה, לא יתפור שם בחוטי כותנה (עיין לעיל בתאריך יט כ' מרחשון. באיזה מין חוטין, לאיזה סוג בגד, מועיל לעשות ציצית). ודווקא בחוט לבן, אבל בחוט צבוע, אין לחוש. (שם ס\"ל)"]]},{"h":"יא כסלו יום שבת פרשת ויצא","s":"הלכות ציצית","d":["לעילוי נשמת שלום בן מארי חיים גראפי | ברכה והצלחה ורפוא\"ש לשרה בת יחיא מהצרי הלוי | ברכה והצלחה שחר בן אופיר"],"b":[["t","האם מותר להסיר הציציות מהטלית?"],["b","אם רוצה להסיר ציציות מן הטלית כדי לתלות בה ציציות אחרות יותר יפות, אף על פי שגם הראשונות עדיין כשרות, מותר. והוא הדין שמותר להתיר ציציות מטלית הזאת, כדי ליתנם בטלית אחרת. אבל שלא להניחם בבגד אחר, לא. והטעם משום שהוא מבטל מצות ציצית מטלית זו:"],["s","(שו\"ע סי' ט\"ו ס\"א. מג\"א סק\"א. שע\"ה סי' ח' סל\"א)"],["t","יזהר בביזיון הציציות"],["b","כשמחליף ציציות יפות יותר מהראשונות, יש אומרים שאין לנתקם באופן שיתקלקלו, אלא אם כן קשה בעיניו הטרחה. ויזהר שלא להשליך את הראשונות למקום ביזיון. ואפילו ציציות שנפסלו, לא יזרקן לאשפה, משום ביזוי מצווה. והמנהג לגנזם. (שע\"ה שם וסל\"ב)"]]},{"h":"יב כסלו יום ראשון","s":"הלכות ציצית","d":["לעילוי נשמת שושנה (שמעה) בת סעיד ע\"ה | בריאות איתנה ושפע פרנסה ושמחה ליוסף בן סעדיה | ברכה והצלחה לכפיר בן שמשון | ברכה והצלחה דבורה בת אילנה"],"b":[["t","האם מותר ליכנס בטלית לבית הכסא?"],["b","מותר ליכנס בציצית לבית הכסא: ונכון לומר זה דווקא בטלית קטן, מפני שהוא בגד שהוא עשוי למלבוש. אבל בטליתות של מצוה שלנו, שהם מיוחדים רק לתפילה, ראוי שלא יכנס לבית הכסא."],["b","טלית קטן מעיקר הדין מותר ללבוש על בשר גופו ממש, וטוב להחמיר. (שו\"ע סי כ\"א ס\"ג. ט\"ז סק\"ג. שע\"ה סי' ח' סל\"ג)"],["t","האם יש עניין לעשות עטרה לנוי לצד הראש?"],["b","יש אומרים שראוי לעשות היכר איזה ציציות לפנים ואיזה לאחור שלא יתחלפו. ועל פי זה נתפשט המנהג לעשות עטרה לנוי בצד הראש. ויש חולקים."],["b","ועל כל פנים אם נתעטף בטלית כשהעטרה כלפי הקרקע, ראוי להעלותה. (שע\"ה שם סל\"ה)"]]},{"h":"יג כסלו יום שני","s":"הלכות ציצית","d":[],"b":[["t","אדם הלובש בגד ארבע כנפות בלא ציצית"],["b","הלובש בגד שהוא חייב בציצית, בלא ציצית, הרי זה ביטל מצוות עשה. וגדול עונש המבטל מצוות ציצית. והזהיר במצוה זו, זוכה ורואה פני השכינה."],["s","(שע\"ה סי' ח' סל\"ז)"],["t","בגד ארבע כנפות שרוצה לפטור אותו מציצית, כיצד יעשה?"],["b","בגדים שיש להם ארבע כנפות, אם רוצה לפטור אותן מציצית, צריך לחתוך מהן קרן אחת שתהא עגולה."],["b","אם כפל את הקרן ותפר אותה באופן שנראית עגולה, לא מהני, דכל מה שלא חתכו, עדיין בכלל הבגד הוא."],["b","אמנם לא יבקש תחבולות ליפטר מהמצווה, אלא אם כן, גם בלא הבגד הזה, הוא מקיים מצות ציצית שלובש טלית קטן. (שם)"]]},{"h":"יד כסלו יום שלישי","s":"הלכות עשיית מלאכת בערב שבת","d":["לעילוי נשמת אסתר בת יסים עודד | לעילוי נשמת רומיה בת סאלם ענאקי"],"b":[["t","האם מותר לעשות מלאכה בערב שבת לאחר זמן מנחה?"],["b","אסרו חכמים לעשות מלאכה בערב שבת ויום טוב מזמן מנחה קטנה ולמעלה. דהיינו שתי שעות זמניות ומחצה לפני הלילה, (ויש מחמירים בזה ממנחה גדולה, דהיינו חמש שעות זמניות ומחצה לפני הלילה). וכל העושה מלאכה, אינו רואה סימן ברכה. (שו\"ע סי' רנ\"א ס\"א. ר\"ז ס\"א. שע\"ה סי נ\"ד ס\"י)"],["t","מה הדין אם עושה מלאכה בחינם, ולצורך שבת?"],["b","במה דברים אמורים; דווקא בעושה מלאכה לקבל שכר, או מלאכה שאינה לצורך השבת. אבל מלאכה שאינו מקבל שכר, וגם היא לצורך השבת, מותר לעשות מלאכה גם לאחר זמן מנחה. ולכן מותר לתקן בגדים וכלים, בין שלו בין של חבירו, לצורך שבת ויום טוב, אם אינו לוקח שכר."],["s","(טור. ב\"י. שו\"ע. רמ\"א רנ\"א ס\"ב. שע\"ה שם)"]]},{"h":"טו כסלו יום רביעי","s":"הלכות עשיית מלאכת בערב שבת","d":["ברכה והצלחה וזיווג הגון לאילון בן עודד הלל"],"b":[["t","מה הדין במלאכת עראי?"],["b","מלאכה שאסרו, דווקא אם היא מלאכה קבועה לו לאחר זמן מנחה, אבל מלאכה שנזדמנה לו לפי שעה דרך עראי, מותר, אע\"פ שאינה לצורך שבת. לפיכך אם נזדמן לו לכתוב אגרת שלומים וכיוצא בזה, מותר. (רמ\"א ס\"ב. ר\"ז ס\"ד. שע\"ה סי' נ\"ד ס\"י)"],["t","מה הדין לכתוב חידושי תורה?"],["b","לכתוב לעצמו ספרים דרך לימודו, מותר. אפילו כותב בקביעות, ואפילו אינו צורך שבת, מפני שהוא דבר מצוה. (שו\"ע סי' רנ\"א ס\"ב. רמ\"א שם ס\"א. ר\"ז ס\"ג. כה\"ח סקט\"ז. ועיין מ\"ב סק\"ו. שע\"ה סי' נ\"ד ס\"י)"]]},{"h":"טז כסלו יום חמישי","s":"הלכות עשיית מלאכת בערב שבת","d":["לעילוי נשמת זקננו מארי עמרם חביב בן סעיד יחיא ז\"ל"],"b":[["t","האם מותר להתעסק במלאכת התספורת לאחר זמן מנחה?"],["b","מותר לספר יהודי כל היום, אפילו מעשה אומן, ואפילו בשכר. ואינו דומה לתפירת בגדים ושאר מלאכות שאין הדבר ניכר שהמלאכה נעשית עכשיו בשביל השבת. אבל התספורת ניכרת שנעשית עכשיו בשביל השבת. (ב\"י בשם הכל בו. רמ\"א ס\"ב. מג\"א סק\"ה. ר\"ז ס\"ד. שע\"ה סי' נ\"ד ס\"י)"],["t","האם צריך לסגור את החנויות מזמן מנחה?"],["b","כל מה שאסרו חכמים, הוא דווקא מלאכה גמורה, אבל מקח וממכר בחנויות (הנקרא בלשון חז\"ל פרקמטיא), מותר אף לאחר זמן מנחה. ויש לסגור את החנויות עד שעה אחת לפני השבת. (ר\"ז סי' רנ\"א ס\"ג. וסי' רנ\"ו. שע\"ה סי' נ\"ד ס\"י)"]]},{"h":"יז כסלו יום שישי","s":"הלכות חנוכה","d":["לעילוי נשמת זוהרה בת יחיא סאלם ע\"ה | לעילוי נשמת יוסף בן מנשה ז\"ל | לעילוי נשמת יחיא בן יחיא | ברכה והצלחה לאורטל בת זהבה ומשפחתה"],"b":[["t","היכן נרמזו ימי החנוכה בתורה?"],["b","רמז לחנוכה מן התורה, שכתוב אחר כל המועדות בפרשת אמור, \"ויקחו אליך שמן זית זך כתית למאור להעלות נר תמיד\". ומתוך שכתב אותו עם המועדות, למדנו שהוא יום טוב כשאר ימים טובים. (מחזור ויטרי)"],["b","ואין כוונתו שהם כימים טובים שאסורים במלאכה, אלא כעין ימים טובים, ולומר הלל באותם ימים כמותם. (נפלאות מתורתך, פרשת אמור, נדפס בהקדמה לפסקי מהרי\"ץ על הלכות חנוכה)"],["t","כיצד נוכל לקבוע בלב בני המשפחה את מהותם של ימי החנוכה?"],["b","יש שנהגו לקרוא את מגילת בני חשמונאי שנתחברה על ידי הקדמונים [יש אומרים על ידי החשמונאים בעצמם. ויש אומרים על ידי זקני בית הלל ובית שמאי] כדי לפרסם הנס בישראל. ומה טוב לקרוא אותה ביחד עם הביאורים ומדרשי חז\"ל בחבורת בני הבית אחרי ההדלקה. (ש\"ע המקוצר סימן ק\"כ סעיף ל\"ו, ועיני יצחק ס\"ק ע\"ד)"]]},{"h":"יח כסלו יום שבת פרשת וישלח","s":"הלכות חנוכה","d":["לעילוי נשמת שמחה בת מחם כוכבי ע\"ה"],"b":[["t","האם ראוי לצאת לטיולים וכיוצא בזה בחנוכה?"],["b","החיד\"א הזהיר שלא להוציא את ימי החנוכה בשחוק וליצנות, כי אלו ימים שנועדו להודות ולהלל בהם, ואיך יחטא ואשם, רחמנא ליצלן. (מורה באצבע אות ש\"ג)."],["t","לשם מה ימי החנוכה נועדו?"],["b","כתב השל\"ה הקדוש שימי החנוכה ראויים ומסוגלים להתמדת התורה יותר משאר הימים. גם החתם סופר הקפיד בימים אלו שלא לבטל רגע מלימודו, משום שבהם נמסרו סודות התורה למשה רבינו עליו השלום. (פוסקים. מורה באצבע אות ש\"ג. ילקוט יוסף חנוכה דף נ\"ה)"]]},{"h":"יט כסלו יום ראשון","s":"הלכות חנוכה","d":["להצלחה בצניעות ובקדושה ומידות טובות לתמר בן דקל"],"b":[["t","האם גם העניים חייבים בהדלקת נר חנוכה?"],["b","אפילו עני המתפרנס מן הצדקה, שואל או מוכר כסותו ולוקח שמן להדליק. ואם יש לו כדי להדליק בכל לילה נר אחד, הרי הוא כבר לא צריך להשאיל או להשכיר את כסותו."],["s","(עץ חיים למהרי\"ץ, נדפס בפסקי מהרי\"ץ על הלכות חנוכה דף ח')"],["t","באיזה גובה צריכים להעמיד את הנרות?"],["b","מצוה להניחם למעלה משלושה טפחים מן הקרקע. ודעת מרן השלחן ערוך שמצוה להניחם למטה מעשרה טפחים, ואם הניחם למעלה מעשרה יצא. אבל לדעת הרי\"ף והרמב\"ם ועוד ראשונים מצוותם לכתחילה בין בתוך עשרה ובין למעלה מעשרה. וכן הוא מנהגינו. אך אם הניחם למעלה מעשרים אמה לא יצא, מפני שלמעלה מעשרים אין העין שולטת. (עץ חיים למהרי\"ץ, הובא בפסקי מהרי\"ץ דף י', וע\"ש בבארות שלמה. ש\"ע המקוצר סימן ק\"כ סעיף ט')"]]},{"h":"כ' כסלו יום שני","s":"הלכות חנוכה","d":["לעילוי נשמת לאה שרים בת מורי יצחק אברהם ע\"ה | ברכה והצלחה ליסכה בת יואב"],"b":[["t","מתי זמן ההדלקה?"],["b","זמן הדלקת החנוכה עם סוף שקיעת החמה, דהיינו כמה דקות לפני צאת הכוכבים, לא מאחרין ולא מקדימין. (עץ חיים למהרי\"ץ, הובא בפסקי מהרי\"ץ דף י\"ד, ובארות שלמה שם. ש\"ע המקוצר סימן ק\"כ סעיף י\"א)"],["t","כיצד דין ההדלקה בבית הכנסת?"],["b","משום פרסום הנס, תיקנו חז\"ל להדליק נרות חנוכה בבית הכנסת ולברך עליהם, וכן מנהג כל ישראל. וכיון שמתפללים ערבית בצאת הכוכבים, צריכים להדליק את הנרות קודם ערבית. ומניחין אותן בכותל דרום, ומסדרין אותן שם בין מזרח למערב. ואין אדם יוצא ידי חובתו בנרות בית הכנסת."],["b","(עץ חיים למהרי\"ץ, הובא בפסקי מהרי\"ץ דף י\"ב, ובארות שלמה שם ס\"ק ל\"ב – ל\"ד. ש\"ע המקוצר סימן ק\"כ סעיף ט\"ז, וע\"ש בהערה ל\"ח שמברכים את כל הברכות בבית הכנסת ממש כמו בהדלקה שבבית)"]]},{"h":"כא כסלו יום שלישי","s":"הלכות חנוכה","d":["ברכה והצלחה לביא בן ליאל ועדוה בידני"],"b":[["t","מה דין הסעודות בחנוכה, וכיצד צריכים לשמוח?"],["b","ריבוי הסעודות בימי החנוכה הם סעודות הרשות, שלא קבעום לימי משתה ושמחה [בשונה מיום פורים]. ואם אומרים בהם שירות ותושבחות, נחשבים לסעודת מצוה. אולם יש ליתן לב שהשמחה תהיה מעורבת ובלולה בשמחת תורה בלי ביטול מקביעות הלימוד. ובעוונותינו הרבים יש אנשים שתחת זמירות ותושבחות, מרבים במשחקי קלפים וכיו\"ב, והרבה הרעישו בספרים הקדושים על זה."],["b","האם סעודות שבת שחלה להיות בחנוכה הן כמו סעודות שבת רגילות?"],["b","יש אומרים כי בשבת חנוכה ראוי להוסיף איזה מאכל מיוחד לכבוד החנוכה. וכל שכן אם ראש חודש טבת, חל בשבת. [יש להעיר כי בשנה זו ה'תשפ\"ז, חלים שתי שבתות בימי החנוכה]. (ש\"ע סימן עת\"ר סעיף ב', וביאור הלכה ד\"ה ונוהגין. בן איש חי פרשת וישב אות כ\"ח. ש\"ע המקוצר סימן ק\"כ סעיף ב')"]]},{"h":"כב כסלו יום רביעי","s":"הלכות חנוכה","d":["לעילוי נשמת יוסף בן לולווה","כמוהר\"ר חיים כסאר זצוק\"ל תשנ\"ח - ר\"י בית אלשרעבי"],"b":[["t","מהו אופן ההדלקה למהדרין מן המהדרין?"],["b","מצות חנוכה מהדרין מן המהדרין. מנהגינו פשוט שבעל הבית לבדו מדליק בלילה הראשון נר אחד, ובלילה השני שני נרות, וכן מוסיף והולך בכל יום ויום. בין שהיו אנשי הבית מרובים או מועטים. ואין לשנות. ואם בני הבית רוצים להשתתף, יכול להביא להם את הדלקת ה\"שמש\". וכן פשט המנהג בכל תפוצות ספרד. ומנהג אשכנז שכל אחד מבני הבית מדליק נרות חנוכה לבדו בברכה. (רמב\"ם פ\"ד מהלכות חנוכה. ש\"ע סימן תרע\"א. ש\"ע המקוצר סימן ק\"כ סעיף ז', ועיני יצחק הערה י\"ז)"],["t","כיצד ינהג מי שטעה והדליק נרות יותר מהחיוב?"],["b","מי שטעה והדליק בלילה הראשון יותר מנר אחד (לבד מהשמש) או בלילה השני יותר משני נרות, יש אומרים כי הוא לא יצא ידי חובה, משום שהוא מזיק לשיעור המכוון, ועפ\"י הוראתם אפשר שהוא צריך לכבות את כל הנרות ולחזור ולהדליק בברכה. אך העיקר לדינא שבדיעבד יצא. ויש להורות לו לכבות את הנר המיותר, ולא לברך שוב. (מהר\"ש קלוגר שו\"ת האלף לך שלמה או\"ח סימן ש\"פ. שו\"ת להורות נתן ח\"ב סימן נ\"א. תשובות והנהגות ח\"א סימן שצ\"ג. פניני חנוכה דף ל\"ה בשם הגרי\"ש אלישיב. ילקוט יוסף חנוכה דף קל\"ד. דעת מרן שליט\"א)"]]},{"h":"כג כסלו יום חמישי","s":"הלכות חנוכה","d":["לעילוי נשמת מלכה בת מורי יחיאל תשעה ע\"ה | ברכה והצלחה יאיר בן לירן","כמוהר\"ר חיים סעיד דמתי תרע\"ז - חבר ביה\"ד ירושלים"],"b":[["t","איזה מנורה ראוי לקנות לימי החנוכה?"],["b","ראוי שתהיה לו מנורה נאה של מיני מתכות או זכוכית וכיו\"ב. ומי שידו משגת, יקנה מנורה של כסף להידור מצוה. ובדרך כלל יש עדיפות למנורה הדורה ונאה על פני מנורה עתיקה, אך באופן שהיא הייתה שייכת בעבר לאדם גדול וצדיק, הרי היא עדיפה על החדשה, אלא אם כן היא כבר נראית בלתי מכובדת."],["b","יש ענין מסויים להדר שהבזיכים יהיו אף הם מכסף."],["s","(ש\"ע המקוצר סימן ק\"כ סעיף ו'. קובץ דברי חפץ חלק י\"ח, ע\"ש בארוכה. שמעתי בע\"פ)"],["t","האם יש ענין שרק נר אחד יהיה מכסף"],["b","מי שתשיג ידו, ראוי לו להתנאות לפני המקום במצוות, שידליק במנורת כסף. ובספר סדר היום כתוב שיהדר בנר אחד כסף לכל הפחות. (בארות שלמה אות י\"ז, דף ו')"]]},{"h":"כד כסלו יום שישי ערב חנוכה מדליקין בלילה נר ראשון","s":"הלכות חנוכה","d":["שלום בית הצלחה ופרנסה עדי בת רוחמה"],"b":[["t","מה הדין בעלייה לקבר ולימוד ביום השנה (יארצייט) ובימי השבעה והשלושים?"],["b","אם חל יום פקודת השנה(\"יארצייט\") בימי החנוכה, יכולים לעלות לקבר הנפטר ולערוך אצלו את סדר הלימוד כרגיל, רק יזהרו שסדר הלימוד והדרשות יהיו באופן שלא יבואו לידי בכי. אך אם יש חשש שיבואו לידי בכי, יש להקדים או לאחר את העלייה לקבר. העליה לקבר בסיום ימי השבעה והשלושים אסורה בחנוכה מכיון שיש חשש גדול שיבואו לידי בכי. אך יכולים לעשות סעודה ולימוד עם אמירת דברי תורה לעילוי נשמת המנוח בלי אמירת דברי הספד כנ\"ל."],["t","האם אפשר לעלות להתפלל על קברי צדיקים בחנוכה?"],["b","עלייה לקברי צדיקים מותרת לגמרי, משום שאין רגילות לבכות שם. (שמעתי ממרן שליט\"א. וכן הוא בחזון עובדיה דף י\"ד. ילקוט יוסף חנוכה דף ס\"א וס\"ג)"]]},{"h":"כה כסלו יום שבת פרשת וישב","s":"הלכות חנוכה","d":["בריאות איתנה ולב שמח אברהם בן ישראל | אורך ימים ושנות חיים לר' שלום בן שלמה קרואני"],"b":[["t","האם מותר לחמם סופגניה על הפלאטה בשבת"],["b","סופגנייה שנקנית מהמאפיות המצויות היום, אסור להניחה על הפלאטה במקום שה\"ריבה\" יכולה להתחמם בשיעור שהיד סולדת בה, משום שהאופים רגילים לערב בתוך הריבה מים שלא התבשלו."],["t","האם מותר להניח סופגניה על הפלאטה רק כדי שתפשיר?"],["b","מי שמפריע לו שהסופגניה או הריבה שבתוכה יתחממו כל כך, והוא מניח את הסופגניה על הפלאטה רק כדי שתפשיר מעט, ומשגיח ליטלה משם קודם שתתחמם יותר, יכול להקל בזה. (בנין משה ח\"ג פרק ל' סעיף ט\"ו, יעו\"ש באורך)"]]},{"h":"כו כסלו יום ראשון","s":"הלכות חנוכה","d":[],"b":[["t","מהי ברכת הסופגניות?"],["b","ברכת הסופגניות המטוגנות בשמן, בתחילה בורא מיני מזונות, ולבסוף על המחיה. ואפילו באופן שקבע סעודתו עליהם, כיון שהטיגון מוציאן מתורת לחם כמו הבישול. אולם באופן שהכניסום לאחר הטיגון לאפייה קלה במשך כרבע שעה (כמו שעושים בחלק מהמאפיות, משום שהדבר מועיל להקפאה), מכיון שטעם השמן לא נרגש כבתחילה, יש בהם משום קביעות סעודה."],["s","(ש\"ע המקוצר סימן ק\"כ סעיף כ\"ד. שמעתי ממרן שליט\"א)"],["t","מה דין טיגון סופגניות על ידי גויים"],["b","יש אומרים כי סופגניות שהושלכו לטיגון בשמן עמוק ע\"י גוים במקומות שהבעלים הם יהודים [כמו שהוא בדרך כלל] הרי הן מותרות באכילה מעיקר הדין, ואין בהם איסור בישולי גויים. ומכל מקום יש להיזהר שהישראל ידליק את האש. ודעת מרן הגר\"י רצאבי שליט\"א שראוי להחמיר בזה, אף אם הישראל ידליק את האש. אך אם הן היו אפויות בתחילתן, יש יותר מקום להקל. [כל זה הוא רק מדין בישולי גויים, אך הנוהגים להיזהר תמיד מלאכול אפילו פת שנאפתה על ידי הגוי, יש מקום להחמיר ולהיזהר גם מאכילת סופגניות אלו]."],["s","(עיין בהרחבה בשערי יצחק מקץ ה'תש\"ע, ובילקוט יוסף חנוכה דף ע')"]]},{"h":"כז כסלו יום שני","s":"הלכות חנוכה","d":["שלום בית הצלחה ופרנסה מתתיהו בן יעקב | להצלחה ורפוא\"ש וחז\"ב לאלקנה בן דקל | לרפואה, הצלחה שלום בית עוזי בן רחל וליטל בת אפרת"],"b":[["t","כיצד מניחים את הנרות?"],["b","הנרות יהיו בשורה אחת בשווה, לא אחד נכנס ואחד יוצא, ולא אחד גבוה ואחד נמוך. ויהיה הפסק (כשני סנטימטר) בין נר לנר, שלא יתקרב הלהב של זה לזה ויהיו כמו מדורה. ובנרות של שעוה, יהיה הפסק, שלא יתחממו זה מזה ותיטוף השעוה ויתקלקלו."],["s","(ש\"ע המקוצר סימן ק\"כ סעיף י')"],["t","האם אמירת הספד וצידוק הדין מותרים בחנוכה?"],["b","אין מספידין בימי החנוכה, זולתי לתלמיד חכם בפניו [ולפי דעת חכמי תימן, גם בזמן הזה יש דין תלמיד חכם]. אבל היום שלפני חנוכה והיום שלאחר החנוכה מותרים בהספד. צידוק הדין [= הצור תמים פעלו וגו', אהוב ירחמו וגו', צור ממעונו וגו'] לעומת זאת אינו נחשב להספד, ומותר בימי החנוכה. (בית יוסף יו\"ד סימן ת\"כ, מהרי\"ץ בשו\"ת פעולת צדיק ח\"ג סימן כ\"ז. ש\"ע המקוצר סימן ק\"כ סעיף ג', ועוד)"]]},{"h":"כח כסלו יום שלישי","s":"הלכות חנוכה","d":[],"b":[["t","כיצד זוכים לבנים תלמידי חכמים?"],["b","אמרו חז\"ל, הרגיל (ויש גורסים הזהיר) בנר, הויין ליה [=יהיו לו] בנים תלמידי חכמים. ופירש רש\"י, שאמרו כן על נר חנוכה ובנר שבת. ונאמרו כמה פירושים על איזו זהירות מדובר. יש אומרים שצריך להיזהר בהם בהידור ובדרך חיבוב. ויש אומרים שהזהירות היא להדליקם בזמן, וכפי כללי ההלכה בלי פשרות. ויש אומרים שהזהירות היא להדליק יותר מן החיוב. ויש אומרים שהזהירות היא להדליק את הנרות בכלי נאה. וראוי להיזהר בכל עניינים אלו."],["b","(מסכת שבת דף כ\"ג ע\"ב, חידושי המאירי שם, ב\"ח בסימן רס\"ג, שתילי זיתים סימן תרע\"א סק\"א בשם הלבוש, פתח עיניים להחיד\"א בשבת שם, פלא יועץ ערך נר, ילקוט יוסף דף פ\"ז, משנה ברורה מהדורת דרשו ריש סימן תרע\"א. ועיין שערי יצחק תרומה ה'תשע\"ט)"],["t","האם המדליק במקום שהרוח מצויה יצא ידי חובה?"],["b","אדם שהעמיד את הנרות במקום שהרוח מצויה והנרות עומדין להיכבות, לא קיים את המצוה, וחייב לחזור ולהדליקן שנית, אבל לא יברך. אמנם אם העמידן כראוי ועל ידי מקרה כבו, כבר קיים המצוה ואינו מחוייב לחזור ולהדליקן. ומכל מקום ראוי לעשות כן."],["s","(ש\"ע המקוצר סימן ק\"כ סעיף י\"ד)"]]},{"h":"כט כסלו יום רביעי ערב ראש חודש","s":"הלכות חנוכה","d":["ואל בן סעדיה שרים ז\"ל נלב\"ע כ\"ט חשוון תשפ\"ה"],"b":[["t","האם מותר ליהנות מאור הנרות?"],["b","אסור ליהנות מאור נרות חנוכה כל זמן מצוותן, דהיינו חצי שעה, בין מהנרות שבבית ובין מהנרות שבבית הכנסת. לכן נוהגים להניח אצלן נר נוסף, כדי שאם ישתמש אצלן, ישתמש לאור השמש. וצריך להניח את השמש קצת למעלה מן הנרות, שיהא ניכר שאינו ממנין הנרות. (ש\"ע המקוצר סימן ק\"כ סעיף ט\"ו)"],["t","מדוע טוב להרבות בצדקה בחנוכה?"],["b","טוב להרבות בצדקה בימי חנוכה, כי נתינת הצדקה לעניים בימים האלו, מסוגלת ביותר לתקן את פגמי הנפש. יש להקפיד בייחוד להחזיק את לומדי התורה יותר מעניים רגילים. לכן אף מי שיש לו עני הקרוב ללבו או שהוא ממשפחתו אך אינו בן תורה, עדיף יותר שיתרום לאחרים שהם לומדי תורה. אבל אם התרומה לאותו העני תוכל לסייע לו להוסיף שעות לימוד, עדיף שיתן לו. (ש\"ע המקוצר, סימן ק\"כ סעיף ב', שמעתי בע\"פ)"]]},{"h":"ל' כסלו יום חמישי א' דראש חודש","s":"הלכות חנוכה","d":["לעילוי נשמת שרה בת סלימאן ג'ובאני"],"b":[["t","היכן נהגו לתת \"דמי חנוכה\"?"],["b","בענין מעות חנוכה לילדים שהוא מנהג בני שאר קהילות, ידוע שלא נהגו כן בקהילות תימן. ויש לחוש בזה קצת משום מנהג שמקורו מאומות העולם. גם מבחינה חינוכית יש לדון ולבחון האם הוא דבר ראוי או שאינו ראוי. כיצד ראוי לנהוג בענין זה?"],["b","הטוב ביותר הוא להעניק לילדים מתנות או מעות לפי שכלם בשמחה ובטוב לבב מתוך השתתפות בשמחת החנוכה, לא לשם דמי חנוכה, אלא בשביל להרבות אהבה ושמחה, ובשביל לחבב עליהם את הלימוד."]]},{"h":"א' טבת יום שישי ב' דראש חודש","s":"הלכות חנוכה","d":["אורי בן תומר עוזירי ברכה והצלחה קדושה ובריאות | ברכה והצלחה ורפואה שלימה לברכה בת סאלם"],"b":[["t","האם מותר להתענות בחנוכה?"],["b","ימי החנוכה אסורים בתענית. ומסתבר שאף תענית שעות אסורה. ומשום כן, מי שחושש שיתאחר מלאכול את ארוחת הבוקר שלו עד לאחר חצות, הרי הוא חייב לטעום משהו מקודם, ומספיק אפילו לשתות. ובערב חנוכה ובמוצאי חנוכה אין איסור להתענות. האם מותר לחתן להתענות בערב חופתו שחלה להיות בחנוכה?"],["b","יש בקהילותינו מקומות שנהגו שהחתן [ולא הכלה] מתענה בערב חופתו, ונאמרו על כך כמה טעמים. ומכל מקום אם החתונה חלה בימי החנוכה, אין לו להתענות בערב החתונה. (ש\"ע סימן עת\"ר. הגהת הרמ\"א סימן תקע\"ג סעיף א'. כף החיים סימן תי\"ח סק\"ג חולק ומתיר להתענות שעות. אור לציון ח\"ג פ\"א שאלה א'. אשרי האיש ח\"ג פרק מ' אות א'. ש\"ע המקוצר סימן ק\"כ סעיף ג', וסימן ר\"ו סעיף י\"ט, יעו\"ש כמה טעמים)"]]},{"h":"ב' טבת יום שבת פרשת מקץ. זאת חנוכה","s":"הלכות חנוכה","d":["לעילוי נשמת יחיא בן נסים גרמה | לעילוי נשמת אלכסנדר בן יעקב ז\"ל | לעילוי נשמת מרים בת דוד ימיני ע\"ה"],"b":[["t","כיצד ינהג מי שאין לו שמן כשיעור?"],["b","מי שעומד ביום השני או השלישי ואין לו מספיק שמן בכדי לתת לכל הנרות כדי שיעור חצי שעה, יתן בנר אחד שמן כשיעור, ואת המותר יחלק שוה בשוה לשאר הנרות. (מגן אברהם סימן תרע\"א, משנה ברורה שם ס\"ק ו')"],["t","באיזה אופנים אסור להדליק נרות מנר חנוכה?"],["b","השמש דינו כנר של חול, ולכן אסור להדליקו מאחד מנרות החנוכה אפילו בלא נר אמצעי. נכון להחמיר: א. שלא להדליק נר שבת מנר חנוכה. ב. שלא להדליק נר לצורך תלמוד תורה או חולה מנר חנוכה. ג. שלא להדליק נר הבדלה מנר חנוכה. (סימן תרע\"ד סעיפים א' וב' ואחרונים שם. תורת המועדים סימן ו' סעיף מ\"ב. מועדי ה' דף ו')"]]},{"h":"ג' טבת יום ראשון","s":"הלכות רחיצה בשבת","d":[],"b":[["t","האם יש הבדל בין מים שהוחמו קודם שבת למים שהוחמו בשבת"],["b","מים שהוחמו בשבת, אסור לרחוץ בהם אפילו פניו ידיו ורגליו, ואפילו אבר אחד מאברי הגוף אסור. ויש אומרים שאיסור זה, הוא אפילו על מים שהוחמו בשבת בדרך היתר, כגון שחיממם ישראל מעט בשיעור שאין היד סולדת בהם, או שחימם הגוי לצורך עצמו ואין ישראל מכירו. ובמקום הדחק יש להקל אם הוחמו בשבת בהיתר. (בנין משה פנ\"א ס\"ד)"],["t","האם מותר לרחוץ בשבת במים פושרים"],["b","איסור רחיצה במים חמים בשבת, הוא אפילו כשהמים חמים קצת. שכל שהגוף נהנה מחמימותם, הרי הם בכלל חמים ואסור. והשיעור של חום שמותר לרחוץ במים הוא לערך עד 35 מעלות, שבשיעור כזה אין הגוף נהנה מחום המים. (בנין משה פנ\"א ס\"ה)"]]},{"h":"ד' טבת יום שני","s":"הלכות רחיצה בשבת","d":["ברכה והצלחה לטליה בת גלעד"],"b":[["t","האם מותר לנגב את השיער במגבת?"],["b","כשמתרחץ במים שאינם חמים צריך ליזהר שלא לסחוט שערו, כגון הראש והזקן והפיאות והשפם, לפי שאסור לסחוט את השיער בשבת. אמנם יכול הוא לנגב את השיער במגבת בנחת לאט לאט, (בדרך קינוח, בלא ללחוץ על השערות). (שע\"ה סי' סט ס\"ג)"],["t","האם מותר לטבול במקוה חם בשבת?"],["b","מותר לטבול מטומאתו את כל גופו בצונן, ואין זה נחשב מתקן. והמקילים לטבול אף במקוה חם, יש להם על מה שיסמוכו. ובפרט מי שצריך טבילה. (שם סעיף ד')"]]},{"h":"ה' טבת יום שלישי","s":"הלכות רחיצה בשבת","d":["לעילוי נשמת יהודה בן צאלח כהן | ברכה והצלחה לחגי בן אברהם ומשפחתו"],"b":[["t","האם מותר להתרחץ בסבון?"],["b","יש אוסרים רחיצה בסבון, אלא אם כן הוא נוזל. ויש מתירים (וסוברים שאין זה נחשב ממרח, כיון שאין הכוונה להחליק ולמרח את הסבון וכו'. וגם דעתם שאין בזה משום נולד.) וכן הוא המנהג. ומקרוב יש שנהגו להחמיר. (שע\"ה סי' סט ס\"ו)"],["t","האם מותר להשתמש במגבות נייר בשבת?"],["b","מותר לנגב את גופו, או את ידיו, ב\"מגבת נייר\" (נייר סופג וכדו'). אף על פי שעלולה להיקרע. וכן מותר לקנח את האף בנייר. (שע\"ה סי' סט ס\"ח)"]]},{"h":"ו' טבת יום רביעי","s":"הלכות שבת מלאכת חורש","d":[],"b":[["t","האם מותר לגרור כלים על קרקע בשבת?"],["b","מותר לגרור כלים על קרקע בשבת, אם אין זה ודאי שיעשו חריץ. ואם עשו חריץ, אינו חושש, לפי שלא נתכוין לזה. אבל כלי גדול שודאי יעשה חריץ, אסור אפי' שאינו מכוין לחריץ. (וזהו הנקרא בלשון רבותינו פסיק רישיה). (בנין משה פ\"ב סעיף ה')"],["t","האם מותר להסיע עגלת ילדים בעפר?"],["b","עגלת ילדים גם אם היא גדולה מאוד מותר להסיעה בדרך עפר אפילו שבוודאי תעשה חריץ בקרקע הואיל ואין הגלגלים חופרים אלא כובשים את העפר ואין בכך משום חורש. (בנין משה פ\"ב סעיף ו')"]]},{"h":"ז' טבת יום חמישי","s":"הלכות שבת מלאכת חורש","d":["ברכה והצלחה לרות בת אחינועם | ברכה והצלחה ובריאות איתנה לשמעון בן שלום"],"b":[["t","האם מותר לחיגר או זקן ללכת במקל על עפר בשבת?"],["b","נחלקו הפוסקים בדבר זה אם הוא במקום שודאי יעשה גומא ולכן יש ליזהר בזה. (שם ח') ולילך במנעלים שיש להם עקב על עפר באופן שבוודאי הוא עושה בהם חריץ תוך כדי הילוכו, אפשר להקל במקום צורך, כיון שנעשה כלאחר יד בדרך הילוכו ובלא כוונה כלל."],["s","(בנין משה פ\"ב סעיף ט')"],["t","האם מותר לשחק בארגז חול בשבת?"],["b","ארגז חול המוכן לילדים לשחק בו שהחול שם דק ויבש. אף על פי שמיד שלוקח חול, נופל תחתיו חול מן הצדדים, מותר לשחק בו, ואין איסור עשיית גומא בחול ועפר שכזה. ואין בו איסור מוקצה, משום שמוכן הוא מבעוד יום. (שם י')"]]},{"h":"ח' טבת יום שישי","s":"הלכות שבת מלאכת חורש","d":["לעילוי נשמת יפת (חסן) בן דוד סעיד ז\"ל | ברכה והצלחה לסימה שמחה בת יצחק | ברכה והצלחה למירב בת ארז"],"b":[["t","האם מותר לנעוץ חפץ בעפר בשבת?"],["b","אסור לתחוב יתד וכדומה בתוך עפר מפני שעושה גומא. אבל לשלוף דבר התחוב בקרקע, מותר, אע\"פ שנעשית גומא הואיל ונעשית ממילא. (בנין משה פ\"ב ד')"],["t","האם מותר להניח כסא או שולחן על עפר?"],["b","מותר להניח כסא או שולחן על עפר גם אם על ידי ישיבתו נכנסים רגלי הכסא בארץ ונעשית גומא, משום שנעשה כלאחר יד וגם לא מכוון לגומא. אבל לצדדם על הארץ כדי שיתיישבו בטוב, אסור, שמא ישווה גומות. (פ\"ג סעיף ד')"]]},{"h":"ט' טבת יום שבת פרשת ויגש","s":"הלכות ארבעה צומות","d":[],"b":[["t","מדוע צמים?"],["b","בעשירי בטבת סמך נבוכדנצאר הרשע על ירושלים והביאה במצור ובמצוק ומזה נמשך החרבן עד יז' בתמוז וט' באב. ולכן חובה עלינו לעורר הלבבות ולפתוח דרכי התשובה ויהיה זה זכרון למעשינו הרעים וכל אדם חייב לשום אל ליבו באותם ימים לפשפש במעשיו כי אין עיקר התענית אלא התשובה, ולכן אותם אנשים שכשמתענים הולכים לטייל ומבלים כל היום בדברים בטלים תפסו את הטפל והניחו את העיקר. (סימן ק\"ב ס\"א)"],["t","דין מעוברות ומניקות בשאר צומות"],["b","מעוברות ומניקות פטורות מן התענית ואפילו שלא מצטערות פטורות מהתענית ואינן צריכות לפרוע ביום אחר [ואם רוצה להחמיר על עצמה ומרגישה שהיא בריאה ואין שום חשש נזק יכולה להחמיר על עצמה]. (סימן ק\"ב ס\"ז)"]]},{"h":"י' טבת יום ראשון. צום עשירי בטבת","s":"הלכות ארבעה צומות","d":["ברכה והצלחה לאלישבע בת אחינעם | ברכה והצלחה מנחם בן כפיר | ברכה והצלחה עובדיה יוסף בן לירן | ברכה והצלחה לאה בת דניאל"],"b":[["t","גדר מעוברות ומניקות"],["b","מעוברת שאמרנו זה דווקא אחר שמלאו לה שלשה חודשים מההריון. ואם מרגישה צער אפילו אחר ארבעים יום מתחילת ההריון, יכולה לאכול. ובפחות מזה, הרי היא כשאר נשים. אלא אם כן מצטערת מאוד או מרגישה חולשה וחשה בגופה סחרחורת, חוסר דם (מוגלובין 10 ומטה), דפיקות לב, לחץ דם גבוה או נמוך, בכל המצבים הללו אין לצום. ומניקה שאמרנו שפטורה, זה דווקא מניקה בפועל. (סימן ק\"ב ס\"ח)"],["t","אם בירך ונזכר שהיום תענית"],["b","מי שלקח בטעות מאכל או משקה ובירך עליו ונזכר שתענית היום יטעם מעט ולא יבלע אלא יפלוט מיד כדי שלא תהא ברכתו לבטלה. (עולת יצחק ח\"ג ר\"ה)"]]},{"h":"יא טבת יום שני","s":"הלכות שבת מלאכת חורש","d":["לעילוי נשמת שלום בן עואץ וזוהרה בן צור ז\"ל | לעילוי נשמת רות כהן בת יפת ותמר | ברכה והצלחה לזהר בת אליהו | לרפואת יורם בן יעקב זינר | ברכה והצלחה ליהודית בת אחינועם"],"b":[["t","האם מותר לטאטא קרקע בשבת?"],["b","אסור לטאטא קרקע שאינה מרוצפת בשבת שמא ישווה גומות. אבל קרקע מרוצפת מותר. ואין חילוק בין בבית ובין בחצר. ומותר לומר לגוי לטאטא קרקע שאינה מרוצפת. (בנין משה פ\"ג שם י')"],["t","האם מותר לשטוף בית בשבת?"],["b","אסור לשטוף בית אפי' מרוצף, ואין להקל בזה גם במקום דוחק, כגון שהבית מלוכלך או בתי חולים. ובמקום דוחק וצורך גדול מותר ע\"י גוי. (שם יא')"]]},{"h":"יב טבת יום שלישי","s":"הלכות שבת מלאכת חורש","d":["לעילוי נשמת כאדיה בת פנחס"],"b":[["t","באיזה אופן מותר להדיח את הרצפה בשבת?"],["b","אם נשפך שמן על הרצפה, ויש חשש שיחליקו בו בני אדם, מותר לשטוף את הרצפה. וכן אם ישנו לכלוך, כגון קיא וכדומה, מותר לשפוך מים על אותו לכלוך, ולגורפו במגב גומי בלי סמרטוט. (בנין משה פ\"ב יב')"],["t","האם מותר להדיח שיש מטבח?"],["b","מותר להדיח שיש במטבח וכן שולחן, וכן אסלה, ואפי' שמחוברים לקרקע שלא אסרו חכמים אלא הדחת קרקע בלבד. (שם יד')"]]},{"h":"יג טבת יום רביעי","s":"הלכות שבת מלאכת זורע","d":["ברכה והצלחה לישי בן גלעד"],"b":[["t","האם מותר להשליך גרעיני פירות בקרקע בשבת?"],["b","יש ליזהר שלא להשליך גרעיני פירות בקרקע לחה משום שסופם להצמיח. ואם זורקם במקום שאין סופם להצמיח כגון בקרקע יבשה ולא עומדת להשקיה וכן מקום הילוך בני אדם, מותר. (פ\"ד ג')"],["t","דבר שלא יצמיח בשבת האם מותר להשליכו בקרקע?"],["b","האיסור להשליך גרעינים בקרקע בשבת זה גם אם הם לא צומחים בשבת משום שעיקר מלאכת זורע היא נתינת הזרע בקרקע אבל מותר לתת זרע בקרקע קודם השבת אפי' שיודע שיתחיל להשריש בשבת. (שם ה')"]]},{"h":"יד טבת יום חמישי","s":"הלכות שבת מלאכת זורע","d":["לעילוי נשמת שושנה עומסי בת ר' סעדיה האם מותר לרחוץ ידיו על עשבים בשבת?"],"b":[["b","האוכלים בגינות אסור להם ליטול ידיהם על עשבים או במקום שנטועים אילנות שהרי מים אלו מועילים לגדלם."],["b","ואם אין נראים שם עשבים ואין ידוע לו על זרעים הטמונים בקרקע מותר אם אינו מכוין להשקות."],["s","(בנ\"מ פ\"ד סעיף ז')"],["t","האם מותר לשתות מברז בגינה בשבת?"],["b","אם האדמה שתחת הברז רטובה ושבעה ממים שנשפכו שם קודם אין לחוש לתוספת מים אלו שאינם מועילים להצמיח ומותר. (שם סעיף ט')"]]},{"h":"טו טבת יום שישי","s":"הלכות שבת מלאכת זורע","d":["ברכה והצלחה לדוד בן אלדד","כמוהר\"ר נחשון נחשון זצוק\"ל - תשנ\"ג מחכמי ראצבה"],"b":[["t","האם מותר לפתוח כיור שנשפכים מימיו על עשבים בשבת?"],["b","כיור שמימיו יורדים דרך צינור על קרקע החצר מותר להשתמש בו בשבת ואפי' שהמים נשפכים על עשבים. והטעם שמותר, משום שהעשבים שתו כבר הרבה מים מהכיור ביום חול. ועוד שאינו מכוון להשקותם. ועוד שזה אינו מכוחו, אלא גרמא. מהכיור לצינור, ומהצינור לעשבים. ומ\"מ טוב להמנע מזה. (בנ\"מ פ\"ד סעיף יב')"],["t","מה הדין בכיור שנעשה להשקות?"],["b","כיור שנעשה להשקות צמחים שבחצר אין להשתמש בו כלל בשבת כיון שנעשה לכך בכוונה ובאופן קבוע."],["s","(בנ\"מ פ\"ד סעיף יד')"]]},{"h":"טז טבת יום שבת פרשת ויחי","s":"הלכות שבת מלאכת זורע","d":["לעילוי נשמת מרים בת מנשה"],"b":[["t","האם מותר לפתוח ממטרות מערב שבת שישקו בשבת?"],["b","מותר לפתוח מערב שבת צינורות השקיה והם משקים את הגינה בשבת וכן מותר לסוגרן בשבת ועדיף לסגור את הברז הראשי שסוגר את כולם שלא יתחזק הזרם במקום אחד. וכן מותר לכוון שעון שיפעיל את מערכת ההשקיה בשבת. כיון שהיום ידוע שזה אוטומטי ואין בעיה של מראית עין. (בנין משה סעיף טו')"],["t","האם מותר להטיל מי רגלים על עשבים בשבת?"],["b","מותר להטיל מי רגלים על עשבים בשבת משום שמי רגלים עזים ושורפים את העשבים ומונעים אותם מלצמוח. (שם פ\"ד סעיף יא')"]]},{"h":"יז טבת יום ראשון","s":"הלכות שבת מלאכת זורע","d":["לעילוי נשמת רחמים בן יחיא סעיד ענקי"],"b":[["t","מה הדין להניח גרעין אבוקדו במים בשבת?"],["b","אסור להניח בשבת גרעין אבוקדו בתוך כלי עם מים כדי שיצמיח שם משום זורע, וכן כל כיוצא בזה. ואם נתנו קודם השבת והשריש, אסור להוציאו מן המים, מדרבנן, כמו שתולש מעציץ שאינו נקוב."],["s","(בנין משה פרק ד' סעיף יז')"],["t","מה הדין לשרות פירות יבשים במים?"],["b","מותר לשרות פירות יבשים במים כדי שיתרככו ויהיו ראויים לאכילה וכן מותר לשרות פירות וירקות תלושים במים בשבת כדי שלא יכמושו ואין בפעולות אלו איסור משום כובש כבשים. (בנ\"מ פ\"ד סעיף יח')"]]},{"h":"יח טבת יום שני","s":"הלכות שבת מלאכת זורע","d":["לעילוי נשמת זהור בת מוסא ימיני ז\"ל | בו\"ה ברוחניות וגשמיות צניעות וקדושה מיתר בת תומר עוזירי","הרה\"ג שמעון בעדני זצוק\"ל חבר מועצחה\"ת"],"b":[["t","האם מותר להעמיד בשמים בכלי עם מים בשבת?"],["b","מותר להעמיד בשבת ענפי בשמים לריח או לנוי בתוך כלי שיש בו מים כדי שלא יכמושו ומותר ליתן גם בשבת מים בכלי או להחליף את המים. ואע\"פ שיש שהחמירו בדבר, העיקר להלכה שמותר. וכן המנהג. (בנין משה פ\"ד סעיף יט')"],["t","האם מותר להעמיד פרחים הנפתחים במים בשבת?"],["b","פרחים ושושנים וכל כיוצא בזה שבנתינתם למים הפרחים נפתחים מותר להעמידם במים בשבת וכן נוטלים ומחזירים אותם למים הואיל ואין מצמיחים דבר חדש שלא היה מקודם. (שם כ')"]]},{"h":"יט טבת יום שלישי","s":"הלכות שבת מלאכת זורע","d":[],"b":[["t","מה הדין להעמיד בשמים שמשרישים במים בשבת?"],["b","אם נותן את הבשמים כדי שישרישו שם חייב משום זורע ואף אם אינם משרישים בשבת אלא לאחר כמה ימים כגון הריחאן שמצוי שמשריש במים אסור."],["s","(בנין משה פ\"ד סעיף כא')"],["t","אם אינו מכוין להשריש האם חייב להוציאם קודם שישרישו?"],["b","לכתחילה ראוי להוציאם במוצאי שבת ולהחזירם למים ומי שמעמידם במים באופן שלא יוציאם אין למחות בידו אם אינו מכוין להשריש. (שם)"]]},{"h":"כ' טבת יום רביעי","s":"הלכות שבת מלאכת זורע","d":["ברכה והצלחה לתהילה בת יואב"],"b":[["t","מה הדין לפתוח או לסגור חלון בשבת בבית שיש בו עציץ?"],["b","מותר לפתוח חלון בבית שיש בו צמחים אע\"פ שהשמש והאויר מועיל לגידולם, כיון שאין זו תועלת ניכרת וכן אין זה דרך מלאכת זריעה ובלבד שלא יכוין לזה. וכן מותר לסגור חלון אפי' אם מתכוין להגן על הצמחים מפני הקור וכדומה כיון שאין כאן אלא מניעת נזק."],["s","(בנין משה פ\"ד סעיף כו')"],["t","מה הדין מי שזרע בשבת באיסור?"],["b","מי שזרע או נטע בשבת באיסור בין בשוגג בין במזיד צריך לעקור הנטיעה במוצאי שבת משום קנס. (שם כז')"]]},{"h":"כא טבת יום חמישי","s":"הלכות שבת מלאכת זורע","d":["לעילוי נשמת אליהו בן יפת"],"b":[["t","האם מותר ללכת על עשבים בשבת?"],["b","מותר ללכת וכן לרוץ על עשבים בשבת בין ארוכים בין קצרים ואפי' הולך בלא מנעלים ונכנסים בין קשרי אצבעותיו ונתלשים ובלבד שלא יתכוין לתולשם. (בנין משה פ\"ה סעיף יא')"],["t","אם נתלשו ונדבקו ברגליו איך יסירם?"],["b","אם נדבקו עשבים ברגליו או במנעליו לא יסירם בידיו משום מוקצה אלא יסירם ע\"י דבר אחר שטלטול מן הצד שלא לצורך המוקצה מותר. (שם)"]]},{"h":"כב טבת יום שישי","s":"הלכות שבת מלאכת זורע","d":["לעילוי נשמת נעמה דהרי בת סליאמן עדווי ז\"ל"],"b":[["t","האם מותר לטלטל עציץ נקוב בשבת?"],["b","עציץ נקוב המונח על הארץ אסור לטלטלו מפני שיונק מן הקרקע והמגביהו הרי זה כעין תולש, וכן אם היה מונח על שולחן אסור להניחו על הקרקע משום זורע. ואם מונח על דבר שמפסיק מותר להעבירו על דבר מפסיק אחר רק לא יעבירנו באויר מעל הארץ. (בנין משה פ\"ו סעיף ג')"],["t","מה הדין לטלטל עציץ נקוב המונח על הרצפה בבית?"],["b","גם דרך רצפת אבנים, בלטות, קרמיקה, בטון, עוברת יניקת העציץ ולכן אסור להגביהו מן הארץ אם אין כלי חוצץ אבל בבתים שבקומות מעל קומת קרקע מותר להגביהו. (שם סעיף ד')"]]},{"h":"כג טבת יום שבת פרשת שמות","s":"דיני השתמשות באילן בשבת","d":["אריה בן ניסים עוזירי התעלות בקדושה נחת ופרנסה ברווח"],"b":[["t","מה הדין השתמשות באילן בשבת?"],["b","התולש בשבת מן המחובר חייב משום קוצר. לפיכך אין עולים באילן בשבת גזירה שמא יעלה ויתלוש עלים וכדומה ואפי' לעלות מבעוד יום כדי לשבת שם כל השבת אסור וכן אסור לסמוך עצמו על האילן בשבת וכן לא יניח חפץ על האילן בשבת, וכן לא יקשור בהמה לאילן שאין משתמשין באילן כלל בשבת."],["s","(בנין משה פ\"ז סעיף א')"],["t","מה הדין באילן יבש?"],["b","אסור להשתמש ולעלות באילן כלל בין לח בין יבש ואפי' נתייבש לגמרי שאין בו שום לחלוחית ואפי' אין בו עלים כלל, משום גדר וסייג שלא לחלק בין אילן לאילן. (שם סעיף ב')"]]},{"h":"כד טבת יום ראשון","s":"דיני השתמשות באילן בשבת","d":["כמוהר\"ר סאלם צאלח זצוק\"ל תרצ\"ד מרבני צנעא - ירושלים","הרה\"ג עזריה בסיס זצוק\"ל - רב העיר רה\"ע"],"b":[["t","מה הדין להשתמש בשבת בנדנדה הקשורה באילן?"],["b","כשם שאסור להשתמש באילן כך אסור להשתמש בצדדי האילן כגון דבר המחובר לאילן אבל בצידי צדדים מותר ולכן אם הנדנדה קשורה לאילן אסור להשתמש בה משום שזה צדדי האילן אבל אם הנדנדה קשורה ליתד התקוע באילן מותר להשתמש בה משום שזה צידי צדדים ובלבד שלא יתנדנד האילן. (בנין משה פ\"ז ס\"ו)"],["t","מה הדין בסל או מגבת התלויים באילן?"],["b","סל או מגבת התלויין באילן אסור להשתמש בהם על פי המבואר בהלכה הקודמת אבל אם תלוין על יתד התקוע בעץ מותר להשתמש בהם לנגב בהם ידים או להניח חפץ בסל, ובלבד שלא יורידם מהיתד. (שם)"]]},{"h":"כה טבת יום שני","s":"דיני השתמשות באילן בשבת","d":["לשמירה הצלחה ובריאות לאושר בן עזרא דחיאני"],"b":[["t","מה הדין להישען על אילן בשבת?"],["b","ליגע באילן בלא להשתמש בו, מותר, ובלבד שלא ינידנו. ולהישען עליו (מבלי שינידנו), אם הוא אדם בריא ונשען קצת, הרי זה כנגיעה ומותר, ובלבד שלא יסמוך עליו בכל כוחו שזה נחשב כמשתמש. (בנין משה פ\"ז ס\"י)"],["t","מה הדין לישב על גזע נמוך?"],["b","כל הסמוך לקרקע בתוך ג' טפחים חשיב כקרקע לכן אין איסור להשתמש באילן בג' טפחים הסמוכים לקרקע וכן גזע החתוך בתוך ג' טפחים ושורשים היוצאים מהאילן מותר לשבת עליהם בשבת. (בנין משה פ\"ז ס\"ג)"]]},{"h":"כו טבת יום שלישי","s":"דיני השתמשות באילן בשבת","d":["לעילוי נשמת אבי מורי ישראל בן יוסף שיבה סיאני זצ\"ל נלב\"ע | לעילוי נשמת אמי מורתי שרה בת זכריה וגזל | לעילוי נשמת סאלם בן יעיש ידעי"],"b":[["t","מה הדין להריח בשבת בשמים המחוברים לעץ?"],["b","לא אסרו חכמים להשתמש במחובר בשבת כי אם באילן שאפשר לעלות עליו אבל קנים הרכים אפי' גבוהים יותר מג' טפחים מותר להשתמש בהם ובלבד שלא יתלוש, ולכן מותר לתפוש בידיו הדס, ריחאן, וכדומה המחוברים לעץ כדי להריחם וגם אין בהם משום מוקצה משום שמוכנים לכך. (בנין משה פ\"ז סעיף יד')"],["t","מה הדין להריח פירות המחוברים בשבת?"],["b","כל דבר הראוי לאכילה כגון אתרוג או תפוח אסור להריח בו בעודו מחובר ואפי' שרק מתקרב אליו להריחו ואינו תופסו בידו גזירה שמא ישכח ששבת ויקוץ אותו לאוכלו. (שם סעיף יט')"]]},{"h":"כז טבת יום רביעי","s":"הלכות שבת מלאכת דש","d":["לעילוי נשמת ינאי בן ליאור ורעות אילו"],"b":[["t","האם מותר לסחוט פירות בשבת?"],["b","הסוחט זיתים וענבים בשבת אם היה במשקים שסחט שיעור גרוגרת (18 סמ\"ק) חייב חטאת משום מפרק שהוא תולדה דדש. מהתורה אסור רק בזיתים וענבים, וחכמים אסרו גם תותים ורימונים משום שהדרך לסוחטם."],["b","והיום שהדרך בעולם לסחוט למשקה כמעט את כל סוגי הפירות והירקות אין היתר לסחוט כמעט שום פרי כדי לשתות מימיו. (בנין משה פ\"י סעיף ב')"],["t","מה הדין בפירות מבושלים?"],["b","פירות וירקות מבושלים שרוצה לסוחטם אם סוחטם לתועלת הפרי ואינו צריך את מימיהם אלא לתקן את הפרי לאכילה מותר לסוחטו אפי' לא לאיבוד אלא לקערה ריקה ואם סוחטם לצורך מימיהם אסור."],["s","(שם פ\"י סעיף ג')."]]},{"h":"כח טבת יום חמישי","s":"הלכות שבת מלאכת דש","d":[],"b":[["t","האם מותר לסחוט בשבת כובאנה מהשמן שבה?"],["b","פת השרויה במשקים דהיינו במרק, יין, וכדומה וכן אוכלים המטוגנים בשמן או ברוטב כגון כובאנה, ג'חנון, חצילים וכדומה אם סוחטם כדי להשתמש בנוזל היוצא מהם אסור, אבל אם סוחטם כדי לתקנם לאכילה מותר. (בנין משה פ\"י ס\"ד)"],["t","האם מותר לסחוט פרי שלא לצורך מימיו?"],["b","פירות וירקות חיים שאינם מבושלים או כבושים מותר לסוחטם אם אינו מכוין לצורך מימיהם אלא לצורך גוף הפרי כדי למתקו ודין זה מותר בכל הפירות חוץ מזיתים וענבים שאסור לסוחטם אפי' למיתוק הפרי. (שם סעיף ה')"]]},{"h":"כט טבת יום שישי ערב ראש חודש","s":"הלכות שבת מלאכת דש","d":["ברכה והצלחה לשירה בת אלדד"],"b":[["t","מה הדין לסחוט לימון בשבת?"],["b","בזמנינו שיש רגילות לסחוט לימון לשם משקה ולא רק לאכילה ראוי להחמיר שלא לסחוט בין לתוך כלי ריק בין לתוך משקה לתת בו טעם כגון תה מרק וכדו' ובשעת הדחק או לצורך רפואה המיקל לסחוט לכלי ריק או למשקה יש לו על מה לסמוך."],["s","(בנין משה פ\"י סעיף יב')"],["t","מה הדין לסחוט לימון על חילבה?"],["b","מותר לסחוט לימון על אוכל כגון ירקות, חילבה, סחוק, טחינה וכדומה ובלבד שלא ניגרים כמשקה, שמשקה הבא לאוכל נחשב כאוכל ולכן אין על מיץ הלימון שם של משקה. (שם סעיף יג')"]]},{"h":"א' שבט יום שבת פרשת וארא ראש חודש","s":"הלכות שבת מלאכת דש","d":[],"b":[["t","האם מותר לסחוט לימון על סוכר בשבת?"],["b","לסחוט לימון על סוכר ואח\"כ ליתן עליהם מים אפשר להקל שנחשב כמו שסוחט לימון על אוכל שמותר ואפי' שהסוכר נהפך למשקה והמחמיר תבוא עליו ברכה. (בנין משה פ\"י סעיף יד')"],["t","מה הדין ליתן חתיכת לימון לכוס תה?"],["b","מותר לחתוך מהלימון וליתנו בשבת בכוס תה חם (בכלי שני שאינו מבשל) והוא מוציא טעמו למשקה ואין זה נחשב שסוחטו. ואם רוצה ללוחצו בכפית יש מקום להקל במקום צורך והמחמיר תבוא עליו ברכה. (שם סעיף טו')"]]},{"h":"ב' שבט יום ראשון","s":"הלכות שבת מלאכת דש","d":[],"b":[["t","מה הדין לחתוך פירות בשבת ויוצא מהם מיץ?"],["b","מותר לחתוך פירות בסכין בצלחת ואפי' שזב מהם משקים כיון שאינו מתכוין לכך וגם אין דרך סחיטה בכך וכן מותר לשתות את המיץ שנשאר בצלחת."],["s","(בנין משה פ\"י סעיף טז')"],["t","מה הדין לאכול אשכולית בכף?"],["b","מותר לאכול אשכולית בכף אפי' שהפרי נסחט תוך כדי אכילתו כיון שאינו מתכוין לסוחטו למשקה וכך היא דרך אכילה, אבל לדחוק כף באשכולית כדי להוציא ממנה משקה אסור. וכן מותר לסחוט פרי בשבת לאחר שסחטוהו קודם השבת ועכשיו רק מוציא ממנו את תמצית המיץ שבו. (שם יז', יח')"]]},{"h":"ג' שבט יום שני","s":"הלכות שבת מלאכת דש","d":["לעילוי נשמת עודד בן ר' סאלם הלל | ברכה והצלחה לאמיתי בן ארז"],"b":[["t","מה הדין משקים שזבו בשבת?"],["b","פירות שזבו מהם משקים מעצמם בשבת אם זיתים וענבים הם, אסור לשתותם עד מוצאי שבת גזירה שמא יסחוט אותם בידים, ושאר פירות אם עומדים לאכילה משקה שזב מהם מותר ואם עומדים לסחיטה אסורים. וכל המשקים שאסורים בשתיה, אסורים גם בטלטול, משום מוקצה מחמת גופו. (בנין משה פרק י' סעיף כג')"],["t","מה הדין משקים שזבו מפירות מרוסקים?"],["b","כל סוגי הפירות שנתרסקו קודם השבת משקים היוצאים מהם בשבת מותרים והמחתך סלט פירות בשבת ומתקבץ מיץ בתחתית הקערה מותר לשתותו בשבת ומותר לחתוך בסלט גם ענבים שהמיץ הזב מהם מתערב עם שאר פירות. (שם כו')"]]},{"h":"ד' שבט יום שלישי","s":"הלכות שבת מלאכת דש","d":["לעילוי נשמת ר' ישראל אבוחצירא הבבא סאלי זצ\"ל | לעילוי נשמת יחיא דהרי בן אהרון ז\"ל"],"b":[["t","דין ריסוק שלג ברד וקרח בשבת"],["b","אין מרסקים בשבת שלג או ברד או קרח כדי שיזובו מימיהם אבל ליתן לתוך כוס משקה כדי לצננה והוא נימוח מאליו מותר וכן אם הניחו קוביות קרח בצלוחית וזב מהם מים מותר לשתותם. (בנין משה פרק יב' סעי' א' ב')"],["t","האם מותר להניחם סמוך לאש כדי להפשירם?"],["b","מותר להניח שלג או קרח במקום חם כגון בחמה או סמוך לאש כדי שיפשירו ואין על המשקים היוצאים מהם איסור נולד משום שגם בעודם קרושים שם משקה עליהם. והוא הדין במרק קפוא או שומן קרוש שמותר להניחם על האש שיפשירו במקום שאין חשש משום איסור מבשל (חום שהיד סולדת בו). (שם סעיף ג')"]]},{"h":"ה' שבט יום רביעי","s":"הלכות שבת מלאכת דש","d":["לעילוי נשמת מאיר בן סימי מרגי ז״ל"],"b":[["t","מה הדין לבחוש בשבת בכוס משקה שיש בה קוביות קרח?"],["b","מותר לנענע את הכוס שיש בה קוביות קרח, וכן לבחוש בכף קטנה כדי שהקרח ילך ויימס מהר. ובלבד שלא ירסק אותו בכף ממש. וכן מותר ליתן קוביות קרח בכוס ריקנית וליתן עליהם משקה ואין לחוש שבנתינת המים ממיס את הקרח. (בנין משה פ' יב' סעיפים ד', יב')"],["t","מה הדין לנענע בשבת בקבוק קפוא?"],["b","בקבוק שתיה קפוא אין לנענע את הבקבוק מצד לצד או להכות עליו כדי שיתרסק המשקה שבתוכו משום שזהו בכלל מרסק בידיים וראוי להחמיר גם אם מקצתו קפוא ומקצתו אינו קפוא. (שם סעי' ה')"]]},{"h":"ו' שבט יום חמישי","s":"הלכות שבת מלאכת דש","d":["לעילוי נשמת רבקה טאג'י בת ברוריה | ברכה והצלחה לדבורה בת יונה","המקובל כמוהר\"ר ישי שרעבי זצוק\"ל - רב שכונת מרמורק רחובות"],"b":[["t","מה הדין לשבר חתיכות מן הקרח בשבת?"],["b","מותר לשבר חתיכות מהקרח כדי ליתנם בתוך משקה אפי' שחלק מהקרח מתרסק אין לחוש לזה שלא אסרו אלא במרסק כדי שיזובו מימיו ועוד שאינו מכוין לכך ועוד שהם הולכים לאיבוד. (בנין משה פ' יב' סעי' ז')"],["t","מה הדין לשפוך מים על פי בקבוק קפוא?"],["b","בקבוק שנעשה קרח סביבות פי הבקבוק מותר לשפוך עליו מים כדי שיתמוסס הקרח ויוכלו להוציא המשקים שבתוכו כיון שלא חשיב מרסק בידיים אלא כלאחר יד ועוד שהקרח הנופל מתערב עם המים ואינו ניכר."]]},{"h":"ז' שבט יום שישי","s":"הלכות שבת מלאכת דש","d":[],"b":[["t","מה הדין לרסק \"איגלו\" בפה בשבת?"],["b","מיני משקה קפואים בתוך שקית שקוראים \"איגלו\" וכדומה אם בעת אכילתם מרסקם כדי לאוכלם פתיתים לשם תענוג הרי זה מותר כיון שאינו מרסקם בשביל שיזובו מימיו ואדרבה רוצה לאוכלם בעודו קרח אבל אם מרסקו כדי שיזובו מימיו הרי זה אסור ולרסקו בפיו תוך כדי אכילתו מותר בכל אופן. (בנין משה פ' יב' סעיף יג')"],["t","מה הדין לשבר סחוק קפוא, חילבה וכדומה?"],["b","סחוק קפוא מותר לשברו לחתיכות כדי שיפשיר מהר ואינו דומה לשלג וברד שבשעה שמרסקים תיכף נעשה מים ממש וכן מותר ליתן סחוק, חילבה וכדומה קפואים בכלי עם מים ואפי' חמים כדי להפשירם משום שנימוח מאליו. (שם יד')"]]},{"h":"ח' שבט יום שבת פרשת בא","s":"הלכות מצוות מעקה","d":["לעילוי נשמת אפריים בן יצחק ואסתר לאון"],"b":[["t","מה פירוש מצות \"מעקה\"?"],["b","מצות עשה שיעשה האדם מעקה לגגו, שנאמר \"ועשית מעקה לגגך ולא תשים דמים בביתך כי יפול הנופל ממנו\" בין שהוא בנה את הבית בין אם קנה בית מוכן. אך כל זה רק בגג שמשתמשים בו, אבל גג שאין משתמשים בו כלל, או גג שהוא משופע ואי אפשר להשתמש בו, ורק לעתים רחוקות עולים עליו לזמן קצר, פטורים. (שע\"ה ח\"ח עמ' רכ' רכא')"],["t","איזה מעקה חייבה תורה?"],["b","גובה המעקה צריך להיות לא פחות מעשרה טפחים - 80 סנטימטר, ויהא חזק כדי שכשישען האדם עליו לא יפול המעקה, ולא די בשלוש רוחות אלא בכל ארבעת הרוחות צריך להיות מעקה. (שם)"]]},{"h":"ט' שבט יום ראשון","s":"הלכות מצוות מעקה","d":["שילה בן כפיר ברכה והצלחה | ברכה והצלחה לאפרת בת יעקב","המקובל כמוהר\"ר שלום שבזי זצוק\"ל"],"b":[["t","האם ישנו חיוב לעשות מעקה גם במדרגות?"],["b","לא רק הגג בלבד חייב במעקה, אלא כל דבר שיש בו סכנה שעלול אדם להיכשל בו ולמות חייב במעקה, כגון מי שיש לו בור בחצירו חייב לעשות לו גדר גבוהה עשרה טפחים או לשים כסוי שלא יפול בהם אדם. וכן חובה לעשות מעקה מימינם ומשמאלם של מדרגות שעולים ויורדים בהן וכדומה. וכל המניחן בלי מעקה ביטל מצות עשה ועבר על לא תעשה שנאמר \"ולא תשים דמים בביתך\". (שע\"ה ח\"ח עמ' רכב')"],["t","האם ומתי צריך לברך על עשיית מעקה?"],["b","קודם התחלת עשיית המעקה, יברך בא\"י אמ\"ה אשר קידשנו במצוותיו וציוונו לעשות מעקה, ולפי מנהגינו מוסיף לברך שהחיינו. ואם עושה מעקה לאחרים, יברך בנוסח \"על עשיית מעקה\" אך לא יברך אז שהחיינו. (שם עמ' רכג')"]]},{"h":"י' שבט יום שני","s":"הלכות מצוות מעקה","d":["לעילוי נשמת סעידה בת שמעה | לע״נ לאחותי גאולה בן דוד ז״ל בת שרה וסעדיה חתוכה | אפרת שושנה בת אבנר ברכה והצלחה ברוחניות וגשמיות ולזש\"ק","כמוהר\"ר שלום שרעבי זצוק\"ל - תקל\"ז"],"b":[["t","עד מתי אפשר לברך על מצוות מעקה?"],["b","מי שלא בירך בתחילת עשיית המעקה, יברך כל זמן שלא סיים לעשות גובה עשרה טפחים שאז נשלמה המצוה. (שע\"ה ח\"ח עמ' רכד' ד\"ה ואם)"],["t","האם יש לברך על מעקה שעושה הגוי?"],["b","גוי הבונה מעקה בשביל ישראל, נחלקו האחרונים אם בכל זאת יברך על הבית, מטעם, שאף על פי שאין שליחות בגוי להיות שליח לישראל, מכל מקום יד פועל כיד בעל הבית, ולכן אין לברך, משום דספק ברכות להקל. (שם עמ' רכה' ד\"ה גוי)"]]},{"h":"יא שבט יום שלישי","s":"הלכות מצוות מעקה","d":["לעילוי נשמת קמר בת סלימן מעטוף ז\"ל","כמוהר\"ר רצא מנגמי זצוק\"ל - תשל\"ז אב\"ד תעיז"],"b":[["t","האם אדם מחוייב להסיר כל מכשול?"],["b","כל מכשול שיש בו סכנת נפשות, כגון סולם רעוע העומד בביתו או בחצירו, וכן כלי נשק, או חלון ללא סורגים, או חוט חשמל גלוי, וכיוצא בזה, גם בזה יש מצות עשה להסירו ולהישמר ממנו ולהיזהר בדבר היטב, שנאמר \"השמר לך ושמור נפשך מאד\", ואם הניח ולא הסיר את המכשולים המביאים לידי סכנה, ביטל מצות עשה ועבר \"בלא תשים דמים\". (שע\"ה ח\"ח עמ' רכז')"],["b","אך על כל הדברים שנזכרו בסעיף הקודם, לא יברך עליהם כלל, משום שזה אינו בכלל עשה דמעקה אלא מצות עשה אחרת. (שם אות כ\"ד)"],["b","האם מותר לגדל כלב בבית?"],["b","אסור לגדל \"כלב רע\". וההגדרה לכלב רע; אם הוא נושך, או אפילו אם אינו נושך, אלא רק נובח, אסור לגדלו, מחשש שמא תפחד ממנו אשה מעוברת ותפיל. ואם ידוע שהוא קשור בשלשלאות של ברזל מותר. (שם עמ' רכז' רכח')"]]},{"h":"יב שבט יום רביעי","s":"הלכות סעודה","d":["לעילוי נשמת אביאל אברהם בן יהושע וגלית | ליהי בת טל חזרה בתשובה זיווג הגון","הרה\"ג עובדיה יעבץ זצוק\"ל - רב קרית עקרון"],"b":[["t","האם מותר ליתן מאכל למי שיודע בו שלא יטול ידיו ויברך?"],["b","מרן כתב בשו\"ע (סי' קס\"ט ס\"ב): \"לא יתן לאכול אלא למי שיודע בו שיברך\" (וכך הוא ברמ\"א סי' קס\"ג ס\"ב לעניין נט\"י)."],["b","אולם כתבו האחרונים אם האורח ייעלב או יפגע מכך, ומחמת כן יתכן שאף יתרחק יותר, עדיף לכבדו מאשר להימנע מכך, משום \"לפני עוור לא תתן מכשול\", שלא"],["b","תצא תקלה גדולה יותר חס ושלום. (שע\"ה ח\"א רמ\"ז ואות כ\"ב)"],["t","סעודה שאינה מספקת:"],["b","אסור לאכול מסעודה שאינה מספקת לבעליה, שזהו אבק גזל, אף על פי שבעל הבית מזמינו לאכול עמו. והוא עוון גדול ומן הדברים שקשה לשוב עליהם. (שע\"ה ח\"א רמ\"ח)"]]},{"h":"יג שבט יום חמישי","s":"הלכות סעודה","d":["לעילוי נשמת סלימאן בן עמראן | לעילוי נשמת שמעה בת סלימאן ג'ובאני | לעילוי נשמת שושנה שרעבי בת סלימאן ג'ובאני | לעילוי נשמת יוסף בן עוואד אפרתי ז\"ל","כמוהר\"ר יחיא קורח זצוק\"ל תרפ\"ט מרבני צנעא-מצרים"],"b":[["t","שכח לברך ברכה אחרונה ויצא האם צריך לחזור למקומו?"],["b","לכתחילה אסור לצאת ממקומו עד שיברך ברכה אחרונה, שמא ישכח לברך. ובדיעבד כשיצא, אם הוא צריך לברך נפשות יכול לברך היכן שנמצא אבל אם הוא צריך לברך מעין שלוש לכתחילה צריך לחזור למקומו כמו בברכת המזון. (שע\"ה ח\"א רמ\"ח)"],["t","האם מותר לצאת ממקום שאוכל בו, או לשנות מקומו למקום אחר?"],["b","אסור לצאת ממקומו קודם שיברך ברכת המזון. כמו כן יש ליזהר מללכת באמצע הסעודה אפילו מן החדר שאוכל בו לחדר אחר לגמור שם סעודתו, או שיחזור אחר כך לכאן לגמור סעודתו. ובשעת הצורך יש מקום להקל בזה, בשינוי מקום מחדר לחדר. (שם רמט)"]]},{"h":"יד שבט יום שישי","s":"הלכות לט\"ו בשבט","d":["לעילוי נשמת נצח בן אברהם | לעילוי נשמת שלום בן פנחס"],"b":[["t","מהו סדר הקדימה בפירות שברכותיהם שוות?"],["b","אם יש ביניהם משבעת המינים שנשתבחה בהם ארץ ישראל, יברך עליו אפילו שהוא לא שלם. ואם אין ביניהם ממין שבעה יברך על מה ששלם. ואם אין שלם או שכולם שלמים יברך על מה שחביב לו בדרך כלל. (שע\"ה ח\"א שי'ב)"],["t","מהו סדר הקדימה בפירות שאין ברכותיהם שוות?"],["b","אם יש לפניו פירות שברכתם \"העץ\" \"והאדמה\" יקדים בורא פרי העץ לבורא פרי האדמה אפי' כשפרי האדמה חביב, ושניהם קודמים לברכת שהכל מאחר והיא ברכה כללית. (שם וע'מ שי'ג ועריכ\"ש רמ'ד רמ'ה)"]]},{"h":"טו שבט יום שבת פרשת בשלח","s":"הלכות לט\"ו בשבט","d":["לעילוי נשמת לאה (לולוה) בת משה רצאבי ז\"ל | ברכה והצלחה למיכל בת אחינעם","הרה\"ג מאיר צוברי זצוק\"ל - תשנ\"ה רב העיר גדרה"],"b":[["t","האם דין שינוי מקום שייך באותו חדר?"],["b","אם משנה מקומו בחדר אחד מפינה לפינה, אף על פי שהחדר גדול מאד, לא הוי שינוי מקום."],["s","(שע\"ה ח\"א רמ\"ט)"],["t","היוצא באמצע סעודתו האם חוזר לברך?"],["b","אם יוצא ממקומו חוץ לפתח ביתו, בין שיחזור למקומו לגמור סעודתו, וכגון שקראו חבירו לדבר עמו, בין שיגמור סעודתו במקום שהלך לשם. צריך לברך ברכת המזון למפרע על מה שאכל, ושוב לחזור ולברך המוציא ויגמור סעודתו. וזה אפילו אם בשעת ברכת המוציא הייתה דעתו ללכת אחר כך לבית אחר לגמור שם סעודתו ולברך שם ברכת המזון. והוא הדין בכל זה לפירות ומשקין. (שע\"ה ח\"א רמ\"ט)"]]},{"h":"טז שבט יום ראשון","s":"הלכות לט\"ו בשבט","d":["לעילוי נשמת קמר בת עוואד הלל ז\"ל"],"b":[["t","חברים היושבים לאכול ויצאו מקצתן:"],["b","חברים שהיו יושבים לאכול ויצאו מקצתן מהבית על דעת לחזור לכאן. אם נשאר אפילו רק אחד מהם, לא נתבטלה הקביעות, וכשחוזרים אינם צריכים לברך שוב. (שע\"ה ח\"א רמ\"ט)"],["t","יחיד האוכל ויצא לחוץ לצורך סעודתו האם חשיב הפסק?"],["b","אם יצא לצורך סעודתו כגון להביא איזה מין לפתן לא הוי הפסק ואין צריך לחזור ולברך. (שם ועריכה\"ש קע\"ד ח\"ב)"]]},{"h":"יז שבט יום שני","s":"הלכות לט\"ו בשבט","d":["הנשיא כמוהר\"ר שלום בן אהרן הכהן (אלאצטא) זצוק\"ל תקמ\"ב","הרה\"ג סעדיה חוזה זצוק\"ל - תשנ\"ח רב שכונה בפ\"ת"],"b":[["t","היוצא באמצע סעודתו לזמן קצר האם הוי הפסק?"],["b","יש אומרים שאם חזר מהר אפילו לא השאיר אדם אינו חוזר לברך. אולם אין כן דעת מרן השו\"ע, שמפורש בו שאין הדבר תלוי בשיעור הזמן, שהרי כתב הואיל \"ושינה מקומו\" ושינוי מקום הוא מעשה ולא זמן. (עריכה\"ש ח\"ב קע\"ד אות ב')"],["t","המתפלל באמצע סעודתו האם חשיב הפסק?"],["b","אם הפסיק באמצע אכילתו כדי להתפלל, כשחוזר לאכול אינו צריך לחזור ולברך. אלא אם כן יצא לבית הכנסת, ולא הניח שומר. דאם הניח שם אדם, אנו חוזרים לדין חברים לעיל. (שע\"ה ח\"א רמ\"ט ועריכ\"ש ח\"ב קע\"ז)"]]},{"h":"יח שבט יום שלישי","s":"הלכות לט\"ו בשבט","d":["ברכה והצלחה אדל בת לירן"],"b":[["t","הישן באמצע סעודתו האם חשיב הפסק?"],["b","אם ישן שינת עראי, אף על פי שנמשך איזה זמן, לא מקרי הפסק. אבל אם ישן על המיטה, הוי הפסק. (שע\"ה ח\"א רמ\"ט)"],["t","הנצרך לנקביו באמצע סעודתו האם חשיב הפסק?"],["b","אדם שהוצרך לילך לבית הכסא באמצע סעודתו לא הוי הפסק ומכל מקום צריך נטילת ידים מחדש משום דהוי היסח הדעת, אך לא יברך על הנטילה כי משום היסח הדעת לא מברכים על הנטילה (בשע\"ה ועריכ\"ש, שם)"]]},{"h":"יט שבט יום רביעי","s":"הלכות ברכה ראשונה","d":["לעילוי נשמת דיאנה (דינה) בת רבקה ומנשה","כמוהר\"ר מוסא דמארי זצוק\"ל תשל\"ג - מרבני מחוז דמאר"],"b":[["t","האם יכול אדם לברך \"שהכל\" כאשר אינו יודע מה לברך?"],["b","אף על פי שבדיעבד אם טעה ובירך שהכל על כל דבר יצא, לכתחילה אסור לעשות כן, אלא צריך ללמוד מה לברך על כל מין ומין. ורק בדבר שאי אפשר לו להתברר מאיזה מין הוא, או שהפוסקים נסתפקו ולא הכריעו בו, אז יוצאים ידי חובה בברכת שהכל. ואם יכול לפוטרו בתוך הסעודה עדיף יותר. (שע\"ה ח\"א ר\"צ)"],["t","הטועם את התבשיל האם צריך לברך?"],["b","מטעמת אינה צריכה ברכה. כלומר שהטועם תבשיל לידע אם חסר בו מלח וכדומה ופולט, אינו צריך לברך. ואם הוא בולע, דעת הרמב\"ם שאין צריך לברך, עד רביעית, כיון שאין כוונתו לאכילה. ויש אומרים שצריך לברך כיון שהוא בולע. ולכן טוב ליזהר שיכוין ליהנות ממנו בתורת אכילה, ויברך עליו ויבלע. (שם רצ\"ב)"]]},{"h":"כ' שבט יום חמישי","s":"הלכות ברכה ראשונה","d":["לעילוי נשמת רג'ינה בת יצחק | אליאב בן יעקב ועדי לרוס ברכה והצלחה | התחזקות ויראת שמים ליאיר בן יואב"],"b":[["t","האוכל או שותה לרפואה האם מברך?"],["b","אם יש לו טעם טוב, והחיך נהנה ממנו, מברך לפניו ולאחריו ברכה הראויה לו. אך אם הוא דבר מר שאינו נהנה ממנו, אינו מברך עליו. (שע\"ה ח\"א רצ\"ב)"],["b","בספר פסקי הלכות (עמ' קצד) הביא בשם הגר\"ח כסאר והגר\"י צוברי, שאין מברכים כלל על תרופות, אף שיש להם טעם טוב."],["b","הכניס אוכל לפיו ושכח לברך מה עליו לעשות?"],["b","אם המאכל שהכניס הוא קשה שאם יפלטנו לא יהא נמאס צריך להוציאו ולברך עליו ואם הוא דבר רך שאם יפלטנו יהא נמאס יסלקו בפיו לצד ויברך עליו ואם אירע לו כן במשקין, בולען ומברך רק ברכה אחרונה אמנם יש אומרים שאם יש לו עוד משקין יפלוט מה שבפיו ויברך על השאר ברכה ראשונה. (שם רצ\"ג)"]]},{"h":"כא שבט יום שישי","s":"דברים הבאים בתוך הסעודה, שלא מברכים עליהם בתחילה","d":["להצלחת יגל ואופיר ידעי והבנות אבישג והלל"],"b":[["b","כל מה שאוכלים בתוך הסעודה מדברים שבאים להשביע כגון: בשר, דגים, ביצים, ירקות חיים ומבושלים, דייסא ומיני לביבות אפילו דברים שאוכלים"],["b","בלא לחם כולם נפטרים בברכת המוציא וברכת המזון. וכן דברים שרגילים לאכול בין מאכל למאכל כדי לגרור תאוות האכילה, כגון זית ומלפפון חמוץ נחשבים מחמת הסעודה כיון שעל ידי כן יאכלו יותר, ולכן אינו מברך עליו, שהפת פוטרו. (שע\"ה ח\"א רנ\"ד עריכ\"ש קע\"ב)"],["t","השותה מים ושאר משקין האם מברך עליהם בסעודה?"],["b","על מים ושאר משקין אינו מברך שאין דרך אכילה בלא שתייה חוץ מעל היין לפי שהוא דבר חשוב (שבכמה מקומות מחויבים לברך עליו אף על פי שאינו צריך לשתות, כגון קידוש והבדלה), צריך לברך עליו גם בתוך הסעודה. ואם בירך על היין קודם נטילת ידים והייתה דעתו לשתות גם בתוך הסעודה, או שהוא רגיל בכך לשתות יין בתוך הסעודה, אין לברך עליו שנית, כי נפטר בברכה שבירך עליו קודם הסעודה. (שם)"]]},{"h":"כב שבט יום שבת פרשת יתרו","s":"הלכות דברים הבאים בתוך הסעודה","d":["לעילוי נשמת יששכר שמואל בן משה ישראל (מורי מוסא) | לעילוי נשמת צדוק בן סאלם עורקבי ז\"ל | לעילוי נשמת אברהם בן רבי אברהם ערוסי | ברכה והצלחה ורפוא\"ש לאברהם בן ניסים חדד","כמוהר\"ר יחיא בסיס זצוק\"ל תשל\"ז - מרבני רדאע"],"b":[["t","האם מברכים על פירות בסעודה?"],["b","אם רוצה לאכול פירות בתוך הסעודה בלא פת, חייב לברך עליהם, כיון שאין הפירות מעיקר הסעודה, לכן אפילו אם היו מונחים על השלחן קודם ברכת המוציא, אינן נפטרים בברכת המוציא וצריך לברך עליהם ברכה ראשונה. אבל לא ברכה אחרונה, כי נפטרים בברכת המזון. (שע\"ה ח\"א רנ\"ה רנ\"ו)."],["t","האם צריך לברך על גלידה שמגישים בסעודה?"],["b","אע\"פ שיש אומרים שאין לברך על גלידה בסעודה, וכדין משקים, להלכה העלו רוב ככל הפוסקים שצריך לברך עליה מאחר שבאה לקינוח ואינה שייכת לסעודה, ושוב לא שייך לדון בזה מצד משקה. (שם רנ\"ה אות ה' והל\"ב ח\"ט קצ\"ג)"]]},{"h":"כג שבט יום ראשון","s":"הלכות דברים הבאים בתוך הסעודה","d":["לעילוי נשמת רומיה ערוסי בת רבי חיים"],"b":[["t","האם צריך לברך על \"קומפוט\" בסעודה?"],["b","פירות מבושלים הבאים לקינוח סעודה שנקראים בשם \"קומפוט\" צריכים ברכה. (שע\"ה ח\"א עמוד רנ\"ה)"],["t","האוכל עוגות ועוגיות בסעודה האם צריכים ברכה?"],["b","דברי מאפה שברכתן בורא מיני מזונות, אם אוכל מהם בתוך הסעודה או אפילו בסופה מחמת רעב, כדי לשבוע מהם, לא יברך עליהם. ואם אוכלם רק לתענוג וקינוח, יברך לפניהם בורא מיני מזונות. ולא יברך לאחריהם, כי ברכת המזון פוטרתם אבל על מעשה קדירה כגון \"עציט\" (קמח ששופכים למים רותחים) או \"הריס\" (גריסים מחמשת מינים שבישלם) אין לברך בתוך הסעודה בכל מצב כיון שהם באים מחמת הסעודה. (שע\"ה ח\"א רנ\"ו)."]]},{"h":"כד שבט יום שני","s":"הלכות דברים הבאים בתוך הסעודה","d":["לעילוי נשמת משה בן אברהם | לעילוי נשמת מרים בת דוד ותמניה"],"b":[["t","שכח לברך ברכת המזון עד מתי יוכל לברך?"],["b","ברכת המזון יכול לברך עד שיעור עיכול דהיינו שמתחיל להיות רעב. ויש אומרים דשיעור עיכול הוא 72 דקות. ולכן בסעודות גדולות יש ליזהר שלא להתעכב בשירה ובדברי תורה בין האכילה לברכת המזון יותר מזמן זה, אע\"פ שעוסקים בינתיים בשתייה ופרפראות. ובספר ילקוט יוסף שובע שמחות הביא תרעומת על אותם שנוהגים בזמנינו להמשיך בריקודים באמצע הסעודה עיין שם (פרק א' הערה קל\"ה). ועל כן תבוא ברכה על מי שהיכולת בידו להנהיג שהריקודים יתחילו אחרי ברכת המזון. (שע\"ה ח\"א רס\"ב, ושם עיני יצחק אות ל\"ו)"],["t","יצא מביתו ולא בירך ברכת המזון מה דינו?"],["b","עבר ויצא ממקומו אם יש לו במקום שהוא שם קצת פת יאכל שם ואין צריך לברך עליו \"המוציא\". ולאחר מכן יברך ברכת המזון ואם אין לו שם פת כלל צריך לחזור למקומו לברך ואם הוא רחוק כל כך יברך במקום שהוא שם. והני מילי בעבר ויצא אבל אם הייתה יציאתו בשוגג יכול לברך במקום שנזכר (רמב\"ם ומהרי\"ץ)."],["s","(שע\"ה ח\"א רס\"ב)"]]},{"h":"כה שבט יום שלישי","s":"הלכות ייחוד","d":["לעילוי נשמת זכריה גרמה בן שלום | לעילוי נשמת מרים בת סעיד סאלם אהרון ע\"ה"],"b":[["t","דין איסור יחוד?"],["b","אסור להתייחד עם שום אשה בין פנויה ובין נשואה בין קרובתו כגון דודתו או חמותו או כלתו וכן לאשה אסור להתייחד עם הדוד או חמיה או חתנה וכדומה, כי דבר זה עלול לגרום לגילוי ערוה חס ושלום. (שע\"ה ח\"ו עמ' רפב')"],["t","מהו גדר האיסור?"],["b","ייחוד פירושו, שנמצאים לבדם בבית אחד \"שדלתו נעולה\" או שאין רשות לאדם אחר שיכנס לשם, גם וכן אם הם במקום שומם מאין עובר וכל כיוצא בזה, אפילו למשך זמן קצר מאוד. ואם הדלת סגורה ולא נעולה מותר, ומדרכי הצניעות שתישאר הדלת פתוחה לכל הפחות מעט. (שם עמ' רפד')"]]},{"h":"כו שבט יום רביעי","s":"הלכות ייחוד","d":["לעילוי נשמת זכריה בן יוסף ידעי ז\"ל | לעילוי נשמת שמעה בת סעיד אביאד"],"b":[["t","האם יש חשש יחוד בבייביסיטר?"],["b","אסור לנערה מעל גיל מצוות לעשות בייביסיטר על ילד מעל גיל תשע, וכן אסור לנער מעל גיל מצוות לשמור על בת מעל גיל שלוש. (שע\"ה ח\"ו ס\"ח)"],["t","באלו דרכים אפשר להתיר?"],["b","אולם אם הדלת איננה נעולה ניתן להקל בזה, ונכון יותר להשאירה פתוחה מעט. ואם מוכרחים לנעול את הבית, יתנו מפתח ביד אחד השכנים או השכנות, ויבקשו מהם להיכנס לבית מפעם לפעם ללא נטילת רשות. (שע\"ה שם ס\"ב. ועיין משנת היחוד עמ' רל')"]]},{"h":"כז שבט יום חמישי","s":"הלכות ייחוד","d":["לעילוי נשמת אהרון בן אברהם","כמוהר\"ר חיים חובארה זצוק\"ל - תשכ\"ב"],"b":[["t","האם יש חשש יחוד במעלית?"],["b","מעלית אין בה איסור ייחוד כיון שאחרים יכולים לפתוח בכל קומה וקומה, אך כל זה הוא דוקא במקומות ציבוריים כגון בתי חולים ובניינים משרדיים, אבל בבנין משותף ראוי להימנע משום צניעות ומשום הרחק מן הכיעור. (שע\"ה ח\"ו עמ' רצב')"],["t","האם יש חשש יחוד בנסיעה במכונית?"],["b","בנסיעה במכונית אין איסור ייחוד בדרך כלל, כיון שמצויים נוסעים רבים בכבישים, אך בסמטאות חשוכות או ברחובות צדדיים או במקומות נדחים או שחלונות המכונית מוגפים וכן בשעות הלילה המאוחרות יש לאסור. (שם)"]]},{"h":"כח שבט יום שישי","s":"המשך דיני ייחוד והלכות ביטוח חיים","d":["לעילוי נשמת סעידה בת דוד סעיד ז\"ל | לעילוי נשמת אביגיל בת רחל ויהודה | ברכה והצלחה אדר בן דניאל","כמוהר\"ר סאלם יחיא זכריה זצוק\"ל - תש\"ט חבר ביה\"ד בידא"],"b":[["t","האם מותר להתייחד במקלט בזמן שיש אזעקה?"],["b","בזמן שיש חשש סכנה וכפי שמצוי בזמן אזעקה, נחלקו הפוסקים אם יש איסור ייחוד, ולכן אין למהר להקל בזה כאשר ניתן ללכת למקום אחר, ובשעת הצורך ניתן להקל, ובלבד שיצא הוא או היא מיד בחלוף הסכנה. (עיין עול\"י ח\"ב סי' ר\"מ)."],["t","האם יש חסרון באמונה בעשיית ביטוח חיים?"],["b","אין מניעה לפי הדין מלעשות ביטוח לעסקיו ורכושו, בתנאי שיהיה תקוע בדעתו שהכל מאתו יתברך, כי הוא הנותן לך כח לעשות חיל, והבוטח בה' חסד יסובבנו. (עול\"י ח\"ב סי' רנ\"ז)."]]},{"h":"כט שבט יום שבת פרשת משפטים ערב ראש חודש","s":"הלכות קירבה לעריות","d":["ברכה והצלחה רפואה שלמה פוריות שלום בית וכל טוב לעדי דהרי ומזל טוב ליום הולדתה","כמוהר\"ר יחיא עומייסי זצוק\"ל תשמ\"ו - אב\"ד רדאע","הרה\"ג צדוק עומייסי זצוק\"ל - רב קהילת שערי ציון רשל\"צ"],"b":[["t","האם מותר לאחים ואחיות לגעת אחד בשני?"],["b","יש להקפיד שאח לא יגע באחותו אפילו היא קטנה, אך כל זה רק בנגיעה שיש בה חיבה כל שהיא, כגון נשיקה, חיבוק וכדומה, אבל נגיעה בעלמא, כגון להסב את תשומת לבה, אין לאסור."],["s","(שע\"ה ח\"ו עמ' רכח'. ובס' בלכתך עמנו לאשה ולבת, מהדו\"ח עמ' 138)"],["t","מה הדין בתספורת הבת לבן, או להיפך?"],["b","ולכן יש להחמיר שאין לאח או לאחות לספר אחד את השני מאחר שנעשה הדבר ליפוי, ויש בזה חיבה כל שהיא. (עול\"י ח\"ב סי' רל\"ז)"]]},{"h":"ל' שבט יום ראשון א' דראש חודש","s":"הלכות קירבה לעריות","d":[],"b":[["t","האם מותר ללכת אחרי אשה?"],["b","אסור להלך אחורי אשה אפילו אם היא מכוסה מכף רגל ועד ראש, ואם נזדמנה לו בדרכו, ימהר בדרכו שתישאר היא לצדדים או לאחוריו. ואם היא לפניו במרחק של שני מטרים, מעיקר הדין מותר, אך אם אפשר ישתדל להתרחק עד שאינו מבחין בהילוכה. (שע\"ה ח\"ו עמ' רי')"],["t","מה הדין לעמוד אחרי אשה בתור?"],["b","וכן יש להקפיד שלא לעמוד מאחורי אשה בתור, ואם אין אפשרות אחרת, יטה את גופו לצד אחר או יתן את עיניו בקרקע או באיזה ספר. (שם)"]]},{"h":"א' אדר א' יום שני ב' דראש חודש","s":"הלכות קירבה לעריות","d":["לעילוי נשמת מארי עואץ צפר בן מארי סליאמן זצ\"ל","כמוהר\"ר דוד חג'בי זצוק\"ל - תשנ\"ח רב העיר רה\"ע"],"b":[["t","האם מותר לעבור בין שתי נשים?"],["b","יש ליזהר שלא יעבור איש בין שתי נשים המכוונות זו כנגד זו, משום שהדבר גורם לשכחה, ואם יש מרחק ארבע אמות ביניהן, מותר. וכשאין ברירה יחזיק בידו איזה חפץ {כמו עט, שעון, ציצית} שיהיה חוצץ ביניהם. (שע\"ה ח\"א עמ' יג')"],["t","מה הדין לעבור בין שתי ילדות?"],["b","מי שיכול להקפיד שלא לעבור גם בין שתי ילדות קטנות, תבוא עליו ברכה. (עיין עול\"י ח\"ב סי' רל\"ח)"]]},{"h":"ב' אדר א' יום שלישי","s":"הלכות קירבה לעריות","d":["אורה בת רועי ברכה והצלחה"],"b":[["t","האם מותר לשבת בתערובת גברים ונשים?"],["b","כל מקום שמתאספים בו אנשים ונשים, או בנים ובנות, הן בבתים פרטיים, הן בבתי כנסיות, ואולמות, וכדומה, חובה להעמיד מחיצה מליאה להפריד ביניהם, כדי שלא יבואו לידי קלות ראש. וכל שכן שאסור להם לשבת יחדיו. ולא רק כשאוכלים במסיבה של שמחה וסעודה, כגון נישואין, וברית מילה, אלא גם בעת שיעור, או דרשה, וכדומה. ואפילו בשעת צער, כגון ניחום אבלים. (שע\"ה ח\"ו עמ' רלו')."],["t","מה הדין לשבת גברים ונשים כשכולם קרובי משפחה?"],["b","אמנם בסעודה קטנה, שאין יושבות שם רק קרובות המשפחה. כגון; אחותו, ודודתו, כלתו, וחמותו, אשת אחיו, ואחות אשתו, אין צריך מחיצה כלל, ומותר אז, אפילו לישב ולאכול סביב שולחן אחד כנהוג, האנשים בצד האחד, והנשים בצד השני. (שם)"]]},{"h":"ג' אדר א' יום רביעי","s":"הלכות קירבה לעריות","d":["לעילוי נשמת מארי אברהם בן חיים ז\"ל | להצלחת הזוג דהרי חן ועדי בשפע ברכה והצלחה רפואה שלימה ושלום בית וגמילות חסדים זרע של קיימא וכל טוב"],"b":[["t","האם מותר לילדים וילדות לשחק יחדיו?"],["b","ילדים קטנים וילדות קטנות צריך לחנכם שלא יהיו רגילים אלו עם אלו, ולכן לא ילמדו יחדיו כגון בבתי ספר וכדומה, אולם קרובי משפחה או שכנים שמשחקים יחד אם זה רק דרך עראי אין צריך להקפיד עליהם אלא מגיל תשע ומעלה. (שע\"ה ח\"ו עמ' רלח')"],["t","האם מותר לקחת ילד קטן לים של נשים?"],["b","אין להביא ילד מגיל שלוש למקום שנשים מתרחצות כגון חוף הים או בריכה, וכן אין להביא ילדה מגיל שלוש למקום שאנשים מתרחצים. (שע\"ה ח\"ו עמ' רלט')"]]},{"h":"ד' אדר א' יום חמישי","s":"הלכות כיבוד אב ואם","d":["ברכה והצלחה להדסה בת גלעד | ברכה והצלחה לשני בת נחמיה"],"b":[["t","חשיבות ענין כיבוד מאביו ואמו"],["b","צריך האדם ליזהר מאוד בכבוד אביו ואמו ובמוראם. שהשווה אותם הכתוב לכבודו ולמוראו יתברך, שנאמר כבד את אביך ואת אמך, ונאמר כבד את י\"י מהונך. באביו ובאמו נאמר איש אמו ואביו תיראו, ונאמר את י\"י אלהיך תירא. כדרך שציווה על כבוד שמו הגדול ומוראו, כך ציווה על כבודם ומוראם. בזמן שאדם מכבד את אביו ואת אמו, אומר הקב\"ה; מעלה אני עליהם כאילו דרתי ביניהם וכבדוני. (שע\"ה סי' קס\"ב ס\"א)"],["t","מהו עניין המורא מאביו ואמו?"],["b","עניין המורא שכתוב \"איש אמו ואביו תיראו\" הוא שיתנהג עמהם כמו עם מי שהוא ירא ומפחד ממנו שיענישהו כגון מן המלך. בכלל המורא הוא שלא ישב ואף לא יעמוד במקום המיוחד לאביו לתפילה, או במקום המיוחד לו כשהוא בביתו, או במקום עבודה שלו, וכל זה אפילו שלא בפניו. (שע\"ה סי' קס\"ב ס\"א וס\"ב)"]]},{"h":"ה' אדר א' יום שישי","s":"הלכות כיבוד אב ואם","d":["המקובל הרה\"ג סעדיה בן אור זצוק\"ל תשנ\"ז"],"b":[["t","אם יכול לישב במקום שהיה מיוחד לאביו"],["b","אם אביו עבר להתפלל בבית הכנסת אחרת, שוב לא ן נחשב אותו מקום שהיה יושב שם מקומו, ומותר לב לשבת שם. וכן אם שינה מקומו בתוך בית הכנסת, יכול הבן לשבת באותו מקום שהיה מיוחד לו."],["s","(שע\"ה סי' קסב הע' ח' ובעול\"י ח\"ב סי' רצ\"א)"],["t","האם גם במקום אמו אסור לישב"],["b","כן. הדין באמו, כמו באביו. שאם יש לה מקום קבוע בבית, אין לשבת שם. וכן הבת לא תשב במקום הקבוע לאמה בעזרת נשים. (שע\"ה סי' קס\"ב ס\"ב)"]]},{"h":"ו' אדר א' יום שבת פרשת תרומה","s":"הלכות כיבוד אב ואם","d":[],"b":[["t","איך יתייחס לדברי אביו"],["b","לא יסתור דברי אביו או יחלוק עליהם ואפי' להכריע את דבריו בפניו אסור כגון שיאמר על דבריו \"נכון\" או \"אני מסכים אתך\" \"אתה צודק\" וכדומה. שבזה נראה שהכרעתו חשובה יותר מדברי אביו. (שע\"ה סי' קס\"ב ס\"ב)"],["t","איסור קריאה לאביו בשמו"],["b","עוד בכלל דיני מורא האב, שלא יקראנו בשמו הפרטי, הן בפניו, הן שלא בפניו, הן בחייו, הן במותו. אלא יאמר \"אבא מרי פלוני\"(שפירושו אדוני בארמית). [ומדברי האחרונים מתבאר; שמעיקר הדין מספיק לומר \"אבי פלוני\", והמילה מרי, היא לתוספת כבוד]. וכל זה דוקא כשאומר בפיו, אבל כשכותב, כגון שחותם שמו ושם אביו, יכול לכתוב את שמו של אביו. [ובאמואין המנהג לומר, \"אימי מורתי\" אפילו כשמזכירים לאחרים]."],["s","(שע\"ה סי' קס\"ב ס\"ד. עיני יצחק י\"ד)"]]},{"h":"ז' אדר א' יום ראשון","s":"הלכות כיבוד אב ואם","d":["לעילוי נשמת סעיד סלאם עורקבי ז\"ל"],"b":[["t","מה הדין אם שואלים מה שמו של אביו?"],["b","אם יש צורך להזכיר את שמו של אביו בפירוש, כגון בשביל קריאתו לעלות לספר תורה, או מי שאינו מכירו השואלו בן מי אתה, יש אומרים שיקדים לומר אבא מרי פלוני. ויש אומרים שאינו צריך, כי כיון שאומר \"בן פלוני אני\", הרי זה כאומר \"אבי פלוני\". וכן הוא מנהגינו להקל. (שע\"ה סי' קס\"ב ס\"ד)"],["t","איך יקרא לאדם אחר ששמו כשם אביו"],["b","לאדם אחר ששמו כשם אביו, לא יקרא בשמו בפני אביו, שמא יסבור אביו שהוא קורא לו, או הנמצאים שם יסברו כן. ויש בזה זלזול לכבודו. (שע\"ה סי' קס\"ב ס\"ה)"]]},{"h":"ח' אדר א' יום שני","s":"הלכות כיבוד אב ואם","d":[],"b":[["t","מה הדין אם שמו של אביו מיוחד, ואינו מוכר?"],["b","אם שם אביו הוא שם מיוחד, שלא נמצאים אנשים בשם כזה, לא יקרא לאחר ששמו כשם אביו, אפילו שלא בפני אביו. אלא ישנה אותו. (אך לאחר מותו מותר). כמו שמצינו בחכמי התלמוד, שאביי נקרא נחמני, אך כיון שהיה יתום, וגדל ולמד תורה אצל רבה בר נחמני, לא היה קורא לו \"נחמני\" כשם אביו, אלא \"אביי\" בלשון ארמי, כאדם שקורא אבי. (שע\"ה סי' קס\"ב ס\"ה)"],["t","מהו הכבוד שהבן חייב באביו ואמו"],["b","מאכיל ומשקה, מלביש ומכסה, ומשרת אותם גם בשאר דברים שהשמש משרת בהם את רבו. והכל בסבר פנים יפות. שאפילו אם מאכילם בכל יום מאכלים משובחים, אך מראה להם פנים זועפות, נענש עליהם. וידבר אליהם בנחת, ובלשון רכה, ובכבוד, בצניעות ובבושת פנים. (שע\"ה סי' קס\"ב ס\"ז)"]]},{"h":"ט' אדר א' יום שלישי","s":"הלכות כיבוד אב ואם","d":["ברכה והצלחה לאייל ידעי"],"b":[["t","עד היכן מגיע חיוב כבודם ומוראם"],["b","היה הבן לבוש בגדי חמודות, ויושב בראש הקהל, ובאו אביו או אמו וקרעו את בגדיו, והכוהו על ראשו, וירקו בפניו. לא יבייש אותם. וכן אם נטלו כסף וזהב שלו, והשליכום לים בפניו, לא יבייש אותם, ולא יראה צער בפניהם, ולא יכעוס עליהם, אלא יקבל גזירת הכתוב וישתוק, ויירא ממלך מלכי המלכים ברוך הוא שציווהו בכך. (ומ\"מ מותר לו לתובעם לדין תורה על ההפסד הממוני שעשו לו)."],["s","(טור, ב\"י. שו\"ע יו\"ד סי' ר\"מ סעיפים ג' ח'. שע\"ה סי' קס\"ב ס\"ו וס\"ט)"],["t","אם מותר להעיר את אביו או אמו משנתם"],["b","היו אביו או אמו ישנים ומפתח החנות של הבן תחת ראשם, אסור להקיצם משנתם, אף על פי שיפסיד רווח הרבה. אבל אם הם ירויחו, ואם לא יקיצם, יצטערו על מניעת הרווח. מצוה להקיצם כיון שישמחו בזה. וכן מצוה להקיצם לדבר מצוה, כגון לבית הכנסת, מפני שכולם חייבים בכבוד המקום ברוך הוא."],["s","(שע\"ה סי' קס\"ב ס\"ט)"]]},{"h":"י' אדר א' יום רביעי","s":"הלכות כיבוד אב ואם","d":["לע״נ סבתי רחל בת ר׳ שלום אהרון ז״ל | לעילוי נשמת רפאל בן יחיא | לעילוי נשמת נעמי בת רומיה"],"b":[["t","כבוד אביו במקום שיגרם צער לאמו"],["b","אם אמרה לו אמו לעשות איזה דבר ועשה, ואחר כך בא אביו ושאל אותו, מי אמר לך לעשות זאת, אם מרגיש שאם יאמר שאמו אמרה לו, יכעס אביו עליה, לא יאמר לו שאמו אמרה לו לעשות הדבר, אף על פי שעל ידי כך יכעס האב עליו. שאם לא כן, נחשב כאילו הבן ציער אותה בכעס הזה. (שע\"ה סי' קס\"ב ס\"י)"],["t","כיצד חיוב עמידה בפני אביו"],["b","חייב לעמוד מלא קומתו מפני אביו, כדרך שעומד מפני רבו המובהק. וכן המנהג כשהאב נכנס לבית הכנסת, עומדים בניו לכבודו עד שישב במקומו. וכן כשנכנס למסיבה, וכיוצא בזה. והוא הדין שצריך לעמוד כשנכנס לביתו בשובו מבית המדרש, או מעסקיו בחוץ. ומכל מקום אינם עומדים בכל פעם שיעמוד, אלא רק בפעם הראשונה כשנכנס. (שע\"ה סי' קס\"ב סי\"א. עיני יצחק ל\"ה.)"],["b","בספר פסקי הלכות (עמ' תס\"ב) הביא בשם הגר\"י צוברי, שהמנהג לעמוד רק בבית הכנסת, וכדומה, ולא בבית, שאז הוא מוחל על כבודו."]]},{"h":"יא אדר א' יום חמישי","s":"הלכות כיבוד אב ואם","d":["ברכה והצלחה רועי בן משה ודקלה אזולאי","כמוהר\"ר סאלם יעקב מנחם זצוק\"ל תש\"ז - אב\"ד עדן"],"b":[["t","אם נהגו לעמוד מפני האם"],["b","לאם לא נהגו לעמוד כלל, ואפילו לא הידור (דהיינו קימה מועטת), כפשט משמעות רבינו הרמב\"ם ומרן השו\"ע שלא הזכירו נשים כלל בדין זה."],["s","(שע\"ה סי' קס\"ב הע' לה וסי' קס\"ג הע' ט\"ז)"],["t","אם מזכיר משם אביו דברי תורה"],["b","חייב לכבד את אביו אפילו אחר מותו. כיצד; היה אומר דבר הלכה, או דברי תורה ששמע מפיו, לא יאמר כך אמר אבא. אלא, אם הוא בתוך י\"ב חודש לפטירתו, יאמר; \"כך אמר אבא מרי הריני כפרת משכבו\". ואם לאחר י\"ב חודש, יאמר; \"כך אמר אבא מרי זכרונו לחיי העולם הבא\". (שע\"ה סי' קס\"ב סי\"ב)"]]},{"h":"יב אדר א' יום שישי","s":"הלכות כיבוד אב ואם","d":[],"b":[["t","ספיר בת משה ברכה והצלחה"],["b","כמוהר\"ר אברהם אלנדף זצוק\"ל אם מזכיר משם אביו דברים, שאינם דברי תורה."],["b","אם היה מזכיר בשמו דברים במילי דעלמא, אינו חייב לכבדו בדברים אלו, אלא בסגנון אחר כרצונו, כגון; \"עליו השלום\", \"מנוחתו בגן עדן\", \"מנוחתו כבוד\", \"זכרונו לברכה\", וכיו\"ב. וכל אלו, הן בתוך י\"ב חודש, הן אפילו אחרי שנים רבות. (שע\"ה סי' קס\"ב סי\"ב)"],["t","ראה את אביו עובר על דברי תורה"],["b","ראה הבן את אביו שעבר על דברי תורה, לא יאמר לו; \"אבא, עברת על דברי תורה\". אלא יאמר לו; \"אבא כתוב בתורה כך וכך\", כאילו הוא שואל ממנו, ולא כמזהירו, והאב יבין מעצמו. (שע\"ה ח\"ה סי' קס\"ב סי\"ג)"]]},{"h":"יג אדר א' יום שבת פרשת תצוה","s":"הלכות כיבוד אב ואם","d":["נתנאל בן כפיר ברכה והצלחה","כמוהר\"ר יחיא נחום זצוק\"ל תשכ\"ב - שליח בי\"ד לכל גלילות תימן"],"b":[["t","מה הדין אמרו לו אביו או אמו לעבור על דברי תורה?"],["b","אמרו לו אביו או אמו לעבור על דברי תורה, בין אם היא מצווה מן התורה, או אפילו מצווה מדרבנן, לא ישמע להם. מפני שאף אביו ואמו חייבים במצוות ה' יתברך. ויש אומרים שאפילו לעבור על מנהג, לא ישמע להם, כי מנהגי ישראל תורה הם. (שע\"ה ח\"ה סי' קס\"ב סי\"ד)"],["t","מה הדין אם אמרו לו אביו או אמו לשנוא אדם אחד?"],["b","מן ההלכה הקודמת, הוא הדין אם אמרו לו אביו או אמו שלא ידבר עם פלוני, ושלא ימחול לו, והבן רוצה להתפייס איתו, אין לו לחוש לפקודתם. כי אסור לשנוא שום יהודי, ונמצא שציוו אותו לעבור על דברי תורה. (אלא אם כן ראהו שעבר עבירה, והתרה בו, ולא חזר בו, וגם לא חזר בתשובה). (שע\"ה ח\"ה סי' קס\"ב סט\"ו)"]]},{"h":"יד אדר א' יום ראשון פורים קטן","s":"דיני פורים קטן","d":[],"b":[["t","האם יש ענין להרבות בשמחה בי\"ד וט\"ו של אדר הראשון?"],["b","בי\"ד וט\"ו של אדר א', ג\"כ אין נופלים על פניהם ואין אומרים 'אל ארך אפים' בהוצאת ס\"ת ולא 'למנצח' בסדר היום, ואסורים בהספד ובתענית ויש אומרים שמותרים בהספד ובתענית. ולגבי ריבוי שמחה יש אומרים שחייבים להרבות בו במשתה ושמחה ואין נוהגין כן. (שע\"ה קכ\"ג י' ע\"פ שו\"ע תרצ\"ז)"],["t","מה הדין אם טעו וקראו את הפרשיות 'שזפ\"ה' והמגילה באדר הראשון?"],["b","אם טעו וחשבו שהשנה אינה מעוברת וכבר קראו את כל או את חלק מהפרשיות (שקלים, זכור, פרה, החודש) או שכבר קראו את המגילה, צריך לחזור ולקרותן באדר שני. (אף שלענין קריאת הפרשיות משמע ממרן ה'בית יוסף' שלא צריך לחזור, אך מסקנתו בחיבורו 'בדק הבית' שכן צריך לחזור, וכן בדרכי משה). (משנ\"ב תרפ\"ה א', שת\"ז תרפ\"ח כ\"ב)"]]},{"h":"טו אדר א' יום שני שושן פורים קטן","s":"הלכות כיבוד אב ואם","d":["לעילוי נשמת חממה יונה בת חיים וחממה | לרפואה, הצלחה, אושר ובריאות לאביתר בן ליטל | ברכה והצלחה לירן בן דניאל"],"b":[["t","אם הבן רוצה ללמוד תורה במקום אחד, והוריו רוצים שילמד במקום אחר"],["b","אם הבן רוצה ללכת לאיזה מקום ללמוד תורה, מפני ששם תהיה לו תועלת יותר מאשר כאן, והאב או האם מוחים בידו באיזה טעם, אינו צריך לשמוע להם, כי תלמוד תורה גדול מכיבוד אב ואם. (שם סט\"ז)"],["t","אם רוצה הבן לישא אשה מסויימת והוריו מתנגדים"],["b","אם הבן רוצה לישא אשה שהוא חפץ, והיא הגונה א לאיש ראוי ש וראויה. והוא הדין לבת שרוצה להנ והגון. והאם או האב מוחים, אין הבן או הבת צריכים לשמוע להם. גם בעניין נוסח התפילות, כשהבן רוצה לשנות (באופן שהדבר מותר, דהיינו שאין בזה משום \"אל תיטוש תורת אמך\"), אינו חייב לשמוע בקול אביו המוחה כנגדו. (שע\"ה ח\"ה סי' קס\"ב סי\"ז)"]]},{"h":"טז אדר א' יום שלישי","s":"הלכות כיבוד אב ואם","d":["כמוהר\"ר עוואד נגאר זצוק\"ל תש\"ל - מרבני סוואדיה"],"b":[["t","אם האב יכול למנוע מבנו לומר קדיש על האם"],["b","אם חס ושלום מתה האם, המנהג שאומר קדיש על אמו כל י\"א חודש אפילו בפני האב, ואין בידו למנוע. וכל שכן להיפך שאומר קדיש על אביו שמת, ואין אמו יכולה למונעו. (שע\"ה סי' קס\"ב סי\"ז)"],["t","האם אשה נשואה חייבת בכל דיני כיבוד אב ואם?"],["b","גם הבת חייבת בכל ענייני כיבוד אביה ואמה ומוראם. וכן אשה גרושה או אלמנה. אבל אשה נשואה, פטורה מלכבדם (אבל חייבת במוראם), כיון שהיא משועבדת לבעלה לעסוק במלאכות הבית וכדומה. אך אם בעלה אינו מקפיד עליה, חייבת בכל דבר שאפשר לה. (שע\"ה ח\"ה סי' קס\"ב סי\"ח)"]]},{"h":"יז אדר א' יום רביעי","s":"הלכות כיבוד אב ואם","d":[],"b":[["t","איך ינהג עם הוריו שנשתטו"],["b","מי שנטרפה דעת אביו או אמו, ישתדל לנהוג עמהם כפי דעתם, עד שירחם ה' עליהם, ואם אי אפשר לו (מבלי לגעור בהם)מפני שנשתטו ביותר, יצוה לאדם אחר להנהיגם כראוי. (שע\"ה סי' קס\"ב סי\"ט)"],["t","אם יכול האב למחול על כבודו"],["b","אב שמחל על כבודו, כבודו מחול. והוא הדין על מוראו. לפיכך אם מחל האב על כבודו, והתיר לבן לשבת במקומו, או שלא לעמוד בפניו, יהיה מותר לשבת במקומו, ולא לעמוד בפניו. ומכל מקום מפסיד הבן מצוה. אבל על בזיונו אינו יכול למחול, ולכן לעולם אסור לקרוא לו בשמו, גם אם נתן לו רשות, מפני שהוא זלזול בכבודו. והוא הדין בכל זה באמו, שיכולה למחול על כבודה, אבל לא על בזיונה."],["s","(שע\"ה סי' קס\"ב הע' לה וס\"כ)"]]},{"h":"יח אדר א' יום חמישי","s":"הלכות כיבוד אב ואם","d":[],"b":[["t","איך האב ינהג עם ילדיו"],["b","אף על פי שנצטוינו על כיבוד אב ואם אסור לאדם להכביד על בניו, ולדקדק בכבודו עמהם. כדי שלא יביאם לידי מכשול. אלא ימחול ויעלים עיניו מהם, שהאב שמחל על כבודו, כבודו מחול. אבל לא ימחול על בזיונו. (שע\"ה סי' קס\"ב ס\"כ)"],["t","אם חייב בכבוד אשת אביו"],["b","חייב אדם לכבד את אשת אביו אף על פי שאינה אמו, כל זמן שאביו קיים. וכן חייב לכבד את בעל אמו, אף על פי שאינו אביו, כל זמן שאמו קיימת. ודבר הגון הוא לכבדם גם אחרי מות אביו ואמו. (שע\"ה סי' קס\"ב סכ\"ב)"]]},{"h":"יט אדר א' יום שישי","s":"הלכות כיבוד אב ואם","d":["לעילוי נשמת דוד עומסי בן ר' יעקב | להצלחת שמעון נשיא בן גביר נשיא ומשפחתו"],"b":[["t","האם חייב בכבוד אחיו הגדול"],["b","כתוב בפסוק; \"כבד את אביך ואת אמך\" דרשו חז\"ל מריבוי המילה \"את\" אביך ואת אמך שצריך לכבד אף את אחיו הגדול. ולאו דוקא אחיו הגדול ממש אלא גם שאר האחים הגדולים ממנו וכן אחותו הגדולה ושאר אחיותיו הגדולות ממנו. ומכל מקום אינו חייב אלא בכבודו, ולא במוראו. לפיכך אינו צריך לנהוג עמו בעניינים של מורא אביו ואמו."],["s","(שע\"ה סי' קס\"ב סכ\"ב ועינ\"י הע' ס\"ט)"],["t","האם חייב בכבוד חמיו וחמותו?"],["b","חייב גם בכבוד חמיו וחמותו, כמו שמצינו בדוד המלך עליו השלום שחלק כבוד לשאול המלך שהיה חמיו וקראו \"אבי\". (שנאמר (שמואל א' כ\"ד י\"ב) \"ואבי ראה גם ראה\"). וכן חייב בכבוד אבי אביו, ואבי אמו, ואם אביו ואם אמו, (דהיינו הסבים והסבתות בין מצד האב בין מצד האם). ובכלל זה מה שנוהגים שלא לקרותם בשמם. אלא בכינוי \"דודה\" – לחמותו. וכן \"סבא\" – לזקינו.ד\" – לחמיו. ו\"דו ו\"סבתא\" לזקינתו. (שע\"ה שם. ועיני יצחק ע\"ב)"]]},{"h":"כ' אדר א' יום שבת פרשת כי תשא","s":"הלכות כיבוד אב ואם","d":["להצלחת צורית בת דבורה"],"b":[["t","מהו הכיבוד שצריך לכבד שאר הקרובים?"],["b","גדול כבוד אביו מכבוד כל הקרובים שהזכרנו, כגון שאינו חייב לעמוד מפניהם מלוא קומתו, רק לעשות להם הידור (דהיינו לקום קצת) כשעוברים לפניו. ויתן להם דין קדימה בדיבור ובאכילה. וידבר אליהם בלשון כבוד וחשיבות, וכיוצא באלו. (שע\"ה ח\"ה סי' קס\"ב סכ\"ב)"],["t","האם צריך לכבד לעמוד בזמן שקוראים בספר תורה?"],["b","המנהג לעמוד מלוא קומתו גם לשאר קרובים, ובפרט בעת שהם קוראים בספר תורה. (יש שנוהגים לעמוד כל משך הקריאה, ויש נוהגים רק בזמן הברכה). חוץ מחמיו שיש מקומות שאין נוהגים לעמוד. (ולכל מנהג יש שורש וסמך בפוסקים). (שע\"ה ח\"ה סי' קס\"ב סכ\"ב. עיני יצחק ע\"ד. שע\"ה סי' כ\"ב הערה ס\"ב)"]]},{"h":"כא אדר א' יום ראשון","s":"הלכות כיבוד אב ואם","d":["להצלחת אלה זינו בת דבורה"],"b":[["t","האם מצוות כיבוד אב ואם ושאר קרובים, שייכת גם כשאינם שומרי תורה ומצוות?"],["b","קרובים אלו שאמרו שחייב לכבדם, זה אפילו אם הם עמי ארצות. אך אם הם רשעים ובעלי עבירות, לא יכבדם. אבל את אביו, אפילו אם הוא רשע ובעל עבירות, חייב לכבדו ולהתיירא ממנו."],["s","(שע\"ה ח\"ה סי' קס\"ב סכ\"ב)"],["t","באילו עבירות שיעשה האב, אינו חייב לכבד ולירוא ממנו?"],["b","מה שאמרנו שאפילו אביו עושה עבירות, חייב לכבדו, היינו דווקא כשעושה מפני תאוותו ולהנאתו. אבל אם עושה להכעיס, או שאינו מאמין בדברי חכמינו ז\"ל, וכל שכן אם נשתמד, לא יכבדנו ולא יתיירא ממנו. (שם)"]]},{"h":"כב אדר א' יום שני","s":"הלכות כיבוד אב ואם","d":["להצלחת גביר נשיא בן שמעון"],"b":[["t","דין המבזה אביו או אמו"],["b","כל המבזה את אביו או את אמו אפילו בדברים ואפילו ברמיזה, (ויש אומרים דהוא הדין אם מבזה אותם בליבו), הרי זה בכלל ארור מפי הגבורה, שנאמר (דברים כ\"ז ט\"ז) \"ארור מקלה אביו אמו\". (שע\"ה ח\"ה סי' קס\"ב סכ\"ד)"],["t","האם מותר להוציא דם מאביו או אמו לצורך רפואה?"],["b","היה קוץ תחוב לאביו או לאמו, לא יוציאנו, שמא יעשה בהם חבורה, שהיא באיסור האמור בפסוק \"ומכה אביו ואמו, מות יומת\". וכן אם הבן הוא רופא, לא יקיז להם דם, ולא יחתוך להם איבר, ולא יעשה להם ניתוח, וכיוצא בזה, אפילו שהוא צורך רפואה. (שע\"ה ח\"ה סי' קס\"ב סכ\"ה)"]]},{"h":"כג אדר א' יום שלישי","s":"הלכות כיבוד אב ואם","d":["לעילוי נשמת זכריה בן מנשה"],"b":[["t","האם מותר לעשות זריקות לאביו לצורך רפואה?"],["b","לעשות זריקות לאביו לרפואה, זריקות הנעשות בתוך הבשר, הואיל ואין מצוי לצאת דם על ידם מותר. אבל זריקות הנעשות בתוך הוורידים, דינן כהקזת דם, ואסור. (שע\"ה ח\"ה סי' קס\"ב סכ\"ה)"],["t","מה הדין אם האב חולה, ואין מי שיטפל בו מבלעדי הבן?"],["b","אם האב חולה ומצטער, ואין שם רופא שיכול לטפל בו, והבן רופא. בשעת הדחק אפשר להקל, שהבן הרופא יקיז דם, ויחתוך מבשרו, וינתח כפי צורך הרפואה. (וטוב שישאל מורה הוראה). (שע\"ה ח\"ה סי' קס\"ב סכ\"ה. עיני יצחק פ\"ד)"]]},{"h":"כד אדר א' יום רביעי","s":"הלכות כיבוד אב ואם","d":[],"b":[["t","היאך גר ינהג בהוריו האינם יהודים"],["b","\"גר\" אסור לקלל את הוריו הגויים, ולא יבזה אותם. אלא ינהג בהם מקצת כבוד. דהיינו באופן שלא ייראה כפוי טובה בעיני הבריות. (שע\"ה סי' קס\"ה סכ\"ו)"],["t","מהו כיבוד הורים הגדול ביותר"],["b","הרוצה לכבד את הוריו לפי האמת יעסוק בתורה ובמעשים טובים שזהו הכבוד הגדול לאבות שאומרים הבריות אשרי לאב ואם שגדלו בן כזה. אבל אם אין הבן הולך בדרך הישר הרי אבותיו ישאו חרפה עליו והוא מביישם בבושה שאין גדולה הימנה. (שע\"ה סי' קס\"ב סכ\"ז)"]]},{"h":"כה אדר א' יום חמישי","s":"הלכות סדר ארבע פרשיות","d":["ברכה והצלחה ברו\"ג נחת מהילדים ופרנסה בשפע ליעל בת יוסף","כמוהר\"ר יהודה שרעבי זצוק\"ל תשל\"ה - מרבני מחוז דמאר"],"b":[["t","כיצד נקראת השבת שלפנינו ומהו סדר קריאתה?"],["b","השבת הקרובה פרשת 'ויקהל' נקראת 'שבת שקלים', ומוציאין בה שני ספרים. בראשון קורין שבעה עולים בפרשת השבוע, ובשני קורא אחד בתחילת פרשת 'כי \" (בשונה תשא', ומפטירין \"בן שבע שנים יהואש במלכו מתחילת ההפטרה למנהג שאר קהילות, כמובא בשו\"ע סי' תרפ\"ה)."],["b","ומוציאין שני ספרים בדווקא, ולא כמי שרצה לומר שיוציאו רק ספר אחד, כיון ואין טירחא דציבורא בגלילת הספר מפרשתינו פרשת 'ויקהל' ל'כי תשא'"],["b","הצמודות זו לזו, אלא יוציאו שני ספרים להראות את כבוד היום שנתחייב בקריאה נוספת."],["s","(שע\"ה קכ\"א א' ובהערה ב')"],["t","האם יאמרו קדיש לאחר הקריאה בס\"ת שני?"],["b","מנהג הבלדי שלעולם אין אומרים קדיש לאחר המפטיר, ומנהג רוב השאמי לומר קדיש אחר קריאת כל ספר בפני עצמו, (מלבד הנוהגים לקרוא ששה עולים בס\"ת ראשון, שלשיטתם ממילא יאמרו קדיש רק לאחר ס\"ת שני שבו סיימו השבעה עולים). (שת\"ז תרפ\"ד י', שע\"ה ס' ט\"ז)"]]},{"h":"כו אדר א' יום שישי","s":"הלכות קריאת המגילה","d":["לעילוי נשמת שמשון בן יחיא"],"b":[["t","האם מותר לקרות את המגילה קודם צאת הכוכבים?"],["b","אסור לקרות את המגילה קודם צאת הכוכבים, ואף על פי שיש מתירים לקרותה קצת מבעוד יום, כדי להקל על החולים והמעוברות שמתענים, מנהגינו להחמיר בזה כדי שיהא לילה ממש. (שע\"ה קכ\"ב י')"],["t","האם מותר לטעום קצת קודם קריאת המגילה בלילה וביום?"],["b","אסור לטעום קודם קריאת המגילה שבלילה, וחולים ומעוברות המתענים ופתיחת הצום תקל עליהם בשמיעת קריאת המגילה, יכולים הם לטעום קצת קודם קריאתה, כגון קפה, ושאר משקין, עד שיעור כביצה או פת כביצה."],["b","וכן ביום אסור לאכול קודם קריאת המגילה, אבל המנהג שהנשים שקוראין להן בבית, יכולות לאכול קודם קריאתה. (שע\"ה קכ\"ב י')"]]},{"h":"כז אדר א' יום שבת פרשת ויקהל. פרשת שקלים.","s":"הלכות קריאת המגילה","d":["לעילוי נשמת מארי עואד חזן בן מארי חיים יהודה חסן זצ\"ל | ברכה והצלחה הדס בת לירן","המקובל כמוהר\"ר חיים סינוואני תשל\"ט - אב\"ד חוגריה","כמוהר\"ר סעיד נחום זצוק\"ל תשל\"ב - רב מושב טירת שלום והסביבה"],"b":[["t","מהו הזמן לפי מנהגינו לקריאת המגילה בלילה?"],["b","למנהג הבלדי אחרי שמסיימים 'עלינו לשבח' קוראין את המגילה. ולמנהג השאמי, אחרי 'שמונה עשרה' אומר חצי קדיש, ואז קוראים את המגילה ולאחריה, \"ואומר ואתה קדוש וגו', ואח\"כ קדיש תתקבל וכו'."],["t","האם יש עניין להעמיד שני אנשים על יד הקורא?"],["b","כל הקהל יושבים בשעת קריאת המגילה והברכות, ורק השליח ציבור עומד מפני כבוד הציבור. ואין מנהגינו להעמיד שני אנשים על יד הקורא, אחד מימינו ואחד משמאלו. (שע\"ה קכ\"ב י\"ב)"]]},{"h":"כח אדר א' יום ראשון","s":"הלכות קריאת המגילה","d":["לעילוי נשמת שלום בן סעיד ז\"ל | טל סער יניב מלר שפע רוחני וגשמי לכל בני משפחתם"],"b":[["t","האם יש עניין לכוון בברכת \"שהחיינו\" שעל המגילה גם על מצוות היום?"],["b","יש אומרים שבברכת \"שהחיינו\" יכוונו גם על מצוות משלוח מנות, מתנות לאביונים וסעודת פורים, ולכן שליח ציבור צריך לכוון להוציא את הציבור בברכת \"שהחיינו\" שעל המגילה גם על מצוות אלו. (שע\"ה קכ\"ב י\"ז. עריכ\"ש תרצ\"ב ד', משנ\"ב סי' תרצ\"ב בשם מג\"א. וכ\"כ הגר\"י צוברי בסידורו עמ' ת\"ר)"],["t","מה הדין כאשר שכח לברך ברכת 'שהחיינו' בקריאת המגילה של הלילה?"],["b","אם שכח לברך ברכת 'שהחיינו' בקריאת המגילה של הלילה, יברך ביום קודם קריאתה."],["b","ואם שכח לאומרה גם קודם קריאתה שביום, הפסיד הברכה ולא יברכנה על שאר מצוות היום כיון שאין דין ברכת 'שהחיינו על עצם היום כמו בימים טובים אלא רק על מצוות קריאת המגילה."],["b","וכדאי לדעת שיש חילוק בין 'ברכת שהחיינו' על המגילה לבין 'ברכת שהחיינו' על פרי חדש, שכאשר שכח לברך 'ברכת שהחיינו' על פרי חדש בפעם הראשונה, אינו מברך כן כאשר יאכל בשנית משום שהשמחה על התחדשות הפרי כבר עברה אצלו, משא\"כ בברכת 'שהחיינו' שעל המגילה, ענין הברכה הוא כל משך זמן קיום המצווה ולכן כאשר שכח לברך 'שהחיינו' בלילה, יברך כן ביום שהרי עדיין נהנה מקיום המצווה. (כמבואר בשו\"ע בסי' תרע\"ו א' לעניין 'שהחיינו בנר חנוכה)"]]},{"h":"כט אדר א' יום שני ערב ראש חודש","s":"הלכות קריאת המגילה","d":[],"b":[["t","כיצד הוא אופן קריאת המגילה?"],["b","מנהגינו לקרות המגילה בנעימה עריבה ומהירה, בדקדוק אותיותיה נקודותיה וטעמיה. ובין פסוק לפסוק אין נושמים ואפילו בין פרשה לפרשה, אלא מנעים בטעם שלפני סוף הפסוק, ומסמיך אותו לפסוק שאחריו. וכל זה גם בפסוקי \"חסדי י\"י אזכיר\" שנוהגין אנו לומר לפני הברכות. (שע\"ה קכ\"ב י\"ג)"],["t","האם יש עניין לתת מעות קודם פורים 'זכר למחצית השקל'?"],["b","בשאר קהילות ישראל נוהגין ליתן לעניים מעות קודם פורים 'זכר למחצית השקל', ואצלינו אין נוהג מנהג זה, דחיוב זה רק בזמן שבית המקדש היה קיים, שהיו מחוייבים ליתן ללשכה לקרבן התמיד ולכן היו מכריזים ואוספים המעות מר\"ח אדר, ומכל מקום בזמנינו טוב לעשות כן לחיזוק הישיבות ושאר מוסדות התורה הזקוקים לעזרה, \"כי הם חיינו ואורך ימינו\"."],["s","(שע\"ה קכ\"ב ז', עריכ\"ש תרצ\"ד ז')"]]},{"h":"ל' אדר א' יום שלישי א' דראש חודש","s":"הלכות קריאת המגילה","d":["לעילוי נשמת אהרן בן אברהם"],"b":[["t","מה הטעם שצריך לומר עשרת בני המן בנשימה אחת?"],["b","כיון שעשרת בני המן נהרגו ונתלו כאחד, לכן יש לקוראם בנשימה אחת כדי להודיע על כך. ומכל מקום יש לשים לב לקרוא את כל ה\"ואת\" של עשרת בני המן מתוך הכתב, כדי שהקריאה תהיה לכתחילה הן בזה שקוראם בנשימה אחת, והן בזה שקוראה כולה מתוך הכתב. (שע\"ה קכ\"ב י\"ט)"],["t","מה הדין כשאינו מצליח גם לקוראם בנשימה אחת וגם לקוראם מתוך הכתב?"],["b","אם הוא מכיר את עצמו שאינו מסוגל גם לקוראם בנשימה אחת, וגם לקרוא את כל ה\"ואת\" מתוך הכתב, מפני שמעכבות את קריאתו, עדיף שיאמר את ה\"ואת\" בעל פה, ובכך יספיק לקרוא הכל בנשימה אחת."],["b","וכשנאלץ להפסיק לצורך נשימה, עדיף שיחזור שוב לקוראם בנשימה אחת, אם משער שמסוגל."],["s","(מפי מרן הגר\"י רצאבי)"]]},{"h":"א' אדר ב' יום רביעי ב' דראש חודש","s":"הלכות קריאת המגילה","d":["לרפואה, הצלחה, פרנסה טובה לשחר בן אריה וב\"ב"],"b":[["t","מתי רצוי לגוללה לאחר הקריאה?"],["b","לאחר קריאתה גוללה כולה ומניחה לפניו, ואח\"כ מברך ברכת 'הרב את ריבנו'. ויש אומרים שיכול לגלול אחר הברכה, ויש נוהגין שהשליח ציבור נותנה לאחר לגוללה בעוד שהוא מברך. (שע\"ה קכ\"ב י\"ד)"],["t","מה הדין כאשר איחר לביהכנ\"ס וכבר התחילו בקריאת המגילה?"],["b","אם הגיע באיחור לביהכנ\"ס וכבר התחילו הציבור בקריאת המגילה, יברך מיד את הברכות הראשונות שעל המגילה, ויתחיל לקוראה בדקדוק, מתוך מגילתו הכשרה, עד שידביק את החזן. ואם אין לו מגילה כשרה, יקרא ממגילה פסולה שבידו, עד שיגיע לקצב של החזן, וימשיך לשמוע ממנו, כל זאת בתנאי שישמע יותר מחצי המגילה מהחזן, כדי שתהיה רוב קריאתה ממגילה כשרה."],["b","ואין קריאתו נחשבת כהפסק בין ברכתו לקריאת החזן, כיון שזה כדין כל הפסק שנועד לצורך אותה המצווה, שלא נחשב להפסק בדיעבד. ולכן כיון שזה שעת הדחק ואין לו ברירה אחרת, יכול לעשות כן לכתחילה."],["s","(מרן הגר\"י רצאבי בע\"פ, הליכות מועד אות ה' ע\"פ שו\"ע סי' תר\"צ ס\"ג)"]]},{"h":"ב' אדר ב' יום חמישי","s":"הלכות קריאת המגילה","d":["לעילוי נשמת סעדיה גרמה בן צאלח | ברכה והצלחה להדר בת גלעד | ברכה והצלחה לחיים בן שלום | ברכה והצלחה למשה בן הראל | לרפואה, הצלחה אושר ובריאות לעלמה בת ליטל"],"b":[["t","מה דין אדם שלא היה מרוכז בשמיעת המגילה?"],["b","צריך להשתדל מאוד להיות מרוכז בהקשבתו לכל מילה בסיפור במגילה. ואם אירע שהתנתקה מחשבתו לגמרי, לא יצא ידי חובה."],["b","אך אם תוך כדי שחלם, עקב באצבעו אחר קריאת החזן, וכשמתעורר ממחשבותיו יודע היכן נמצא החזן, יצא ידי חובה בדיעבד, שאין זה ניתוק מוחלט."],["s","(מרן הגר\"י רצאבי בע\"פ, הליכות מועד אות ז')"],["t","מה ראוי לעשות כאשר יצא ידי חובה בדיעבד?"],["b","אדם שלא הצליח להקשיב בריכוז, או שבנו הקטן הסיח דעתו, באופן שיצא ידי חובה רק בדיעבד, כמבואר בהלכה הקודמת, ומעוניין כעת להשלים את אותן המילים או השורות שהפסיד, כדי לצאת ידי חובה לכתחילה. תלוי הדבר; אם יש לפניו מגילה כשירה, ויודע לבטא היטב את המילים, עדיף שיחזור ויקרא משם את אותם המילים או השורות, עד שיתחבר לקריאת החזן. אך אם יש בידו מגילה פסולה או חומש, לא ישלים מהם אלא ימשיך לשמוע את הקריאה מהחזן, כיון שגם במגילה פסולה יוצאים ידי חובה רק בדיעבד, וא\"כ אין בקריאה בה תוספת מעלה ותיקון."],["s","(מרן הגר\"י רצאבי בע\"פ, הליכות מועד אות ז')"]]},{"h":"ג' אדר ב' יום שישי","s":"הלכות קריאת המגילה","d":[],"b":[["t","מה הדין כאשר הפסיק בדיבור לאחר הברכה או באמצע קריאת המגילה?"],["b","אדם שהפסיק בדיבור בין הברכה לקריאה, תלוי הדבר; אם הפסיק בדיבור שלא לצורך המגילה, דינו שווה לאדם שבירך 'ברכת הנהנין' והפסיק בדיבור לפני אכילתו, שצריך לחזור ולברך שנית. ואם הפסיק בדיבור לצורך המגילה, אינו צריך לחזור ולברך. אך אם הפסיק אפילו בדיבור באמצע קריאתה, אף שאין לעשות כן, יצא ידי חובה. רק שיש לו להשלים מיד כמבואר לעיל. (שו\"ע ורמ\"א תרצ\"ב ס\"ב)"],["t","מה הדין כשחיסר באונס מילה אחת משמיעת המגילה?"],["b","אם חיסר אפי' מילה אחת מהמגילה, לרוב הפוסקים לא יצא ידי חובה. ולכן כשיודע שחיסר איזו שהיא מילה, הפתרון הוא להשלים מיד ממגילה כשרה שבידו, או אפילו ממגילה פסולה, עד שידביק את מקום קריאת החזן. וכן הדין כאשר מסופק אם החסיר, שיש לו לעשות כן. (מרן הגר\"י רצאבי בע\"פ, הליכות מועד אות א')"]]},{"h":"ד' אדר ב' יום שבת פרשת פקודי","s":"הלכות קריאת המגילה","d":["לעילוי נשמת אברהם בן אליזבט ושמעון | ברכה והצלחה למיכאל בן הראל"],"b":[["t","מה הדין כשנזכר כן בסיום הקריאה שחיסר מילה אחת מהמגילה?"],["b","אם אירע שבסיום קריאת המגילה מסתפק על איזו מילה אם חיסר אותה או לא, תלוי הדבר; אם מסתפק כן בלילה שחיוב קריאתה מדרבנן, לא צריך שוב לחזור ולקרוא, משום ש'ספק דרבנן לקולא'. ואם מסתפק כן ביום, שחיוב קריאתה מ'דברי קבלה' הנחשבים כ'דברי תורה', חייב לחזור ולקוראה. משום שהכלל הוא 'ספק דאורייתא לחומרא'. (מרן הגר\"י רצאבי בע\"פ, הליכות מועד אות א')"],["t","מה הדין כאשר נאלץ לצאת באמצע קריאת המגילה?"],["b","כאשר נאלץ לצאת באמצע קריאת המגילה בדחיפות, כגון לשירותים, או כשבנו הקטן הפריע והיה צריך לקחתו. אם עדיין לא שמע את רוב המגילה מהחזן, יצטרך לקוראה אחר כך שוב מתחילה, או ימשיך בקריאתה ממגילה כשירה, (ויקפיד לקוראה בדקדוק), ויצא בזה ידי חובה לכתחילה."],["b","אך אם כבר שמע את רוב קריאתה מהחזן, יכול להשלימה אחר כך אפילו ממגילה פסולה כשאין לו מגילה כשירה. וכל זה אפילו כאשר ההפסק היה זמן ארוך של יותר מזמן קריאת המגילה. (מרן הגר\"י רצאבי בע\"פ, ע\"פ שו\"ע תר\"ץ ס\"ב בשונה מפסק הרמ\"א שם)"]]},{"h":"ה' אדר ב' יום ראשון","s":"הלכות קריאת המגילה","d":["לעילוי נשמת מיכל בת שלום ע\"ה | לרפואת שרה ליטל בת סימונה"],"b":[["t","על מה נאמר הגדר 'ברוב עם הדרת מלך'?"],["b","מצווה מן המובחר לשמוע קריאת המגילה בבית הכנסת, במקום שיש ריבוי אנשים משום ש'ברוב עם הדרת מלך', ולכל הפחות במניין עשרה. ואין הכוונה בזה לציבור המתפללים בקביעות במניין מצומצם, שיצטרכו לעקור מקום תפילתם הקבוע וללכת לבית הכנסת גדול יותר, שבוודאי שצריכים המה להתפלל ולקרוא במקומם. אלא הכוונה בגדר זה, לאדם יחיד שאין לו מקום קבוע, ומסתפק היכן לשמוע המגילה, שצריך להעדיף מקום שיש ריבוי עם. ואם נמצאים יחידים במקום שאין אפשרות להשיג מניין, יקרא כל יחיד לעצמו מתוך מגילה כשרה עם הברכות שלפניה, ואפילו את הברכה שלאחריה."],["s","(שע\"ה קכ\"ב י\"א, עריכ\"ש תר\"צ י\"א)"],["t","האם בנשים שייכת המעלה \"ברוב עם הדרת מלך\"?"],["b","אף על פי שאשה חייבת בקריאת המגילה כיון שגם הן היו באותו הנס, אך אינה צריכה להחמיר וללכת לבית הכנסת כדי לקיים את המעלה של \"ברוב עם הדרת מלך\", אלא לכתחילה יכולה לשמוע את המגילה בביתה, ע\"י בעלה, או בקריאה המיוחדת לנשים. (ועוד שלפעמים בשמיעת הקריאה בציבור דרך עזרת הנשים, עלולה להפסיד שמיעת מילה אחת). והטעם שלא חייבו את הנשים בתוספת המעלה של \"ברוב עם הדרת מלך\", כיון ש\"כל כבודה בת מלך פנימה\"."],["s","(מרן הגר\"י רצאבי בע\"פ, חזו\"ע עמ' נ\"ב)"]]},{"h":"ו' אדר ב' יום שני","s":"הלכות קריאת המגילה","d":["לעילוי נשמת יוסף בן אברהם | כרמלה בת יחיאל רפואה שלמה ניסים ונפלאות"],"b":[["t","מה דין הקורא לאשתו או לציבור נשים לאחר מכן?"],["b","אדם שאמור לקרוא לאשתו או לציבור נשים, לא יאמר 'גם ככה אצא ידי חובה בקריאתי אז', ועל ידי זה יתבטל מללכת לשמוע הקריאה שבביהכנ\"ס, אלא ילך קודם לביהכנ\"ס להרוויח את המעלה הגדולה של 'ברוב עם הדרת מלך', ולאחר מכן יקרא להם שוב."],["s","(מרן הגר\"י רצאבי בע\"פ)"],["t","הקורא לנשים האם יברך ברכות המגילה תחילה וסוף?"],["b","הקורא לנשים מברך תחילה וסוף, כיון שגם הן מחוייבות בקריאתה, וממילא גם בברכותיה. אם הפסיקה בדיבור באמצע הקריאה, לא יברך ברכה אחרונה. ואם יודע מראש שקשה להן להיזהר בזה, לא יברך כלל גם ברכה ראשונה."],["s","(שע\"ה קכב ט' ע\"פ אחרונים בסי' תרפ\"ט, מהרי\"ץ בעץ חיים, עריכ\"ש תרפ\"ט א'. וכ\"כ בשם הגר\"י צוברי בס' פסקי הלכות עמ' תל\"ד)"]]},{"h":"ז' אדר ב' יום שלישי","s":"הלכות משלוח מנות ומתנות לאביונים","d":[],"b":[["t","לכמה אנשים צריך לשלוח 'משלוח מנות' ו'מתנות לאביונים' ובמה עדיף להרבות?"],["b","חייב כל אדם לשלוח לכל הפחות לאדם אחד שתי מנות, שכתוב \"ומשלוח מנות איש לרעהו\" משמע שתי מנות לאחד. וכל המרבה לשלוח מנות לעוד רעים הרי זה משובח. 'ומתנות לאביונים' לכל הפחות לשני אביונים, שנאמר \"ומתנות לאביונים\", ומיעוט רבים שניים, וגם עני מחוייב בזה. (ומתנות לאביונים יכול ליתן גם לאביון קטן, מה שאין כן במשלוח מנות שנאמר 'איש לרעהו' - איש כמותו)."],["b","ומוטב להרבות במתנות לאביונים, מלהרבות בסעודתו ובמשלוח מנות לרעים, כי אין שמחה גדולה ומפוארת לפני הקדוש ברוך הוא, אלא לשמח לב עניים, יתומים,"],["b","ואלמנות. (שע\"ה קכ\"ג א' ג'. עריכ\"ש תרצ\"ה י\"א תרצ\"ד א')"],["t","האם מותר לשלוח מנות למי שאינו מברך?"],["b","הנותן משלוח מנות למי שאינו מברך, עובר משום 'לפני עוור לא תתן מכשול' ולכן אין לתת משלוח מנות למי שוודאי לא יברך, אבל אם אין זה וודאי, מותר לתת לו. ובמקרה שיש צורך משום דרכי שלום כגון שזה שכן שעלול להיפגע אם לא יתן לו, יש להקל לתת לו. וטוב שירמוז לו על הברכה או שיכתוב על המוצרים את ברכתם או שיזכיר זאת בפתק האיחולים. (שע\"ה קכ\"ג ד')"]]},{"h":"ח' אדר ב' יום רביעי","s":"הלכות משלוח מנות ומתנות לאביונים","d":["לעילוי נשמת רבקה טפחא בת מלכה"],"b":[["t","האם אפשר לצאת ידי חובת משלוח מנות באוכל שאינו ראוי לאכילה כמות שהוא?"],["b","יש בזה מחלוקת. והעיקר להלכה, שלא נקרא 'מנות', אלא דבר שראוי לאוכלו כמות שהוא בלי תיקון, כגון בשר ודגים מבושלים, ולא חיים."],["s","(שע\"ה קכ\"ג ב'. עריכ\"ש תרצ\"ה י\"א)"],["t","האם מותר לשלוח מנות בכלי שאינו טבול?"],["b","מקובל היום שיש השולחים את ה'משלוח מנות' בתוך כלי חדש מזכוכית כתוספת מתנה והשלמת העיצוב, ועל אף שכלי זה אינו טבול, אין בעיה בנתינה באופן זה. כיון שהדין הוא שכלי הנקנה מגוי לסחורה, או על לאדם אחר במתנה, לא רק שאין מועילה מנת ליתנו בו טבילה, אלא גם לא תעזור לו טבילה, כיון ששינוי הכלי משם גוי שעליו, לשם ישראל, צריך להיעשות ע\"י הישראל המטבילו לצורך אכילה לעצמו, ולא לצורך מתנה לאחר. ולכן לא יועיל שהנותנו יטבילנו, ולאחר מכן יצרפו למשלוח המנות כיון שעדיין אין חיוב טבילה על כלי זה."],["b","אך צריך לשים לב לצרף ב'משלוח המנות' פתק שבו יכתב 'לא טבול', כדי שהמקבל יזהר לא להשתמש בו לפני הטבלתו. (מרן הגר\"י רצאבי בע\"פ)"]]},{"h":"ט' אדר ב' יום חמישי","s":"הלכות משלוח מנות ומתנות לאביונים","d":[],"b":[["t","האם מותר להטביל את הכלי לפני אריזתו למשלוח המנות?"],["b","אם בכל זאת מעוניין השולח להטביל הכלי כדי להקל על המקבלו, (בפרט כאשר יודע שהמקבל לא יקפיד להטבילו), צריך שיאמר לאדם אחר שיזכה בכלי זה עבור אותו פלוני שאמור לקבלו, ואז יוכל הנותן להטבילו ובברכה."],["b","אלא שישים לב גם במקרה זה, לצרף פתק קטן בו ייכתב 'הכלי טבול', כדי שידע מכך המקבלו, ולא יטבילנו שוב. ובכך גם לא יכשל בברכה לבטלה. ראוי לציין שאם המקבל חושש שהנותן הטבילו שלא באופן הנכון כמתבאר, יטבילנו שוב, אך ללא ברכה."],["s","(מרן הגר\"י רצאבי בע\"פ)"],["t","האם מותר להניח אוכל ללא כיסוי בכלי שאינו טבול?"],["b","כל האמור לעיל בשליחת המנות בכלי שאינו טבול, הוא דווקא כאשר האוכל מונח בכלי כשהוא עטוף בכיסוי. אבל אין להניח לכתחילה אוכל גלוי בתוך כלי שאינו טבול, על אף שעדיין לא נתחייב בטבילה. ואם עשה כן, אין בעיה לאכול את המאכל שהונח שם, אלא שיעבירנו המקבל לכלי אחר. (מרן הגר\"י רצאבי בע\"פ)"]]},{"h":"י' אדר ב' יום שישי","s":"הלכות קריאת פרשת זכור","d":["שוהם בת תומר עוזירי ברכה והצלחה רוחיות וגשמיות"],"b":[["t","כיצד נקראת השבת שלפנינו ומהו סדר קריאתה?"],["b","השבת שלפנינו נקראת \"שבת זכור\", ומוציאין שני ספרי תורה וקורין בראשון שבעה פרשת השבוע, ובשני קורא אחד \"זכור\" (שבסוף פרשת כי תצא) ומפטיר \"ותהי המלחמה\". (שע\"ה קכ\"א ב')"],["b","ובשאר קהילות ישראל מקפידים בזה להוציא הספר תורה היותר מוגה ומהודר, ואצלינו לא נהגו בזה."],["s","(למנהגינו: האות ז' בתיבת \"זכר\" עמלק בניקוד צירי, והוא הנכון, ואין חוששין כלל להסוברים שהוא בניקוד סגול. (שע\"ה קכ\"א ג')"],["t","מצוות קריאת \"פרשת זכור\" מדאורייתא או מדרבנן?"],["b","יש האומרים שחובת קריאת \"פרשת זכור\" מדאורייתא, והרבה פוסקים סוברים שאינה אלא מדרבנן, וכן נראה דעת רבינו הרמב\"ם. ולכתחילה אין להעלות קטן, כדי לחוש להסוברים שחובת קריאתה מדאורייתא. ואם כבר עלה קטן אין להורידו, רק יש להזהיר לציבור שיאמרו עמו בלחש מילה במילה. (שע\"ה סי' קכ\"א ג'. עריכ\"ש תרפ\"ה א' ורפ\"ב י\"א)"]]},{"h":"יא אדר ב' יום שבת פרשת ויקרא. פרשת זכור","s":"הלכות קריאת פרשת זכור","d":[],"b":[["t","האם נשים חייבות לשמוע קריאת \"פרשת זכור\"?"],["b","הנשים פטורות מלשמוע קריאת \"פרשת זכור\". וכן המנהג שאינן באות לבית הכנסת. ואם רוצה להחמיר על עצמה, תקרא בביתה מתוך החומש. (שע\"ה קכ\"א ד'. עריכ\"ש תרפ\"ה א'. וכ\"כ בשם הגר\"י צוברי בס' פסקי הלכות עמ' תכ\"ו)"],["t","האם מותר לעשות מלאכה ביום פורים?"],["b","מנהגינו שלא לעשות מלאכה ביום הפורים, (דהיינו הפרזים בי\"ד והמוקפים בט\"ו). ומי שעושה בו מלאכה, אינו רואה מאותה מלאכה סימן ברכה לעולם, ומנדים אותו. ועל ידי גוי מותר. אך לצורך פורים, מותר לעשות אפילו מלאכות גמורות. (שע\"ה קכ\"ג ח')"]]},{"h":"יב אדר ב' יום ראשון","s":"הלכות תענית אסתר ומקרא מגילה","d":["לעילוי נשמת נח בנימין בן מנשה ז\"ל"],"b":[["t","האם כולם חייבים לצום ב'תענית אסתר'?"],["b","אין תענית זו חובה כל כך כמו ד' תעניות הידועות. ולכן יש להקל בה, לא רק למעוברות, ומניקות, ולחולה שאין בו סכנה, וכן ליולדת שאינה מניקה כל 30 יום, אלא אפילו רק כואבי עיניים, אם הם מצטערים הרבה, לא יתענו. אלא שהם (כואבי עיניים), צריכים לפרוע את התענית ביום אחר. וחתן וכלה בתוך שבעת ימי המשתה לא צריכים להתענות. אבל שאר הבריאים לא יפרשו מן הציבור. (שע\"ה קכ\"ב ב')"],["t","מהן הערים המוקפות חומה מימות יהושע בן נון וכיצד ינהגו בהן לגבי קיום מצוות הפורים?"],["b","כרכים המוקפים חומה מימות יהושע בן נון כגון ירושלים, קורין בהן את המגילה בט\"ו באדר (שושן פורים דפרזים). וכן קיום שאר מצוות היום בתאריך זה. וישנן ערים שספק מוקפות חומה מימות יהושע בן נון. (ואלו הן: טבריה, צפת, חברון, עכו, יפו.) ומחמת כן מקיימים את כל המצוות של הפורים בי\"ד כבכל הפרזים. ורק לעניין קריאת המגילה, קוראים שם מספק גם בט\"ו כדין מוקפות, וללא ברכה. (שע\"ה קכ\"ג י\"א ובהערה כ\"ח. עריכ\"ש תרפ\"ח א' ב'):"]]},{"h":"יג אדר ב' יום שני. תענית אסתר","s":"הלכות סעודת פורים","d":["עדיאל בן רביד לרפואתו והצלחתו | אור בן יפה רפואה שלימה ניסים ונפלאות"],"b":[["t","מתי הוא זמן סעודת פורים על פי מנהגינו?"],["b","עיקר זמן סעודת פורים הוא ביום, שנאמר \"ימי משתה\". (ובכל אופן גם בלילה יש עניין לשמוח ולהרבות קצת בסעודה). ומנהגינו לעשותה לפני הצהריים, כדרך שעשתה אסתר הסעודה בשחרית. וכשאין מתאפשר כן, ובפרט כיום שמרבים במשלוח מנות ושאר המצוות, ומתעכבין כלל המסובין והאורחים בהגעתם לסעודה, עד לשעות הצהריים. יכוון בארוחת הבוקר על הפת, שתהיה לשם סעודת פורים, ובזה יצא ידי חובת המנהג. (שע\"ה קכ\"ג ה' עריכ\"ש תרצ\"ה ג')"],["t","מהו גדר החובה של שתיית יין?"],["b","כיוון שכל הנס היה ע\"י יין, המלכה ושתי נטרדה במשתה היין, ובאה אסתר במקומה. וכן עניין המן ומפלתו, היה ע\"י יין. לכן חייבו חכמינו ז\"ל להרבות בשתיית יין, 'עד דלא ידע בין ארור המן לברוך מרדכי'."],["b","ולפחות ישתה יותר מהרגלו כדי לזכור את הנס הגדול, ויישן, ומתוך שישן, אינו יודע בין ארור המן לברוך מרדכי. מי שיודע בעצמו שעל ידי כך יזלזל חס ושלום באיזו מצווה, בברכה, או בתפילה, מתוך קלות ראש, מוטב שלא יתבסם, וכל מעשיו יהיו לשם שמים. (שע\"ה קכ\"ג ו'. עריכ\"ש תרצ\"ה ז')"]]},{"h":"יד אדר ב' יום שלישי. פורים.","s":"הלכות פורים","d":["לעילוי נשמת סלימאן בן סעיד ג'מיל ז\"ל"],"b":[["t","מה הדין אם שכח לומר על הניסים בתפילה?"],["b","אם שכח אמירת \"על הניסים\" בברכת מודים, אם נזכר קודם שאמר ברוך אתה ה' שבחתימת הברכה, חוזר ומתחיל \"על הניסים\". ואם כבר אמר את ה', גומר את הברכה, ואינו חוזר. וכן בברכת המזון אם כבר הזכיר את שם ה' בברכת \"על הארץ ועל המזון\" מסיימה ואינו חוזר. (עריכ\"ש תרפ\"ב א')"],["t","האם יש עניין להדליק נרות בסעודת פורים?"],["b","כתב המהרי\"ץ שבזמן הסעודה ראוי להדליק נרות שעווה דרך שמחה, ואפשר ליתן לזה טעם על פי מה שכתב (בשער הכוונות ענייני פורים ל-) האר\"י, שביום זה מתחדשת הארה גדולה עד מאוד, שאין אפילו בשבתות וימים טובים. (קכ\"ג ה')"]]},{"h":"טו אדר ב' יום רביעי. שושן פורים.","s":"הלכות פורים","d":["לעילוי נשמת משה בן הרב שלום יצחק ז\"ל | לעילוי נשמת רומיה בת מוסא גיאר | גדעון בן יחיאל רפואה שלימה ניסים ונפלאות | לרפואה, הצלחה, אושר ובריאות לאביתר בן ליטל"],"b":[["t","האם הפרזים אומרים תחנון ביום טו' באדר?"],["b","גם אצל הפרזים שאצלם הוא נקרא 'שושן פורים', אין נפילת אפיים ולא אמירת 'אל ארך אפיים' ו'למנצח' ואסור גם בהספד ותענית. וי\"א שחייבים בו קצת משתה ושמחה (ע\"פ שת\"ז שהביא לרמ\"א) אבל אין אומרים בו על הניסים. (שע\"ה קכ\"ג ט')"],["t","שואלין ודורשין בהלכות הפסח קודם לפסח שלושים יום:"],["b","משה רבינו תיקן להם לישראל, שיהיו דורשים בהלכות פסח בפסח, ובהלכות עצרת (דהיינו שבועות) בעצרת, והלכות חג (דהיינו סוכות) בחג. והלכות פסח צריך להקדים לשאול ולדרוש קודם לפסח שלושים יום, מפני שהלכותיו מרובות. וצריכים כולם לדעת איך יתנהגו בדברים שאין להם תקנה בתוך הפסח, כגון ביעור החמץ והגעלה הכלים. לפיכך מנהגינו ללמוד בציבור מאז הלכות פסח. וטוב להתחיל ביום פורים עצמו כמו שהעלו האחרונים. (שע\"ה סי' פ' א' והערה ב')"]]},{"h":"טז אדר ב' יום חמישי","s":"הלכות פסח","d":["לעילוי נשמת מרים בת סלאם"],"b":[["t","האם מותר להשהות בפסח תערובת חמץ?"],["b","כל דבר שיש בו תערובת חמץ, ואפי' יש בו רק טעם מהחמץ, כגון שהסירו את החמץ אסור להשהותו בפסח. אבל דבר שאין בו חמץ, ורק נתבשל או נכבש קודם הפסח בכלי חמץ אפי' בן יומו, מותר להשהותו בפסח."],["s","(סי' פ\"ב ס\"א)"],["t","כיצד מכשירים כלים לפסח?"],["b","בהגעלת כלים הכלל הוא, \"כבולעו כך פולטו\" כלומר אם השימוש על ידי משקה ועל האש כמו סירים, צריך להגעיל על ידי משקה ועל האש. ואם זה בכלי שני, דהיינו לא על האש באופן ישיר, כגון צלחות כפות ומזלגות, מספיק להכשירו בכלי שני. (שע\"ה סימן פ\"ד ס\"ג)"]]},{"h":"יז אדר ב' יום שישי","s":"הלכות פסח","d":[],"b":[["t","האם ניתן להכשיר את הסיר של הכובאנה ואם כן כיצד?"],["b","דרך הכנת הכובאנה היא רק עם תוספת קצת שמן, ונכנסנו למחלוקת האם הכשרתו על ידי הגעלה, או שצריך דווקא ליבון באש, ולכן טוב יותר לא להשתמש בסיר זה בפסח, כיון שהוא יתקלקל בליבון. אבל הרוצה להגעיל ולהשתמש, יש לו על מי שיסמוך."],["s","(עול\"י ח\"ב סימן ק\"כ)"],["t","האם, ואיך, ניתן להכשיר את המיקרוגל לפסח?"],["b","במיקרוגל עדיף לא להשתמש אבל אנשים הזקוקים לו מאוד ולא ישמעו להצניעו צריכים: א) לנקות אותו היטב מכל השאריות שבו. ב) להמתין 24 שעות. ג) להכניס קערה עם מים בכמות מספיקה שלא יתאדו מהר וייגרם נזק למכשיר, שיש בה חומר ניקיון לא אקונומיקה כדי שלא ייגרם נזק או סכנה ד) יפעיל אותו בערך 10 דקות, וישתמש בו בפסח רק בכלים סגורים. (נזר המועדים עמ' ע\"ב, הליכות מועד עמ' ע\"ו)"]]},{"h":"יח אדר ב' יום שבת פרשת צו. פרשת פרה.","s":"לעילוי נשמת חסן בן יצחק מעטוף ז\"ל","d":[],"b":[["t","דיני פרשת פרה"],["b","השבת \"פרשת פרה\" מוציאים ב' ספרי תורה, בראשון קורים ז' גוברי בפרשת השבוע ובשני קורין בתחילת פרשת חוקת עד \"תטמא עד הערב\" ומפטיר ביחזקאל \"בית ישראל יושבים על אדמתם\". (שע\"ה סי' קכ\"א ס\"ב)"],["t","האם קריאת \"פרשת פרה\" היא מדאורייתא?"],["b","יש אומרים שקריאת \"פרשת פרה\" היא מדאורייתא ועל כן אין קורין בה קטן למפטיר, אך הרבה פוסקים סוברים שקריאתה מדרבנן וכן נראה דעת רבינו הרמב\"ם, ומכל מקום יש לחוש לפוסקים הסוברים שקריאתה מדאורייתא ולכתחילה לא יעלו קטן, ואם כבר עלה הקטן, יזהירו את הציבור לומר עמו מילה במילה. (שם ס\"ג)"]]},{"h":"יט אדר ב' יום ראשון","s":"הלכות פסח","d":[],"b":[["t","מה דין הקטניות בפסח?"],["b","כל מיני הקטניות והאורז המנהג פשוט כפי הדין שמותרים לאכול בפסח בין לקלייה בין לבישול, אך יש לברור אותם היטב מחשש תערובת מיני דגן, וכן לחקור אם לא נארזו במקום שאורזים גם קמח. (סי' פ\"ג ס\"ד)"],["t","מה הדין לגבי גרעיני החילבה?"],["b","גרעיני ה\"חילבה\" הם דבר ששכיח שיימצא בהם חיטים, ולכן יש ליזהר מאוד לבודקם היטב אחד אחד במקום שיש הרבה אור, כי החיטים דומים מאוד לחילבה, וראוי לבדוק כמה פעמים, וכן לטחון קודם הפסח. (שם)"]]},{"h":"כ' אדר ב' יום שני","s":"הלכות פסח","d":["לעילוי נשמת עמיקם בן שלום ודבורה עותיני ז\"ל"],"b":[["t","מצא חמץ בביתו בפסח מה יעשה?"],["b","אם מצא בחול המועד, יוציאנו וישרפנו בלא ברכה ואפילו אם הוא מצא יותר מכזית. ואם מצא בשבת או ביו\"ט שאסור לטלטלו משום מוקצה, יכפה עליו כלי עד מוצאי שבת או יו\"ט ואז ישרפנו."],["s","(פ\"א ט\"ז, ערי\"ש תל\"ה ב', ותמ\"ו א')"],["t","עד מתי אפשר לאכול מצה לפני פסח ומי שייך באיסור?"],["b","עד ליל בדיקת חמץ מותר לאכול מצה, והלילה בכלל ההיתר. ורק מעמוד השחר של ערב פסח אסור לאכול מצות, ואפילו להאכיל ילדים וילדות קטנים אסור, בתנאי שהם מבינים מעניין יציאת מצרים. אבל אם אינם מבינים מותר להאכילם, ושיעור הגיל הוא בערך גיל חמש."],["s","(שע\"ה סימן פ\"ח סעיף ב' ושערי יצחק פרשת ויקרא תשפ\"א)"]]},{"h":"כא אדר ב' יום שלישי","s":"הלכות פסח","d":["לעילוי נשמת חבצלת בת סעדיה ושולמית"],"b":[["t","על איזה מצות נאמר האיסור לאכלם בערב פסח?"],["b","האיסור נאמר על מצות שאפשר לצאת בהם ידי חובה בליל הסדר, ולכן 'מצה עשירה' מותר לאכול עד שעה עשירית, אבל מצה שלא 'שמורה' משעת קצירה אסור לאכול בערב פסח כל היום, והוא הדין 'מצות חמץ' המצויות בזמנינו שאסורות כל היום."],["s","(שו\"ת עולת יצחק ח\"א סי' ס\"ב אות ג' סוף ד\"ה ומפורש, ומפי הרב)"],["t","האם מותר לאכול בערב פסח מאכלים הנעשים מקמח מצה?"],["b","עוגה או עוגיות הנעשות מקמח מצה מותר לאכלם בערב פסח עד שעה עשירית, כיון שאין עליהם צורת מצה, שהמצה נטחנה לגמרי לכדי קמח, אבל מאכל הנעשה ממצה המפוררת לחתיכות גדולות אסור לאכול כיון שיש על זה צורת מצה."],["s","(זה\"ש סי' תע\"א הע' ט\"ז ע\"פ שערי יצחק פרשת ויקרא התשפ\"א)"]]},{"h":"כב אדר ב' יום רביעי","s":"הלכות פסח","d":["לע״נ אחי חיים בן ר׳ סעדיה ושרה חתוכה ז״ל"],"b":[["t","האם אומרים קרית שמע שעל המיטה בליל הסדר?"],["b","מה שנוהגים האשכנזים שאין קורין כל סדר קרית שמע שעל המיטה רק פרשת \"שמע\" \"וברכת המפיל\", להורות שהוא 'ליל שימורים' מן המזיקים ואין צריך שמירה, אינו נהוג אצלינו אלא אומרים כבשאר ימים."],["s","(שע\"ה סימן צ\"א סעיף כ\"ב)"],["t","האם אפשר לצאת ידי חובת מצה בליל הסדר במצה עשירה?"],["b","מצה עשירה, דהיינו שלשו קמח עם מי פירות, אינה מחמיצה אפילו אם השהו את הבצק כל היום, אבל אין יוצאים בה ידי חובת מצה בליל הסדר לכזית ראשון משום שצריך 'לחם עוני', דהיינו לחם הנעשה בדרך עניות שזה קמח ומים בלבד, ולא בדרך עשירות שהוא נילוש במי פירות. (שע\"ה סימן פ\"ז סעיף י\"ט)"]]},{"h":"כג אדר ב' יום חמישי","s":"","d":["להצלחה ברו\"ג ובשלום בית לזוהר חיים בן דקל"],"b":[["t","בעניין מצות 'הסיבה', ולאיזה צד מיסב האיטר?"],["b","יכין מושבו מבעוד יום במצעות נאות וחשובות כפי יכולתו ובאופן שיוכל להטות ולהסב בשמאלו. ואפילו הוא איטר, יסב לצד שכולם מסבים אליו, ואם היסב לצד ימינו לא יצא ידי חובה."],["s","(מהרי\"ץ בעץ חיים ח\"ב דף י': ד\"ה כל, שת\"ז סי' תע\"ב סק\"ד)"],["t","מי שפטור 'מהסיבה' האם יכול לשתות או לאכול בעמידה?"],["b","יש מפוסקי זמנינו שכתבו לחדש שאשה שפטורה מהסיבה חייבת לאכול או לשתות דווקא בישיבה, כי לאכול מעומד זה דרך העבדים (ירושלמי ריש ערבי פסחים). אבל דברים אלו הם בגדר חידוש, ומי שפטור מהסיבה יכול לשתות ולאכול בכל אופן שירצה, אלא שמדין דרך ארץ לא יאכל וישתה בעמידה."],["s","(שו\"ת נתונים המה ע\"פ מהר\"י רצאבי שליט\"א)"]]},{"h":"כד אדר ב' יום שישי","s":"הלכות פסח","d":["לעילוי נשמת נעמי בת סליימאן | לעילוי נשמת שרה בת שמעה | ברכה והצלחה לישראל בן אבשלום כהן"],"b":[["t","בן אצל אביו האם חייב 'בהסיבה' ואם כן באיזה אופן?"],["b","בן אצל אביו צריך 'הסיבה' למרות שהוא חייב בכבודו ובמוראו של האב, כיון שמסתמא מוחל האב על כבודו ומוראו בעבור המצווה, וזו הסיבה גם שמותר לבן 'להסב' לצד של האב ולא חוששים, כיון שדרכו של האב לא להקפיד, ואם האב 'מקפיד' ולא מוחל על כבודו, אסור לבנו להסב. (זה\"ש סי' תע\"ב הע' י\"ג י\"ד)"],["t","האם מותר לאכול קודם הבדיקה, ומה הדין כשהגיע כבר זמן הבדיקה?"],["b","חצי שעה קודם הבדיקה אסור לאכול סעודה של פת או עוגה יותר משיעור כביצה (בערך 50 גרם) אבל לאכול פת עד שיעור זה, מותר. ופירות וירקות מותר אפילו יותר מכביצה, וכן תבשיל מחמישה מיני דגן כל עוד שלא קבע עליהם סעודה וכיוצא בזה, מותר. וכן לשתות כוס קפה או תה. (מועדי ה' דיני בדיקת חמץ הל' ט' זה\"ש סי' תל\"א הע' ה')"]]},{"h":"כה אדר ב' יום שבת פרשת שמיני. פרשת החודש","s":"הלכות פסח","d":[],"b":[["t","האם צריך לכבות את אור החשמל קודם בדיקת חמץ?"],["b","מן הדין אין צורך לכבות כיון שהאור עוזר ומסייע א בטיהרא מאי' מהני רג לבדיקה, ולא שייך לומר 'ש כיון שאור הנר נצרך לחורים ולסדקים ולפינות הבית וכיוצא בזה שאלו מקומות שיש בהם צל ואין אור החשמל מאיר שם, אלא שיש מחמירים לכבות."],["s","(זהב שבא סימן תל\"ג הערה א')"],["t","האם מותר לבדוק על ידי פנס, ואם כן האם יברך?"],["b","במקומות שיש לחוש לשריפה כגון בתוך מכוניות, ארונות, ותחת רהיטים הסמוכים לארץ, לכתחילה יבדוק לאור פנס בדווקא, כדי שיוכל לבדוק היטב בחורים ובסדקים, אלא שמתחילה יברך ויתחיל לבדוק על ידי נר במקומות שאפשר על ידי נר, ואח\"כ ימשיך הבדיקה על ידי פנס במקומות שיש חשש שריפה."],["s","(זהב שבא שם, שו\"ת נתונים המה סימן קל\"ט)"]]},{"h":"כו אדר ב' יום ראשון","s":"הלכות פסח","d":["לעילוי נשמת יחיא סעיד בן סעיד ענקי"],"b":[["t","מהו זמן בדיקת חמץ?"],["b","זמנה בליל י\"ד מיד בתחילת הלילה לאחר התפילה, ואם בדיעבד בדק חמץ קודם צאת הכוכבים אחר השקיעה, יצא ידי חובה. אבל נכון לבדוק עוד זמן מה אחר צאת הכוכבים. (מועדי ה' דיני בדיקת חמץ הל' ו')"],["t","כיצד יעשה מי שעדיין לא התפלל ערבית וכבר הגיע זמן הבדיקה?"],["b","ואם עדיין לא התפלל ערבית והגיע זמן הבדיקה, יקדים להתפלל ערבית ואחר כך יבדוק, שתדיר ושאינו תדיר קרית שמע מדאורייתא ובדיקת תדיר קודם. ועוד ש חמץ מדרבנן, וראוי לומר לאחר שיזכיר לו לבדוק אחר תפילתו. (מועדי ה' דיני בדיקת חמץ הל' י')"]]},{"h":"כז אדר ב' יום שני","s":"הלכות פסח","d":["הדס בת לירן"],"b":[["t","כיצד ינהג מי שסיים את הבדיקה, ושכח לבדוק עוד מקומות שמחויב לבדקם?"],["b","אם כבר אמר את נוסח הביטול ורק לאחר מכן נזכר שלא בדקם, כיון שהסיח דעתו מהבדיקה הראשונה, צריך לברך שנית כשחוזר לבדקם, אבל אם לא אמר את נוסח הביטול יכול לחזור ולבדקם על סמך ברכתו הראשונה אם לא הסיח דעתו בינתיים לדברים אחרים. (זה\"ש סימן תל\"ב הערה ז')"],["t","האם צריך לבדוק את הספרים מחמץ?"],["b","אין נוהגים לבדקם כלל ואפילו שלא לאור הנר. אבל נראה שראוי להחמיר על כל פנים לבדוק ספרים שרגיל להשתמש בהם בשעת הסעודה. ומה שלא נהגו אבותינו לבדקם, מפני שבתימן לא היו רגילים להביא ספרים בזמן האוכל מה שאין כן בזמנינו. (שע\"ה סימן פ\"א עינ\"י ו')"]]},{"h":"כח אדר ב' יום שלישי","s":"הלכות פסח","d":["לעילוי נשמת מנחם ישראל בן ישורון הלל ז\"ל | לעילוי נשמת נחמיה בן לוי בוני ז\"ל | לעילוי נשמת שלום בן מארי סעיד עורקבי | לעילוי נשמת שמעה הלל בת מוסא"],"b":[["t","מאימתי אסור לעשות מלאכה בערב פסח, ואילו מלאכות נאסרו?"],["b","אחרי חצות היום אסור לעשות מלאכה גמורה, כגון תפירת בגדים חדשים. ותספורת, והיא אסורה אפילו לקטן למרות שבחול המועד מותר לספר קטן. וכביסה אסורה, אלא שאפשר להקל להפעיל מכונת כביסה קודם חצות, אף שתמשיך לפעול אחר חצות."],["s","(שע\"ה סימן פ\"ח סעיף ה' הע' י')"],["t","עוד בעניין תספורת בערב פסח:"],["b","מה שאמרנו שאסור להסתפר זהו דווקא על ידי אחר, אבל המספר עצמו יש להקל בשעת הצורך כיון שזה לא מוגדר כמלאכה אלא כמסדר עצמו, ולכן מי שלא הספיק להסתפר עד חצות, יכול לספר עצמו בשעת הצורך. והוא הדין שיכול להסתפר על ידי ישראל שאין לו מה שיאכל בהרווחה, ויעשה זאת בצינעא."]]},{"h":"כט אדר ב' יום רביעי ערב ראש חודש","s":"הלכות פסח","d":["הרה\"ג זכריה מדר הלוי זצוק\"ל - תשכ\"ז"],"b":[["t","מה כן מותר לעשות לאחר חצות?"],["b","מנהגינו להתיר לקצוץ ציפורניים אחר חצות בכל אופן. מותר לגהץ בגדים אחר חצות. סידור זקן שנהוג בזמנינו שכל אחד עושה לעצמו בביתו, מותר. פרקמטיא = קנייה ומכירה אינה בכלל מלאכה ומותרת בכל המקומות עד חצות. מותר לצחצח נעליו במשחה אפילו לאחר חצות. (זה\"ש הערות ו', ט', יא', יח')"],["t","האם מותר לברך ברכת האילנות בשבת?"],["b","מותר לברך ברכה זו ביום השבת ויש המחמירים לדחותה ליום חול, אבל אם חל ראש חודש ניסן בשבת מידת הזריזות גוברת על כל החששות שהזכירו הפוסקים, בפרט שנמצאים עמו ביום השבת הרבה מן המתפללים לעומת ימות החול."],["s","(נזר המועדים עמ' ה', מועדי ה' הל' ברכת האילנות ס\"ד)"]]},{"h":"א' ניסן יום חמישי ראש חודש. ברכת האילנות.","s":"הלכות פסח","d":["לעילוי נשמת קמר בת סאלם הלל ז\"ל | משפחת אהרון בריאות, הצלחה, פרנסה | ברכה והצלחה לישעיה בן סאלם יעיש | ברכה והצלחה ורפואה שלימה למאור בן שלמה | לרפואה הצלחה, פרנסה טובה ובריאות לרחל בת סביחה","כמוהר\"ר יחיא צארום תרע\"ז - מרבני צנעא ירושלים"],"b":[["t","האם נשים צריכות לברך ברכת האילנות?"],["b","נשים פטורות מהברכה הזאת, מצד 'כל כבודה בת מלך פנימה'. ולא מתאים שתלכנה לחפש עצים אלא אם כן מזדמן לה דהיינו שעברה וראתה עץ וזה לא פוגע בצניעות אדרבה שתברך אבל ללכת באופן מיוחד או לעשות אסיפה של נשים, וודאי שלא."],["s","(שערי יצחק שנת תש\"ע פרשת ויקה\"פ - החודש)"],["t","מי שראה עץ בלבלובו האם יברך מיד או יחכה ל'ברוב עם הדרת מלך'?"],["b","מברך ברכה זו תכף כשרואה את הלבלוב אפילו בעודו יחידי, ולא ידחה את הברכה לזמן אחר שיהיו עמו ריבוי אנשים, ש'זריזים למצוות' קודם ל'ברוב עם הדרת מלך'. (נזר המועדים עמ' ו', יחוה דעת חלק ד' סי' יח בהערה)"]]},{"h":"ב' ניסן יום שישי","s":"הלכות פסח","d":["כמוהר\"ר חיים יצחק הלוי זצוק\"ל - רב העיר הרצליה"],"b":[["t","אילו קטעי תפילה מדלגים בחודש ניסן?"],["b","בכל חודש ניסן אין נופלין על פניהם, ואין אומרים וידוי ותחנונים, וכן \"א-ל ארך אפיים\" בהוצאת ס\"ת ו\"למנצח יענך\". וכן אין אומרים \"צדקתך\" בשבתות במנחה למנהג השאמי, ולמהרי\"ץ אין אומרים \"צדקתך\" רק ביום שיש בו הלל וכן מנהג הבלדי. וסימנך, ביום שיש בו דו\"ץ לשון דיצה והלל, אין אומרים צו\"ץ 'צדקתך' 'וצדקתך' 'צדקתך'. (שע\"ה סימן פ' סעיף ב')"],["t","מהו סדר הקערה?"],["b","טוב שלפני בעה\"ב יניחו קערה לפי הסדר שכתב מהרי\"ץ, שיש לסדר את המינים באופן שלא יצטרך להעביר על המצוות דהיינו הכרפס לפניו ממש, החרוסת סמוך לו מן המצה, והמצה מן המרור, והמרור יותר מהבשר והביצה. (שע\"ה סימן צ' סעיף ח')"]]},{"h":"ג' ניסן יום שבת פרשת תזריע","s":"הלכות פסח","d":["לעילוי נשמת שלמה שאקי בן דוד ושמעה"],"b":[["t","מה צריך להקפיד באכילת המרור?"],["b","השולחן ערוך הכריע שמי שבלע את המרור לא יצא ידי חובה, כיון שצריכים לטעום את טעם המרור וכשבולעים הוא לא מורגש, על פי זה כתב מהרי\"ץ שיש להקפיד ללעוס את המרור היטב, ואם לא כן הרי הוא בלע מרור שאנו יוצא ידי חובה."],["s","(אגדתא דפסחא עץ חיים, שע\"ה סימן צ\"א סע' י\"ח)"],["t","כיצד היא מצות 'כורך'?"],["b","לאחר אכילת המרור נוטלים כולם כזית מצה וכזית מרור והמנהג הוא לשים את המצה בפנים ואת המרור מבחוץ שהרי כך היה הסדר: קודם כל מררו אותם ולאחר מכן הייתה המצה ביציאת מצרים, ואומרים הנוסח '(בלא ברכה) זכר למקדש...) ולאחר מכן מטבלים בחרוסת כך הוא מנהגינו, ואוכלים בהסיבה."],["s","(שע\"ה סימן צ\"א סעיף יח, זה\"ש סימן תע\"ה הע' ט'.)"]]},{"h":"ד' ניסן יום ראשון","s":"הלכות פסח","d":["לעילוי נשמת רחל בת יהודה | זרע של קיימא לאסנת בת יואב | ברכה והצלחה למשה בן אבישלום כהן"],"b":[["t","כיצד הוא אופן הכנת החרוסת?"],["b","החרוסת בשעת עשייתה צריכה שתהיה עבה זכר לטיט, ולפני הטיבול ישפוך לתוכה יין, או מיץ ענבים, או חומץ, כדי שתהיה ניגרת כמים זכר לדם וגם שתהיה ראויה לטבל בה ובפרט למנהג הבלדי לברך על הטיבול הראשון בחרוסת. (שע\"ה סימן צ' סעיף י')"],["t","במה ירכך את החרוסת לפני שמטבלים בה?"],["b","ריכוך החרוסת צריך להיעשות דווקא מיין או ממיץ ענבים שאינו מבושל ואינו מפוסטר, מכיוון שלגבי יין מבושל יש אומרים שהבישול מוציאו מתורת משקה ולא מברכים 'על נטילת ידים' אם מטבלים בו, ולגבי יין מפוסטר יש אומרים שדינו כדין המבושל, ואם אין לו חוץ מאלו, ידלל בהם אבל יוסיף לחרוסת מעט מים שהם לכל הדעות נחשבים כמשקה, ולמנהגנו הוא מצריך ברכה על טיבולו."],["s","(זה\"ש סי' תע\"ג הע' ל', שע\"ה ח\"א סי' כ\"ז הע' מ\"ג וסע' כ\"א)"]]},{"h":"ה' ניסן יום שני","s":"הלכות פסח","d":["לעילוי נשמת שמעה בת סעיד | בריאות איתנה ולב שמח חנה בת סעדיה"],"b":[["t","כמה מדיני הד' כוסות:"],["b","יכין כוסות מהודרים למצות ד' כוסות [למנהגינו לפחות 86.4 סמ\"ק] וישטפם וידיחם יפה. ונכון להדיחם אף בין כל כוס וכוס משום חיבוב מצוה אם אפשר בלי טורח, ובפרט בזמנינו שהמים זורמים בצינורות, קל הדבר לרחצם וגם הם מתנקים יותר טוב."],["s","(הקדמת העץ חיים להגש\"פ ופע\"ח אות י\"ב)"],["t","מהו אופן שתיית הכוס?"],["b","לכתחילה צריך לשתות את כל הרביעית בבת אחת. אבל בדיעבד יזהיר לבני ביתו לשתות לפחות רוב רביעית בפעם אחת מכל כוס וכוס. ובכוס האחרונה ישתו את כל הרביעית בפעם אחת, כדי שיוכלו לברך עליה ברכה אחרונה לכל הדעות."],["s","(עריכת שולחן סי' תע\"ב סע' כ', אגדתא דפסחא עמ' כד')"]]},{"h":"ו' ניסן יום שלישי","s":"הלכות פסח","d":["לעילוי נשמת דוד בן אברהם | ברכה והצלחה ליואב בן שלום מהאצרי הלוי | ברכה והצלחה לאריאל בן ארז","כמוהר\"ר סלימאן מלאחי זצוק\"ל תשל\"ח - אב\"ד דמאר"],"b":[["t","איזה יין עדיף לד' כוסות אדום או לבן?"],["b","אם יש יין אדום כשר ומשובח כמו היין הלבן, היין האדום עדיף משום שנאמר 'אל תרא יין כי יתאדם', אבל אם הלבן כשר יותר או משובח יותר מן האדום יש להעדיפו על פני האדום. (שע\"ה סימן צ' סעיף א')"],["t","האם ילדים קטנים חייבים בד' כוסות?"],["b","קטן וקטנה שהגיעו לחינוך, דהיינו שהם יודעים מקדושת יום טוב ומבינים מה שמספרים מיציאת מצרים, נותנים להם גם כן כוס של רביעית יין שישתו ממנו, ואם הם לא מסוגלים אז של מיץ ענבים. וצריכים שישתו רוב רביעית."],["s","(שע\"ה סימן צ\"א סעיף א' וזה\"ש סימן תע\"ב הע' מ\"ד)"]]},{"h":"ז' ניסן יום רביעי","s":"הלכות פסח","d":[],"b":[["t","האם צריך לומר סברי מרנן בכל הד' כוסות?"],["b","דעת הרב שליט\"א שטוב לומר 'סברי מרנן' בכל הד' כוסות ולא רק בראשון, כיון שזו מחלוקת מנהגים וגם הנוהגים לומר רק בראשון זה מחמת שאין צורך בשאר הכוסות אבל לא שיש קפידא שלא לומר את זה."],["s","(שע\"ה סי' צ\"א הע' ו', אגדתא דפסחא פרי עץ חיים הע' ט\"ל)"],["t","מי מוזג את הכוסות?"],["b","אשת בעל הבית או אחד מבני ביתו ימזגו את הכוסות וכן בכל פעם שמוזגין ימזגו הם ולא הוא בעצמו כדי להראות דרך חירות ואין חוששים לדרך החירות של המוזגת בעצמה כיון שזה תפקידה אין הרגשת החירות נפגמת או על כל פנים אחד ימזוג לשני."],["s","(שע\"ה צ\"ה ה' והע' י', זה\"ש סי' תע\"ג הע' יא)"]]},{"h":"ח' ניסן יום חמישי","s":"הלכות פסח","d":["לעילוי נשמת אורה בת משה"],"b":[["t","מה הדין במי ששהה באמצע שתיית הכוס?"],["b","לכתחילה יזהרו לא לשהות יותר בין לגימה ללגימה יותר מכדי שיעור שתיית רביעית והוא שיעור של שתיית 86 מ\"ל בשתי לגימות ולא בלגימה אחת, שהוא ממידת דרך ארץ, ואם שהה יותר מזה חוזר ושותה, דין זה נאמר לכל ה-ד' כוסות. (משנ\"ב תע\"ב סקל\"ד, זה\"ש הע' לג', לד')"],["t","למנהגנו שמכסים את השולחן במפה האם מועילה מפת ניילון שקופה?"],["b","אע\"פ שלעניין קידוש וברכת המזון לא מועיל כיסוי שקוף מכל מקום בשעת ההגדה שהסיבה שאנו מכסים היא בשביל שישאלו התינוקות אם כן מועיל לזה גם מפה שקופה. (אגדתא דפסחא פרי עץ חיים עמוד רל\"ג)"]]},{"h":"ט' ניסן יום שישי","s":"הלכות פסח","d":["לעילוי נשמת שושנה בת הרב שלום יצחק ז\"ל | קארין בת ליאור בריאות נחת שמחה אמיתית והצלחה בכל | להצלחה וחז\"ב למתיא בן דקל | ברכה והצלחה להדס בת שרה מהצרי הלוי"],"b":[["t","עד מתי זמן אכילת אפיקומן?"],["b","נחלקו הפוסקים עד מתי זמן אכילת אפיקומן, האם דווקא עד חצות או כל הלילה, וכדי לצאת ידי חובת כולם, יש להקפיד לאכול אותו קודם חצות. אך אם עבר זמן חצות, בדיעבד יאכל את האפיקומן גם לאחר חצות. (שו\"ע שימן תע\"ז סעיף א' ובאחרונים שם)"],["t","בעניין מנהג 'גניבת' האפיקומן:"],["b","לא נהגו אצלנו שהילדים 'גונבים' את האפיקומן, ואסור לעשות מן הדין ולא רק מתורת מנהג כמבואר בהלכות גניבה, וגם בליל פסח קיים האיסור לגנוב, ואין לחנך את הילדים לגנוב בכלל. (שע\"ה סי' צא, ז', שע\"ה סימן רכ\"ב עינ\"י הע' ג', באר הלכה לגר\"ש מחפוד עמ' פה)"]]},{"h":"י' ניסן יום שבת פרשת מצורע שבת הגדול","s":"הלכות פסח","d":["לעילוי נשמת רבקה בת והב אברהם"],"b":[["t","האם מותר לאכול אפיקומן בכמה מקומות?"],["b","אסור לאכול אפיקומן בשני מקומות, וכן לא בשתי חבורות שונות, גם אם הם בחדר אחד. ולכן משפחות העורכות את הסדר בחדר אוכל של בית הארחה או מלון, וכל משפחה אוכלת בפני עצמה, נחשבים כשתי חבורות. אבל אם זו משפחה אחת שמחמת ריבוי הסועדים יושבים בכמה שולחנות, כולם נחשבים כחבורה אחת. (זהב שבא סימן תע\"ח הערה ה')"],["t","האם מותר לאכול או לשתות לאחר האפיקומן?"],["b","למהרי\"ץ, אסור לטעום שום דבר אחרי הארבעה כוסות רק מים, כדי שיישן וטעם מצה בפיו. אבל השתילי זיתים מתיר כל דבר שאינו משכר, כגון מיצים טבעיים ומשקאות קלים תה וקפה ואפילו עם סוכר. ולכן כשיש צורך גדול לנוהגים כשתילי זיתים יהיה מותר לשתות קפה או תה וכדומה, והוא הדין לעניין סיגריות וצחצוח שיניים. (שע\"ה סימן צ\"א סעיף כ\"ב ובהערה נ\"ב)"]]},{"h":"יא ניסן יום ראשון","s":"הלכות פסח","d":["לעילוי נשמת סגולה בת יפת סעיד ז\"ל | ברכה והצלחה ורפוא\"ש לאליה בן יאיר | לזיווג הגון חגית בת יוסף | ברכה והצלחה ברו\"ג למרגלית בת ימימה"],"b":[["t","מהו דין שני תבשילין?"],["b","בשעת אמירת ההגדה יהיו על השלחן שני מיני תבשילין, אחד זכר ל'קרבן פסח' והוא צריך להיות צלוי (ומקרוב נהגו שיהיה זרוע לזכר שגאלם הקב\"ה בזרוע נטויה) והשני 'בשר מבושל' זכר לקרבן חגיגה וכן ראוי לעשות. ויש שנוהגים שהמין המבושל יהיה ביצה. (שע\"ה צ' ו' ובעינ\"י יד')"],["t","כמה שיעור כזית?"],["b","לפי המנהג המקובל בידינו הוא כ17- גרם בקירוב שהוא כדעת הראשונים שסוברים שכזית הוא כשליש ביצה (וי\"א רביע ביצה) וטוב להחמיר לקחת כ28- גרם כפי שיטת הסוברים שהוא כחצי ביצה."],["s","(שע\"ה צ\"א סעיף ט\"ז ועינ\"י מ\"א)"]]},{"h":"יב ניסן יום שני","s":"הלכות פסח","d":["לעילוי נשמת שלמה בן דוד","כמוהר\"ר שלום אבהר זצוק\"ל - תשנ\"ג רב בעיר אשקלון","כמוהר\"ר יוסף שמן זצוק\"ל - תשכ\"א חבר ביה\"ד צנעא ורב בעיר הרצליה"],"b":[["t","האם מותר לרכך את המצה היבשה במים?"],["b","אפשר לרכך את המצות הקשות והיבשות ע\"י לחלוח קל במים זמן מה לפני שמגיעים לברכת המוציא ועל אכילת מצה (ובשריה מרובה שטעם מצה מתבטל על ידה, יוצאים רק בדיעבד). (שע\"ה סימן צא סעיף י\"ז)"],["t","האם יכול לשרותה בשאר משקים?"],["b","מי שהוא זקן או חולה ואינו יכול לאכול שרויה במים, יכול לשרותה ביין ובשאר משקים, ובין אם שורה במים או בשאר משקים יזהר שלא ישרה מעת לעת דהיינו 24 שעות, שאז נחשבת כמבושלת ואין יוצאים בה כלל."],["s","(שע\"ה צ\"א י\"ז)"]]},{"h":"יג ניסן יום שלישי בדיקת חמץ בלילה","s":"הלכות פסח","d":["לעילוי נשמת דוד בן דוד | לעילוי נשמת רחל נדרה בת ר' סעדיה ז\"ל | ברכה והצלחה ובריאות איתנה ליאירה בת סעדיה"],"b":[["t","מהו סדר בציעת המצה למנהגינו?"],["b","מנהגינו שבעל הבית המברך בוצע לעצמו, וגם מחלק לכל אחד מהמסובים כזית מצה באמצע, בין ברכת 'המוציא' לברכת 'על אכילת מצה'. דהיינו שהוא מברך \"המוציא\" ובוצע ומחלק והם מחזיקים אותה בידיה וממתינים בלא לאכול אותה עד שהוא חוזר ומברך 'על אכילת מצה'. (סימן צ\"א הל' י\"ג)"],["t","כיצד מחלק למסובים את המצה במוציא מצה?"],["b","בזמנינו שהמצות דקות מאוד ואין אפשרות לחלק לכל אחד כזית משל המברך כל אחד מהמסובים ישלים לעצמו מהמצה המשומרת עד שיעור כזית, והמברך יחלק לכל אחד ואחד רק מעט משלו בשביל חיבוב מצוה, שיטעמו ממה שבירך הוא, באופן שבשעת הברכה לכולם יהיה כזית, ולאחר סיום הברכה יוכלו לאכול מיד. (סימן צ\"א הל' י\"ד)"]]},{"h":"יד ניסן יום רביעי ערב פסח","s":"הלכות פסח","d":["לעילוי נשמת יצחק בן אברהם וכאדיה"],"b":[["t","דין מי שטעה וחתם \"מקדש השבת\" במקום \"מקדש ישראל והזמנים\":"],["b","הטועה בתפילת יום טוב שחל ביום חול וחתם \"מקדש השבת\" במקום \"מקדש ישראל והזמנים\", אם נזכר תוך כדי דיבור ותיקן ל\"מקדש ישראל והזמנים\", יצא ידי חובה, ואינו צריך לחזור לראש הברכה. וצריך להיזהר בזה מאוד, כי דין זה שנוי במחלוקת הפוסקים, אלא שלא חוזרים, משום ספק ברכות להקל."],["s","(זהב שבא סימן תפ\"ז הערה ו')"],["t","עוד בעניין הנ\"ל אם לא נזכר תוך כדי דיבור:"],["b","ואם נזכר לאחר תוך כדי דיבור, נחלקו הפוסקים: דעת השתילי זיתים שכיון שהזכיר באמצע הברכה \"יום טוב\" יצא ידי חובה, כי יום טוב נקרא שבת, אבל מהרי\"ץ פסק שכיון שלא חתם כהוגן, חוזר לראש הברכה."],["s","(זהב שבא סימן תפ\"ז הערה ה')"]]},{"h":"טו ניסן יום חמישי. חג הפסח. ספירת העומר בלילה.","s":"הלכות ספירת העומר","d":[],"b":[["t","צות הספירה בזמן הזה"],["b","בערבית במוצאי יו\"ט הראשון של פסח מתחילים לספור \"ספירת העומר\", ויש אומרים שגם בזמן הזה שאין בית המקדש קיים ואין מקריבים את העומר, המצווה לספור היא מן התורה. ויש אומרים שבזמן הזה המצווה לספור מדרבנן, זכר למקדש, וכן העיקר להלכה. (שע\"ה סצ\"ב ס\"א, מקרא קודש פ\"א ס\"א)"],["t","מתי זמן הספירה לכתחילה?"],["b","מצוה לספור מיד בתחילת הלילה אחר צאת הכוכבים, שנאמר \"שבע שבתות תמימות תהיינה\", ואימתי הן תמימות? משסופר מתחילת הלילה, וזה מלבד מצות זריזין מקדימים למצוות, ובדיעבד זמנה כל הלילה. צאת הכוכבים הוא כשלוש עשרה וחצי דקות אחר השקיעה הנראית לעינינו ויש אומרים כעשרים דקות, והזמן המובחר לספור לכתחילה הוא קרוב לחצי שעה אחר השקיעה הנראית לעינינו. (מקרא קודש פ“א ס\"ג וס\"ד)"]]},{"h":"טז ניסן יום שישי יום ב' דפסח. א' בעומר","s":"הלכות איסור מלאכה בחול המועד","d":["לעילוי נשמת ר' סאלם בן יצחק מעטוף ז\"ל | ברכה והצלחה לדוד בן שלום"],"b":[["t","האם מותר לתקן בחול המועד כסא או שולחן שנשברו?"],["b","ימי חול המועד נקראו בתורה בשם מקראי קודש. והם ימי חג ושמחה. ואסור לעשות בהם כל מלאכת אומן, אף אם הם לצורך המועד. ואין מתקנים כסא או שולחן או ארון בגדים מעשה אומן. (לבוש ס\"א. מועדי ה' סי' תק\"מ ס\"ח)"],["t","האם מותר לתקן בחול המועד מקרר או תנור שנתקלקלו?"],["b","כל דבר שהוא לצורך אוכל נפש מותר לעשותו בחול המועד, אפילו במעשה אומן. ולכן מותר לתקן מקרר חשמלי שנתקלקל. וכן מותר לתקן כיריים של גז, ותנור האפיה, וברז המים במטבח, אפילו ע\"י טכנאי אומן. (מועדי ה' שם ס\"י)"]]},{"h":"יז ניסן שבת חוה\"מ יום ג' דפסח. ב' בעומר","s":"הלכות איסור מלאכה בחול המועד","d":[],"b":[["t","האם מותר לתקן דברים שדרך להשתמש בהם במועד, אך אינם צורך אוכל נפש?"],["b","אסור לתקן מנעליו או מלבושיו ע\"י אומן. ומי שצריך לו בגד במועד, אם היה הדיוט, ואינו מהיר באותה מלאכה, הרי זה עושה אותה כדרכו. ואם היה אומן מהיר, הרי זה עושה אותה מעשה הדיוט. [וישאל מורה הוראה, כיצד לעשות מעשה הדיוט]."],["b","(שו\"ע סי' תקמ\"א סעיפים ד' ה'. מועדי ה' שם סעיפים ג' ה'):"],["t","האם מותרת מלאכת הדיוט שלא לצורך המועד?"],["b","כל מלאכה שאסורה ביו\"ט, אסור לעשותה בחול המועד. אפילו אם היא מלאכה פשוטה שלא צריכה אומנות. שאין בה טורח כלל, כגון תלישת עלה מן העץ, או קריעת נייר, אסורה. ורבים נכשלים מחוסר ידיעה."],["s","(צ\"ט עינ\"י י\"ג)"]]},{"h":"יח ניסן יום ראשון יום ד' דפסח. ג' בעומר","s":"הלכות איסור מלאכה בחול המועד","d":["לעילוי נשמת ציונה גרמה בת צאלח"],"b":[["t","מלאכת הדיוט לצורך המועד"],["b","מה שאמרנו בהלכה הקודמת שכל מלאכה אסורה ביום טוב אסורה בחול המועד, זהו דווקא שלא לצורך המועד, אבל אם לצורך המועד, מותר, כל זמן שאינו מעשה אומן. לפיכך מותר לנסוע באוטו לצורך המועד. כגון לראות פני חבירו או רבו או בני משפחתו, ואפילו לשם טיול מותר. מותר לו גם לתקן את הרכב לצורך הנסיעה, כגון להחליף גלגל. ודוקא מעשה הדיוט, ולא אומן."],["b","(ב\"י סי' תקל\"ו. שע\"ה סי' צ\"ט כ\"א מועדי ה' תקל\"ו ס\"א):"],["t","האם מותר לעשות סחורה בחול המועד?"],["b","כל סחורה אסורה בחול המועד אפילו כל שהוא, בין לקנות בין למכור, כדי שלא יהיו כשאר ימי החול שאין בהם קדושה כלל. אבל דברים הנצרכים למועד, כגון; תבלין או ירקות או חלב וכל דבר שאינו מתקיים, פותחים חנויותיהם ומוכרין כדרכן אפילו בפרהסיא, מפני שהכל יודעים שהן לצורך המועד. (שו\"ע תקל\"ט ס\"י שע\"ה סי' ק' ס\"א וס\"ה):"]]},{"h":"יט ניסן יום שני יום ה' דפסח. ד' בעומר","s":"הלכות איסור מלאכה בחול המועד","d":["לעילוי נשמת חנה סאלם בת חיים אהרון ע\"ה"],"b":[["t","אלו חנויות מותר לפתוח בחול המועד, וכיצד?"],["b","מוכרי פירות שמתקיימים אף לאחר המועד כגון אגוזים וכיוצא בזה, וכן מוכרי בגדים, ונעלים, כלים, ותכשיטים, מוכרים לצורך המועד בצנעה. [וישאל מורה הוראה כיצד לעשות]. (טוש\"ע תקל\"ט סי\"א. שע\"ה סי' ק' ס\"ה. מועדי ה' סכ\"ה):"],["t","גיהוץ וצחצוח נעליים"],["b","מותר לגהץ בגדים לצורך המועד בלי שינוי, אבל אין לעשות בבגד קפלים חדשים כגון מכפלת, שזהו מעשה אומן. וכן מותר לצחצח נעליים במשחה לצורך המועד. (צ\"ט ט\"ו)"]]},{"h":"כ' ניסן יום שלישי יום ו' דפסח. ה' בעומר","s":"הלכות איסור מלאכה בחול המועד","d":["לעילוי נשמת מארי סלם בן עווד הלל | עידן בן רענן וסמדר לזיווג הגון בקרוב"],"b":[["t","קציצת צפרניים"],["b","מותר לקצוץ צפרניים, בין של ידיים, בין של רגליים. ואפילו במספריים, או בגוזז צפרניים. (צ\"ט י\"ג)"],["b","רפואה בחול המועד כל דבר שהוא לצורך רפואה, מותר לעשות, בין לאדם ובין לבהמה. ומשקפיים שנשברו בחול המועד, מותר לתקנם אם יש לו צער קצת, דהוי כרפואה. (צ\"ט ט\"ז)"]]},{"h":"כא ניסן יום רביעי שביעי של פסח. ו' בעומר","s":"הלכות ספירת העומר","d":["לעילוי נשמת יהודה בן ברטה | לעילוי נשמת משומר שמריה בן יהושוע לאה | לעילוי נשמת יחיא בן משה ובדרה הארונה | לעילוי נשמת ציונה ז\"ל בת","הרב שלום אבהר זצ\"ל"],"b":[["t","האם צריך לספור מעומד?"],["b","צריך לספור \"ספירת העומר\" מעומד, שנאמר: \"מהחל חרמש בקמה\", אל תקרי \"בקמה\" אלא בקומה. ויעמוד קודם הברכה, ואם נשען על הכותל או סטנדר וכדומה, באופן שאם יישמט ממנו הכותל או הסטנדר, יפול, דינו כיושב. ובדיעבד אם ספר מיושב, יצא. (מקראי קודש פ\"ב סק\"ג)"],["t","באיזה לשון מותר לספור, ומהו מנהגינו?"],["b","מותר לספור בכל לשון ודווקא בלשון שמבין. ואם אינו מבין וספר, ואפילו בלשון הקודש, לא יצא, משום שלא יודע מה הוא אומר ואין זו ספירה. והמנהג הקדום לספור בלשון ארמי כפי שנזכר בתשובת הגאונים, וכן הוא מנהגינו. (שע\"ה סצ\"ב ס\"ב, ובהערה אות ה' ד\"ה ומקרוב ושת\"ז סתפ\"ט סק\"ו, ערי\"ש תפ\"ט, ז')"]]},{"h":"כב ניסן יום חמישי. ז' בעומר","s":"הלכות ספירת העומר","d":["ברכה והצלחה רבקה בת דניאל"],"b":[["t","מי ששמע הספירה מאחר"],["b","מי שלא ספר בעצמו אלא סמך על מה ששמע הספירה מאחר או מהקהל שסופרים בקול רם, כיוון שסופרים כל אחד לעצמו, אינם מתכוונים להוציא אחרים בספירתם, הרי זה לא יצא, וחוזר וסופר בברכה. ואם אמר לחברו שיכווין להוציאו אף בספירה, נחלקו הפוסקים אם אומרים בספירת העומר דין \"שומע כעונה\" בספירה עצמה, לכן יחזור ויספור בעצמו בלא ברכה. (מקרא קודש פ\"ב סק\"ט)"],["t","לידע הספירה קודם שמברך"],["b","לכתחילה קודם שיברך צריך לידע מניין הספירה של אותו היום. ובדיעבד אם בירך על דעת שיספור מה שישמע מחבירו או מהקהל, יצא. ומטעם זה נוהגים שהגדול המברך מודיע תחילה קודם הברכה אתמול כך וכך בעומרא וכו', כדי שידעו הציבור מניין הספירה קודם ברכתם וכן שלא יטעו במניין הספירה. (שו\"ע סתפ\"ט ס\"ה, ערי\"ש תפ\"ט, כ\"ב)"]]},{"h":"כג ניסן יום שישי. ח' בעומר","s":"הלכות ספירת העומר","d":["ברכה והצלחה להלל בן גלעד"],"b":[["t","מי שבירך וספר אם יכול לברך שוב להוציא את הקהל בברכתו"],["b","מי שבירך וספר, ואחר כך בא לבית הכנסת או לאיזה מקום שמתפללים, וכיבדו אותו לברך על ספירת העומר להוציא את הקהל ידי חובה, לכתחילה יסרב, ויתן לאחר שעוד לא ספר, ומכל מקום בדיעבד אם בירך הוא, יצאו כולם בברכתו. דקיימא לן, \"כל הברכות אף על פי שיצא, מוציא. שכל ישראל ערבים זה לזה, חוץ מברכות הנהנין\". (מקרא קודש פ\"ב סק\"כ)"],["t","נשים בספירת העומר"],["b","נשים פטורות מספירת העומר, וכן הוא מנהגינו שאינן סופרות כלל. אמנם אם רוצה, יכולה לספור, אך לא תברך. ויש אומרים שעל פי הסוד אין הנשים רשאיות לקיים מצוה זו אפילו בלא ברכה, וכמו ציצית ותפילין. (מקרא קודש פ\"ז ס\"ד)"]]},{"h":"כד ניסן יום שבת פרשת אחרי מות. ט' בעומר","s":"הלכות ספירת העומר","d":["לעילוי נשמת ברכה בת יחיא מטרי | תמר בת יוסף רפואת הנפש והגוף שמחה ואמונה"],"b":[["t","מה הדין אם ספר קודם צאת הכוכבים?"],["b","המדקדקים אינם סופרים אלא לאחר צאת הכוכבים, וכן הוא מנהג העולם. ובדיעבד אם ספר בזמן בין השמשות, והוא מהשקיעה קודם צאת הכוכבים, יצא. (שו\"ע סתפ\"ט ס\"ב, משנ\"ב סקט\"ו)"],["t","מה הדין כשמתפללים ערבית בליל שבת מפלג מנחה?"],["b","המנהג בקהילותינו, כשמתפללים מוקדם קודם השקיעה שהרב מברך על הספירה, ואחר כך, הוא וכל הקהל סופרים ביחד. והמנהג אז לדחות הספירה לאחר עלינו לשבח. וטוב שיחזרו ויספרו בלא ברכה אחר צאת הכוכבים. וכל זה הוא במקום שכך הציבור נוהג, ואי אפשר לשנות. הואיל ויש להם על מה לסמוך. אבל לכתחילה יש להשתדל מאד לדקדק, לכוון את זמן התפילה, באופן שתהיה הספירה לכל הפחות לאחר השקיעה. (מקרא קודש פ\"א ס\"ט וסי\"א, פעו\"צ ח\"ג סי' רו, שושנה\"מ במקום, עריה\"ש תפ\"ט, י\"ז)"]]},{"h":"כה ניסן יום ראשון. י' בעומר","s":"הלכות ספירת העומר","d":["לרפואת אורן עזרא | ברכה והצלחה ובראיות איתנה לדליה בת שלמה"],"b":[["t","הזמן שאסור לאכול ולעשות מלאכה עד שיספור"],["b","כשהגיע זמן הספירה אסור לאכול עד שיספור, ואין להתחיל לאכול כרבע שעה, ויש מחמירים מחצי שעה, קודם השקיעה. וכן אסור מזמן זה ליכנס להתרחץ או להסתפר, ולעשות מלאכה או שאר עניינים שאפשר שיימשך בהם או יטרידוהו. חוץ מן האופנים המותרים שיבוארו לקמן. (מקרא קודש פ\"ד סק\"א וסק\"ב, ערי\"ש תפ\"ט, כ\"א)"],["t","אכילה מועטת, ו\"שומר\""],["b","לטעום מעט פת או עוגה עד שיעור כביצה ולא יותר, או פירות וכיוצא באלו אפילו הרבה, מותר קודם שיגיע זמן הספירה, שמה שאסרו היא סעודה שיש בה קביעות, וע\"י כך ימשך בסעודתו וייטרד מן הספירה. וכן אם העמיד שומר (שאינו אוכל או עושה מלאכה), או שעון מעורר שיזכיר לו לספור לכשיגיע הזמן, מותר לאכול אפילו הרבה. וכל זה סמוך לזמן הספירה, אבל כשהגיע זמן הספירה, דהיינו צאת הכוכבים, יפסיק ויספור מיד. ובמקום הדחק שאינו יכול להפסיק מיד, אפשר לסמוך על \"שומר\" ותיכף כשיוכל יפסיק ויספור. (מקרא קודש סק\"ד וסק\"ה)"]]},{"h":"כו ניסן יום שני. יא בעומר","s":"הלכות ספירת העומר","d":[],"b":[["t","האם מותר למי שיש לו מניין קבוע מאוחר לאחר את הספירה?"],["b","מי שרגיל להתפלל ערבית במניין קבוע מאוחר בלילה, יכול לאכול ולעשות מלאכה גם אחר צאת הכוכבים עד הזמן שמתפלל. והוא הדין ביום אחד קבוע מימי השבוע שמתפלל בו מאוחר, כגון שיש לו באותו היום שיעור תורה קבוע ואחריו מתפללים, שרשאי באותו היום לאכול ולעשות מלאכה קודם לכן. (מקרא קודש פ\"ד סק\"ח)"],["t","מה הדין אם טעה בספירה ונזכר מיד?"],["b","מי שטעה בספירה והבחין מיד לאחר שספר, אם נזכר תוך כדי דיבור, שהוא שיעור אמירת \"שלום עליך רבי\", חוזר וסופר מיד המניין הראוי, בלא ברכה. ואינו צריך לחזור על תיבת \"האידנא\". וכיון שתיקן מיד תוך כדי דיבור, הברכה שבירך עולה לו. ואם לא הבחין עד שעבר שיעור זה, חוזר ומברך וסופר המניין הראוי. ובכל אופן אם כבר ספר המניין הראוי, אינו חוזר ומברך, ש\"ברכות אינן מעכבות\". (מקרא קודש פ\"ה סקט\"ז)"]]},{"h":"כז ניסן יום שלישי. יב בעומר","s":"הלכות ספירת העומר","d":["לעילוי נשמת חנה בת שמעון וברטה ז\"ל | טוהר בת תומר עוזירי ברכה והצלחה רוחניות וגשמיות צניעות וקדושה","הרה\"ג זכריה אביגד זצוק\"ל - תש\"ס"],"b":[["t","מי ששכח ולא ספר בלילה?"],["b","מי ששכח כל הלילה ולא ספר, יספור ביום בלא ברכה ובלילות שאחר כך יספור בברכה, מדין ספק ספיקא. ספק שהלכה כהסוברים שמקיימים מצוות ספירה ביום, וספק שהלכה כהסוברים שכל יום היא מצווה בפני עצמה. ועל כל פנים עדיף שימנה עם הציבור, שאז יוצא ידי חובתו בשמיעת הברכה מפי הרב. ודווקא במקום שנוהגים לצאת חובת הברכה מהשליח ציבור, שאז ודואי מכווין להוציאו בברכתו. (שו\"ע סתפ\"ט ס\"ח, שע\"ה סצ\"ב ס\"ג, ערי\"ש תפ\"ט, כ\"ג)"],["t","מה הדין אם שכח מלספור בלילה וביום שלאחריו?"],["b","אם שכח לספור בלילה וגם כל היום שלאחריו יספור אחר כך בכל הלילות בלא ברכה, אבל אם נסתפק אם ספר בלילה או לא, או נסתפק אם ספר כתקנו, כגון את היום הנכון או לא, אע\"פ שלא ספר ביום שלאחריו מכל מקום בשאר הלילות יכול לספור בברכה. ואם ודאי לו שלא ספר בלילה ומסופק אם ספר ביום כתקנו, יספור מכאן ואילך בלא ברכה. וראוי שישמע הברכה מאחר. (שע\"ה סצ\"ב ס\"ג)"]]},{"h":"כח ניסן יום רביעי. יג בעומר","s":"הלכות ספירת העומר","d":["לעילוי נשמת דוד שלמה בן חיה דבורה ז\"ל","כמוהר\"ר יחיא צאלח זצוק\"ל - מהרי\"ץ גאון רבני תימן ותפארתם"],"b":[["t","כיצד לנהוג בעניין חינוך הקטנים בספירה?"],["b","מצוה לחנך את הקטנים שהגיעו לחינוך, אחרי שמתפללים ערבית, לספור ספירת העומר בכל יום בברכה, ומחנכים אותם לזה, אפילו אם נראה שישכחו לספור או ידלגו באחד מימי הספירה. (מקרא קודש פ\"ז סק\"א)"],["t","כיצד ינהג קטן שדילג?"],["b","קטן שדילג יום אחד ולא ספר, אם ממשיך לספור בברכה אין צריך למונעו, ואם הוא גדול קצת ומבין ההלכות יש לחנכו לידע ההלכה שאם שכח לספור אינו מברך בשאר הימים, ואם אפשר לו, שישמענה מאחר."],["s","(מקרא קודש פ\"ז סק\"ב)"]]},{"h":"כט ניסן יום חמישי ערב ראש חודש. יד בעומר","s":"הלכות ספירת העומר","d":["כמוהר\"ר יהודה כמרי זצוק\"ל - תר\"פ, רבה של כאו בתימן ורב מושב שתולים"],"b":[["t","כיצד יענה מי ששאלו חברו למניין הספירה?"],["b","מי ששאלו חברו למניין הספירה והשיבו מניין אותו היום בלבד בלא לומר \"היום\", או שכיוון בפירוש שלא לצאת ידי חובה בספירה זו, אפילו אמר היום, חוזר וסופר בברכה. ומכל מקום, לכתחילה המובחר לצאת מכל ספק הוא, שיאמר לשואל אתמול היה כך וכך. (מקרא קודש פ\"ו סק\"ה, ערי\"ש תפ\"ט, י\"ט)"],["t","מה הדין אם אמר מניין הספירה בלשון שאלה?"],["b","מי ששאל לחבירו \"היום כך וכך?\" בלשון שאלה, וחברו השיבו \"כן\", לא יצא השואל בכך שאין דרך למנות בלשון שאלה, וכל שכן שהמשיב לא יצא, ושניהם סופרים בברכה. (מקרא קודש פ\"ו סק\"ט)"]]},{"h":"ל' ניסן יום שישי א' דראש חודש. טו בעומר","s":"הלכות ספירת העומר","d":["לעילוי נשמת יהושע בן שלמה דוד נדלר ז\"ל"],"b":[["t","מנהגים הנהוגים בימי הספירה"],["b","בימי הספירה מתו תלמידי רבי עקיבא והמה ימי דין. ולכן נוהגים בימים אלו קצת אבלות, שאין נושאים נשים, ואין מסתפרים כפי שיבואר. (שע\"ה סצ\"ב סק\"ו, ערי\"ש תצ\"ג, א')"],["t","האם מותר למי ששערו מגודל להסתפר בימי הספירה?"],["b","מי שהיה טרוד ולא הספיק להסתפר קודם הפסח, וכעת שערו מגודל באופן שצריך להסתפר לכבוד שבת, יכול גם בזמנינו להסתפר אפילו קודם ל\"ג בעומר, אבל צריך להשתדל שלא להגיע לידי כך."],["s","(שע\"ה סצ\"ב ס\"ו, ערי\"ש תצ\"ג, י\"ב ועיי\"ש בהערה)"]]},{"h":"א' אייר יום שבת פרשת קדושים ב' דראש חודש. טז בעומר","s":"הלכות ספירת העומר","d":["לעילוי נשמת אורלי בת ישורון הלל ז\"ל | לעילוי נשמת יוסף בן מאיר סעדה ז\"ל | לעילוי נשמת סעדה בת יוסף | להצלחה בלימוד התורה ומידות טובות לנתנאל יהודה בן דקל"],"b":[["t","עד מתי נמנעים מתספורת?"],["b","בעניין הזמן שנוהגים מקצת אבילות יש אצלנו בקהילות קודש תימן כמה מנהגים בזה, יש נמנעים מן התספורת מערב פסח עד ערב שבועות כדעת האר\"י ז\"ל, וכן אין עושים נישואין עד אחרי שבועות. ויש שאין נמנעים אלא עד ל\"ג בעומר וכן המנהג הרווח, ודווקא מיום ל\"ג עצמו מותרים ולא מבלילה, וכשחל ל\"ג ביום ראשון מסתפרים כבר ביום שישי שלפניו לכבוד שבת. ויש המסתפרים כהרגלם בכל שישי לכבוד שבת. וגילוח הזקן דינו כמו תספורת הראש. (שע\"ה סצ\"ב ס\"ו והערה י\"ד, ערי\"ש תצ\"ג, ה' ו-י\"א)"],["t","מה הדין לבעלי מצוות ברית מילה לעניין תספורת?"],["b","הסנדק והמוהל ואבי הבן מותרים להסתפר לכבוד המילה ואפילו ביום שלפני המילה סמוך ללילה קודם הליכה לבית הכנסת, והנוהגים כהאר\"י נמנעים מלהסתפר גם בזה. (שע\"ה סצ\"ב ס\"ח)"]]},{"h":"ב' אייר יום ראשון. יז בעומר","s":"הלכות ספירת העומר","d":["לעילוי נשמת יצחק בן ישורון הלל ז\"ל | לעילוי נשמת שלום בן יחיא דוד רצאבי ז\"ל"],"b":[["t","מהם המנהגים לגבי נשיאת אשה?"],["b","נוהגים שלא לישא אשה בימי הספירה עד ל\"ג בעומר ויש נוהגים עד אחרי שבועות. ומי שעדיין לא קיים פריה ורבייה או אין לו מי שישמשנו, מותר לישא אז אשה, ומכל מקום המנהג להימנע, הן הנוהגים בזה עד ל\"ג והן הנוהגים עד אחרי שבועות כנ\"ל."],["s","(שו\"ע סתצ\"ג ס\"א, שע\"ה סצ\"ב ס\"ז, שת\"ז סק\"ד, ערי\"ש תצ\"ג, א' ו-ו')"],["t","האם נמנעים מלערוך שידוכים בימי הספירה?"],["b","שידוכין, דהיינו שעושים הצדדים תנאים ביניהם, מותר לעשות ואפילו עם סעודה, אבל בלא ריקודים ומחולות. (שע\"ה סצ\"ב ס\"ז, ערי\"ש תצ\"ג, ד'):"]]},{"h":"ג' אייר יום שני. יח בעומר","s":"הלכות כבוד ת\"ח וזקן","d":["לעילוי נשמת גליה בת עוואד אהרוני","הרה\"ג לוי קשת זצוק\"ל"],"b":[["t","מנין נלמד החיוב לכבד ת\"ח וזקן?"],["b","נאמר \"והדרת פני זקן\", ופירוש \"זקן\" - \"תלמיד חכם\". והוא נוטריקון; \"זה קנה חכמה\". וכמו שנאמר \"אספה לי שבעים איש מזקני ישראל\"."],["b","עוד נאמר \"מפני שיבה תקום\", ונלמד מזה לקום מלוא קומתו מפני שיבה, דהיינו מבן שבעים שנה ואילך, ואפילו אם הוא עם הארץ. ובלבד שלא יהיה רשע."],["s","(שע\"ה סי' קס\"ג ס\"א)"],["t","כיצד מכבד ת\"ח?"],["b","תלמיד חכם מופלג בתורה, ואפילו אם הוא צעיר בשנים, ואינו רבו, מצות עשה לקום מלוא קומתו מפניו, דהיינו שיגיע התלמיד חכם לתוך ד' אמותיו, וכשיעבור מכנגד פניו יכול לשבת מיד. וכן הדין באדם מבוגר מעל גיל שבעים. (שע\"ה סי' קס\"ג ס\"א וס\"ב)"]]},{"h":"ד' אייר יום שלישי. יט בעומר","s":"הלכות כבוד ת\"ח וזקן","d":[],"b":[["t","אם חייב לעמוד מפניהם גם כשעוסק במצוה?"],["b","אפילו בשעת קרית שמע וברכותיה, או כשהוא עוסק בתורה, חייב לעמוד. וכן המנהג. וכן הדין כשספר תורה עובר. (שע\"ה סי' קס\"ג ס\"ב ועינ\"י הע' ח')"],["t","האם תלמיד חכם צריך לעמוד מפני שיבה?"],["b","תלמיד חכם אינו צריך לעמוד מפני שיבה מלוא קומתו, גם אם הוא צעיר, אלא רק יעשה לו הידור, דהיינו שינוע מעט כאילו הוא רוצה לעמוד מפניו. וכן הדין בשני תלמידי חכמים, או שני זקנים, אינם צריכים לעמוד אחד מפני חבירו, אלא רק לעשות הידור. (שע\"ה סי' קס\"ג ס\"ג)"]]},{"h":"ה' אייר יום רביעי. כ' בעומר","s":"הלכות כבוד ת\"ח וזקן","d":["ברכה והצלחה לשירה בת ארז","כמוהר\"ר יחיא יצחק סאלם אזרק - תשנ\"ד, מחכמי מחוז ירום"],"b":[["t","כיצד ינהג הרב עם תלמידו?"],["b","הרב אינו צריך לעמוד מפני תלמידו, אפילו אם הוא תלמיד חכם גדול. אך טוב שיעשה לו הידור קצת. וקורא לו בשמו (בלא תואר), שאין דרך הרב לקרוא לתלמידו בשם רבי. (שע\"ה סי' קס\"ג ס\"ג ועינ\"י הע' י\"ב)"],["t","האם שווה דין זקן לזקנה?"],["b","יש אומרים שצריך לעמוד גם מפני אשתו של תלמיד חכם, וכן מפני זקנה בת שבעים שנה, ולאשה חכמה. ואצלנו אין המנהג כן, ואפילו הידור אין עושין להן. וכן מובא בשם האר\"י שאין חיוב. ומכל מקום מהדרים אותן בדברים, ובכל כבוד שאפשר. (שע\"ה סי' קס\"ג ס\"ד ובעינ\"י הע' ט\"ז)"]]},{"h":"ו' אייר יום חמישי. כא בעומר","s":"הלכות כבוד ת\"ח וזקן","d":["לעילוי נשמת שלום בן יחיא | ברכה והצלחה לזהרה בת יאיר"],"b":[["t","מהו רבו המובהק?"],["b","עד כאן הוזכרו דיני תלמיד חכם שאינו רבו המובהק. אבל רבו המובהק, דהיינו שרוב חכמתו ממנו, אם מקרא, או משנה, או גמרא, או מדרש, או קבלה, וכיוצא בזה מחכמות התורה, חייב לעמוד משיראנו מרחוק מלוא עיניו. וגדול הדור המפורסם בדורו, ומופלג בתורה יותר משאר חכמי הדור, דינו כרבו המובהק, גם למי שלא למד ממנו כלום. (שע\"ה סי' קס\"ג ס\"ה)"],["t","היאך ינהג כבוד בכהן?"],["b","כהן וישראל שהם תלמידי חכמים, ושווים זה לזה בחכמה, וכן כששניהם אינם תלמידי חכמים, מצות עשה מן התורה לנהוג כבוד בכהן ולהקדימו, שנאמר \"וקדשתו\" ודרשו חז\"ל לכל דבר שבקדושה, כגון להיות ראש המדברים בכל קיבוץ עם, לדרוש תחילה. וכן בסעודה, הוא קודם לברך המוציא וברכת המזון, וכיוצא באלו. (שע\"ה סי' קס\"ג סי\"א)"]]},{"h":"ז' אייר יום שישי. כב בעומר","s":"הלכות כבוד ת\"ח וזקן","d":["לעילוי נשמת ברכה בת שלמה"],"b":[["t","היאך ינהגו ת\"ח ישראל וכהן?"],["b","אע\"פ שאין חיוב לתלמיד חכם שגדול בחכמה מן הכהן, להקדים את הכהן. מכל מקום טוב שיקדימנו. אבל אם אין הכהן תלמיד חכם כלל, אסור שיקדימנו דרך חוק ומשפט מפני שהוא כהן, כי מעלת התורה גדולה וחשובה ממעלת הכהונה. אבל אם החכם נותן רשות לכהן לא מצד מעלת הכהונה, מותר. מפני שהחכם יכול ליתן רשות אפילו לישראל פחות ממנו. (שע\"ה סי' קס\"ג סי\"א. ב\"י אה\"ח סי' ר\"א)"],["t","האם יש חיוב להקדים לוי לישראל?"],["b","כשאין כהן, אין צריך להקדים לוי לישראל. וכן המנהג. ולא כמו שהעלו כמה אחרונים שטוב להקדימו. (שע\"ה סי' קס\"ג סי\"א ועינ\"י הע' מ\"ד)"]]},{"h":"ח' אייר יום שבת פרשת אמור. כג בעומר","s":"הלכות כבוד ת\"ח וזקן","d":["לעילוי נשמת מארי עואד צ'אהרי בן סאלם זצ\"ל איש החסד | לעילוי נשמת ניבה בת משה ומרים דהרי ז\"ל"],"b":[["t","האם יש איסור להשתמש בכהן?"],["b","אסור להשתמש בכהן, דהיינו שיעשה לו איזה שירות. משום שנחשב כמועל בהקדש, שנאמר \"וקדשתו כי את לחם אלהיך הוא מקריב\". ואע\"פ שאין לנו קרבנות בזמן הזה, מכל מקום בקדושתו הוא עומד, שלפיכך אסור הוא להיטמא למתים, ולישא גרושה. ויכול הכהן למחול על כבודו, וליתן רשות לישראל להשתמש בו."],["s","(שע\"ה סי' קס\"ג סי\"ב)"],["t","על מה הכהן יכול למחול ועל מה לא?"],["b","בהלכה הקודמת הובא, שיכול למחול לישראל ולהרשות לו להשתמש בו, וכן יכול לחלוק כבוד לישראל ולהקדימו בדברים שנזכרו בהלכות הקודמות. אמנם בקריאת ספר תורה, אינו יכול למחול, ואפילו לתלמיד חכם גדול, אלא לעולם הכהן עולה ראשון. (שע\"ה סי' קס\"ג סי\"ב)"]]},{"h":"ט' אייר יום ראשון. כד בעומר","s":"הלכות כבוד ת\"ח וזקן","d":["לעילוי נשמת אביב שמעון בן מאיר סעדה ז\"ל | לעילוי נשמת ר' יוסף בן סאלם הלל ז\"ל"],"b":[["t","מהי חומרת הזלזול בכבוד תלמידי חכמים?"],["b","עוון גדול לבזות תלמיד חכם, או לשנוא אותם. ולא חרבה ירושלים עיר קדשנו ותפארתנו, עד שביזו בה תלמידי חכמים, שנאמר \"ויהיו מלעיבים במלאכי האלהים, ובוזים דבריו, ומתעתעים בנביאיו\". כלומר בוזים מלמדי דבריו. וכן זה שאמרה תורה \"ואם בחקותי תמאסו\" הכוונה אם במלמדי חוקותי תמאסו. וכל המבזה את החכמים, אין לו חלק לעולם הבא, והוא בכלל מי שנאמר עליו \"כי דבר ה' בזה\"."],["s","(רמב\"ם פ\"ו הי\"א מהלכות ת\"ת שע\"ה סי' קס\"ג סי\"ג)"],["t","איסור השתמשות בתלמיד חכם"],["b","מי שהוא שונה הלכות, וכל שכן מי ששונה גמרא, אסור להשתמש בו, וכתב החיד\"א שבשונה הלכות, אין מועילה מחילתו, משום שלא הגיע למדרגת \"תורה דיליה היא\" (תורה שלו היא), מה שאין כן כהן שמועילה מחילתו, לפי שהכהונה שלו. ואם עושה מעצמו, או תמורת שכר, מותר אף בשונה הלכות או גמרא."],["s","(שע\"ה סי' קס\"ג סי\"ג ועינ\"י הע' נ\"ד)"]]},{"h":"י' אייר יום שני. כה בעומר","s":"הלכות יום טוב","d":["לעילוי נשמת אבי מורי ר' סעדיה בן ר' חיים חתוכה ז\"ל | לעילוי נשמת החייל יגאל בן זכריה שמח ז\"ל | ברכה והצלחה ינאי בן לירן"],"b":[["t","מלאכות האסורות והמותרות ביום טוב"],["b","כל מלאכה שאסור לעשותה בשבת, אסור לעשותה ביו\"ט. וכמו שבשבת אסור לעשות על ידי גוי, הוא הדין ביו\"ט. שאין בין יו\"ט לשבת אלא צורך אוכל נפש בלבד, שנאמר \"אך אשר יאכל לכל נפש הוא לבדו יעשה לכם\" (שמות י\"ב, ט\"ז) דהיינו לישה, אפיה, שחיטה ובישול. שאם יעשם מערב יו\"ט יש בהם חסרון טעם. וכמו שיתבאר. (שע\"ה סצ\"ד ס\"א)"],["t","מלאכה לצורך בעלי חיים"],["b","כל המלאכות המותרות לעשות ביו\"ט, זה דווקא לצורך אדם, אבל לא לצורך בהמה. דכתיב \"יעשה לכם\" ודורשים חז\"ל \"לכם\" ולא לבהמה. לכן אסור לבשל או להוציא איזה דבר מרשות לרשות לצורך בהמה כמו בשבת. (שע\"ה סצ\"ד ס\"י, ערי\"ש תקי\"ב, א' נקט \"גוי\" והוא הדין \"בהמה\")"]]},{"h":"יא אייר יום שלישי. כו בעומר","s":"הלכות יום טוב","d":[],"b":[["t","מלאכת הוצאה והבערה"],["b","הוצאה מרשות לרשות, וכן הבערה מאש מצויה, מותרים ביו\"ט לא רק לצורך אוכל נפש שבמלאכות אלו קיבלו רבותינו שמתוך שהותרו לצורך אוכל נפש, הותרו גם שלא לצורך אוכל נפש. (שע\"ה סצ\"ד ס\"ב)"],["t","במה הותרה מלאכת הוצאה?"],["b","יש אומרים שהוצאה הותרה אפילו שאינה לצורך היום כלל. ובלבד שלא יהיה לצורך מחר, שאסור מדין \"מכין מיו\"ט לחול\". ויש אומרים שאין להוציא אלא כשיש קצת צורך בדבר, כגון שעון, מטפחת, וכיוצא בזה, או אם מתיירא שמא יגנב, וכן נכון להחמיר."],["s","(שע\"ה סצ\"ד ס\"ז)"]]},{"h":"יב אייר יום רביעי. כז בעומר","s":"הלכות יום טוב","d":["לעילוי נשמת מורי גיאת בן מו\"ר משה גיאת"],"b":[["t","הטבלת כלים בשבת ויו\"ט"],["b","יש מחמירים שלא להטביל כלים בשבת ויו\"ט משום שנראה כמתקן הכלי, שבלא להטבילו אינו ראוי לתשמיש. לכן אם שכח ולא הטביל את הכלי מבערב, יתנהו לגוי במתנה, ויחזור וישאילו ממנו. שכלי הגוי אינם צריכים טבילה. ואם אפשר שלא יראה כמתכוון להטבילו, כגון שאם הכלי ראוי להביא בו מים, ישאב בו מים, וממילא נמצא מטבילו. וכן אם הכלי מלוכלך, ידיחנו במי המקווה, שאינו נראה כמתכוון לתקנו, ולכן יברך בלחש, ואם אי אפשר לו באופנים הללו, אז מותר לו להטבילו לכתחילה לצורך השבת והחג ויברך בקול, שהוא כפי עיקר הדין בשו\"ע. (שע\"ה יו\"ד סקל\"ח סי\"ב)"],["t","שלא לנהוג בדרך חול"],["b","לא ישא משאות גדולים ברחובות כמו שהוא עושה בחול, ואפילו לצורך אוכל נפש כגון פירות ומשקאות, אלא ישנה. כיצד, דבר שהדרך לישא אותו ביד, ישאהו בכתיפו. בכתיפו, ישאהו ביד. ואם אי אפשר לשנות, כגון שממהר מפני שיש לו הרבה אורחים ועל ידי השינוי נגרם עיכוב, עושה כדרכו. (שע\"ה סצ\"ד ס\"ח)"]]},{"h":"יג אייר יום חמישי. כח בעומר","s":"הלכות יום טוב","d":[],"b":[["t","האם מותר לבשל ולאפות בשביל גוי?"],["b","אסור לבשל או לאפות ביו\"ט לצורך גוי. אך מי שיש לו משרת גוי, יכול להוסיף ולבשל בקדירה אחת שיהא בה גם בשביל המשרת. ולאפות פת (אפילו בתוספת), אסור. אבל מותר לתת לו איזה דבר ממה שבישל או אפה."],["b","מה הדין בגוי מכובד? שאר מלאכות יו\"ט? ומחלל שבת בפרהסיא?"],["b","במה דברים אמורים בגוי שאינו מתכבד בו. אבל בשביל גוי מכובד, אסור אפילו להוסיף. ולא עוד אלא אפילו אם בישל הישראל או אפה בשביל עצמו, אסור להזמין גוי שיאכל עמו, שחששו חז\"ל שמא יבשל לו בקדרה בפני עצמה. והוא הדין שאסור לעשות כל מלאכות האסורות ביו\"ט בשביל גוי. ומחלל שבת בפרהסיא, דינו כגוי. (שע\"ה סי' צ\"ד סי\"א)"]]},{"h":"יד אייר יום שישי. פסח שני. כט בעומר","s":"הלכות יום טוב","d":["לעילוי נשמת יעקב בן שלביה"],"b":[["t","הכנת מאכלים שאין מפיגים טעמם"],["b","אוכל נפש אף על פי שאפשר לעשותו מערב יו\"ט, מותר לעשותו ביו\"ט כרגיל, ואפילו בדבר שאין מפיג טעמו, כגון ללוש בצק, לאפות מיני עוגות ועוגיות (על האש, אך לא בתנור חשמלי), או לבשל מרק פירות וכדומה, אמנם ממיני דברים אלו שאין מפיגים טעמם. ראוי להחמיר לעשותם מערב יו\"ט, ואם שכחו או לא הספיקו, אם אפשר יעשו בשינוי קצת."],["s","(שע\"ה סצ\"ד סי\"ג, ערי\"ש תק\"ד א', תק\"ז א')"],["t","הכנת מאכלים שדרך לעשותם לימים הרבה"],["b","דברי אוכל נפש שאינם מפיגים טעמם אלא שהדרך לעשותם לימים רבים, כגון מיני מרקחת (ריבה), שוקולד, וכן \"סמנה\", אסור לעשותם כרגיל אלא דוקא ע\"י שינוי. וכן אין עושים גבינה או חמאה ביו\"ט, ואין מעמידין החלב שיתקבץ ויקפה. (שע\"ה סצ\"ד סי\"ד, ערי\"ש תק\"י, ב')"]]},{"h":"טו אייר יום שבת פרשת בהר. ל' בעומר","s":"הלכות יום טוב","d":["לעילוי נשמת נדרה (אורה) בת שלום"],"b":[["t","מלאכת אוכל נפש המפיג טעמו"],["b","מותר ללוש בצק ולאפות פת ביום טוב בלי שום שינוי. ומכל מקום אסור למדוד את הקמח, אלא לוקחים באומד הדעת. ואם לוקח כלי המיוחד למידה, אלא שאינו מצמצם את המידה, אלא פוחת או מוסיף, מותר. ומותר ללוש ולהקציף \"חילבה\" בלי שום שינוי."],["s","(שע\"ה סצ\"ד סט\"ו)"],["t","ניפוי הקמח ביו\"ט"],["b","קמח שכבר נופה מערב יו\"ט ורוצים לנפותו שנית, יש לנפותו ע\"י שינוי קצת, כגון על השולחן במקום לתוך כלי, או באחורי הנפה. וקמח שעדיין לא נופה, אסור לנפותו אפילו בשינוי ואפילו ע\"י גוי. ומותר לברור פסולת מתוך הקמח, כגון שנפלו צרורות או קיסמים וכדו'. (שע\"ה סצ\"ד סט\"ז, ערי\"ש תק\"ו, ג')"]]},{"h":"טז אייר יום ראשון. לא בעומר","s":"הלכות ל\"ג בעומר","d":[],"b":[["t","מהו טעם השמחה בל\"ג בעומר?"],["b","יום ל\"ג בעומר הוא יום שמחה לכבוד התנא רבי שמעון בר יוחאי, שהיום הוא יום ההילולא שלו, ועוד אפשר שהשמחה על אותם תלמידים שהוסיף ר' עקיבא, ולא מתו כאותם עשרים וארבע אלף תלמידים, ובשם האר\"י ז\"ל כתוב שבאותו היום סמך ר' עקיבא את חמשת תלמידיו, ור' שמעון בר יוחאי הוא מגדולי תלמידיו. (כף החיים סתצ\"ג אות כו-כז, ושת\"ז סק\"ח)"],["t","האם אומרים תחנון ביום ל\"ג בעומר?"],["b","אין אומרים תחנון בל\"ג בעומר וגם במנחה של יום ל\"ב, ומעשה בגדול אחד שהיה רגיל לומר נחם בכל יום, ואמרו גם בל\"ג בעומר ונענש."],["s","(סי' תצג ס\"ב, שת\"ז סק\"ט)"]]},{"h":"יז אייר יום שני. לב בעומר","s":"הלכות ל\"ג בעומר","d":[],"b":[["t","מנהג הלימוד בל\"ג בעומר"],["b","יש הנוהגים לעשות לימוד בליל ל\"ג בעומר במניין, ולומדים שבחי - רבי שמעון בר יוחאי המפוזרים בזוהר ובאדרא זוטא, ומנהג יפה הוא. (כף החיים סי' תצג' אות כז)"],["t","האומר היום ל\"ג בעומר"],["b","יש להזהר בסוף יום ל\"ב אחר השקיעה שלא לומר \"היום ל\"ג בעומר\" קודם שיספור, והדבר שכיח שמספר כן לילדים וכדומה. ובדיעבד, כיוון שלא התכוון בזה לצאת ידי חובה, ואינו דרך ספירה אלא סיפור דברים בעלמא, והואיל ויש אומרים שספירה בראשי תיבות אינה ספירה אפילו במתכוון, יכול לחזור ולספור בברכה. ולכתחילה נכון יותר שישמע הברכה מהרב כמנהגינו, או מאחר. (מקרא קודש פ\"ו סק\"י)"]]},{"h":"יח אייר יום שלישי. לג בעומר","s":"הלכות יום טוב","d":["לעילוי נשמת ברכה בת תמר וסעדיה ע\"ה","הרה\"ג לוי קשת זצוק\"ל"],"b":[["t","הפרשת חלה ביום טוב"],["b","עיסה שנילושה ביו\"ט, מותר להפריש ממנה חלה. אבל אסור לשרפה שאין שורפים קודשים ביו\"ט, וכן אסור לאפותה משום שאינה ראויה לאכילה (מלבד חלת חוצה לארץ שאפשר להאכילה לכהן שטבל) ואסורה גם כן בטלטול, לכן בעודה בידו, יניחנה במקום המשתמר עד מוצאי יו\"ט, וישרפנה. (שע\"ה סצ\"ד סי\"ז)"],["t","עיסה ששכחו להפריש ממנה חלה בערב יו\"ט, האם מותר להפריש ממנה חלה ביו\"ט?"],["b","עיסה שנילושה בערב יו\"ט אסור להפריש ממנה חלה ביום טוב, ואין לה תקנה אלא אם ילושו עוד עיסה שצריכים אותה, ויפרישו ממנה גם על הראשונה. (שע\"ה סי' צ\"ד סי\"ז)"]]},{"h":"יט אייר יום רביעי. לד בעומר","s":"הלכות יום טוב","d":[],"b":[["t","האם מותר למלוח בשר או דגים ביום טוב?"],["b","מותר למלוח בשר להכשירו מדמו, אפילו שהיה אפשר למלחו מאתמול. ודווקא אם יש בו לצורך היום. אבל בשר שכבר נמלח מדמו, וכן דגים שמשתבחים כשמניחים אותם במלח, והיה אפשר למלחם בערב יום טוב, אסור למלחם ביום טוב. (שע\"ה סי' צ\"ד סי\"ט)"],["t","האם מותר להשחיז סכין ביו\"ט?"],["b","אסור להשחיז סכין במשחזת שלה, אבל מותר לחדדה על גבי עץ או אבן או על גבי סכין אחרת. ואין להורות דבר זה לרבים, אלא כל אדם מעצמו מותר לעשות כן. (שע\"ה סי' צ\"ד ס\"כ)"]]},{"h":"כ' אייר יום חמישי. לה בעומר","s":"","d":["להצלחה ברו\"ג לנדב בן עזריאל","כמוהר\"ר יחיא עבאהל זצוק\"ל - תשכ\"ח, אב\"ד בירושלים"],"b":[["t","טחינת תבלין ביו\"ט"],["b","מיני תבלין שאם יטחן אותם קודם יו\"ט יפיגו טעמם, מותר לדוכם ביו\"ט בלי שינוי. לכן מותר לגרד חזרת (חריין בלשון אשכנז) במגרדת שלה. וכן מותר לרסק שום או בצל וכיוצא בהם. וכן מותר לגרד במגרדת גזר או צנון ולרסק תפוחי אדמה(פירה) וכיוצא בהן. וכן לטחון בשר במכונה ידנית. ומותר אף להרכיב חלקי המכונה."],["s","(שע\"ה סצ\"ד סכ\"א, ערי\"ש תק\"ד, א')"],["t","מה הדין דברים שאינם מפיגים טעם?"],["b","דברים שלא ירד מטעמם הטוב אם ידוכו אותם מערב יו\"ט, צריכים ליזהר לדוכם מערב יו\"ט, אך אם שכח יש להתיר ע\"י שינוי. וכל הנזכר לעיל, אינו מותר, אלא מה שהוא צריך לאותו היום, ולא למחר. (שם)"]]},{"h":"כא אייר יום שישי. לו בעומר","s":"הלכות יום טוב","d":[],"b":[["t","ברירה לצורך אוכל נפש ביו\"ט"],["b","מותר לברור קטניות וכיוצא בזה, כמות שצריכים לאותו היום, אבל לא בנפה ולא בכברה. וגם לא יתנם לתוך המים כדי שתצוף הפסולת או האוכל, אלא יברור ביד וילקט מה שהוא נוח לו יותר, אם נוח לו ללקט הפסולת, ילקט הפסולת, ואם נוח לו יותר ללקט האוכל, ילקט האוכל. וכל זה מותר אפילו שהיה אפשר לו לברור מערב יו\"ט. (שע\"ה סצ\"ד סכ\"ב)"],["t","דין סחיטה ביו\"ט"],["b","אסור לסחוט פירות ביו\"ט, אפילו דברים שאם יסחטם מערב יו\"ט יפגם טעמם, והדין בזה כמו בשבת. וכן אסור לעשות יין-שרף (ערק) בשום אופן. (שע\"ה סצ\"ד סכ\"ג, ערי\"ש תק\"ד, ד')"]]},{"h":"כב אייר יום שבת פרשת בחוקותי. לז בעומר","s":"הלכות יום טוב","d":["ברכה והצלחה לר' יעקב בן ר' אברהם חדד"],"b":[["t","דיני הבערה ביו\"ט"],["b","אסור להוציא אש, בין מאבן, בין מזכוכית, והוא הדין להדלקת גפרור ע\"י חיכוך. שלא הותר ביו\"ט להבעיר, אלא מאש מצויה. לכן להדליק הגפרור מנר, מותר. ואחר גמר ההדלקה, לא ישליך את הגפרור בחוזקה, שעל ידי כך מתכבה, אלא יניחנו בנחת שיכבה מעצמו. לכן לא ישתמש במצית כלל, אפילו אם ידליקה מנר, שעל ידי שעוזב לחצן ה\"גז\", גורם לכיבויה בידיים. (שע\"ה סצ\"ד סכ\"ה, ערי\"ש תק\"ב, א')"],["t","דיני כיבוי אש ביו\"ט"],["b","אסור לכבות אש ביום טוב. לכן אסור לכבות שלהבת ה\"גז\" בסיום הבישול. ויש מחמירים גם שלא להנמיך שלהבת של \"גז\" כדי שלא יקדיח התבשיל או כדי שיתבשל יפה, אם יש לו אפשרות להדליק שלהבת אחרת קטנה יותר. ומעיקר הדין מותר לכבות הגז ע\"י גרמא. לכן מותר לכבות את הגז ביו\"ט על ידי שעון גז הנקרא \"חגז\" הנמצא כיום שגורם לכיבוי הגז. והכיבוי על ידי שעון, עדיף על כיבוי על ידי גלישה של הרתחת מים שכוונתו לשתותם. וכן מותר להניח כף בין הלהבה לזיז המתכת שבסמוך אליה הגורם לניתוק זרימת הגז בשעה שאינו מרגיש מקור חום, שהוא גרם כיבוי המותר. (שע\"ה סצ\"ד סכ\"ז, מקרא קודש בשם מועדי ה', הרב בע\"פ, ערי\"ש תק\"ז, ד'-ה')"]]},{"h":"כג אייר יום ראשון. לח בעומר","s":"הלכות עירובי תבשילין","d":[],"b":[["t","האם מותר לבשל ביום טוב לכבוד שבת?"],["b","ביום טוב שחל להיות בערב שבת, אסור לאפות או לבשל בקדירה נפרדת לשבת, אלא על ידי \"עירוב תבשילין\" שעושה בערב יום טוב, דהיינו שלוקח בידו איזה תבשיל או צלי, ונוהגין לקחת גם פת, ומברך \"ברוך וכו' אשר קדשנו במצותיו וצונו על מצות עירוב\" ולאדלוקי שלאטמוני ורגא ולמעבד כל צרכנא מיובם טוואומר: \"בהדין עירובא יהא שרי לן לאפויי ולבשולי לשבת\", (פירוש: בזה העירוב יהא מותר לנו לאפות ולבשל ולהטמין ולהדליק נר ולעשות כל צרכינו מיום טוב לשבת). ואם מערב בשביל אחרים מוסיף: \"לנא ולכל ישראל שבעיר הזאת\", ואם אינו מבין לשון זה, יאמר בלשון שהוא מבין. ומי שלא בירך או שלא אמר הנוסח, אינו מעכב. (שע\"ה ח\"ג סצ\"ז ה\"א)"],["t","איזה תבשיל מניחים לצורך העירוב?"],["b","התבשיל צריך שיהא דבר שדרכו לאכלו עם פת כגון בשר או דגים או ביצים, אבל דבר שאין דרכו לאכלו עם פת, כגון דייסא, לא מועיל. (שע\"ה ח\"ג סצ\"ז ה\"ב)"]]},{"h":"כד אייר יום שני. לט בעומר","s":"הלכות עירובי תבשילין","d":["הרה\"ג שלמה טובים זצוק\"ל - תשע\"ז, רב העיר יהוד"],"b":[["t","מהו שיעור התבשיל שמניחים לצורך העירוב?"],["b","שיעור התבשיל והפת, צריך שיהא מכל אחד כזית, בין לאחד בין למאה בין לאלף. ויש להדר אחר מנה יפה לכבוד המצוה. והפת יכולה להיות פרוסה. ואם היא שלימה, טוב שיניחנה בשבת ללחם משנה, ובסעודה שלישית יבצע עליה, דכיון דאתעביד בה מצוה חדא זימנא, יתעביד בה נמי מצוה אחריתא, אבל מצד הדין יכול לאכלה אחר שהכין צרכי שבת כמו שיתבאר. (שע\"ה ח\"ג סצ\"ז ה\"ב)"],["t","כיצד מזכים את העירוב לאחרים?"],["b","אם מערב בשביל אחרים, צריך לזכות להם ע\"י אדם אחר, ואומר לו: זכה בזה בשביל פלוני ופלוני או בשביל כל בני העיר הזאת, ונותנו לזוכה, והלה מגביהו טפח ואומר: זכיתי, כן הוא מנהגינו. וחוזר ונוטלו ממנו, ומברך, ואומר הנוסח דלעיל. (שע\"ה ח\"ג סצ\"ז ה\"ג)"]]},{"h":"כה אייר יום שלישי. מ' בעומר","s":"הלכות עירובי תבשילין","d":["לעילוי נשמת אברהם בן סעיד"],"b":[["t","האם מצווה על כל אחד לערב לעצמו?"],["b","מצוה על כל בעל בית לערב בעצמו, ואפילו אשה שאין לה בעל, צריכה לעשות בעצמה. ומאידך מצוה על כל רב קהילה או גדול העיר לערב על כל בני הקהילה והעיר, ועל כל הקרוב אליה בתוך התחום, ומודיע להם ביום טוב, קודם שיתחילו לבשל לצורך שבת."],["s","(שע\"ה ח\"ג סצ\"ז ה\"ג)"],["t","למי מועיל העירוב של גדול העיר וכיצד ההכרזה?"],["b","נוהגים שמכריז הרב בבית הכנסת בזמן שכל הקהל מקובצים בליל יום טוב ראשון, קודם הקדיש שלפני עלינו לשבח או בשחרית בזמן הוצאת ספר תורה, בנוסח זה: כל מי שלא הניח עירובי תבשילין יסמוך על עירובי. ולפי מנהגינו זה מועיל לא רק למי ששכח או נאנס או אבד עירובו, אלא אפילו למי שהתעצל או שבמזיד לא הניח עירוב. (ומכל מקום מצווה על כל בעל בית לערב לעצמו כמו שכתבנו לעיל). (שע\"ה ח\"ג סצ\"ז ה\"ג)"]]},{"h":"כו אייר יום רביעי. מא בעומר","s":"הלכות עירובי תבשילין","d":["לעילוי נשמת סעדיה בן ניסים שרים","כמוהר\"ר שלום בשארי זצוק\"ל - תשל\"א"],"b":[["t","מתי יש לעשות צרכי השבת ביו\"ט?"],["b","יש אומרים שעירוב התבשילין מועיל להתיר לעשות כל צרכי שבת ביום טוב, דווקא בעוד היום גדול. דהיינו, שיהא שהות שאם יזדמנו לו אורחים, יוכלו להנות ממלאכתו שעשה, ביום טוב. אבל, אם אין שהות בו ביום ליהנות ממלאכתו, אינו מועיל העירוב תבשילין. ולכן לכתחילה, צריך שיהיו זריזין לגמור הכל מבעוד יום. מיהו בשעת הדחק יש להקל, ויש להימנע מלהגיע לידי כך. (שע\"ה ח\"ג סצ\"ז ה\"ד)"],["t","עד מתי צריך לשמור את העירוב?"],["b","צריך שיהא העירוב קיים עד שיכין כל צרכי שבת, לפיכך, יצניענו במקום שמור. ולכל הפחות, יהא קיים עד שיתחיל אחד מצרכי שבת, ואז כיון שהתחיל יכול לגמור את כולם. (שע\"ה ח\"ג סצ\"ז ה\"ו)"]]},{"h":"כז אייר יום חמישי. מב בעומר","s":"הלכות עירובי תבשילין","d":["יעל בת אליהו ברכה והצלחה אהבה אמונה דבקות וביטחון בשם"],"b":[["t","מה הדין אם אבד או נאכל העירוב?"],["b","אם נאבד או נאכל התבשיל, והוא הדין אם התקלקל, אם נשאר כזית לא הפסיד העירוב. אבל אם לא נשתייר ממנו כזית ועדיין לא התחיל אפילו אחד מצרכי השבת, אסור לו לבשל כאלו לא עירב כלל. (וזה דווקא במקום שאין גדול שעירב בשביל אחרים, אבל אם יש גדול שעירב בשביל אחרים, יכול הוא לסמוך על עירוב הגדול, שלא גרע משלא עירב כלל.) אבל אם נאכל או נאבד הפת, אין בכך כלום, ומותר אפילו לאפות. (שע\"ה ח\"ג סצ\"ז ה\"ו)"],["t","כיצד יעשה מי שאין לו עירוב לסמוך עליו?"],["b","מי שלא עירב, ושוהה במקום שאין רב שעירב בשביל אחרים, אם נזכר קודם שבישל לסעודת שחרית, יכול לבשל בקדירה גדולה, ולהותיר לשבת. אם נזכר עד אחר סעודת שחרית, אינו מותר לו אלא לבשל קדירה אחת ולאפות פת אחת ולהדליק נר אחד לשבת. ואם יש שם מי שעירב לעצמו ולא בשביל אחרים, יתן לו במתנה המצרכים הנדרשים, והוא יזכה בדברים אלו בהגבהה, ויבשל ויאפה עבורו ואפילו בביתו של זה שלא עירב. (שע\"ה ח\"ג סצ\"ז ה\"ז)"]]},{"h":"כח אייר יום שישי. מג בעומר","s":"הלכות תפילות יום טוב","d":["לעילוי נשמת יעקב בן משה | אביטל בת יצחק נהרי ברכה והצלחה רוחניות וגשמיות בריאות"],"b":[["t","מצות עטיפה בציצית לכבוד החג"],["b","מצוה להדר ללכת מביתו לבית הכנסת בכניסת החג כשהוא מעוטף בציצית וגם בחזרתו לביתו, וכן הוא מנהגינו. והמדקדקים אינם מסירים הטלית מעליהם, עד אחרי הקידוש. ואם מתעטף אחר השקיעה, לא יברך על הציצית. (שע\"ה סי' נ\"ח ס\"ב)"],["t","האם צריך להסדיר את התפילה?"],["b","בתפילת ערבית של כניסת החג, אחר אמירת מזמורי החג, עומד הגדול שבציבור ומסדיר את התפילה של חג לפני הקהל, אפילו שיש ביד הקהל סידורים, כדי שתהא התפילה שגורה בפיהם, כן הוא דעת מרן השו\"ע, וכן הוא מנהגינו. (שו\"ע שם ס\"ק ס\"א)"]]},{"h":"כט אייר יום שבת פרשת במדבר ערב ראש חודש. מד בעומר","s":"הלכות תפילות יום טוב","d":["לעילוי נשמת נעמי בת מורי יחיא בסיס"],"b":[["t","מה הדין אם טעה בתפילת החג?"],["b","בכל תפילות החג אם טעה והתחיל בברכה אמצעית של חול (היינו אחר ברכת \"האל הקדוש\") \"אתה חונן\", צריך לגמור כל אותה ברכה שהתחיל, ואח\"כ יתחיל ברכה אמצעית של יו\"ט \"אתה בחרתנו\". ואם התחיל רק תיבת \"אתה\", ימשיך לומר בחרתנו מכל העמים וכו'. מלבד תפילת מוסף שאם טעה יפסיק מיד ויתחיל \"אתה בחרתנו וכו'..\" (שע\"ה סי' נ\"ח סי\"ח)"],["t","מה דין המסופק אם אמר 'והשיאנו וכו\"?"],["b","המתפלל ביו\"ט, וכשהגיע לברכת \"מודים\" נסתפק אם בסוף יעלה ויבוא סיים \"והשיאנו\" וחתם כדין או שהמשיך \"ותרצנו ותחזנה עיננו\", כמו שרגילים בראש חודש וחול המועד ונמצא שלא חתם ברכת \"אתה בחרתנו\", צריך לחזור ולומר \"והשיאנו\" ויסיים התפילה כדין. ואם נזכר אחר שסיים תפילתו, צריך לחזור לראש התפילה. אמנם אם ברור לו שכל הזמן התפלל מתוך הסידור, אז בודאי אמר כדין, ואינו חוזר. (מקרא קודש שבועות פ\"ב סי\"ב)"]]},{"h":"א' סיון יום ראשון ראש חודש. מ\"ה בעומר","s":"הלכות תפילות יום טוב","d":["לעילוי נשמת מנשה בן זכריה","כמוהר\"ר סאלם עואד אחרק זצוק\"ל - תשי\"ח, מרבני מחוז דמאר"],"b":[["t","האם יש להקפיד להתפלל תפילת ערבית של יו\"ט אחר צאת הכוכבים?"],["b","תפילת ערבית של ליל שבועות, יש אומרים שאין להתפלל אלא בצאת הכוכבים, כדי שלא יחסר אפילו מעט ממ\"ט ימי הספירה, משום שנאמר \"שבע שבתות תמימות תהיינה\". ומהרי\"ץ פסק כהסוברים שאין להקפיד בזה, אלא לעניין הקידוש וסעודת יום טוב. (שע\"ה סצ\"ג ס\"א. וכ\"כ הגר\"י צוברי בס' פסקי הלכות עמ' שיז)"],["t","מהו סדר ליל שבועות?"],["b","התפשט המנהג ע\"פ הזוהר הקדוש להיות ניעורים כל ליל שבועות לעסוק בתורה, וקוראים שלושה פסוקים מתחילת כל פרשה וסופה וכן בנביאים ובכתובים, ואחרי כן משנה ראשונה ואחרונה מכל מסכתא. ואם נותר זמן עד התפילה קוראים \"אדרא רבה\", ויש נוהגים לקרוא \"תהילים\" במקום ה\"אדרא\". ואפילו תלמידי חכמים ובני ישיבות צריכים ללמוד בעניינים אלו כסדר הנזכר. וכן מנהג גדולי עולם בכל העדות. (שע\"ה סצ\"ג ס\"ב, ערי\"ש תצ\"ד, ז')"]]},{"h":"ב' סיון יום שני. מו בעומר","s":"הלכות ליל חג השבועות","d":[],"b":[["t","האם מברך שנית על שתיה ומאכל במשך הלילה?"],["b","הלומדים בלילה ומגישים להם במשך הלילה לשתות תה או קפה וכדו', אפילו שהו יותר מכדי שיעור עיכול, אינם צריכים לחזור ולברך על כל כוס וכוס, אלא די בברכה ראשונה כל זמן שלא גמר בליבו שלא לשתות ולאכול עוד. וטוב שיכוון דעתו בברכה ראשונה, לפטור כל מה שיביאו לפניו לאחר מכן. (מקרא קודש פ\"ד קט\"ו)"],["t","יצא לחוץ וחזר האם צריך לחזור ולברך?"],["b","אם יצא לחוץ מפתח בית הכנסת (והיה בדעתו לחזור) ואחר כך חזר, בדברים הטעונים ברכה במקומם כגון עוגות ועוגיות, מועיל שהניח מקצת חברים במקום הראשון, ולכן לא יחזור ויברך. אבל בדברים שאין טעונים ברכה במקומם כגון שתיה ופירות וכדו', אף על פי שנשארו מקצת חברים צריך לחזור ולברך משום ששינה מקומו. והיות שהדבר שנוי במחלוקת, לכתחילה יברך ברכה אחרונה קודם שיצא, ואם יצא בלא לברך ברכה אחרונה וחזר, לא יברך שנית ברכה ראשונה, אלא יהרהר הברכה בליבו. (מקרא קודש פ\"ד קט\"ו)"]]},{"h":"ג' סיון יום שלישי. מז בעומר","s":"הלכות ליל חג השבועות","d":[],"b":[["t","הניעור כל הלילה"],["b","מי שניעור כל הלילה אין צריך לקרות \"קרית שמע שעל המיטה\". ולפני תפילת שחרית נוטלים הידיים שלוש פעמים כשאר הימים, אבל בלא ברכה. ומברכין כל ברכות השחר חוץ מברכת \"המעביר שינה\" למנהג הבלדי, ומנהג השאמי לברך אף \"המעביר שינה\". (שע\"ה סי' צ\"ג ס\"ג)"],["t","האם יש לברך ברכת התורה לניעור כל הלילה?"],["b","וכן מברכין ברכות התורה אפילו היו ניעורין כל הלילה, ונכון להדר לחוש לסוברים שאין לברך, ולשומעם מפי אחר שישן, בכוונה לצאת ידי חובה, ושהוא יכוון להוציאו. (שע\"ה ס\"ז ס\"ה)"]]},{"h":"ד' סיון יום רביעי. מח בעומר","s":"הלכות ליל חג השבועות","d":[],"b":[["t","האם מותר להתפלל מעלות השחר?"],["b","ביום חג השבועות יכולים אפילו לכתחילה להקדים ולקרות קרית שמע וברכותיה ותפילת שחרית תכף שיעלה עמוד השחר, ואת התיקון וברכות השחר וברכות התורה והזמירות, יכולים לומר קודם עלות השחר. אבל לא יברכו אז על הציצית, שזמנה משיכיר בין תכלת ללבן. (מקרא קודש פ\"ה ס\"ב)"],["t","מנהג קריאת האזהרות וטעמו?"],["b","נוהגים לקרות האזהרות שיסד ר' שלמה בן גבירול, אחרי ההפטרה. והטעם מפני שאולי עבר אחד מהקהל על איזו מצוה, ויהרהר תשובה לתקן דרכיו. לפיכך יכוין למה שאומר השליח ציבור, ויתבונן בפירושם. (שע\"ה סי' צג ס\"ד)"]]},{"h":"ה' סיון יום חמישי ערב חג שבועות. עירוב תבשילין. מט בעומר","s":"הלכות ליל חג השבועות","d":["להצלחה בלימוד התורה ומידות טובות להלל בן דקל | נריה חיים בן רועי ברכה והצלחה | שלום בית הצלחה ופרנסה דורון בן מתתיהו"],"b":[["t","לימוד תורה בחג"],["b","ישתדל כל אדם לעסוק בתורה ביום החג וכמו שאמרו חז\"ל (פסחים סח:) חציו לה' וחציו לכם. ויש להזהיר שלא יעבירו את היום בשינה. ויקבעו זמן ללמוד גם ביום טוב עצמו, אחר שינוחו מהלימוד של הלילה. (ילקו\"י סתצ\"ד סכ\"ט)"],["t","מנהג קישוט הפרחים ואכילת מאכלי חלב"],["b","אין אצלנו המנהג לשטוח עשבים ולהעמיד אילנות בשבועות בבית הכנסת או בבתים. וכן לא נהגו לאכול מאכלי חלב, אלא בשר כשאר ימים טובים. ויש מקומות שנהגו לאכול \"זלאבייא\" שהוא בצק מטוגן בהרבה שמן. ואפשר שהטעם לזה מפני שהתורה נמשלה לשמן כנזכר במדרשים. (שע\"ה סי' צג ס\"ה. וכ\"כ באמת ויציב ח\"ב עמ' ש\"פ)"]]},{"h":"ו' סיון יום שישי חג שבועות","s":"הלכות סעודות יום טוב","d":["להצלחת ברו\"ג לאוהד בן עזריאל"],"b":[["t","מהו חיוב סעודות החג?"],["b","חייב לאכול ביו\"ט שתי סעודות אחת בלילה ואחת ביום, אבל סעודה שלישית אין נוהגים ביו\"ט אלא בשבת בלבד. וחייב לקדש על היין קודם הסעודה, ולבצוע על שתי ככרות שלימות כמו בשבת. (שע\"ה סי' צ\"ח ס\"ג, ערי\"ש תקכ\"ט, י\"א-י\"ב)"],["t","מה הדין אם שכח \"יעלה ויבוא\" בברכת המזון?"],["b","מי ששכח לומר יעלה ויבוא בברכת המזון, אם נזכר קודם שהזכיר שם השם מן הברכה של \"ברוך אתה ה' בונה ברחמיו את ירושלים\", יאמר שם יעלה ויבוא ויסיים \"ובנה את ירושלים וכו'..\". ואם הזכיר השם בלבד, יסיים תיכף \"למדני חוקיך\" שלא יהא השם לבטלה וחוזר ליעלה ויבוא. ואם סיים את ברכת בונה ירושלים, יאמר שם \"ברוך אשר נתן ימים טובים לעמו ישראל לששון ולשמחה ברוך אתה ה' מקדש ישראל והזמנים\". ואם נזכר לאחר שהתחיל ברכה רביעית, אפילו אמר רק תיבת \"ברוך\" בלבד, שוב אין לו תקנה וחוזר לראש ברכת המזון. ודין זה שחוזר לראש ברכת המזון הוא בכל ימים טובים בין בסעודת הלילה ובין בסעודת היום. (שע\"ה סל\"ב סי\"ד)"]]},{"h":"ז' סיון יום שבת פרשת נשא. אסרו חג","s":"הלכות צדקה","d":["לעילוי נשמת אברהם בן יחיא וחממה עוזרי | לעילוי נשמת יחיאל בן יהושע | לעילוי נשמת מאיר בן חילווה | לרפואה, הצלחה, בריאות פרנסה טובה לליטל בת אפרת"],"b":[["t","האם מצוות הצדקה היא מן התורה?"],["b","מצות עשה ליתן צדקה לעניי ישראל, שנאמר פתוח \". וכל הרואה תפתח את ידך לו. ונאמר \"וחי אחיך עמך עני מבקש, והעלים עין ממנו ולא נתן לו צדקה, עובר בלא תעשה, שנאמר \"לא תאמץ את לבבך, ולא תקפוץ את ידך, מאחיך האביון\". (שע\"ה סי' קס\"ט ס\"א)"],["t","האם יכול להגרם דבר רע מן הצדקה?"],["b","לעולם אין אדם מעני מן הצדקה, ואין דבר רע ולא היזק מתגלגל בשביל הצדקה, שנאמר \"והיה מעשה הצדקה, שלום\": והצדקה דוחה גזירות רעות, ומוסיפה חיים לאדם, ומביאתו לחיי העולם הבא. (שע\"ה קס\"ט ס\"ג)"]]},{"h":"ח' סיון יום ראשון","s":"הלכות צדקה","d":[],"b":[["t","עד כמה חייבה התורה ליתן לעני?"],["b","עני המקבל בסתר, מחוייבים אנשי העיר ליתן לו כל מחסורו, כאשר היה רגיל מקודם שהעני. ועל זה נאמר \"די מחסורו אשר יחסר לו\". אבל עני המחזר על הפתחים, אין נותנים לו אלא מתנה מועטת לפי ערכו. ולכל הפחות יתנו לו בכל עיר לחם ומזון שיעור שתי סעודות, ומקום ללון. ואם הוא צריך לשאת אשה, וכן אשה הצריכה להינשא, נותנים להם צרכי הבית והוצאות הנישואין כפי הראוי להם. (שע\"ה קס\"ט ס\"ו)"],["t","מידות נתינת הצדקה"],["b","בא העני (המקבל בסתר)ושאל די מחסורו, ואין יד הנותן גת, נותן לו כפי השגת ידו. וכמה? מידה בינונית מש ליתן אחד מעשרה מנכסיו. נתינה פחות ממעשר, נקראת \"עין רעה\". ומצווה מן המובחר שיתן עד חמישית מנכסיו. אבל יותר מחומש לא יבזבז, שלא יצטרך לבסוף הוא עצמו לבריות. ובמקום שיש פיקוח נפש, יבזבז אף יותר מחומש (רמב\"ם הלכות מתנות עניים פ\"ז ה\"ה והלכות ערכין וחרמין פ\"ח הלי\"ג. טוש\"ע סי' רמ\"ט ס\"א. שע\"ה קס\"ט ס\"ח וט')"]]},{"h":"ט' סיון יום שני","s":"הלכות צדקה","d":["לעילוי נשמת זוהרה בת הרב שלום יצחק"],"b":[["t","תוספת מעלות בדרך נתינת הצדקה"],["b","יתן הצדקה ביד ימינו, שהיא החשובה. ואפילו הוא איטר. ועל פי האר\"י, טוב לעמוד בעת שנותן צדקה. והגבאי צריך להתחיל לאסוף מצד יד ימינו, כפי הכלל תמיד שכל פניות שאתה פונה, יהיו דרך ימין. (שע\"ה סי' קס\"ט הערה ה')"],["t","האם יש בני אדם שפטורים מן הצדקה:"],["b","כל אדם חייב ליתן צדקה כפי השגת ידו. ואפילו עני המתפרנס מן הצדקה, כגון שיש לו מעט ממון שלו, ואינו נושא ונותן בו (שמותר לו ליטול מן הצדקה, כיון שאין לו קרן כדי להתפרנס מן הריוח), מכל מקום חייב ליתן צדקה ממה שיתנו לו, הואיל ויש לו במה להתפרנס. ואפילו אינו יכול ליתן אלא דבר מועט, אל ימנע את עצמו, כי המעט משלו חשוב כמו הרבה מן העשיר. אבל כל שאין לו אלא די פרנסתו, אינו חייב ליתן צדקה, כי פרנסת עצמו קודמת לכל אדם. (שע\"ה קס\"ט ס\"ד)"]]},{"h":"י' סיון יום שלישי","s":"הלכות צדקה","d":["לעילוי נשמת מורי יהודה כהן בן אברהם | לעילוי נשמת יונה אהרון | ברכה והצלחה לנחמיה בן דוד","כמוהר\"ר ישעיהו משורר זצוק\"ל דיין בפ\"ת"],"b":[["t","האם אשה חייבת בנתינת צדקה?"],["b","אשה, חייבת גם כן בצדקה. אבל כשהיא נשואה, אין לקבל ממנה אלא מעט. אך לא צדקה מרובה, זולתי ברשות בעלה. ואפילו אם היא עוסקת במסחר וכדומה. (שע\"ה קס\"ט ס\"ה)"],["t","מה כמות הצדקה שאפשר לקבל מאשה נשואה?"],["b","מה נחשב מעט, שמותר לקבל אף ללא רשות בעלה, אינו סכום קבוע, אלא הדבר תלוי לפי עושר הבעלים ועניותם. ואם הבעל קמצן ומקפיד, אסור לקבל ממנה אפילו מעט, וזה נחשב גזל. וכן אם אשה נזהרת מבעלה שלא יראה, או שהיא מזהירה שלא יוודע לו מזה. ומכל מקום אשה שאומרת שהיא נותנת בשליחות בעלה או ברשותו, נאמנת, ולא צריך לחשוש. (שע\"ה קס\"ט ס\"ה)"]]},{"h":"יא סיון יום רביעי","s":"הלכות צדקה","d":["כמוהר\"ר יחיא יצחק הלוי זצוק\"ל - תרצ\"ב, אב\"ד צנעא וכל גלילות תימן"],"b":[["t","באיזה אופנים זכותו של-עני ליטול צדקה, ובאיזה לא?"],["b","חכמינו ז\"ל קבעו שאם יש לו מאתים זוז, אינו רשאי ליטול. אבל הדברים אמורים דווקא בזמנם, שהיה סכום מועט זה מספיק לעני להתקיים במשך שנה אחת. מפני שמלבד זה היו מחלקים לעניים בכל יום תמחוי, דהיינו לחם ושאר מיני מאכלים שגבו מן הבתים. וכן נטלו מן השדות לקט שכחה ופאה, ומעשר עני. לפיכך בזמן הזה שאין את כל אלו, יכול ליטול מן הצדקה יותר ויותר, עד שתהא לו קרן שיוכל להתעסק ולהתפרנס הוא ובני ביתו מן הריוח. (שע\"ה קס\"ט ס\"ז)"],["t","הלכות מעשר כספים"],["b","האם יש חיוב לתת עשירית מממון שהרויח?"],["b","אין חובה מן התורה ואף לא מדרבנן ליתן עשירית מכספים שהרויח. רק מגידולי קרקע נצטווינו להפריש תרומות ומעשרות, ולא מריוח ממון. אבל היא הנהגה טובה ומשובחת. ולא עוד אלא שמובטח לו שיזכה על ידה למעלת העושר. (שע\"ה קס\"ט ס\"ח וט')"]]},{"h":"יב סיון יום חמישי","s":"הלכות מעשר כספים","d":["לעילוי נשמת גדעון גולי (דוד) בן יעקב | ברכה והצלחה נאווה בת שלום"],"b":[["t","מעלת מעשר כספים"],["b","אף על פי שאמרנו שמעשר כספים איננה חובה, אלא הנהגה טובה. מכל מקום ישנם פסוקים בתורה שרומזים על מעשר כספים, כגון ממה שנאמר \"עשר תעשר את כל תבואת זרעך\", דורשים חז\"ל \"כל\" לרבות שאר רווחים. וכך נאמר (בראשית י\"ד כ') באברהם אבינו \"ויתן לו מעשר מכל\". וכן יעקב אבינו אמר \"וכל אשר תתן לי עשר אעשרנו לך\". ויש למעשר סוד ויסוד, לכן יזהר שלא להוסיף עליו ולא לגרוע ממנו, כי כל המוסיף גורע. ואם נותן יותר, יתכוון שהוא בתורת צדקה בעלמא, ולא מעשר. (שע\"ה קס\"ט ס\"ט)"],["t","יקבל על עצמו מצוות מעשר כספים בלי נדר"],["b","טוב שיתנה בתחילת קבלתו הנהגה זו, שהוא עושה אותה בלי נדר, וגם שאין בדעתו לנהוג כן לעולם. פן יכשל חס ושלום בעוון נדרים, אם מאיזו סיבה לא יקיים במשך הזמן. ונכון גם כן להתנות שאם יתברר לבסוף שחילק יותר מן המעשר או החומש של רווחיו בשנה זו, יוכל לנכותו מחשבון המעשר או החומש של שנה הבאה. (שע\"ה סי' קס\"ט סי\"א)"]]},{"h":"יג סיון יום שישי","s":"הלכות מעשר כספים","d":["מארי חיים בן מארי סעיד גראפי"],"b":[["t","מאלו רווחים מפרישים מעשר כספים:"],["b","הפרשת מעשר כספים היא מכל מה שמרויח האדם. כגון מעסקיו וסחורותיו, וכן ממשכורתו כגון שהוא כותב או מלמד, או תמורת מלאכה שעשה, כגון נגר, או חייט. והוא הדין ללומדי תורה המקבלים תמיכה מבית המדרש שהם לומדים בו. וכן אפילו אם מצא כסף, ואף אם קיבל ירושה או מתנה. ואף על פי שהבעלים כבר עישרו את הממון הזה, מכל מקום כיון שעבר לרשותו, צריך הוא גם כן לעשר. (שע\"ה קס\"ט סי\"ג)"],["t","מעשר כספים מן הקרן או מן הרווח?"],["b","שנה ראשונה יפריש את המעשר מן הקרן, מכאן ואילך, יתן מעשר מן הרווח שהרוויח כל שנה. (שע\"ה סי' קס\"ט ס\"י)"]]},{"h":"יד סיון יום שבת פרשת בהעלותך","s":"הלכות מעשר כספים","d":["לעילוי נשמת שגיב בן אורן ובשמת הלל ז\"ל | לעילוי נשמת יצחק בן צאלח ציון"],"b":[["t","כל כמה זמן יפריש מעשר כספים וכיצד יחשב את המעשר?"],["b","כדי שלא ישכח ויטעה, ירשום בפינקס מיוחד כל הרווחים שהזמין לו ה', אחר ניכוי ההוצאות המוכרחות לעסק. ואם אירע לו הפסד מרווחיו בתוך הזמן, ינכה אותו מן החשבון, והמעשר או החומש יהיה רק מן הנותר. וירשום בפינקסו כל מה שמזדמן לו ליתן לצדקה בתוך הזמן, כגון למחזרים על הפתחים, וינכה הכל מן המעשר או החומש. (שע\"ה קס\"ט סי\"ב)"],["t","למי נותנים כספי מעשרות?"],["b","עיקר המעשר ניתקן לחלקו לעמלי תורה למען יתחזקו לעסוק בתורת ה'. אמנם אם יש לו קרובים עניים, הם קודמים להם, ואפילו בניו ובנותיו הנשואים אם אין להם כדי פרנסתם. ואפילו לאביו ולאמו מותר ליתן. אבל אם יש בידו יכולת לפרנסם ממקום אחר, על זה אמרו חכמים תבוא מארה למי שמפרנס אביו ואמו ממעות צדקה. (שע\"ה קס\"ט סי\"ד)"]]},{"h":"טו סיון יום ראשון","s":"הלכות מעשר כספים","d":["בריאות איתנה ושפע פרנסה ימימה בת שלמה"],"b":[["t","אלו מעשה מצוה אפשר להשתמש בכספי מעשר?"],["b","יכול להשתמש במעשר כספים להכניס לחופה חתן וכלה נזקקים, או לחולים נצרכים וכדומה. וכן לבנייתם והחזקתם של מקוואות, בתי כנסיות ובתי מדרשות וכדומה מצרכי הציבור. אבל לא לקנות לעצמו חפץ של מצוה, כגון תפילין ואתרוג. (אבל התוספת להידור מצוה, יכול ליקח מן המעשר). ואף לא מתנות לאביונים בפורים, כיון שזו חובה נפרדת. (שע\"ה קס\"ט סט\"ו)"],["t","האם יש מצווה לתת צדקה לאדם שעובר עבירות במזיד?"],["b","עני שהוא עבריין במזיד על אחת מכל המצוות האמורות בתורה ולא עשה תשובה, אין חובה ליתן לו צדקה, ולא להלוות לו. אך עניי גויים מפרנסים ומלבישים אותם מפני דרכי שלום. (שע\"ה סי' קס\"ט סט\"ז)"]]},{"h":"טז סיון יום שני","s":"הלכות מעשר כספים","d":[],"b":[["t","האם מותר לקנות במעשר, עליה לתורה ושאר דברים של מצוה:"],["b","יש אומרים שמותר לקנות במעשר מברכים (עליות)"],["b","בספר תורה, או שאר מצוות בבית הכנסת, הן שיקרא הוא עצמו, הן אם מכבד לאחר, ובלבד שנתכוון בשעת קנייתו שישלם זאת מן המעשר, ולא שאחרי כן עלה בדעתו לפרוע חובו מזה. ויש מתירים אף כל דברים של מצוה, אם לולא המעשר לא היה יכול לעשותם, כגון מנורות לבית הכנסת, ספרים ללמוד בהם ולהשאילם, [ובתנאי שירשום עליהם שנקנו ממעשר כספים]. (שע\"ה קס\"ט סט\"ו)"],["t","האם יכול לתת מכספי מעשר לחינוך הבנים:"],["b","הנותן לבניו ולבנותיו כשאינו חייב במזונותיהם מצד ההלכה, דהיינו כאשר הם יותר מגיל שש שנים, כדי ללמדם תורה, ולהנהיגם בדרך ישרה, הרי זה נחשב לו לצדקה. ולא עוד אלא שצריך להקדימם לאחרים. ואפילו אינו בנו אלא קרובו, הוא קודם לכל אדם. ועניי ביתו קודמים לעניי שכונתו, ועניי שכונתו קודמים לעניי עירו, ועניי עירו קודמים לעניי עיר אחרת, שנאמר (דברים ט\"ו י\"א) \"לאחיך לענייך ולאביונך בארצך\". (שע\"ה קס\"ט סי\"ט)"]]},{"h":"יז סיון יום שלישי","s":"הלכות מעשר כספים","d":[],"b":[["t","נתינת צדקה בסבר פנים רעות:"],["b","כל הנותן צדקה לעני בסבר פנים רעות ופניו כבושות בקרקע, אפילו נתן לו אלף שקלים, איבד את זכותו והפסידה, ועובר על \"ולא ירע לבבך בתתך לו\". אלא צריך ליתן לו בסבר פנים יפות ובשמחה, ומתאונן עמו על צרתו, כמו שאמר איוב \"אם לא בכיתי לקשה יום, עגמה נפשי לאביון\". וידבר אליו דברי נחמות, שנאמר \"ולב אלמנה ארנין\". (שע\"ה קס\"ט ס\"כ)"],["t","מהי הצדקה המשובחת?"],["b","הרוצה לזכות את עצמו, יכוף את יצרו הרע, וירחיב ידו. וכל דבר שהוא לשם שמים, יהיה מהטוב והיפה. כגון אם בנה בית הכנסת, יהיה נאה מהבית שהוא יושב בו. האכיל רעב, יאכילהו מהטוב ומהמתוק שבשולחנו. כיסה ערום, יכסהו מהיפה שבכסותו. הקדיש דבר, יקדיש מהיפה שבנכסיו. וכן הוא אומר (ויקרא ג' ט\"ז) \"כל חלב, לי\"י\". דהיינו מן המובחר, כמו \"ואכלו את את חלב הארץ\" (בראשית מ\"ה י\"ח). (שע\"ה קס\"ט סי\"ח)"]]},{"h":"יח סיון יום רביעי","s":"הלכות שבת דיני מלאכת צד","d":[],"b":[["t","על איזה צידה בשבת חייבים מהתורה?"],["b","הצד בשבת חייב חטאת, והצידה שחייבים עליה מהתורה, הוא בדבר שדרך מינו לצוד אותו כגון חיה ועופות ודגים. והצד דבר שאין דרך מינו לצוד אותו, הרי זה פטור מן התורה אבל אסור לעשות כן מדברי סופרים. (בני\"מ פ' ע\"ג הל' א')"],["t","האם חייב דווקא שתפשו בידו?"],["b","הצד בשבת חייב בין אם תפשו בידו או ע\"י מצודה וכדומה. ואפילו החיה או העוף נכנסו מעצמם לתוך הבית או הכלוב, והוא רק סגר עליו את הדלת או החלון, הרי זה חייב. (שם ב')"]]},{"h":"יט סיון יום חמישי","s":"הלכות שבת דיני מלאכת צד","d":["לעילוי נשמת יחיא סעיד הרון | לעילוי נשמת אמי מורתי סעידה בת אהרן | לעילוי נשמת דבורה נשיא בת שלום"],"b":[["t","מה הדין הצד בשבת למקום המחוסר צידה?"],["b","איסור צידה מהתורה הוא דווקא אם צד למקום קטן שניצוד בו. אבל אם הכניסו למקום גדול, הרי זה פטור מן התורה, שאין זו צידה גמורה. ומכל מקום אסור מדברי סופרים. (בני\"מ פ' ע\"ג הל' ג')"],["t","מה ההגדרה של מקום קטן שחייב מהתורה?"],["b","זה הכלל; כל מקום שאם ירוץ בו אדם בינוני, הוא יתפוש את החיה או העוף בריצה אחת, ואינו צריך להינפש בינתיים קודם שיתפסנו, הרי זה מקום קטן שאינו מחוסר צידה, והצד אותו לשם חייב. (בני\"מ פ' ע\"ג הל' ד')"]]},{"h":"כ' סיון יום שישי","s":"הלכות שבת דיני מלאכת צד","d":["לעילוי נשמת הרב ישראל בן יחיא","הרה\"ג ישראל שרעבי זצוק\"ל - תש\"ס, ראש שוחטים ברה\"ע","כמוהר\"ר לוי חמדי זצוק\"ל - תר\"ץ, מרבני צנעא ירושלים"],"b":[["t","מה ההגדרה של צידה למקום גדול, שאסור בשבת מדברי סופרים?"],["b","כל מקום שהוא גדול, או שיש בו פינות וזויות, בענין שגם אם ירדוף אחר החיה או העוף, אינו יכול לתופשו שם בריצה אחת, וצריך לרוץ אחריו שוב, או שצריך לעשות איזה תחבולה כדי לתופשו, הרי זה מקום המחוסר צידה, ופטור מן התורה, ואסור מדברי סופרים. (בני\"מ פ' ע\"ג הל' ה')"],["t","האם מותר להכניס בעל חי ממקום קטן, לכלוב?"],["b","אם הבעל חי במקום קטן, מותר לדחותו ולהכניסו לכלוב ולנעול בפניו, שכיון שעומד במקום שאינו מחוסר צידה, הרי הוא כניצוד ועומד, ואין צידה אחר צידה. ובלבד שלא יגביהנו, שכל בעלי חיים מוקצה, ואסורים בטלטול. (שם הל' ו')"]]},{"h":"כא סיון יום שבת פרשת שלח לך","s":"הלכות שבת דיני מלאכת צד","d":[],"b":[["t","האם מותר לסגור דלת או חלון על עוף שנכנס לבית בשבת?"],["b","כל העופות כגון יונה או תור וכיוצא הם, אם סוגר בפניהם את הפתח או החלון, איסורו מן התורה. חוץ מציפור דרור, הואיל וטבע הציפור דרור שאינה מקבלת מרות, ודרכה להישמט מזוית לזוית, ולכן אין זו צידה מן התורה, אבל אסור מדרבנן. (בני\"מ פ' ע\"ג הל' ט')"],["t","מה הדין אם סוגר פתח אחד, ויש עוד פתח פתוח?"],["b","עוף שנכנס לחדר ויש שם חלון פתוח, מותר לסגור את הדלת בפניו, כיון שיכול לצאת דרך החלון, וכן בחיה שנכנסה לבית יכול לסגור את הדלת בפניה אם יש פתח פתוח מצד אחר, ואין זה נקרא צידה. (שם י\"א)"]]},{"h":"כב סיון יום ראשון","s":"הלכות שבת דיני מלאכת צד","d":["אדל בת כפיר ברכה והצלחה"],"b":[["t","מה הדין אם סגר בשבת דלת או חלון, ולא ידע שיש עוף בבית?"],["b","הסוגר דלת או חלון בשבת, ולא ידע שיש חיה או עוף בתוך הבית, אינו חייב לפתוח את הדלת, מפני שקדם מעשה הצידה למחשבת הצידה, ויכול להניחו כך עד מוצאי שבת, ולקחת אותו במוצאי שבת. (בני\"מ פ' ע\"ג הל' י\"ג)"],["t","האם מותר לסגור דלת חדר שיש שם עכבר או חתול?"],["b","חתול או עכבר שנכנס לאחד מחדרי הבית בשבת, ויש לבני הבית פחד ובהלה ממנו, מותר לסגור את דלת החדר בעדו שלא יצא, הואיל וחתול ועכבר משתוללים כשבאים לתופשם, והחדר נחשב כמקום גדול המחוסר צידה שאינו אלא מדרבנן, ובמקום צער מותר כשאינו מכוון, ולא איכפת לו בצידתו. (שם הל' יז)."]]},{"h":"כג סיון יום שני","s":"הלכות שבת דיני מלאכת צד","d":["ברכה והצלחה בתחן בת סעדיה"],"b":[["t","האם מותר בשבת לסגור חלון מפני הקור כשיש עוף בבית?"],["b","ציפור שנכנסה לבית, והוא בזמן הקור שיש צער צינה, יפריח תחילה את הציפור החוצה, ואחר כך יסגור. ואם אי אפשר להוציאה כגון שנחבאת וכדומה, אם מדובר בציפור דרור שגם כשהיא בבית אין כאן צידה מדאורייתא, אלא מדרבנן, הרי זה פסיק רישיה דלא איכפת ליה באיסור דרבנן, ובמקום צער התירו. (שם הל' ט\"ז)"],["t","מה הדין בחיה או ציפור שסגירת דלת הבית היא צידה האסורה מהתורה?"],["b","בשאר חיה ועוף (לא דרור) שבסגירת הדלת או החלון, יש איסור מהתורה, אסור לסגור אף על פי שהוא מצטער, ואפילו שלא מכוון לצידה. אמנם במקום חולי או חשש חולי, אפשר להקל לסגור את הדלת או החלון בשינוי כלאחר יד. (שם)"]]},{"h":"כד סיון יום שלישי","s":"הלכות שבת דיני מלאכת צד","d":["לעילוי נשמת עופר בן סעיד שרעבי ז\"ל | לעילוי נשמת שאלתיאל צעדי בן סאלם | ברכה והצלחה ורפוא\"ש לזהבה בת טפחא"],"b":[["t","כיצד לפתוח כלוב להאכיל בעלי חיים?"],["b","כשמכניסים אוכל בשבת לחיות או עופות צריך להיזהר שלא לפתוח הפתח לגמרי, כי אז אסור לסוגרו משום צידה. אלא יפתח בצמצום, או שיסתום חלל הפתח בידו, או בגופו, שלא יוכלו לצאת משם, ואז יוכל לחזור ולסגור. (שם כ\"ב)"],["t","האם מותר לסגור בשבת דלת כלוב של תוכים שנפתחה?"],["b","ציפורי נוי כגון תוכים הנתונות בתוך כלוב, ונפתח הכלוב לגמרי, אין לחזור ולסוגרו בשבת, מפני שנחשב כמו שצד אותם מחדש. וכן אין לישב או לעמוד על הפתח בענין שאינם יכולים לצאת מפניו. והוא הדין בשאר בעלי חיים. ואם הוא חושש שיברחו, יכול לומר לגוי לסגור את הכלוב. (בני\"מ פ' ע\"ג הל' כג' ובהע' ל\"ד ל\"ו)"]]},{"h":"כה סיון יום רביעי","s":"הלכות שבת דיני מלאכת צד","d":["איתי בן כפיר ברכה והצלחה"],"b":[["t","האם מותר להעמיד בשבת מלכודת לבעלי חיים?"],["b","אסור להעמיד מצודה לחיה או לעופות או לדגים. ואם העמיד מצודה, ובשעת העמדה, נכנס חיה או עוף וכדומה לתוכה, הרי זה חייב חטאת. ואם לאחר שגמר להעמידה, נכנס, אסור מדברי סופרים.(בני\"מ פ' ע\"ג הל' כז')"],["t","האם מותר להעמיד בשבת מלכודת עכברים?"],["b","וכן אסור להעמיד בשבת מלכודת לצוד בה עכברים, חתולים, וכדומה. ואפילו שצד על דעת לזורקם. והמלכודת עצמה מוקצה, ואסורה בטלטול, משום כלי שמלאכתו לאיסור. (שם כ\"ט)"]]},{"h":"כו סיון יום חמישי","s":"הלכות שבת דיני מלאכת צד","d":[],"b":[["t","האם מותר להעמיד מלכודת מערב שבת?"],["b","מותר לפרוס מצודות מערב שבת, והן צדות בשבת. מפני שמותר להתחיל מלאכה מערב שבת והיא נגמרת מאליה בשבת. והוא הדין שמותר להעמיד מלכודת עכברים מערב שבת, והם ניצודים בשבת. (בני\"מ פ' ע\"ג הל' כ\"ח כ\"ט)"],["t","מה עושים עם מלכודת שנתפס בה עכבר בשבת?"],["b","מלכודת שהעמידה מערב שבת ונתפס בה עכבר בשבת, מותר לטלטלו עם מצודתו ולהוציאו לחוץ, אם הוא במקום שמאוס בעיניהם, משום גרף של רעי. (שם ל')"]]},{"h":"כז סיון יום שישי","s":"הלכות שבת דיני מלאכת צד","d":["סלמה (שולמית) בת סלימאן ברכה והצלחה"],"b":[["t","האם יש בשבת איסור צידה בזבובים, יתושים, וכדומה?"],["b","זבובים, יתושים, פרעושים, נמלים, וכדומה. אף על פי שאין דרך העולם לצוד מינים אלו, אסור לצודן בשבת מדרבנן, וכן אסור לתופשם בידו, או על ידי כלי, אפילו לזמן קצר על מנת להוציא לחירות. (בני\"מ פ' ע\"ד הל' ד')"],["t","האם מותר להורגם בשבת?"],["b","יש למחות באותם בני אדם, שכשבא אליהם זבוב טורד או יתוש וכדומה, הם מנסים להורגו או לתופשו בידיהם כדי לסלקו, וכדרכם בחול, וזה אסור. אבל לסלקו על ידי הנפת מטלית, בלי לצוד, או להרוג מותר. (שם)"]]},{"h":"כח סיון יום שבת פרשת קרח","s":"הלכות שבת דיני מלאכת צד","d":["לעילוי נשמת סעדה בת עיד'ה | ברכה והצלחה נדב בן אופיר"],"b":[["t","האם בשבת יש איסור צידה בכינים?"],["b","מותר לצוד כינים, ואפילו להרוג אותם בשבת, מפני שהם מתהווים מן הזיעה, ואינם פרים ורבים מזכר ונקבה. אבל לסרוק את השיער במסרק סמיך כדי להוציאם, אסור. מפני שהוא תולש שיער. (בני\"מ פ' ע\"ד הל' י\"ג)"],["t","האם מותר לסגור בשקית פרי שיש בו תולעים?"],["b","פרי שיש בו תולעים, וכן כל דבר מאכל מתולע מותר לסגרו בתוך שקית או בתוך קופסא ולזורקו לאשפה, אף על פי שאין התולעים יכולים לצאת משם. ואין בכך משום צידה, ששם הוא מקומם, לשבוע מפריו ולאכול מטובו. (שם י\"ד ובהערה כ\"ז)"]]},{"h":"כט סיון יום ראשון ערב ראש חודש","s":"הלכות שבת דיני מלאכת צד","d":["לעילוי נשמת ניסים בן סעיד סאלם חדד"],"b":[["t","מה עושים כשרואים נחש או עקרב בשבת (ללא חשש פיקוח נפש)?"],["b","רמשים המזיקים, כגון נחשים ועקרבים וכיוצא בהם, אף על פי שאינם ממיתים, הואיל ונושכים, מותר לצוד אותם בשבת, ואפילו אם אינם רודפים אחריו, כיון שיש לחוש שמא יפנו אליו, או אל אדם אחר ויזיקוהו. (בני\"מ פרק ע\"ה)"],["t","למה צידת נחשים הנושכים, ולא ממיתים מותרת בשבת?"],["b","הטעם שהתירו לצודם, הואיל ואין כאן צידה מהתורה, שהרי הוא לא צריך את הנחש, אלא כל כוונתו להרחיק את ההיזק מעליו, וחשיב \"מתעסק\", שאיסורו מדרבנן. ובמקום צער הגוף, לא גזרו חכמים. (שם הלכה א')"]]},{"h":"ל' סיון יום שני א' דראש חודש","s":"הלכות שבת דיני מלאכת צד","d":[],"b":[["t","האם מותר להרוג נחש בשבת?"],["b","הרואה נחש בשבת, ואינו יודע אם הוא ארסי או לא, והוא במקום שיש חשש שינשוך אותו, או את אחרים, אם יכול לכפות עליו כלי, או לדרוס אותו ברגליו לפי תומו, יעשה כן. ואם אינו יכול לעשות כן, יכול להורגו מיד בכל דרך אפשרית, מחשש סכנה. ובמקום שאין חשש סכנה, עדיף להורגו ע\"י גוי. (בני\"מ פ ע\"ז הל' כ\"ג)"],["t","מה הדין בכלב או תן שרודפים אחריו בשבת?"],["b","היה כלב או תן רודפים אחריו לנשכו, מותר להורגם בשבת. וגם אדם אחר יכול להורגם כדי להציל את הנרדף. ואף על פי שאינם ממיתים מותר להורגם בשבת. (שם הלכה כ\"ד)"]]},{"h":"א' תמוז יום שלישי ב' דראש חודש","s":"הלכות שבת דיני מלאכת צד","d":[],"b":[["t","האם מותר לצוד דבורה בשבת כדי שלא תזיקו?"],["b","צרעה או דבורה, אם לפי המצב והמקום יש לחוש שתעקוץ, מותר לצוד אותה כדי שלא תזיק, אבל אסור להורגה. ואם רודפת אחריו לעוקצו, יכול להורגה, הואיל ויש נזק וצער גדול בעקיצתה להרבה בני אדם. (פרק ע\"ה ה'. פ' ע\"ז כ\"ה)"],["t","האם מותר לצוד יתוש בשבת?"],["b","רמשים שאין נמשך היזק מנשיכתם, אף על פי שהם מצערים, כגון יתושים, פרעושים, וכיוצא בהם, מכל מקום אין זה צער גמור, ואסור לצודן בשבת. (פ' ע\"ה ו')"]]},{"h":"ב' תמוז יום רביעי","s":"הלכות שבת דיני מלאכת צד","d":["לעילוי נשמת רחל בת זכריה וחממה ידעי"],"b":[["t","מה יעשה כשפרעוש או נמלה על גופו בשבת?"],["b","אם היה הפרעוש או הנמלה על גופו ועוקצו, מותר לתופשו בידיים ולהשליכו מעליו, ואין בזה לא צידה, ולא מוקצה. שבמקום צער לא גזרו חכמים."],["b","ואם הוא עתה אינו עוקצו, אבל חושש שיעקצנו, יש אומרים שמותר לתופשו ולהשליכו."],["b","ולכתחילה יש להחמיר. והמיקל, אין מוחין בידו. ועדיף שיפילנו לארץ על ידי ניעור הבגד וכדומה. (פ' ע\"ה הל' ז')"],["t","האם מותר להוציא בשבת יתוש שמפריע לו לישון?"],["b","יתוש שנמצא בחדר ומטריד מאוד עד שאינו יכול לישון, יש אומרים שמותר לכפות עליו כלי, או לתופשו ולהוציאו החוצה, ויש אוסרים."],["b","ובמקום דוחק וצער שיש בו ממש, המיקל יש לו על מה שיסמוך. ובלבד שיזהר שלא להורגו, שזה אסור. (שם ח')"]]},{"h":"ג' תמוז יום חמישי","s":"הלכות שבת מלאכת בורר","d":["לעילוי נשמת אהרון בן ג'ורג'י | לעילוי נשמת אהרון בן משה | לעילוי נשמת יעקב בן יוסף | הראל בן אריה עוזירי תשובה שלימה זיווג הגון פרנסה ובריאות | ברכה והצלחה לארז בן בנימין | ברכה והצלחה לעינת ידעי"],"b":[["t","מה הדין לברור פסולת מאוכל, או אוכל מפסולת בשבת?"],["b","אוכל המעורב עם פסולת, אסור לברור ולהוציא את הפסולת מתוך אוכל, ואיסורו מן התורה. ואפי' אם בורר ביד, ואוכל מיד, חייב מן התורה. האופן המותר הוא, לברור את האוכל מן הפסולת, דווקא ביד, ולאוכלו מיד. ואם מניחו לאוכלו לאחר זמן, איסורו מן התורה. (בנין משה פ' יג' סעיף ב')"],["t","מה דין ברירה בכלי בשבת?"],["b","אסור לברור בשבת בכלי, ואפילו אוכל מתוך פסולת. ואם בורר בכלי המיוחד לברירה, כגון נפה, איסורו מהתורה. ואם בורר בכלי שאינו מיוחד לברירה, איסורו מדרבנן, גזירה שמא יברור בכלי המיוחד לברירה. (בנין משה פ' טו' סעיף א')"],["b","נמצא שבג' תנאים מותר לברור. אוכל, ביד, ומיד. (שם סעי' ג' ד')"]]},{"h":"ד' תמוז יום שישי","s":"הלכות שבת מלאכת בורר","d":["לעילוי נשמת שלום בן ר' סעדיה | לעילוי נשמת שמעון בן סעיד עורקבי | ברכה והצלחה ורפוא\"ש להודיה בת אלדד","כמוהר\"ר מחפוץ נגאר זצוק\"ל - תש\"מ, מרבני סוואדייה"],"b":[["t","מה הדין ליטול אוכל בכף ומזלג ולקלוף בסכין?"],["b","מותר ליטול אוכל בכף ומזלג מתוך פסולת. וכן מותר לקלוף פירות בסכין, אם דעתו לאוכלו לאלתר. ולא נחשב ברירה בכלי שאסור, הואיל וכך הוא דרך אכילת בני אדם, ואינו דרך מלאכה האסורה. (שם ב')"],["t","מה הדין לברור אוכל מאוכל בשבת?"],["b","היו לפניו שני מיני אוכלים מעורבים, כגון בוטנים, שקדים, וכדומה. המין שרוצה לאוכלו עכשיו, נחשב אוכל. והמין השני שאין חפץ לאוכלו עתה, חשיב פסולת. ולכן לא יברור אלא את המין שרוצה לאוכלו עתה. (בנין משה פ' יג' סעיף ה')"]]},{"h":"ה' תמוז יום שבת. לשאמי, פרשת חוקת. לבלדי, חוקת בלק","s":"הלכות שבת מלאכת בורר","d":[],"b":[["t","מה הדין לברור אוכל מאוכל כדי לאוכלם עתה?"],["b","אם ביררם בידו לאכול שניהם לאלתר כל אחד בפני עצמו, הרי זה מותר. ואסור לברור שני מיני אוכלים גם כשמכוון להניח שניהם לאחר זמן. (שם סעיף ו')"],["t","מה הדין להוציא בשבת מתערובת פסולת עם מעט אוכל?"],["b","אוכל ופסולת המעורבים, מותר ליטול את הפסולת אם הוא מוציא עמו מעט מהאוכל. ונכון שיוציא שיעור ניכר מן האוכל. ולברור רק מעט מהפסולת בפני עצמו, אפילו שלא הוציא את כל הפסולת אסור. (בנין משה פ' יג' סעי' יז' יח')"]]},{"h":"ו' תמוז יום ראשון","s":"הלכות שבת מלאכת בורר","d":["כמוהר\"ר שלמה מנצורה זצוק\"ל - תרי\"ט, מחכמי צנעא"],"b":[["t","מה הדין להזיז פסולת לצד בתוך התערובת?"],["b","פסולת המעורב באוכל אסור להזיזו לצדדים, בידו, או בכף, ואפילו שאינו מוציאו לגמרי מחוץ לאוכל. ולכן גרעיני לימון שנפלו לסלט, לא יסלק הגרעינים לצדדים אלא אם כן יסלק עמהם מקצת מן האוכל. (שם סעיף יט')"],["t","מה הדין לברור בשבת שני מינים המונחים זה לצד זה?"],["b","שני מיני אוכלים, וכן אוכל ופסולת, שאינם מעורבים, אלא עומדים זה בצד זה, אף אם שני המינים סמוכים ונוגעים אחד בשני, כיון שכל מין מסודר בפני עצמו, אין זה נקרא תערובת, ומותר ליטול מהם מה שירצה. (בנין משה פ' יג' סעיף כ')"]]},{"h":"ז' תמוז יום שני","s":"הלכות שבת מלאכת בורר","d":[],"b":[["t","מה הדין לברור שני מינים שמונחים זה על גבי זה?"],["b","שני מינים שאינם מעורבים, אלא מונחים זה על גבי זה, כגון פירות, וכדומה, יש שמחשיבים זה כתערובת, ומותר ליטול רק כדי לאוכלו מיד. אבל דעת מהרי\"ץ, כל דבר שהוא צף ועומד למעלה, כולו, או אפילו מקצתו, כיון שאין צריך לתור ולפשפש אחריו, אין זה חשיב מעורב, ואין בהוצאתו משום איסור בורר."],["s","(שם סעיף כא')"],["t","מה הדין מי שברר בשבת באיסור?"],["b","אם ברר במזיד באופן האסור, אסור לו באכילה לעולם. ואם חזר וערבם, אסור לו בו ביום עד מוצאי שבת, משום קנס. ואם ברר בשוגג, אסור בשבת, ומותר במוצאי שבת. ואם חזר וערבם, מותר לו לאכול אף בשבת. (שם סעיף כו')"]]},{"h":"ח' תמוז יום שלישי","s":"הלכות שבת מלאכת בורר","d":["ברכה והצלחה ליעקב בן גיא | ברכה והצלחה ישי בן לירן מהו השיעור סמוך לסעודה שמותר לברור בשבת?"],"b":[["b","בורר לאלתר שמותר כל שבורר סמוך לסעודה, גם אם לא יאכלנו רק בסוף הסעודה. שכל זמן שיושב בסעודה אפילו כמה שעות חשוב הכל כאכילה אחת וענין אחד,"],["b","ואם אוכלם לאחר ברכת המזון יש להחמיר שלא לברור קודם הסעודה. (שם סעי' ד' וה')"],["b","וזמן סמוך לסעודה, הוא מעת שמתחילים לתקן צרכי סעודה. ובדרך כלל יש לשער זמן זה מעת יציאת האנשים מבית הכנסת והוא בערך כחצי שעה."],["s","(בנין משה פ' יד' סעיף א')"],["t","מה הדין כשיש לו הרבה לברור?"],["b","אם יש לו כמות גדולה לברור, והברירה תימשך זמן רב קודם הסעודה, כגון בסעודה גדולה, מותר להתחיל לברור אפילו ביותר משעה קודם הסעודה, ובתנאי שכשיגמור לברור יהיה בזמן סמוך לסעודה, כי שיעור סמוך לסעודה, נמדד מסוף הברירה. (שם סעי' א' ב')"]]},{"h":"ט' תמוז יום רביעי","s":"הלכות שבת מלאכת בורר","d":["לעילוי נשמת שמס צפר בת חסן ז\"ל | לעילוי נשמת אבי דוד בן זוהרה ויעקב יעקובי ז\"ל | לעילוי נשמת ברוריה נחמה בת דינה | להצלחה ברו\"ג וזיווג הגון ליהונתן שלום בן דקל"],"b":[["t","מה שיעור לאלתר בבורר באכילה מועטת?"],["b","אם אינו בורר אלא לצורך אכילה מועטת ולעצמו בלבד ואין לו דבר אחר שהוא צריך להכין ולעשות עוד קודם כדי שיאכלנו, לא יברור אלא סמוך לאכילתו ממש דקות אחדות לפני כן ולא קודם. (בנין משה פ' יד' סעיף ג')"],["t","מה הדין לברור קודם הסעודה לצורך סוף הסעודה?"],["b","מותר לברור סמוך לסעודה גם אם לא יאכלנו רק בסוף הסעודה כגון שבורר מיני פירות וקטניות כדי להגישם בסוף הסעודה שכל זמן שיושב בסעודה אפילו כמה שעות חשוב הכל כאכילה אחת ועניין אחד, ואם אוכלם לאחר ברכת המזון יש להחמיר שלא לברור קודם הסעודה. (שם סעי' ד' וה')"]]},{"h":"י' תמוז יום חמישי","s":"הלכות שבת מלאכת בורר","d":["לעילוי נשמת אסתר בת סעיד סאלם | ברכה והצלחה ליעקב בן גלעד | שלום בית הצלחה ופרנסה מירב בת סעדה"],"b":[["t","האם מותר לברור בשבת לצורך אחרים?"],["b","מותר לברור בידו אוכל מתוך פסולת לאלתר, ולצורך אחרים, ואף על פי שאינו אוכל עמהם. וכן מותר לברור בידו כדי להאכיל בעלי חיים שמזונותם עליו. ויכול לברור להם פסולת מאוכל, שהפסולת נחשבת להם כאוכל, והרי זה כבורר אוכל מתוך פסולת. (בנין משה פ' יד' סעיף ו')"],["t","האם מותר לברור לכבוד אורחים יותר מכדי אוכלם?"],["b","מי שבאו אליו אורחים והוא יודע בוודאות שהם לא יאכלו כל מה שיניח לפניהם, וגנאי להביא לפניהם קערה חסרה, מותר לברור בשבילם כדי מילוי הקערה, שכל הקערה חשובה צורך אותה סעודה (שם סעיף ח')"]]},{"h":"יא תמוז יום שישי","s":"הלכות שבת מלאכת בורר","d":["לעילוי נשמת דליה (גליה) בת מורי יחיא בסיס"],"b":[["t","מה הדין לברור בשבת לצידה לדרך?"],["b","הבורר אוכל כדי ליתנו מיד לאורח היוצא מביתו כדי שיהיה לו צידה לדרך ויודע שלא יאכלנו מיד כיון שאינו אוכלו לאלתר אלא לאחר זמן הרי זה אסור."],["s","(בנין משה פ' יד' סעיף יא')"],["t","מה דין הבורר לאכול לאלתר ונמלך?"],["b","הבורר על דעת לאכול לאלתר אם הוא מוכרח להשהותו לאחר זמן מאיזה סיבה יניח כל מה שבירר לפניו ויאכל ממנו מעט והנשאר שלא יוכל לאכול, יניח. ואם מחמת אונס אינו יכול לאכול אין בכך כלום. (שם סעיף יב')"]]},{"h":"יב תמוז יום שבת. לשאמי, פרשת בלק. לבלדי, פרשת פנחס.","s":"הלכות שבת מלאכת בורר","d":[],"b":[["t","האם מותר לברור בשבת באופן שמצמיד את הכף לסיר או לצלחת?"],["b","אם כשלוקח אוכל עם המצקת מתוך הסיר, מצמיד את הכף או המצקת לדופני הקדירה, או תוך כדי שמערה לתוך הכלי, דוחק שולי הכף או המצקת בתוך הכלי, כדי שיצא רק המשקה, בכל אופנים אלו דינו כבורר ביד שמותר לאלתר. ובלבד שבורר אוכל מתוך פסולת. (בנין משה פ' טו' סעיף ד')"],["t","האם מותר להשתמש בשבת בקנקן שיש בראשו רשת?"],["b","קנקן שיש בפתחו רשת לעכב קוביות הקרח שלא ירדו עם המים מותר להשתמש בו בשבת וכן בקנקן עם עלי תה שבראשו מסננת מותר לערות מתוכו את תמצית התה כדי לשתותו לאלתר. (בנין משה פ' טו' סעי' ה' ז')"]]},{"h":"יג תמוז יום ראשון","s":"הלכות התענית","d":[],"b":[["t","מה הטעם שמתענים בשבעה עשר בתמוז?"],["b","בשבעה עשר בתמוז אירעו חמש צרות. (א) נשתברו הלוחות כשירד משה מן ההר, (ב) נתבטל קרבן התמיד."],["b","(ג) הובקעה העיר בחורבן בית שני {אף על גב דבחרבן ראשון הבקעה בתשעה לחדש, דכתיב \"בחדש הרביעי בתשעה לחדש ויחזק הרעב בעיר\" וגו' \"ותבקע העיר\" אבל בחורבן השני בשבעה עשר בו הובקעה העיר, וחורבן בית שני הוא סיבת היותינו בגלות הזה. ועוד איתא בירושלמי, שגם בראשון היה בשבעה עשר, אלא שמפני הצרות טעו בחשבון} (ד) ושרף אפוסטמוס הרשע ספר התורה.(ה) והעמיד צלם בהיכל. (סי' ק\"ב ס\"ב)"],["t","האם יש עינויים בשאר צומות?"],["b","מעיקר הדין כל הצומות חוץ מט' באב ויום הכיפורים מותרים ברחיצה ותספורת ותשמיש המטה. אלא שהביאו הפוסקים שבעל נפש יחמיר על עצמו וינהג בכל הצומות כמו בט' באב [למעט נעילת הסנדל שלא יראה כחוכא ואטלולא (פירוש, צחוק וליצנות) שלא יחמיר]. וכן הדין בלשמוע כלי זמר יש להחמיר. (שע\"ה ק\"ב ו' עריכת השולחן תק\"נ)"]]},{"h":"יד תמוז יום שני","s":"הלכות התענית","d":["לכמוהר\"ר דוד משרקי זצוק\"ל - הודן ומאורן של ישראל הרה\"ג דוד משרקי זצ\"ל (בני ברק) דור שישי"],"b":[["t","האם אומרים 'עננו' בכל התפילות?"],["b","מוסיפים בתפילת הלחש \"עננו\" בברכת שומע תפילה. ולא רק בשחרית ומנחה, אלא גם בערבית של ליל התענית, אף על פי שמותרים עדיין באכילה ושתיה וכן המנהג. והנוהגים שלא לאמרו אינו אלא מחסרון ידיעה, ואם שכח ולא אמרו אינו חוזר. (ק\"ב סעיף י')"],["t","האם מי שאינו מתענה יכול לעלות לתורה?"],["b","מי שאינו מתענה, לכתחילה לא יעלה לתורה. ובדיעבד אם קראוהו אז, אם נמצאים בימי שני וחמישי יעלה כי יש חיוב ספר תורה בלי הצום . אבל בשאר ימים לא יעלה, אלא יאמר שאינו מתענה. והגבאי לא צריך לשאול את העולה לתורה אם הוא צם, שחזקה על אדם שצם. זולת זקן וחולה שיש לוודאות שמתענים."],["s","(שע\"ה קב' ס'ק לב)"]]},{"h":"טו תמוז יום שלישי","s":"הלכות התענית","d":["לעילוי נשמת אליהו בן סעדיה שרים | לעילוי נשמת יחזקאל בן מלכה ויוסף בלס | לעילוי נשמת יהודה בן סאלם יעיש | לעילוי נשמת יחזקאל בן מלכה ויוסף חיים | ברכה והצלחה למלאכי בן גלעד","כמוהר\"ר שלום מנצורה זצוק\"ל - תר\"ח"],"b":[["t","מתי מתחיל הצום?"],["b","ארבעת הצומות [חוץ מתשעה באב ויום כיפור], מתחילים מעלות השחר."],["b","ומותר לאכול בלילה שלפניהם עד עלות השחר. אומנם אם עלה לשון שנת קבע נחשב כאילו התחיל את הצום, ואסור לאכול. (ועיין בהלכה הבאה)."],["b","האם מותר לקום בעוד לילה לאכול או לשתות קודם הצום?"],["b","אם לפני שעלה לישון עשה תנאי שהוא לא מתחיל את הצום עד עלות השחר, מותר לו לקום לאכול לפני עלות השחר. ואם לא עשה תנאי וישן שנת קבע, אסור לו לאכול אפילו לפני עלות השחר. ולשתות אפשר להקל אפילו אם לא עשה תנאי. (שע\"ה סימן קב' סעיף ו')"]]},{"h":"טז תמוז יום רביעי","s":"הלכות התענית","d":["לעילוי נשמת דוד שאקי בן שלמה ושושנה"],"b":[["t","האם מותר לאכול בתוך חצי שעה שלפני עלות השחר?"],["b","יש מהאחרונים שכתבו שלא יאכל חצי שעה לפני עלות השחר יותר מכביצה לחם או מזונות, (כמו שהדין בתפילה) אבל שתיה ופירות מותר כמה שירצה. {ועיין בשע\"ה שכתב שלא נתברר אם דבריהם מוסכמים לדידן. (שע\"ה ק\"ב ס\"ק י\"ז) ועיין בפסקי תשובות (סימן פ\"ט אות כ\"א) שהביא להקל יותר בליל התענית והמחמיר יחמיר לעצמו}."],["t","ממתי מתחילים דיני אבלות?"],["b","מנהגי אבלות שנוהגים בבין המצרים, יש אומרים, כי הם מתחילים מצאת הכוכבים של ליל י\"ז בתמוז, ויש אומרים שמתחילים רק מהבוקר של יז' בתמוז, וכן עיקר כדעה אחרונה. (מועדי ה' ב', ב')"]]},{"h":"יז תמוז יום חמישי. צום.","s":"הלכות התענית","d":["לע״נ סבתי גזל דמתי בת יהודה זצ״ל"],"b":[["t","ממה נמנעים מיז' בתמוז?"],["b","כיון שבשבעה עשר בתמוז התחילו צרות החורבן, לכן נוהגים כמה עניני אבילות מיז' בתמוז עד ט' באב. אין נושאים נשים, ואפילו מי שעדיין לא קיים פריה ורביה. ואפילו סעודת שידוכין אין עושין בימים אלו, ולא סעודת חנוכת הבית. ורק סעודות של מצוה שהגיע זמנן, כגון מילה ופדיון הבן. ובסעודות אלה שרים כרגיל ואפילו בשבוע שחל בו ט' באב. (שע\"ה קג א)"],["b","אמירת תיקון חצות בבין המצרים."],["b","ראוי לכל אדם בימי בין המצרים לומר תיקון חצות בחצות היום ועוד יותר אחר חצות הלילה . [חוץ מראש חודש וערבי שבתות] וימעט בשחוק ותענוג בימים אלו שכל דור שלא נבנה בית המקדש בימיו כאילו נחרב בימיו, ושיתבונן בזה יקרע סגור לבבו. ( שע\"ה קג' טו')"]]},{"h":"יח תמוז יום שישי","s":"הלכות בין המצרים","d":["כמוהר\"ר יחיא סינוואני זצוק\"ל - תש\"ד"],"b":[["t","האם לובשים בגדי שבת בשבתות של בין המצרים?"],["b","בשבתות של בין המצרים לובשים בגדי שבת כרגיל, וכן בשבת הסמוכה לתשעה באב, [ואפילו תשעה באב שחל בשבת ונדחה ליום ראשון] וכן טלית של שבת, וכן אם יש פרוכת לארון קודש מיוחדת לשבת מניחים אותה בשבת כרגיל. (שע\"ה קג ו)"],["t","האם מותר לאכול בשר ולשתות יין בתשעת הימים?"],["b","בשאר קהילות ישראל נוהגין שלא לאכול בשר ולא לשתות יין מר\"ח אב עד תשעה באב. ואפילו תבשיל שנתבשל בו בשר, או שיש בו שומן ואפילו בשר עוף. אבל בקהילות תימן לא נתקבל מנהג זה, ואפילו בשבוע שחל בו תשעה באב, אין נמנעים מאכילת בשר בהמה ומשתיית יין. ורק בסעודה המפסקת אסור. (שע\"ה סי' ק\"ג ה\"ח עריכת השולחן תקנ\"א.)"]]},{"h":"יט תמוז יום שבת. לשאמי, פרשת פנחס. לבלדי, פרשת מטות.","s":"הלכות התענית","d":["לעילוי נשמת אריה כהן בן שלום ושושנה | לעילוי נשמת אריה כהן בן שלום | ברכה והצלחה לשלום בן עזריאל"],"b":[["t","מתי חולצים תפילין במנחה של תענית?"],["b","בכל הצומות מנהגינו להניח תפילין גם במנחה וחולצין את התפילין בקרית שמע של ערבית כשמגיעין ל\"כימי השמים על הארץ\", ויש שחולצין אותם אחר מנחה."],["s","(שע\"ה סימן קב' סעיף י')"],["t","כיצד מנהגינו בקריאת התורה?"],["b","קוראים קריאת 'ויחל משה' בשחרית ומנחה. ומה שנוהגים האשכנזים שהציבור קורא מתיבות \"שוב מחרון אפך\" וכו', וכן יג' מידות של רחמים, ואחר כך חוזר החזן, אין מנהגינו כן. וכן אין מנהגינו להפטיר בתענית, זולת בט' באב. (שע\"ה ק\"ב י')"]]},{"h":"כ' תמוז יום ראשון","s":"הלכות בין המצרים","d":["לעילוי נשמת שאול בן יוסף גו'בני | לעילוי נשמת גיא אברהם בן מיכאל האם בימים אלו צריך זהירות יתר?"],"b":[["b","יש הנמנעים מללכת במקום סכנה בימים אלו מיז' בתמוז עד ט' באב, וכן לגבי נסיעה במטוס ראוי לימנע אם אפשר."],["b","וללכת לים או לבריכה מותר מעיקר הדין, אלא שנשמעו כמה אסונות בימים אלו רח\"ל, וראוי לימנע. ולא יכו את התלמידים או הבנים בימים אלו. (קג ב' יב' מועדי ה')"],["t","האם מותר לאבל שחל שלושים שלו בבין המצרים להסתפר?"],["b","אבל שחל יום שלושים שלו בי\"ח בתמוז או אח\"כ עד ערב שבת הסמוכה לתשעה באב, מותר לו להסתפר אפילו למחמירים בתספורת מיז' בתמוז. אבל בשבוע שחל בו תשעה באב, אסור בכיבוס ובתספורת. ויש אוסרים מראש חודש אב (קג' סעיף יג')"]]},{"h":"כא תמוז יום שני","s":"הלכות בין המצרים","d":["מורי יצחק בר' יצחק גברא - הצדיק מעגור | ברכה והצלחה בנימין בן דניאל"],"b":[["t","מה הם ההפטרות בשבתות אלו של בין המצרים?"],["b","בשלוש השבתות שבין י\"ז בתמוז לט' באב מפטירים \"תלת דפורענותא\", לפי מנהג הבלדי הן – 'דברי ירמיהו'. 'חזון ישעיה'. 'איכה היתה'. וסימנם דח\"א. ולפי מנהג השאמי מפטירין – 'דברי ירמיהו'. 'שמעו דבר ה\". 'חזון ישעיה'. וסימנם - דש\"ח. ואפילו כשחל ר\"ח אב להיות באחד בשבת לא מפטירין מחר חודש אלא מפטירין \"חזון ישעיהו\" בבלדי, ו\"שמעו דבר ה'\" - בשאמי. ( שע\"ה קג')"],["t","מי ראוי שיקרא הפטריות אלו וכיצד יקרא?"],["b","אין משנים הנעימה של ההפטרות האלו, ויש שמנמיכים את קולם מעט. וכן אין מנהגנו לומר קינות בשום שבת. ויש נוהגים להעלות להפטרות אלו את זקני וחשובי ביהכנ\"ס, ונכון הדבר מפני שהן תוכחה. ( שע\"ה קג')"]]},{"h":"כב תמוז יום שלישי","s":"הלכות בין המצרים","d":["לעילוי נשמת הינדה בת יעקב נדלר ז\"ל"],"b":[["t","האם מותר לקנות כלים בגדים רהיטים וכו'?"],["b","נוהגים שלא לקנות בגדים חדשים [וכן לא ללבוש אפי' שקנה מקודם], והוא הדין שלא לקנות כלים חדשים, משום שמחה, וגם משום שצריך לברך שהחיינו. ואפילו בשבת אין לובשין חדש. אבל לגבי כלי אם קנה לפני יז' תמוז מותר לו להשתמש בבין המצרים. (שע\"ה ק\"ג ב'. מועדי ה' כ\"ג)"],["t","מה מותר לקנות בבין המצרים?"],["b","רהיטים הנחוצים לאדם, ולא לנוי או להרווחה, מותר לו לקנות. ואפילו דירת מגורים, אם זה לצורך ולא רק להרווחה, מותר. וכן לקנות רכב אם להרווחה אסור. ואם יש צורך, או נחשב דבר האבד שאם לא יקנהו עכשיו יקנו אותו אחרים, מותר. וכל דבר שהוא דבר האבד, כגון בגד שיתייקר אח\"כ, או שלא ימצא אותו אחר בין המצרים, מותר לקנות. ויש להעדיף לשלם דמי קדימה כדי שהמוכר ישמור לו את החפץ אם אפשר בכך. (מועדי ה' כג')"]]},{"h":"כג תמוז יום רביעי","s":"הלכות בין המצרים","d":["לעילוי נשמת רחלי בת אהובה אלגמס | לעילוי נשמת עזרא בן אהרון | ברכה והצלחה לאליה בן שלום | בריאות הצלחה בזוגיות ופרנסה רוברט (בן ציון) בן לורן"],"b":[["t","האם מותר להסתפר בבין המצרים?"],["b","נוהגים רבים שלא להסתפר בימים אלו דהיינו מיז' בתמוז, לא שערות הראש ולא שערות הזקן ולא כל שיער שבגופו. חוץ מהשפה העליונה שבזקן, שכל שמעכב האכילה מותר. ואסור לגדולים לספר את הקטנים. ומי שלא הספיק להסתפר ושערו מגודל באופן שצריך להסתפר לכבוד שבת מותר לו להסתפר עד שבוע שחל בו ט' באב, אבל צריך להשתדל ולא להגיע לכך ויש נוהגים כפי עיקר הדין, לימנע מלהסתפר רק בשבוע שחל בו ט' באב. (שע\"ה ק\"ג ה')"],["t","כיצד ינהג בחור תימני הלומד בישיבה אשכנזית?"],["b","בחורים תימנים הלומדים עם בחורים מבני אשכנז [למקילים עד שבוע שחל בו] מותרים להסתפר עד זמן מנהגם, ואין חשש משום לא תתגודדו. ואף מותר לאשכנזי לספר אותם. (מועדי ה' לב')"]]},{"h":"כד תמוז יום חמישי","s":"הלכות בין המצרים","d":[],"b":[["t","האם מותר לקנות ספרים ותפילין?"],["b","מותר לקנות ספרים חדשים, אפילו משנכנס אב, דאין בזה שמחה, וגם הוא צורך מצוה, ולא מברכים עליהם שהחיינו. וכן טלית ותפילין אם נצרך לקנות, מותר לו לקנות בבין המצרים, ואין צורך לשאול מאחרים עד אחר בין המצרים, אלא יכול לקנות מיד. (מועדי ה' כו')"],["t","האם מותר לקנות כלים ובגדים בבין המצרים?"],["b","גם כלים ובגדים שאין מברכים עליהם שהחיינו, אסורים בקניה מטעם השמחה גופא, וכן המנהג. ובגדים שאין בהם שמחה כגון בגדים פנימיים (לבנים גופיות), מותר לקנות ולהשתמש בהם. (מועדי ה' כ')"]]},{"h":"כה תמוז יום שישי","s":"הלכות בין המצרים","d":[],"b":[["t","האם מותר לברך שהחיינו על פרי חדש?"],["b","על פרי חדש יש להקל לברך שהחיינו, ויותר טוב לחכות ליום השבת. ואם לא ימצא פרי זה אחר ט' באב, מותר לכתחילה לברך שהחיינו. וכן אשה מעוברת שרואה פרי חדש ומתאווה לו, מברכת שהחיינו, ואין לה לבטל שהחיינו. (עריכת השולחן תקנ\"א מח')"],["t","הפוגש את חבירו בבין המצרים האם מברך שהחיינו?"],["b","הרואה את חבירו שחביב עליו מאוד ועברו יותר מ30- יום, מברך שהחיינו אף בימי בין המצרים כיון שאי אפשר לדחות הברכה. וכן על מילה ופדיון הבן מברכים שהחיינו כדי שלא להחמיץ המצוה. ברכת הטוב והמטיב מותר לכל השיטות, לברך בבין המצרים. (שע\"ה קג ב' )"]]},{"h":"כו תמוז יום שבת. לשאמי, פרשת מטות מסעי. לבלדי,","s":"","d":["פרשת מסעי. — הלכות בין המצרים לעילוי נשמת אברהם בן יצחק ויוכבד בדרה"],"b":[["t","האם מותר לשמוע שירים בבין המצרים?"],["b","אין שומעים שירים מי'ז בתמוז עד אחר תשעה באב' ,ורבים נמנעים אפילו מסתם שירה בפה, חוץ משבתות וסעודות מצוה בזמנם, שמותר לשיר בפה. וכן מותר לשיר בפה דרך הודאה, בתפילה ובלימוד. וכן מותר לשיר בפה שירים הנוגעים לחורבן. (שע\"ה קג א)"],["t","האם מותר ללמד נגינה בבן המצרים?"],["b","אדם שמלמד נגינה יש להקל לו ללמד אפילו אחר ראש חודש אב ובפרט דאין לו הנאה מכך ויעשה שאלת חכם. (מועדי ה' כז')"]]},{"h":"כז תמוז יום ראשון","s":"הלכות בין המצרים","d":["ברכה והצלחה לשמעון בן הראל","כמוהר\"ר שלום יצחק הלוי - ראב\"ד ת\"א וראש רבני תימן בא\"י"],"b":[["t","באיזה מקרים מותר לשמוע שירים?"],["b","כל מקום שלא מתכוין לשמחה מותר לשמוע שירים. ולכן \"נהג\" שמרגיש חוסר ריכוז מעייפות, ויש חשש סכנה, מותר לו לשמוע שירים המלווים בכלי נגינה בזמן הנסיעה. וכן אדם ששרוי בדיכאון מותר לו לשמוע שירים, וכן אם רוצה להפיג פחד ובדידות, יש להקל לשמוע שירים. ואם יכול למעט בשמחה דהיינו לשמוע שירים רק עם תופים או עם כלי אחד בלבד עדיף כמה שיותר למעט בשמחה. (מועדי ה', כ')"],["t","האם ממעטים בשמחה בעבודת ה'?"],["b","מיעוט שמחה בימים אלו, דוקא בדברים של רשות, אבל בעבודת ד' יתברך, ובתורה ובתפילה, אדרבא יש לעשותם בשמחה רבה כי הזמן מסוגל להתקרב אל המלך, ובפרט, בשבתות של בין המצרים. ויש להרבות בימים אלו באהבה ואחוה בין אדם לחבירו כנגד שנאת חינם, שבעטיה, חרב בית מקדשנו שיבנה במהרה בימינו. (מועדי ה' ב' ו')"]]},{"h":"כח תמוז יום שני","s":"הלכות בין המצרים","d":[],"b":[["t","האם עושים סעודת מצוה בימים אלו?"],["b","אין לערוך סעודות הודיה בימים אלו. סעודת חנוכת הבית יש להמתין עד אחר תשעה באב משום סימנא טבא. הכנסת ספר תורה אין לעשות בימי בין המצרים ואפילו בערב שבת. (מ\"ה, ב')"],["t","האם מותר לקצוץ צפורניים?"],["b","מותר לקצוץ צפורניים אפילו בשבוע שחל בו ט' באב, ויש מחמירים. ואפילו למחמירים, לצורך מצווה כגון מוהל לתקן צפרניו לצורך הפריעה, מותר. (שע\"ה סי' ק\"ג ס\"ד)"]]},{"h":"כט תמוז יום שלישי ערב ראש חודש","s":"הלכות בין המצרים","d":[],"b":[["t","דיני שבוע שחל בו תשעה באב"],["b","שבוע שחל בו תשעה באב אסור לכבס, וכן אסור לגהץ. וגם בגד שאינו רוצה ללובשו עכשיו אסור לכבסו ולגהצו ולהניחו לאחר ט' אב .ואסור לכבס גם במכונת כביסה. וכן אסור ללבוש, או להציע המטות, במכובסים מקודם. ובכלל זה הבגדים הפנימיים כגון גופיות גרביים ומגבות. (שע\"ה קג' ט')"],["t","כיצד יכין את הבגדים לשבוע שחל בו ט' באב?"],["b","צריך כל אדם שיכין לו לפני כן את כל הבגדים שיצטרכו לו לשבוע שחל בו תשעה באב, וללבוש במשך כשעה אחת, שלא ייחשבו כמכובסים. ואם שכח להכין בגדים בשבוע שלפני, ילכלכם בתריסי החלונות או מקומות אחרים שיש בהם אבק, שע\"י זה סר חידושו (קג' ט')"]]},{"h":"א' אב יום רביעי ראש חודש","s":"הלכות בין המצרים","d":["לעילוי נשמת יחיאל בן אברהם | לעילוי נשמת נור בת חסן מעטוף ז\"ל | ברכה והצלחה אליה בן לירן"],"b":[["t","מה מותר לכבס בשבוע שחל בו תשעה באב?"],["b","חיתולים שמלפפים בהם התינוקות תדיר, מותר לכבסן ואפילו בגדי שאר ילדים קטנים נוהגים להקל, ולא יכבסו הרבה יחד, ויכבסו בצנעה (בהסתר)."],["s","(ק\"ג ט' עריכת שולחן תקנ\"א)"],["t","האם מותר לכבס ללא מים?"],["b","מותר לנקות כתם בבגד ללא מים כגון לשפשפו ואם רוצה לשפשף עם מים יש מחמירים ויש מקילים. ניקוי יבש [אע\"פ שזה בלי מים] נחשב כיבוס ואסור. ובגד שיתלכלך וחושש שאם ישאיר את הכתם לא ירד לעולם מותר לשרותו במים בלבד. (מועדי ה' מא')"]]},{"h":"ב' אב יום חמישי","s":"הלכות בין המצרים","d":["ברכה והצלחה לאביאל בן ארז | ברכה והצלחה לדליה בת אליהו","כמוהר\"ר יוסף צוברי זצוק\"ל - הרב ליהודי תימן ת\"א יפו והסביבה"],"b":[["t","האם מותר לרחוץ את הגוף בשבוע שחל תשעה באב?"],["b","אין ראוי לרחוץ את הגוף במים חמים בשבוע שחל בו תשעה באב, אבל במים קרים או פושרים הנוטים לקר מותר, ומותר אפילו עם סבון לשם נקיון ולא לשם תענוג. ולרחוץ לרפואה, כגון יולדת, או אדם חלוש שצווה אותו הרופא לרחוץ, מותרים לרחוץ בחמים, וכן נדה רוחצת כדרכה. (ע\"ש תקנ\"א קג' יא')"],["t","האם מותר להשתמש במשחות ודאודורנט?"],["b","מותר להשתמש במשחות גוף וחומרים המונעים ריח וזיעה וכדומה אבל לשים בושם שריחו נודף לא. (מועדי ה' נ')"]]},{"h":"ג' אב יום שישי","s":"הלכות בין המצרים","d":[],"b":[["t","מה מותר לאכול בסעודה המפסקת?"],["b","סמוך לערב אוכלים סעודה מפסקת, ואסור לאכול אז בשר או לשתות יין, ונהגו לאסור אפילו בשר עוף והוא הדין דגים. ואסור לאכול שני תבשילין, וכן מיץ ענבים נכלל ביין. ואוכלים כשהם יושבין על הארץ כאבלים, ואין צריך לחלוץ את המנעלים. ולא ישבו שלשה ביחד שלא יתחייבו בזימון. ואפילו ישבו יחד לא יזמנו. ובגמר הסעודה יש מחמירים לטבל קצת פת באפר ולאכול. וצריך ליזהר להפסיק מבעוד יום. (קד' ג')"],["t","מתי זמן סעודה המפסקת?"],["b","אין מנהג אצלנו לאכול סעודה קבועה עם הרבה תבשילין, ואח\"כ להתפלל מנחה, ולאחר מכן לאכול סעודה המפסקת, שנמצא אין זו רק סעודת עראי. אלא את סעודת הצהריים הקבועה אוכלים מוקדם יותר משאר ימים, ואחר כמה שעות מתפללים מנחה וחוזרים לאכול סעודה מפסקת. (קד' ד', עריכ\"ש תקנ'ב)"]]},{"h":"ד' אב יום שבת פרשת דברים","s":"הלכות בין המצרים","d":["לע״נ גיסי טוביה בן דוד בן שולמית ודוד ז״ל"],"b":[["t","האם מותר לאכול ב' תבשילים, ומה נחשב לתבשיל?"],["b","אסור לאכול שני תבשילין בסעודה מפסקת, ודברים אפויים לא נחשבים תבשיל ולכן מותר לאכול כמה מיני מאפים. ג'חנון וכובאנה שנעשו בכלי סגור נחשבים תבשיל, ואמנם יש מקילים בכובאנה, דסוף סוף הוא מאפה, ויש להם על מה שיסמוכו. וראוי למעט בתענוג. (מועדי ה' נ\"ד)"],["t","האם מותר לאכול סלטים?"],["b","מעיקר הדין מותר לאכול סלטים, אלא שיש מחמירים שלא לאכול סלטים ודומיהם, שהם דרך תענוג, וגוררים תאוות המאכל. וכן מותר מעיקר הדין לשתות משקאות ממותקים, וגם בזה ראוי למעט משום תענוג. אבל לשתות משקים המשכרים ובכללם בירה, אסור, אלא אם כן אדם חלש. (מועדי ה' נד')"]]},{"h":"ה' אב יום ראשון","s":"הלכות בין המצרים","d":["ברכה והצלחה לנעמי בת גלעד | רביד בן תמיר עדן בת ארנון לרפואה הצלחה פרנסה טובה ושלום בית | הלל שמואל בן טל ירא\"ש ובריאות"],"b":[["t","מה נחשב שני תבשילין?"],["b","שני מיני תבשילים, כגון מרק, תפו\"א, גזר, ושאר ירקות. נחשב כתבשיל אחד, כי כך דרכו לאכול בכל ימות השנה. כגון פלפל ממולא באורז נחשב תבשיל אחד. והכלל הוא כשיש 2 תנאים: א': בשלם יחד. ב': כך הדרך לאוכלו כל השנה נחשב תבשיל אחד. ויש מחמירים בכל הנ\"ל. (מועדי ה' נ\"ח)"],["t","האם ירקות כבושים, דגים, וגבינה נחשבים לתבשיל?"],["b","ירקות כבושים נחלקו הפוסקים אם דינם כתבשיל וראוי להחמיר. סרדינים וממרח טונה מותר לאכול ונחשבים תבשיל אחד, ומה שנהגו לאסור לאכול דגים בסעודה המפסקת ,דווקא דגים חשובים אבל טונה וסרדינים מותר וכן דג מלוח לא נחשב תבשיל, וכן גבינה אין עליה תורת תבשיל, ומותר לשתות תה וקפה לפי רגילותו ולא לתענוג. (מועדי ה' נח')"]]},{"h":"ו' אב יום שני","s":"הלכות תשעה באב","d":["לעילוי נשמת מאור בן ישורון הלל ז\"ל","כמוהר\"ר ניסים רצאבי זצוק\"ל אב\"ד ראצבה"],"b":[["t","האם מברכים את כל ברכות השחר בתשעה באב?"],["b","בברכות השחר בתשעה באב למנהג הבלדי צריך לדלג ברכת 'שעשה לי כל צרכי' לפי שאסורים בנעילת הסנדל, ואפילו מי שצריך לנעול לא מברך. וכן מדלג ברכת 'המעביר' עד סופה שהוא גומל חסדים טובים, לפי שאין רוחצין את העיניים במים להדיא."],["b","ובשאמי נוהגים לברך הכל. ולפי כולם מברכים 'על נטילת ידים' (וכ\"כ את מנהג השאמי באמת ויציב סי ג')."],["s","(שע\"ה קה' ו')"],["t","האם מותר לומר לחבירו שלום בט' באב?"],["b","אסור לומר לחבירו שלום בט' באב ולא ערב טוב ולא בוקר טוב וכו'. וכתבו קדמונינו שאומר לחבירו תזכה לראות בנחמת ירושלים. וכן דרך ארץ שלא יפרדו אחד מחבירו בלי אומר ודברים, או כשפוגשו אינו דרך ארץ שלא יאמרו מאומה, שנראה כשונאים זה את זה. ולאחל מזל טוב או לומר לחבירו חיים ארוכים, מותר. שזה ברכה לחבירו, ולא שלום. (קה' יז' מועדי ה')"]]},{"h":"ז' אב יום שלישי","s":"הלכות תשעה באב","d":["לעילוי נשמת תושיה בת שלום הלל ז\"ל | ברכה והצלחה לאורטל בת אברהם"],"b":[["t","האם מותר לעשות מלאכה ב-ט' באב?"],["b","מנהגינו כהאוסרים לעשות מלאכה שיש בה שהוי (התעסקות), ואפילו מלאכת הדיוט. אבל דבר שאין בו שום שהוי, כגון הדלקה או קשירה, אע\"פ שבשבת אסור, ב-ט' באב מותר."],["b","ואחר חצות מותרים בכל מלאכה, וירא שמיים יחמיר לעצמו. ויש אומרים שההיתר מחצות, זה רק למוכרי צורכי סעודה. (שע\"ה ק\"ה י\"ט)"],["t","האם מותר לעשות מלאכת דבר האבד?"],["b","דבר האבד מותר וכן מותר לכתוב ב-ט' באב מה שמותר לכתוב בחול המועד וכל העושה מלאכה ב-ט' באב אינו רואה סימן ברכה לעולם. (שם)"]]},{"h":"ח' אב יום רביעי ערב תשעה באב","s":"הלכות תשעה באב","d":["לעילוי נשמת שמעון בן יוסף"],"b":[["t","האם מותר לקרוא שניים מקרא ואחד תרגום בט' באב?"],["b","אדם שרגיל לישנות הפרשה כל יום חמישי, ותשעה באב יוצא ביום חמישי (כמו השנה תשפ\"ז), מותר לו לישנות הפרשה כהרגלו. (שתילי זיתים תקנ'ד ד' עריכת שולחן יא')"],["t","האם מותר לירחוץ את ידיו?"],["b","אסור לרחוץ את ידיו בט' באב, ואפילו להושיט את אצבעו במים אסור, אבל הנשים המבשלות, רוחצות את הבשר וכדו', וכן מי שיש לו לכלוך מותר לירחוץ אותו מקום כפי הצורך. (שולחן ערוך תקנד' ס\"ט)"]]},{"h":"ט' אב יום חמישי צום","s":"הלכות תשעה באב","d":["לעילוי נשמת יוסף בן שלמה שאקי"],"b":[["b","צער ובכי בתשעה באב."],["b","כותב מהרי\"ץ מלאכי מרום והקב\"ה עמהם אשר עוז וחדוה במקומו נוהגים בכי ואבל ואנינה ומספד לקרחה ולחגור שק מה יעשה האדם השפל והאפל שראוי להתאבל ולבכות ושק ואפר יציע על אורך גלותינו וצערינו וכו' וכל זה בסיבת עוונינו אשר רבו למעלה ראש אנא נוליך חרפתנו. (עץ חיים תשעה באב)"],["b","בית המקדש וירושלים."],["b","כותב היעב\"ץ כאן המקום להרחיב הדיבור שאלמלא לא היה אלא עוון זה בידנו שאין מתאבלים על ירושלים כראוי די להאריך גלותינו והיא בעיניי הסיבה הקרובה והיותר גלויה ועצומה וחזקה לכל הצרות שפוקדות את עם ישראל לפי שיצא האבל הזה עלינו ובהיותינו שוקטים בארץ שכחנו את ירושלים ולא עלתה על לבבנו ביחוד ביום תשעה באב מי המתאבל ונאנח על חורבן הבית כראוי ממעמקי ליבו וכו'."],["s","(יעב\"ץ שער הדלק מ\"ת)"]]},{"h":"י' אב יום שישי","s":"הלכות לבין הזמנים","d":["לעילוי נשמת אברהם בן יוסף ואמנה | לעילוי נשמת משה בן שלום | להצלחה בחינוך הילדים לדקל בן ציון"],"b":[["t","האומר תפילת הדרך האם חותם בשם?"],["b","לדעת מרן ושאר פוסקים היוצא לדרך צריך להתפלל תפילת הדרך ולחתום בשם אולם לפי מנהג תימן לעולם אין לחתום התפילה עם שם ה' אלא יסיים \"ברוך שומע תפילה\" ולכן אין צריך להסמיכה אחרי איזו ברכה ויכול לאומרה אפי' סמוך לסוף נסיעתו אם שכח לאומרה תחילה וכן יכול לאומרה אפי' כמה פעמים ביום דאינה אלא בקשה בעלמא ולא ברכה."],["s","(עול\"י ח\"ב סימן פ' ושע\"ה שמ'ו וע\"ע עריכ\"ש ש'. וכן דעת הגר\"י צוברי, הובא בס' פסקי הלכות עמ' ר\"א)"],["t","הנוסע מעל 72 דקות האם מברך הגומל?"],["b","אין לברך הגומל, אפילו נסע כמה שעות. מאחר והדרכים מלאות במכוניות נוסעות, וזוהי צורת החיים בזמנינו, בכל יום ויום ובכל שעה ושעה, אף שיש סכנה בדבר. וחז\"ל והפוסקים לא דיברו, אלא במאורעות מיוחדים לפי מצב זמנם, אבל לא על דברים הרגילים וההוויים. וכן לא ראינו ולא שמענו בזמנינו מי שיברך הגומל, זולת מקצת מן הספרדים הנמשכים אחרי הוראת הגרע\"י זצ\"ל. (אולם כיום רבים המה מן הספרדים שמברכים וכ\"פ ברכת ה' ח\"ד (פ\"ו אות כד') והל\"ב ח' יא' (עמ' רג') (עול\"י ח\"ב ס'י פ' ושע\"ה שמ'א אות א'. וכן דעת הגר\"י צוברי, הובא בס' פסקי הלכות עמ' ר')."]]},{"h":"יא אב יום שבת פרשת ואתחנן","s":"הלכות לבין הזמנים","d":[],"b":[["t","הנוסע בדרכים שיש בהם סכנה האם מברך הגומל?"],["b","הנוסע בדרך מסוכנת, כגון ביישובי הערבים, כמו שמצוי בזמנינו. לכאורה היה צריך לברך אם נסע 72 דקות, אבל לא שמענו מי שמברך. ונראה משום דסוף סוף גם זה מצוי. אולם נראה שהכל לפי העניין והזמן, שיש פעמים שצריך לברך. (עול\"י שם)"],["t","הרואה את הר חרמון האם צריך לברך?"],["b","על ההרים הגבוהים המפורסמים מחמת גבהם שניכרת גבורת הבורא בהם כגון הר חרמון בצפון ארץ ישראל והרי האלפים בארצות אירופה מברך בא\"ה אמ\"ה עושה (מעשה) בראשית. (שע\"ה של'ו)"]]},{"h":"יב אב יום ראשון","s":"הלכות לבין הזמנים","d":["לעילוי נשמת מארי שמואל בן הרב יחיא | לעילוי נשמת שלום בן מארי שמעון בן דוד | ברכה והצלחה ליהודה בן ארז"],"b":[["t","ההולך לבית קברות או להתפלל בקברות צדיקים מה צריך לברך?"],["b","הרואה קברי ישראל מברך בא\"ה אמ\"ה אשר יצר אתכם בדין וכו'. (שע\"ה של'ח)."],["b","אך אין לברך על קבר שרואים את הציון והוא קבור למטה למטה כקבר הרשב\"י וכדו' דחשיב כמברך על תמונה היות והמת לא נמצא שם. (מפי הרב בע\"פ)."],["b","הרואה את הים מה מברך?"],["b","הרואה את ים התיכון, מברך בא\"י אמ\"ה שעשה את הים הגדול. (ע\"פ השיעור במוצ\"ש ודלא כמש\"כ בשע\"ה)"],["b","הרואה את ים כנרת, מברך בא\"י אמ\"ה עושה (מעשה)"],["b","בראשית. (מפי הרב)"]]},{"h":"יג אב יום שני","s":"הלכות לבין הזמנים","d":["לעילוי נשמת שרה בת עמרן"],"b":[["t","המבקר את חבירו ולא ראהו 30 יום האם מברך?"],["b","הרואה את חבירו לאחר 30 יום והוא חביב עליו מאוד ומכ\"ש אדם שהוא גדול ממנו כגון אביו או רבו ושמח בראייתו מברך שהחיינו אע\"פ שבתוך הזמן קיבל ממנו מכתב (או דיבר עמו בטלפון) ואין חילוק בין זכרים לנקבות ולכן האיש שרואה את אשתו או אמו או אחותו או בתו או להיפך מברכין כן. (שע\"ה של'ב)"],["t","המבקר את חבירו שלא ראהו י\"ב חודש האם מברך?"],["b","הרואה את חבירו לאחר י\"ב חודש והוא שחביב עליו מאוד ושמח בראייתו מברך בא\"י אמ\"ה מחיה מתים (מפני שנשכח מהלב כמו שהמת נשכח לאחר י\"ב חודש) ואינו מברך שהחיינו אבל אם קיבל ממנו מכתב בתוך זמן זה או ששמע משלומו אינו מברך אלא שהחיינו ואין חילוק בין זכרים לנקבות (וכנ\"ל בתשובה הקודמת)."]]},{"h":"יד אב יום שלישי","s":"הלכות נטילת ידים לסעודה","d":[],"b":[["t","מאור יצחק בן אלי זיווג הגון במהרה"],["b","הרה\"ג מאיר מזרחי זצוק\"ל - תשי\"ז, אב\"ד ברחובות חיוב נטילת ידים לסעודה הרוצה לאכול פת שמברכין עליה המוציא, צריך ליטול ידיו מקודם, אפילו כשאינו יודע להם שום לכלוך. אם הפת גדולה כביצה, מברך על הנטילה. ובפחות מזה, אינו מברך על הנטילה. (שע\"ה ח\"א סי' כ\"ז ס\"א. עריכ\"ש ח'ב קכ'א)"],["t","האם מותר ליטול בכלי שבור או סדוק?"],["b","נטילת ידים צריכה להיות דווקא מן הכלי. וצריך שיהא מחזיק רביעית (86 ג'). וצריך שיהיה הכלי שלם, בלא שום נקב, או סדק מפולש. [כלומר הכלי סדוק מצד לצד, שעל ידי כך ייזל מים מהכלי]. (שו\"ע סי' קנ\"ט ס\"א. שע\"ה שם ס\"ב)"]]},{"h":"טו אב יום רביעי","s":"הלכות נטילת ידים לסעודה","d":[],"b":[["b","יחיאל בן שלמה הקב\"ה ימלא משאלות ליבו לטובה ולברכה בבריאות שמחה נחת ורווחה | ברכה והצלחה ובריאות איתנה ליאיר בן יוסף | לזש\"ק אליאור בן יוסף"],["b","מה הדין כשאין לו כלי אלא סדוק?"],["b","בדיעבד שאין לו כלי שלם, אלא סדוק או נקוב, אם היה רק נקב קטן, שהמשקין יוצאין בו, אבל לא נכנסין מבחוץ לתוכו, יטול בו ידיו, כפי דעת השו\"ע שעדיין נקרא כלי. אבל אם ניקב בכונס משקה דהיינו שאם ישימו אותו על משקים, יכנסו בתוכו דרך הנקב, (והוא גדול מנקב שהמשקים שבתוך הכלי יוצאים בו) אז בטל מתורת כלי ואין נוטלים ממנו לידים. (שו\"ע סי' קנ\"ט ס\"א. מ\"ב סק\"ח. כה\"ח סק\"ט וסקי\"ד)"],["t","האם יש עניין ליטול ידיים יותר מרביעית מים?"],["b","אף על פי ששיעור המים לנטילה רביעית, יוסיף ליטול על כל יד מים בשפע, כמו שאמר ר' חסדא (שבת ס'ב)"],["b","אני נטלתי מלא חופנאי מיא, ונתנו לי מן השמיים מלא חופנאי טיבותא. ומי שנזהר בזה, ואעפ\"כ אינו מתעשר, הוא מפני שמעשיו מעכבים. (שע\"ה ח\"א סי' כ\"ז ס\"ג)"]]},{"h":"טז אב יום חמישי","s":"הלכות נטילת ידים לסעודה","d":["ברכה והצלחה אופיר בן דניאל"],"b":[["t","אופן נטילת ידים"],["b","יקדים ליטול תחילה יד ימין, ואחר כך יד שמאל, אם נוטל ידיו אחת אחת."],["b","וכשהשמש מביא מים (כרגיל בסעודות גדולות), המנהג להגיש את שתי הידיים כאחת. ורבים נוהגים לחבר הידיים מן הצד, כשגב הידיים כלפי קרקע, וצד האגודלים כלפי מעלה, באופן שנעשים כעין כלי קיבול, והשמש מערה המים מכלי כשר לתוכן, ומשם מעבירים המים לשאר חלקי הידיים שלא הגיעו אליהם המים. (שע\"ה ח\"א סי' כ\"ז ס\"ג)"],["t","מהו הסדר הנכון של נטילת ידיים?"],["b","צריך שיבואו המים עד הקנה של זרוע. ויפריד קצת את האצבעות, כדי שיבואו המים בכל אורך האצבעות, ובראשן וברחבן סביב. אין צורך שיהיו כל כמות המים נשפכים בשפיכה אחת, ולכן אין מניעה ליטול ידיו מכלי שפיו צר כגון בקבוק, אף על פי שאין המים יורדים בבת אחת. (כה\"ח קס'ב ס'ק ב' ושע\"ה ח\"א סי' כ\"ז ס\"ד)"]]},{"h":"יז אב יום שישי","s":"הלכות נטילת ידים לסעודה","d":["לעילוי נשמת דוד בן שאול אברהם | לעילוי נשמת רחמים בן יחיא","כמוהר\"ר אברהם בדיחי זצוק\"ל - תרצ\"ט, רה\"י הכללית צנעא"],"b":[["t","ברכת על נטילת ידים"],["b","לאחר שנטל שתי ידיו, טוב לשפשפן ביחד, ואחר כך יגביהן נגד ראשו, כמו שאמר הכתוב \"שאו ידיכם קודש, וברכו את י\"י\". וקודם שמנגב את הידיים, יברך ברוך וכו' אשר קדשנו במצוותיו וציוונו, על נטילת ידיים. ואע\"פ שכל הברכות מברך עליהם קודם עשייתן, מכל מקום תיקנו לברך אחרי הנטילה, כיון שלפעמים אין ידיו נקיות קודם הנטילה. ועוד, שגם ניגוב הידיים הוא מן המצווה. (שע\"ה ח\"א סי' כ\"ז ס\"ה)"],["t","האם יכול לאכול בלא לנגב? ומה הדין אם ניגב קודם שבירך?"],["b","צריך לנגב ידיו היטב קודם שיבצע, שהאוכל בלא ניגוב ידיים, כאילו אוכל לחם טמא. ולא ינגבן במלבושיו, משום דקשה לשכחה. בדיעבד אם שכח לברך קודם הניגוב, וכבר ניגב הידיים. יכול עדיין לברך. אך אם כבר בירך המוציא, שוב לא יברך על הנטילה. (שע\"ה ח\"א סי' כ\"ז ס\"ה. עריכת שולחן ח\"ב ע'מ קכ'ג)"]]},{"h":"יח אב יום שבת פרשת עקב","s":"הלכות נטילת ידים לסעודה","d":[],"b":[["t","מה הדין אם נגע בידיו אדם שלא נטל ידיים?"],["b","אם לאחר ששפך המים על ידיו, ובעודם לחות מן המים, נגע בהם אדם אחר שלא נטל ידיו, המים שעל ידיו נטמאים, וצריך לנגב הידיים, וליטול פעם שנית. ואם אירע לו כן לאחר שכבר בירך, לא יברך שנית. (שו\"ע סי' קס\"ב ס\"ד. שע\"ה ח\"א סי' כ\"ז ס\"ז)"],["t","מי שאין לו כלי לנטילת ידיים האם יכול להטביל ידיו?"],["b","מי שאין לו כלי, יכול להטביל ידיו בנהר, או במקווה, או במעיין, אפילו אין בהם ארבעים סאה, העיקר שיתכסו ידיו בפעם אחת. ומברך גם כן בנוסח \"על נטילת-ידיים\". (שע\"ה ח\"א סי' כ\"ז ס\"ח. עריכ\"ש ח\"ב קכ'ד)"]]},{"h":"יט אב יום ראשון","s":"הלכות נטילת ידים לסעודה","d":[],"b":[["t","כל מיני מים, האם כשרים לנטילת ידיים?"],["b","מים שנפסלו משתיית הבהמה, אם הם בכלים, פסולים לנטילת ידיים. ואם הם בקרקע, כשרים לטבילת הידיים. לפיכך; מים מלוחים(כגון מי הים), או סרוחים, או מרים, אם אינם ראויים לשתיית כלב, פסולים לנטילת ידיים. ואם הם בקרקע (ציבור מי גשמים), כשרים לטבילת הידים. (טור. ב\"י. שו\"ע. סי' ק\"ס ס\"ט. כה\"ח סקמ\"ב. שע\"ה סי' כ\"ז סי\"ב)"],["t","מה הדין מים עכורים?"],["b","מה שאמרנו בהלכה הקודמת שהמים שבקרקע, אפילו שאינם ראויים לשתיית כלב, מועילים לטבילת הידים, זהו דווקא, כשהמים צלולים, אלא שהם מלוחים או סרוחים. אבל אם המים עכורים, כגון מטיט המעורב בהם, אם הבהמה אינה יכולה לשתות מהם, פסולים אף לטבילת הידים. ואם הכלב יכול לשתות מהם, כשרים בין לנטילה, בין לטבילת הידים.(טור. ב\"י. שו\"ע. סי' ק\"ס ס\"ט)"],["b","מים חמים, כשרים לנטילה, אפילו אם היד סולדת בהם: (שע\"ה סי' כ\"ז סי\"ב)"]]},{"h":"כ' אב יום שני","s":"הלכות נטילת ידים לסעודה","d":["לעילוי נשמת יצחק בן שרה | ברכה והצלחה ורפוא\"ש ללירון בת ראובן"],"b":[["t","מה הדין מים שאינם בצבע הטבעי שלהם?"],["b","מים שנשתנו מראיהם, כגון שנצבעו בגלל המקום ששהו בו, או שנפל לתוכן צבע או דיו וכדומה. פסולים לנטילת ידים. (טור שו\"ע ק\"ס ס\"א. שע\"ה סי' כ\"ז ס\"ט)"],["t","מה הדין מים שנפל לתוכן עפר וכדומה?"],["b","מים שנפל לתוכן עפר וצרורות מותר ליטול בהן אפילו קודם שהוצללו. שדווקא צבע שמעורב ואי אפשר להפריד, כגון דיו. מה שאין כן עפר וצרורות, שבמשך הזמן נצללים מאליהם, והצבע לא מחובר, מותר. והוא הדין מה שמצוי בזמנינו, שהמים יוצאים מן הברזים בגוון לבן, (מחמת לחץ המשאבות), מותר ליטול בהם. (פ\"מ במ\"ז סי' ק\"ס אות א'. שע\"ה ח\"א סי' כ\"ז ס\"ט. הערה כ\"ה)"]]},{"h":"כא אב יום שלישי","s":"הלכות נטילת ידים לסעודה","d":["ברכה והצלחה ליעל ידעי"],"b":[["t","האם מים שנעשו בהם מלאכה כשרים לנטילת ידיים?"],["b","מים שנעשה בהם מלאכה, כגון שהדיחו בהם כלים, או ששרו בהם ירקות, או שהניחו בהם בקבוק של תינוק על מנת לצננו, או שכשך ידיו בתוכן לנקותן, ואפילו רק את אצבעו הקטנה, פסולים הם לנטילת ידיים. ואם היו הכלים מודחים, או הירקות נקיים, לא חשיב נעשה בהם מלאכה, וכשרים. (שו\"ע סי' ק\"ס ס\"ב. מ\"א סק\"ה. שע\"ה סי' כ\"ז סעיפים י' י\"א)"],["t","אם נגע אדם במים"],["b","מי שלא נטל ידיו ונגע במים, שלא על מנת לנקותן (או צורך מלאכה אחרת). לא נטמאו המים. אבל אסור ליטול ידיו במים שנטל בהם חבירו. (שע\"ה סי' כ\"ז סי\"א)"]]},{"h":"כב אב יום רביעי","s":"הלכות נטילת ידים לסעודה","d":["לעילוי נשמת נתן בן שאול אברהם","כמוהר\"ר יחיא בשירי זצוק\"ל - תכ\"א"],"b":[["b","מים ששתו בהם תרנגולים, או כלבים."],["b","מים ששתו מהם התרנגולים, וקל וחומר אם שתה מהם אדם, כשרים לנטילת ידיים, ולא נחשב מים שנעשו בהם מלאכה. אבל מים שליקק מהם הכלב או חתול, יש פוסלים אותם מפני שהם נמאסים. (ב\"י שו\"ע סי' ק\"ס ס\"ד. ב\"ח. מ\"א סק\"ז. מחה\"ש. שע\"ה סי' כ\"ז סק\"י: שאר חיות ועופות, דעת המ\"ב ס\"ק כ\"ג להכשיר, כפי דעת מרן. והכה\"ח ס\"ק כ\"ז מחמיר)"],["t","חציצה בנטילת ידיים"],["b","קודם הנטילה צריך להשגיח שיהיו הידיים נקיות בלא שום חציצה. ומי שצפרני אצבעותיו גדולות ועודפות על הבשר, צריך לדקדק לנקותן שלא יהא תחתיהן לכלוך, משום דהוי חציצה. וכן אשה צריכה להסיר הטבעת מטעם זה, ואפילו אם היא רפויה. (שע\"ה סי' כ\"ז סי\"ג)"]]},{"h":"כג אב יום חמישי","s":"הלכות נטילת ידים לסעודה","d":["לעילוי נשמת משה בן סעיד סאלם | לעילוי נשמת רומיה בת אהרון | הודיה בת רועי ברכה והצלחה","כמוהר\"ר שוכר בדיחי זצוק\"ל - תרי\"ט"],"b":[["t","האם יש חציצה בנטילת ידיים לאיש או אשה שידיהם צבועות?"],["b","אם אין שם ממשות הצבע, אלא רק מראה של צבע (כגון חינה), לא הוי חציצה. אבל אם יש עליהם ממשות אפילו מעט, הוי חציצה. אשה שדרכה לצבוע ציפורניה וידיה לנוי, אינו חוצץ, אפילו אם כל הידיים צבועות. אלא אם כן נפגם הצבע, שאינה רוצה בקיומו. (שע\"ה ח\"א סי' כ\"ז סי\"ד והערה ל\"ב)"],["t","בעלי אומנות שרגילותם עם ידים צבועות"],["b","פר ע, או סו אולם אם הוא רגיל בכך כגון שהוא צב ואצבעותיו מלוכלכות בדיו, והוא רגיל בכך, וכל בעלי אומנות זאת, אינם מקפידים בכך ביום יום, מותר. ואף על פי שלכבוד שבת, או כשהולכים לשמחה של מצווה, מקפידים להוריד הצבע, אפשר להקל לעניין נטילה. (שע\"ה רלג' והערה לב')"]]},{"h":"כד אב יום שישי","s":"הלכות נטילת ידים לסעודה","d":["ברכה והצלחה לרבקה בת שלום"],"b":[["t","בעלי אומנות שרוב היד שלהם צבועה, האם חוצץ?"],["b","מה שאמרנו שבעלי אומנות שרגילים שאצבעותיהם מלוכלכות, ואין מקפידים על כך אינו חוצץ, זה דווקא כשהצבע אינו על רוב היד, אבל אם הצבע ברוב היד, חוצץ' אף שאינם מקפידים. (שע\"ה ח\"א סי' כ\"ז סי\"ד)"],["t","מה הדין מי שיש לו תחבושת על היד?"],["b","מי שיש לו פצע על ידו ועליו רטייה (תחבושת), שמצטער להסירה מחמת הכאב, לא הוי חציצה, וייטול את יתר היד. (שע\"ה ח\"א סי' כ\"ז סי\"ד)"]]},{"h":"כה אב יום שבת פרשת ראה","s":"הלכות נטילת ידים לסעודה","d":["לעילוי נשמת סעדה בת סעדה | חן בן משה ומרים דהרי ברכה והצלחה ברוחניות ובגשמיות שפע רב זרעא של קיימא במהרה וחיים טובים"],"b":[["t","ליום הולדתך"],["b","המים צריכים לבוא מכוח אדם חוץ ממה שלמדנו בימים הקודמים שצריך ליטול הידים מתוך כלי, גם צריכים המים לבוא על הידיים מכח גברא (אדם). אבל אם המים באים מאליהם, אינה נטילה. (שע\"ה ח\"א סי' כ\"ז סט\"ו)"],["t","ליטול את הידים מברז של חבית מים"],["b","חבית שיש בה נקב, ובתוך הנקב חסימה הסותמת את הנקב (כגון ברז בימינו), ומסיר את החסימה של הנקב, המים הבאים בכח הראשון, דהיינו קילוח הראשון לבדו הנשפך מהחבית נחשב מכח אדם. אבל המים הבאים אחר כך נחשבים כאילו באו מאליהם מכח הטבע. ולכן מי שרוצה ליטול את ידיו דרך הברז, צריך לידע שבקילוח הראשון נתכסתה כל היד, ויסתום הברז, ויחזור ויפתח לשפיכה שנייה. ומי שאינו יודע לשער, אין לו ליטול בדרך זו. (שע\"ה ח\"א סי' כ\"ז סט\"ו)"]]},{"h":"כו אב יום ראשון","s":"הלכות נטילת ידים לסעודה","d":[],"b":[["t","מה הדין בברזי המים המצויים בימינו?"],["b","ברזי המים המצויים בזמנינו, ברור שאין לדמותם לברז שבחבית, משום שהחבית היא כלי. אבל הברז של היום בא מצינורות, ואינו נחשב כלי. ולא יטול ידיו מהברז ללא כלי. ולענין דיעבד, כשאין לו כלי, מועיל להיחשב הברז שלנו בתורת טבילה, ולא בתורת נטילה, ובתנאי שיוריד ידיו לארץ, או לקרקעית הכיור, כשפותח המים פתיחה מלאה. (מדין ניצוק חיבור. מ\"ב קנ\"ט סקמ\"ז. מנחת יצחק ח\"ד סי' כ\"א אות ו'. עיני יצחק ל\"ד. וכן דיברנו עם הרב בע\"פ)"],["t","מה הדין ליטול בכוס חד פעמית?"],["b","לכתחילה לא יטול בכוס חד פעמית, ואם אין לו כלי אחר, מותר. ועדיף שיטול בכוס חד פעמית מאשר להוריד ידיו לקרקעית הכיור, שזה אינו, רק בדוחק כשאין לו כלי כלל. (מפי הרב)"]]},{"h":"כז אב יום שני","s":"הלכות נטילת ידים לסעודה","d":[],"b":[["t","מה הדין אם אין לו מים לנטילת ידים?"],["b","אסור לאכול בלא נטילה, אפילו אם יכרוך את ידיו במפה. ואם הוא בדרך ואין לו מים, אם יודע כי בעוד דרך ארבע מיל לפניו, ימצא מים, (מהלך 72 דקות, וכן אם הוא ברכב, נסיעה במשך 72 דקות) או לחזור לאחריו, מיל אחד, (שהוא 18 דקות) מחוייב ללכת לפניו ד' מיל, ולאחריו מיל, ליטול ידיו לאכילה. (שע\"ה סי' כ\"ז סט\"ז)"],["t","מה הדין אם אין מים גם במרחק 4 מיל מלפניו, ולאחריו מיל?"],["b","אם גם במרחק ארבע מיל מלפניו, ומיל מלאחריו, לא ימצא מים, או שהוא עם חבורה ומתיירא להיפרד מהם, וכן מי שיש לו אונס אחר שאינו יכול ליטול ידיו, יכרוך ידיו במפה או ניילון, או ילבש בתי ידיים (כפפות), ויאכל כך. (שע\"ה סי' כ\"ז סט\"ז)"]]},{"h":"כח אב יום שלישי","s":"הלכות נטילת ידים לסעודה","d":["ברכה והצלחה להילה ידעי"],"b":[["t","העושה צרכיו קודם שבא לאכול, איך ינהג לעניין נטילת ידיים?"],["b","העושה צרכיו קודם אכילה, שהוא צריך ליטול ידיו קודם ברכת אשר יצר, וגם צריך ליטול ידיו לסעודה, יטול נטילת ידים כדין נטילת ידים לסעודה, והיא עולה אף לנטילת ידים של אשר יצר. ויברך תחילה על נטילת ידים, ואחר כך אשר יצר. וכשיתחיל לאכול, יברך המוציא. (שע\"ה רל'ד. עריכ\"ש חב' קל'ח)"],["t","הנוגע בגופו או עושה צרכיו באמצע סעודה איך ינהג?"],["b","מי שבאמצע סעודה, נגע בגופו במקומות המכוסים, או שחיכך בראשו, או שעשה צרכיו, צריך ליטול ידיו תחילה כדין נטילה לפת, פעם שנית, אבל לא יברך עליהם. (שע\"ה ח\"א סי' כ\"ז סי\"ח. רל'ה)"]]},{"h":"כט אב יום רביעי ערב ראש חודש","s":"הלכות סליחות וחודש אלול","d":[],"b":[["t","ארבעים ימי רצון"],["b","מראש חדש אלול עד אחרי יום הכפורים, המה \"ימי רצון\". ואע\"פ שבכל השנה הקב\"ה מקבל תשובה מן השבים אליו בלב שלם, מכל מקום ימים אלו מובחרים יותר ומזומנים לתשובה, להיותם ימי \"רחמים ורצון\": (שע\"ה סי' ק\"ט ס\"א)"],["t","יזרז עצמו בהם בתשובה תפילה וצדקה"],["b","אמרו דורשי רשומות, \"ומל י\"י אלהיך את לבבך ואת לבב זרעך\" ראשי תיבות אלול. וכן \"אני לדודי ודודי לי\" ראשי תיבות אלול. וכן \"איש לרעהו ומתנות לאביונים\" ראשי תיבות אלול: רמז לשלושה דברים, שהם; תשובה, תפילה, וצדקה, שצריכין להזדרז בהם בחודש זה. ומל י\"י וגו' - רומז לתשובה. אני לדודי וגו' - רומז לתפילה, שהיא רינת דודים. איש לרעהו ומתנות לאביונים - רומז לצדקה: (שם)"]]},{"h":"ל' אב יום חמישי א' דראש חודש","s":"הלכות סליחות וחודש אלול","d":["לעילוי נשמת שושנה שאקי בת סאלם ורומיה","הרה\"ג יעקב מזרחי זצוק\"ל - רב ברחובות ומפעילי אגו\"י"],"b":[["t","זמן אמירת הסליחות. והאם אומרים ברכות השחר לפני הסליחות?"],["b","ימים אלו מובחרים יותר ומזומנים לתשובה, להיותם ימי רחמים ורצון. לפיכך מיום שאחרי ראש חודש אלול, נוהגים להשכים ולבוא לבתי כנסיות באשמורת האחרונה של הלילה לומר סליחות ותחנונים, עד יום הכיפורים, חוץ משבתות וראש השנה. ולכן קוראים אותם בשם \"אשמורות\". (שע\"ה סי' ק\"ט ס\"א וס\"ב)"],["b","ונוהגים לומר לפני האשמורות, כל ברכות השחר וברכות התורה. ויש נוהגים לאמרם רק אחר גמר האשמורות: (שם)"],["b","האם מתעטפים בטלית בזמן הסליחות?"],["b","ו המצויצת קודם שמתחיל. טלית השליח צבור, יתעטף ב ולא יברך עליה, משום דקיימא לן דלילה לאו זמן ציצית הוא. ומנהגינו שגם כל הקהל מתעטפים, וקודם התחלת התפילה כשרואים שהגיע זמן ציצית, מברך הממונה בקול רם להוציא את כולם ידי חובתם. (שע\"ה סי' ק\"ט ס\"ג)"]]},{"h":"א' אלול יום שישי ב' דראש חודש","s":"הלכות סליחות וחודש אלול","d":["לעילוי נשמת מורי זכריה בן יפת | לעילוי נשמת ארז בן סעדיה שרים | לעילוי נשמת אחותי נעמי בת ישראל | לעילוי נשמת משה בן יחיא סעיד ענקי | לעילוי נשמת אילנה בת סעדיה מעטוף ז\"ל | לעילוי נשמת דגנית בת ישראל | לעילוי נשמת הווידה בת חמדי","כמוהר\"ר סאלם אלישיך זצוק\"ל - תש\"ד, אב\"ד בירושלים"],"b":[["t","אמירת הסליחות מעומד או מיושב?"],["b","צריך לומר האשמורות בתחינה וקול בכי. ובמשך כל זמן אמירתם (גם באמירת אל מלך יושב וכו' ושלוש עשרה מדות)"],["b","הקהל יושבים, ורק הש\"צ עומד. חוץ מבוידוי שעומדים בכפיפת קומה, ואח\"כ זוקפים, ונשארים עומדים עד סיום פיסקת \"בטרם שחקים\". ויש מהשאמי שנוהגין לעמוד גם באמירת \"אל מלך יושב\" וכו' ו\"שלוש עשרה מדות\". (שע\"ה סי' ק\"ט ס\"ג)"],["t","מה הדין אם קשה לו להתכופף בזמן הווידוי?"],["b","הווידוי צריך להיות בעמידה. ולא ישען על דבר כדי לסמוך גופו, כלומר, שאם ינטל אותו דבר יפול האדם. וטוב שיכפפו גופם מעט. וכן המנהג. ומי שאינו יכול להתכופף בווידוי מבלי להישען, עדיף שיעמוד זקוף. כי העמידה צריך מן הדין, אבל הכפיפה אינה אלא מנהג על פי השל\"ה. (שע\"ה סי' ק\"ט ס\"ג. עיני יצחק ט\"ז ושע\"ה סי' קי\"ד ס\"ו)"]]},{"h":"ב' אלול יום שבת פרשת שופטים","s":"הלכות סליחות וחודש אלול","d":["לעילוי נשמת לאה בת שמאי","הרה\"ג אברהם צדוק זצוק\"ל - רב קרית בנימין"],"b":[["t","האם תוקעים בשופר כל יום אחרי אמירת הסליחות?"],["b","נוהגים לתקוע בשופר בכל יום לאחר סיום האשמורות. חוץ מערב ראש השנה שאין תוקעין בו, כדי להפסיק בין תקיעות רשות לתקיעות מצוה. וכן בין ראש השנה ליום הכפורים, אין תוקעים. וטעם התקיעות בחודש זה, כדי לעורר את העם לתשובה. כי כן הוא טבע השופר לעורר ולהחריד, כמו שאמר הכתוב \"היתקע שופר בעיר, ועם לא יחרדו\". (שע\"ה סי' ק\"ט ס\"ד)"],["t","התקיעות שתוקעים לאחר אמירת הסליחות?"],["b","סדר התקיעות שתוקעין בחודש אלול, הוא תשר\"ת, דהיינו ת'קיעה ש'ברים תר'ועה ת'קיעה. יש התוקעים ממש בסוף, דהיינו אחרי \"עשה למען שמך\", ויש לפני כן. ויש שאינם תוקעים שם, אלא קודם \"תענו ותעתרו\". ויש מהשאמי שתוקעין גם בשעת אמירת י\"ג מדות."],["s","(שע\"ה סי' ק\"ט ס\"ד. עיני יצחק י\"ח)"]]},{"h":"ג' אלול יום ראשון","s":"הלכות סליחות וחודש אלול","d":["לעילוי נשמת חיים בן אהרון | ברכה והצלחה שרה בת דניאל"],"b":[["t","כיצד יעשו הנוהגים לתקוע בשעת אמירת י\"ג מידות?"],["b","יש מדקדקים שאינם מתחילים לתקוע רק מן נוצר חסד וגו' וממהרים קודם להשלים לעצמם, קודם שיתקעו. ויש המקילים לומר תיבות י\"י י\"י אל רחום וחנון, עמהם, ומיד אח\"כ תוקעים. ובאופן כזה, אם אין עשרה כי אם בצירוף התוקע, לא יתקע. דכיון שאינו מסיים איתם, אינו נחשב לעשירי. (שע\"ה סי' ק\"ט ס\"ד. עיני יצחק י\"ט)"],["t","האם יחיד אומר ויעבור י\"י ביחידות?"],["b","יחיד האומר אשמורות, וכן כשעדיין לא באו עשרה לבית הכנסת. אינו רשאים לומר שלוש עשרה מידות כהווייתן. אלא נוהגים לומר שני השמות בחילוף א\"ת פץ\" אל רחום וגו'. אבל מקום פץ מצ ב\"ש כזה; \"מצ שנזכרו שלש עשרה מדות, כגון; \"זכור לנו ברית שלוש עשרה מידות\" וכדומה, אין מדלגים. (שע\"ה סי' ק\"ט ס\"ה.)"],["b","וכן מנהג השאמי כמו שכתב בספר פסקי הלכות (עמ' שנג)."]]},{"h":"ד' אלול יום שני","s":"הלכות סליחות וחודש אלול","d":[],"b":[["t","האם יחיד אומר סליחות שהן בלשון ארמי?"],["b","בקשות שהן בלשון ארמי, כגון; רחמנא אדכר לן וכו', מרן דבשמיא וכו', מחי ומסי וכו', מנהגינו שאומרים אותן אע\"פ שאין עשרה. ואפילו יחיד ממש. (שע\"ה סי' ק\"ט ס\"ה. וכ\"כ הגר\"י צוברי. פסקי הלכות עמ' שנ\"ב)"],["t","סדר שבע ההפטרות אחרי תשעה באב"],["b","משבת שלאחר תשעה באב ואילך, מפטירים בשבע שבתות \"שבע דנחמתא\", וסימנם נו\"ע ארק\"ש. דהיינו; נחמו נחמו. ותאמר ציון. עניה סוערה. אנכי אנכי. רני עקרה (ולא משלימין עליה גם עניה סוערה אע\"פ שהיא סמוכה לה). קומי אורי. שוש אשיש [ומנהגינו להקדים פסוק ונודע בגויים. (שע\"ה סי' ק\"ט ס\"ח)"]]},{"h":"ה' אלול יום שלישי","s":"הלכות תשובה","d":["ברכה והצלחה לשילת ידעי"],"b":[["t","החוזר בתשובה, האם חייב להתוודות?"],["b","כל המצוות שבתורה בין \"עשה\" בין \"לא תעשה\", אם עבר אדם על אחת מהן בין בזדון בין בשגגה, כשיעשה תשובה וישוב מחטאו, חייב להתוודות לפני האל ברוך הוא. שנאמר \"איש או אשה כי יעשו וגו' והתודו את חטאתם אשר עשו\", זה וידוי דברים. וידוי זה מצות עשה. וכן החובל בחבירו והמזיק ממונו, אף על פי ששילם לו מה שהוא חייב לו, אינו מתכפר, עד שיתוודה וישוב מלעשות כזה לעולם, שנאמר \"מכל חטאות האדם\": (רמב\"ם הלכות תשובה פ\"א)"],["t","בימינו שאין קרבנות ובית המקדש לכפר, האם יש תקנה לחוטא?"],["b","בזמן הזה שאין בית המקדש קיים ואין לנו מזבח וקרבנות לכפרה, אין לנו אלא תשובה. התשובה מכפרת על כל העבירות. אפילו רשע כל ימיו, ועשה תשובה באחרונה, אין מזכירין לו שום דבר מרשעו. שנאמר \"רשעת הרשע לא יכשל בה ביום שובו מרשעו\":"],["s","(רמב\"ם שם ה\"ג)"]]},{"h":"ו' אלול יום רביעי","s":"הלכות תשובה","d":["ברכה והצלחה ליעקב בן סעדיה וכל משפחתו"],"b":[["t","מהי תשובה גמורה?"],["b","אי זו היא תשובה גמורה? זה שבא לידו דבר שעבר בו, ואפשר בידו לעשותו, ופירש ולא עשה מפני התשובה. לא מיראה ולא מכשלון כח. הוא ששלמה המלך אמר \"וזכור את בוראך בימי בחורותיך\". ואם לא שב אלא בימי זקנותו, ובעת שאי אפשר לו לעשות מה שהיה עושה, אף על פי שאינה תשובה מעולה, מועלת היא לו, וכל עוונותיו נמחלין: (רמב\"ם שם פ\"ב ה\"א)"],["t","כיצד היא התשובה?"],["b","ומה היא התשובה? שיעזוב החוטא חטאו ויסירו ממחשבתו ויגמור בלבו שלא יעשהו עוד. שנאמר \"יעזוב רשע דרכו\" וגו'. וכן יתנחם על שעבר, שנאמר \"כי אחרי שובי נחמתי\". ויעיד עליו יודע תעלומות שלא ישוב לזה החטא לעולם, שנאמר \"ולא נאמר עוד אלהינו למעשה ידינו\" וגו'. וצריך להתוודות בשפתיו ולומר עניינים אלו שגמר בלבו: (רמב\"ם שם ה\"ב)"]]},{"h":"ז' אלול יום חמישי","s":"הלכות תשובה","d":[],"b":[["t","המתוודה ואינו עוזב חטאו למה דומה?"],["b","כל המתודה בדברים ולא גמר בלבו לעזוב, הרי זה דומה לטובל ושרץ בידו, שאין הטבילה מועלת לו עד שישליך השרץ. וכן הוא אומר \"ומודה ועוזב ירוחם\". וצריך לפרוט את החטא. שנאמר \"אנא חטא העם הזה חטאה גדולה, ויעשו להם אלהי זהב\": (רמב\"ם שם ה\"ג)"],["t","לאחר התשובה, האם מתכפר מיד?"],["b","יש עבירות שהן מתכפרים לשעתן, ויש עבירות שאין מתכפרים אלא לאחר זמן. כיצד, עבר אדם על מצות \"עשה\" שאין בה כרת, ועשה תשובה, אינו זז משם עד שמוחלין לו. עבר על מצות \"לא תעשה\" שאין בה כרת, ולא מיתת בית דין, ועשה תשובה. תשובה תולה, ויום הכפורים מכפר. עבר על כריתות ומיתות בית דין ועשה תשובה, תשובה ויום הכפורים תולין, ויסורין הבאין עליו גומרין לו הכפרה: (רמב\"ם שם ה\"ד)"]]},{"h":"ח' אלול יום שישי","s":"הלכות תשובה","d":[],"b":[["b","חמשה עוונות שנובעים ממידות רעות, וקשה לפרוש מהן."],["b","חמשה דברים העושה אותם, יימשך אחריהם תמיד וקשים הם לפרוש מהן. לפיכך צריך אדם להיזהר מהן שמא ידבק בהן, והן כולן דעות רעות עד מאד. ואלו הן; רכילות. ולשון הרע. ובעל חימה. ובעל מחשבה רעה. והמתחבר לרשע, מפני שהוא לומד ממעשיו, והן נרשמים בלבו. הוא שאמר שלמה \"ורועה כסילים ירוע\": (רמב\"ם הלכות תשובה פ\"ד ה\"ה)"],["t","חמשה עוונות חמורים שנראין קלים בעיני בני אדם"],["b","חמשה דברים, העושה אותן אין חזקתו לשוב מהן, לפי שהם דברים קלים בעיני רוב האדם, ונמצא חוטא, והוא ידמה שאין זה חטא. ואלו הן; א) האוכל מסעודה שאינה מספקת לבעליה. ב) המשתמש במשכון של עני שהשכין אצלו בעבור חובו. ג) המסתכל בעריות. ד) המתכבד בקלון חבירו. ה) והחושד בכשרים: (רמב\"ם הלכות תשובה פרק ד' ה\"ד)"]]},{"h":"ט' אלול יום שבת פרשת כי תצא","s":"הלכות תשובה","d":["ברכה והצלחה בריאות אודיה בת עדי","כמוהר\"ר סאלם טייבי זצוק\"ל - תשמ\"ז, מרבני צנעא"],"b":[["t","הבחירה ביד האדם לבחור לטוב או לרע"],["b","כל אדם ראוי לו להיות צדיק כמשה רבינו, או רשע כירבעם. או חכם, או סכל, או רחמן, או אכזרי, או קמצן, או נדיב, וכן שאר כל הדעות. ואין לו מי שיכפהו, ולא גוזר עליו, ולא מי שמושכו לאחד משני הדרכים. אלא הוא מעצמו ומדעתו, נוטה לאיזו דרך שירצה. ולפיכך הואיל ובאפשרותינו לבחור בטוב, ומדעתנו עשינו כל הרעות, ראוי לנו לחזור בתשובה ולעזוב רשענו: (רמב\"ם הלכות תשובה פ\"ה ה\"ב)"],["t","עמוד התורה והמצווה"],["b","ודבר זה עיקר גדול הוא, והוא עמוד התורה והמצוה שנאמר \"ראה נתתי לפניך היום, את החיים\" וכו'. וכתיב \"ראה אנכי נותן לפניכם היום\" וכו'. כלומר; שהרשות בידכם. וכל שיחפוץ האדם לעשות ממעשה בני האדם, עושה, בין טובים בין רעים: (רמב\"ם הלכות תשובה פ\"ה ה\"ג)"]]},{"h":"י' אלול יום ראשון","s":"הלכות תשובה","d":["לעילוי נשמת מירב שאקי בת שלמה ושושנה"],"b":[["t","לשוב גם מעבירות שאין בהם מעשה"],["b","אל תאמר שאין תשובה אלא מעבירות שיש בהן מעשה, כגון זנות. וגזל. וגניבה. אלא, כשם שצריך אדם לשוב מאלו, כך הוא צריך לחפש בדעות רעות שיש לו, ולשוב מן הכעס. ומן השנאה. ומן הקנאה. ומרדיפת הממון. והכבוד. ומרדיפת המאכלות, וכיוצא בהן. ואלו העוונות קשים מאותן שיש בהן מעשה, שבזמן שאדם נשקע באלו, קשה הוא לפרוש מהם: (רמב\"ם הלכות תשובה פ\"ז ה\"ג)"],["t","בעל תשובה אהוב לפני הקב\"ה"],["b","ואל ידמה אדם בעל תשובה שהוא מרוחק ממעלת הצדיקים, מפני העוונות והחטאות שעשה. אין הדבר כן, אלא אהוב ונחמד הוא לפני הבורא, כאילו לא חטא מעולם. ולא עוד, אלא ששכרו הרבה. שהרי טעם טעם החטא, ופירש ממנו וכבש יצרו. אמרו חכמים \"מקום שבעלי תשובה עומדין, אין צדיקים גמורין יכולין לעמוד בו\". כלומר; מעלתן גדולה ממעלת אלו שלא חטאו מעולם, מפני שהן כובשים יצרם יותר מהם: (רמב\"ם הלכות תשובה פ\"ז ה\"ד)"]]},{"h":"יא אלול יום שני","s":"הלכות ערב ראש השנה","d":["ברכה והצלחה למלכה בת רבקה טאג'י","הרה\"ג שלמה יגאלי זצוק\"ל - רב שכונה בראשל\"צ"],"b":[["t","האם צריך לעשות התרת נדרים בערב ראש השנה?"],["b","נוהגין לעשות התרת נדרים בערב ראש השנה בסיום תפילת שחרית אחרי עלינו לשבח. (ורמז לדבר, לא יחל דברו ככל, סופי תיבות אלול). (שע\"ה סי' ק\"ט סי\"ב)"],["t","כיצד עושים התרת נדרים?"],["b","המנהג שחולקים את הקהל לשנים, אלו שבצד זה ואלו שבצד זה, ועומד אחד מצד האחד ואומר בלשון רבים, \"שמעו נא רבותינו\" וכו' לפני הקהל שבצד השני, והם משיבים \"הכל יהיו מותרים לכם\" וכו'. ומוסר מודעא, ואומר \"יהי רצון\" וכו' והם משיבים \"הכל מותרים לכם\" וכו'. ואח\"כ עומד אחד מהצד השני, ואומר לפני הראשונים כנז\"ל: (שם)"]]},{"h":"יב אלול יום שלישי","s":"הלכות ערב ראש השנה","d":["לעילוי נשמת שמואל בן דוד לוי ז\"ל"],"b":[["t","תפילה בבית הקברות בערב ראש השנה"],["b","יש נוהגים לילך להתחנן בערב ראש השנה אחר תפילת שחרית בבית הקברות על קברי הצדיקים, וכן על קברי אבותיהם, ונותנים שם צדקה לעניים. ומרבים תחנונים לעורר את הצדיקים הקדושים אשר בארץ המה, שימליצו טוב בעדינו ביום הדין. (שע\"ה סי' ק\"ט סי\"ד)"],["t","היאך היא דרך התפילה על הקברות?"],["b","אל ישים מגמתו נגד המתים השוכנים שם, כי קרוב הדבר שיהיה בכלל מה שנאמר \"לא ימצא בך וגו' ודורש אל המתים\". אך יבקש מהשם יתברך שירחם עליו בזכות הצדיקים שוכני עפר. (שם)"]]},{"h":"יג אלול יום רביעי","s":"הלכות ערב ראש השנה","d":["ברכה והצלחה בריאות וזיוג הגון נדב בן מתתיהו"],"b":[["t","איזה שלוחי ציבור ראוי לבחור שיתפללו בימים נוראים?"],["b","ידקדקו לבחור שלוחי ציבור שיתפללו בימים נוראים אנשים הגונים וגדולים בתורה ובמעשים טובים כפי מה שאפשר למצוא. וגם שיהיו מבני שלושים שנה ומעלה, שאז כבר נחה רתיחת דם הבחרות ונכנע ליבם. וגם שיהיו נשואים (ויהיו להם ילדים), שהם שופכים ליבם ומפילים תחנונים מקירות הלב. (שם סעיף ט')"],["t","את מי עדיף למנות תוקע בימים נוראים?"],["b","ידקדקו לבחור תוקע בעל תורה ויראה כפי מה שאפשר למצוא. מכל מקום בין לתקיעות בין לשלוחי ציבור, כל ישראל כשרים, רק שיהיו מרוצים לקהל. ואם רואה שיש מחלוקת בדבר, ימנע עצמו אף על פי שיעמוד מי שאינו הגון. (שע\"ה סי' ק\"ט סעיף ט')"]]},{"h":"יד אלול יום חמישי","s":"","d":["לעילוי נשמת סעידה בת חמדי","כמוהר\"ר סאלם צאלח זכריה זצוק\"ל - תשכ\"ז, אב\"ד בידא"],"b":[["t","האם יש מצוה להתרחץ ולהסתפר קודם ראש השנה?"],["b","יש נוהגים לטבול בערב ראש השנה במקוה כשרה (אנשים, ולא נשים). ומצוה על כל אדם להסתפר ולהתרחץ לכבוד יום טוב. ויש להיזהר להסתפר קודם חצות [ובדיעבד אפשר כל היום]. (שע\"ה סי' ק\"ט סעיף ט\"ו)"],["t","האם לובש בגדים נאים לכבוד ראש השנה?"],["b","ירבה בצדקה כפי כוחו, כי סגולתה לכפר עוונות וזדונות. ולובשים בגדים נאים בראש השנה, להראות שאנו בטוחים בחסדו יתברך שיוציא לאור משפטינו. (שם)"]]},{"h":"טו אלול יום שישי","s":"הלכות תפילה בעשרת ימי תשובה","d":["ברכה והצלחה לתמר ידעי"],"b":[["t","שינויים בתפילה בעשרת ימי תשובה"],["b","כל השנה אומרים בתפילה \"האל הקדוש\". \"מלך אוהב צדקה ומשפט\". חוץ מראש השנה עד יום הכפורים ועד בכלל, שצריכין לומר \"המלך הקדוש\", \"המלך המשפט\", לפי שבימים אלו הקדוש ברוך הוא מראה מלכותו לשפוט את העולם. וכן מוסיפים; \"זכרנו\", \"ומי כמוך\", \"זכור רחמיך\", \"ובספר חיים\". (שע\"ה סי' ק\"י סעיף א')"],["t","שכח ואמר האל הקדוש, ונזכר תוך כדי דיבור"],["b","אם טעה ואמר \"האל הקדוש\", או שהוא מסופק אולי אמר \"האל הקדוש\" במקום \"המלך הקדוש\", אם נזכר תוך כדי דיבור (דהיינו אמירת שלום עליך רבי), ועדיין לא התחיל ברכה אחרת, אומר המלך הקדוש ואינו חוזר לראש, וכן הדין בהמלך המשפט. (שם)"]]},{"h":"טז אלול יום שבת פרשת כי תבוא","s":"הלכות תפילה בעשרת ימי תשובה","d":["לעילוי נשמת סלימן מאורי הלוי ז\"ל בן יחיא וסלמה ז\"ל | לעילוי נשמת יפת בן סעיד הלל ז\"ל | לעילוי נשמת יוסף בן משה מעטוף ז\"ל","כמוהר\"ר נתנאל אלשיך זצוק\"ל - תרפ\"א"],"b":[["t","טעה ואמר האל הקדוש ולא נזכר תוך כדי דיבור"],["b","אם טעה ואמר האל הקדוש, או שהוא מסופק אולי אמר האל הקדוש במקום המלך הקדוש, ולא נזכר עד לאחר כדי דיבור, צריך לחזור לראש התפילה אפילו מספק, מפני ששלש ברכות הראשונות נחשבות כאחת. (ואפילו שליח ציבור בחזרת התפילה צריך לחזור לראש, ואומרים הקדושה שנית). (שע\"ה סי' ק\"י סעיף א')"],["t","שכח ולא אמר \"ובכן יתקדש\" בברכת אתה קדוש"],["b","אם שכח \"ובכן יתקדש\" וכו' וחתם המלך הקדוש, ואפילו לא אמר עדיין רק ברוך אתה ה', חותם המלך הקדוש ואומר אתה בחרתנו וכו'. (שם)"]]},{"h":"יז אלול יום ראשון","s":"הלכות תפילה בעשרת ימי תשובה","d":["הרה\"ג סעדיה בן יוסף זצוק\"ל - תשנ\"ז"],"b":[["b","אמר ובכן יתקדש, ומסופק אם סיים המלך הקדוש."],["b","אם ברור לו בר\"ה וכיפורים שאמר ובכן יתקדש וכו', רק מסופק אם חתם המלך הקדוש, אינו חוזר, שבודאי סיים כהוגן. וכן הדין למנהג הבלדי שאומרים ובכן יתקדש, גם בכל הימים שבין ר\"ה לכפורים. (שע\"ה סי' ק\"י ס\"ב)"],["t","שכח ולא הוסיף את התוספות בשני ברכות הראשונות והאחרונות בשמונה עשרה"],["b","אם שכח \"זכרנו לחיים\" בברכת האבות. או \"מי כמוך\" בברכת אתה גיבור. \"זכור רחמיך\" - לפי נוסח הבלדי, ב לחיים\" וכו' בברכת ההודאה, \"ובספר ובשאמי - \"וכתו חיים\" בברכת שים שלום, ולא נזכר עד שאמר ברוך אתה ה'. כיון שאמר את השם, גומר את הברכה ומתפלל כסדר ואינו חוזר. (שע\"ה סי' ק\"י ס\"ב)"]]},{"h":"יח אלול יום שני","s":"הלכות תפילה בעשרת ימי תשובה","d":["לעילוי נשמת פרחיה בת עזרא"],"b":[["t","טעה ולא אמר המלך המשפט ולא נזכר תוך כדי דיבור"],["b","אם טעה ואמר מלך אוהב צדקה ומשפט, במקום המלך המשפט, ולא תיקן תוך כדי דיבור. נחלקו הפוסקים. יש אומרים שאפילו יחיד אינו חוזר אפילו לאותה ברכה, כיון שהזכיר תיבת מלך בברכה זאת. ויש אומרים שצריך לחזור. דהיינו שאם נזכר קודם שעקר רגליו, חוזר לברכת השיבה ואומר משם ואילך על הסדר. ואם עקר רגליו, חוזר לראש התפילה: (שם)"],["b","דין הטועה ב\"המלך המשפט\", ואמר \"מלך אוהב צדקה ומשפט\"."],["b","פוסק הגר\"י רצאבי שליט\"א, שאע\"פ שנראה כי נתפשט המנהג להורות כדעת האומרים שצריך לחזור גם בהמלך המשפט, מ\"מ ראוי להכריע שיחזור מ\"השיבה שופטינו\" ואילך בלא להוציא בשפתיו אלא בהרהור. [כי לעניין דינא נראה שאין צריך לחזור. אחרי שכן דעת הרמב\"ם בתשובותיו, וגם לפי הנוסחאות המדוקדקות כת\"י בחיבורו]. (שע\"ה סי' ק\"י עיני יצחק ב')"]]},{"h":"יט אלול יום שלישי","s":"הלכות תפילה בעשרת ימי תשובה","d":["להצלחה והתחזקות בקדושה ובצניעות ליעל בת דקל","כמוהר\"ר אברהם הכהן זצוק\"ל - ר\"י בית אלשרעבי"],"b":[["t","האם יש שינוי בנוסח הקדיש בעשרת ימי תשובה?"],["b","מנהג השאמי לכפול תיבת \"לעילא\", בכל הקדישים שאומרים מראש השנה עד יום הכפורים. וכיון שבקדיש מן יהא שמיה רבא וכו' ואילך צריכין להיות שמונה ועשרים תיבות, ובכל השנה אומרים לעילא \"מן כל\" ברכתא, עתה אומרים לעילא לעילא \"מכל\" ברכתא. אבל בבלדי כופלים תיבת לעילא כל השנה, ואומרים \"מכל\" תיבה אחת. (שע\"ה סי' ק\"י ס\"ג)"],["t","האם יש שינוי בברכת מעין שבע בליל שבת שובה?"],["b","ערבית ליל שבת שבין ראש השנה ליום הכיפורים בברכת מעין שבע, אומר גם כן במקום \"האל\" הקדוש שאין כמוהו, \"המלך\" הקדוש וכו'. ובבלדי אומרים אז המלך הקדוש גם בכל שבתות השנה. (שם ס\"ד)"]]},{"h":"כ' אלול יום רביעי","s":"הלכות תפילה בעשרת ימי תשובה ובימים הנוראים","d":["לעילוי נשמת אברהם בן חסן סאלם | ברכה והצלחה ליהונתן בן שלום","כמוהר\"ר חיים קורח זצוק\"ל - תרע\"ב"],"b":[["t","טעה ואמר האל הקדוש בברכת מעין שבע"],["b","אף למנהג השאמי שנוהגין בברכת מעין שבע לומר המלך הקדוש רק בשבת שובה, אם טעה השליח צבור בברכת מעין שבע ואמר האל הקדוש, אם עדיין לא סיים הברכה, חוזר מהמלך הקדוש ואילך. ואם כבר סיים הברכה, (ואפילו אם אמר רק ברוך אתה ה'), אינו חוזר: (שע\"ה סי' ק\"י ס\"ד)"],["t","האם צריך להתפלל שמונה עשרה בכפיפת הגוף בימים נוראים?"],["b","בראש השנה ויום הכפורים מתפללים תפילת העמידה באיברים זקופים כמו בכל השנה, אבל הלב יהיה כפוף לעבודת היוצר. וכן לא יגביהו את קולם אלא בלחש כמו בכל השנה. ויש נוהגים כדעת המתירים להגביה אז את קולם כדי שיוכלו להתפלל יותר בכוונה, ודוקא מעט אבל לא הרבה. (שם ס\"ה)"]]},{"h":"כא אלול יום חמישי","s":"הלכות ליל ראש השנה","d":[],"b":[["t","סדר אכילת הסימנים בליל ר\"ה"],["b","בליל ראש השנה עושים סימנים לשנה טובה דברים המעוררים את האדם להיישיר מעשיו. ואלו הן: תמר, רימון, תפוח בדבש, קרא, רוביא, כרתי, סלקא, ראש כבש או ראש דג. ולוקחים הסימן בידיהם ובעל הבית אומר נוסח יהי רצון, ולאחר מכן מברך, וכולם שומעים ומכוונים ועונים אמן ואוכלים. וטוב לעשות סדר זה גם בליל שני דראש השנה: (סי' ק\"י ס\"ז והערה כ\"א)"],["t","מתי זמן אכילת הסימנים"],["b","יש נוהגים לאכלם מיד אחר הקידוש לפני שנוטלים ידיהם לסעודה ויש נוהגים לאכלם אחרי אכילת פת הבציעה של ברכת המוציא, וכך נכון לנהוג מפני שתפוח בדבש, הוא דבר שטיבולו במשקה וצריך נט\"י. (שם ס\"ח, ותשובה לשואל בשיעור)"]]},{"h":"כב אלול יום שישי","s":"הלכות תקיעת שופר","d":["לעלוי נשמת עופר עזרא בן אברהם סירי | לעילוי נשמת בועז בן יוסף שמח ז\"ל | לעילוי נשמת תמניה אשאוול בת סעיד ורומיה (יחיא סאלם)| טליה בת אליהו אהבה אמונה דבקות וביטחון בשם"],"b":[["t","האם מותר לשמוע תקיעות שופר עם מכשירי שמיעה?"],["b","כבדי שמיעה המחזקים את שמיעתם ע\"י מכשיר שמיעה העובד ע\"י סוללות (בטריות), אינם יוצאים ידי חובתם כששומעים את התקיעות בעזרת מכשיר השמיעה. ואף אם יש באפשרותם לשמוע ללא המכשיר, מכל מקום אם שומעים את התקיעות בעזרת המכשיר, הרי הוא כקול פסול המעורב עם קול השופר ואין יוצאים בו, לכן יש להם להוציא את מכשיר השמיעה מאוזניהם בשעת התקיעות: (מועדי ה' סי' ב' סי\"א)"],["t","כמה תקיעות אדם חייב לשמוע בראש השנה?"],["b","במספר התקיעות יש חילוקים. על פי הגמרא והגאונים והרמב\"ם תוקעים רק ארבעים אחת תקיעות, שלושים מיושב ועשר מעומד ותרועה גדולה, ויש מהבלדי שמוסיפים ותוקעים שבעים ואחת תקיעות,] שלושים בעלות השחר ושלושים דמיושב, ועשר דמוסף ותרועה גדולה]. ומנהג השאמי (דרך כלל) מאה ואחת תקיעות: (שע\"ה סי' ק\"י ס\"י)"]]},{"h":"כג אלול יום שבת פרשת נצבים וילך","s":"הלכות תקיעת שופר","d":[],"b":[["t","האם מותר לתקוע ללא צורך לאחר התפילה?"],["b","יש אומרים שלאחר גמר התקיעות (כפי מנהג המקום), אין לתקוע יותר אפילו מי שרוצה להתלמד כדי לתקוע ביום שני, זולת קטנים, מותר לומר להם שיתקעו ואף מותר להשתדל ללמדם. אבל מנהגינו להקל שאפילו גדולים תוקעים ללא צורך. ולכולי עלמא השופר אינו מוקצה: (שע\"ה סי' ק\"י ס\"י)"],["t","האם יש שינוי באורך התקיעות בין סימן תשר\"ת לתש\"ת וכו'?"],["b","אין מאריכין בתקיעה של תשר\"ת יותר מבשל תש\"ת, ובשל תש\"ת יותר מבשל תר\"ת, אלא שיעור אחד לכל התקיעות כולן. זהו מנהגינו המקובל בידינו דור אחר דור, והוא מיוסד על דעת הגאונים ורבינו הרמב\"ם, וכן העיקר. (שם סי\"א)"]]},{"h":"כד אלול יום ראשון","s":"הלכות תקיעת שופר","d":[],"b":[["t","כיצד מנהג תימן לעשות את התרועה?"],["b","התרועה אין עושין טו טו טו וכו' כמנהג שאר כמה קהילות ישראל, אלא קול רועד, על ידי הפסקים בנשימה או בלשון, אבל לא בצירוף נענוע היד. ומקובל בידינו מהרבה תלמידי חכמים ומהתוקעים המומחים בכל גלילות תימן, דלהוציא התרועה בנשימה, דהיינו בהפסקות קלות של האויר היוצא מן הבטן ועד קנה הגרון, הוא עדיף יותר מן המוציאים אותה בנדנוד הלשון. (שם סי\"ב ועיני יצחק ל\"ג)"],["t","האם צריכים ליתן לתוקע עליה בספר תורה?"],["b","נוהגין להעלות את התוקע לקרוא \"חמישי\" בספר תורה, הן ביום טוב ראשון הן ביום טוב שני, אא\"כ חל בשבת שאין תוקעין בה: אמנם יש הנוהגים להעלותו בכל זאת אף בשבת \"חמישי\", ויש מעלים אותו \"שביעי\". (שע\"ה סי' ק\"י סי\"ב ועיני יצחק ט\"ל)"]]},{"h":"כה אלול יום שני","s":"הלכות תקיעת שופר","d":["לרפואה, הצלחה, בריאות, פרנסה טובה לאיילת בת רחל"],"b":[["t","כיצד ההכנה למצוות תקיעת שופר"],["b","בעת תקיעת שופר, צריך האדם להכין עצמו לשמוע קול שופר לקיים מצות עשה \"יום תרועה יהיה לכם\". ויחרד וילפת ויבכה על כל עוונותיו, כי אותה שעה עת המוסף, היא שעת הדין. וכל כך עשה ה' חסד ורחמים עם ישראל לדונם אז בעת שהם עסוקים במצוה, כדי שלא לדקדק עליהם. וחייב התוקע להתכוון להוציא לכל השומעים אותו, והם גם כן יתכוונו לצאת: (שם סעיף י\"ג)"],["t","לשמוע הברכה כדי לצאת ידי חובה"],["b","כשהתוקע אומר את הברכות, אל יאמרו הקהל ברוך הוא וברוך שמו, וישמעו היטב את הברכות. ואחר כל ברכה יאמרו בכוונה אמן. ואסור לו ולהם להפסיק מכאן עד לאחר כל התקיעות: (שע\"ה סי' ק\"י סי\"ד)"]]},{"h":"כו אלול יום שלישי","s":"הלכות תקיעת שופר","d":["לעילוי נשמת יצחק בן רבי שלום חסיד | לעילוי נשמת סעיד בן סאלם | לעילוי נשמת שרה בת עוואד ימיני | ברכה והצלחה ורפואה שלימה לדינה הלל בת חיים ענאקי | ברכה והצלחה הראל בן אופיר | ברכה והצלחה לתמר בת אלדד","כמוהר\"ר משה צארום זצוק\"ל - תשי\"א, מרבני צנעא"],"b":[["t","מהם תקיעות דמיושב, ותקיעות דמעומד?"],["b","הברכות והתקיעות צריכים להיות בעמידה. ודוקא התוקע, אבל הקהל יושבים אז, ולכן נקראים תקיעות דמיושב. ובמוסף מפני שעומדים, נקראים תקיעות דמעומד. (שע\"ה סי' ק\"י סט\"ו)"],["t","עניין הווידוי בין סימן לסימן בתקיעות"],["b","בתקיעות דמיושב, נכון לכל אדם להתוודות בלחש שלא יישמעו הדברים לאזניו, ובין סימן לסימן דווקא, דהיינו בין תשר\"ת לתש\"ת ובין תש\"ת לתר\"ת, כי אז השטן מעורבב, ודברי הווידוי עולים למעלה. ויתוודה תחילה באופן כללי, עברתי על \"לא תעשה\" ו\"עשה\", ואחר כך יפרט. (שם סעיף י\"ג)"]]},{"h":"כז אלול יום רביעי","s":"הלכות תקיעת שופר ותפילות ראש השנה","d":["לעילוי נשמת מרדכי בן דוד | זיווג הגון וחזרה בתשובה שלימה אביעד בן יוסף | ברכה והצלחה רחל בת סעדיה ושרה חתוכה","כמוהר\"ר סעיד ועלאני זצוק\"ל - תשנ\"ב, מרבני דמאר"],"b":[["t","היכן עומד התוקע לתקוע?"],["b","נוהגים שהתוקע עומד באמצע בית הכנסת על יד התיבה שקראו שם בספר תורה, וכן במוסף עומד על יד התיבה (לימין שליח ציבור, או לשמאלו). ואם אחר תוקע במוסף, יכול לעמוד במקומו, ואינו צריך לעמוד על יד התיבה: (סי' ק\"י סט\"ו)"],["t","מעלת תפילת מוסף בראש השנה"],["b","בעמדם להתפלל מוסף, צריך כל אחד לכוון דעתו בכוונה יתירה בתפילתו זאת אשר היא ארוכה בכמות ובאיכות, ובחינתה במקום עליון, עולה על כל התפילות. ורבים נוהגים להתפלל תפילה זו בלא לחש תחילה, אלא הש\"צ בקול רם, והקהל אומרים יחד עמו בלחש, וכן הוא העיקר: (שע\"ה סי' ק\"י סט\"ז)"]]},{"h":"כח אלול יום חמישי","s":"הלכות תקיעת שופר ותפילות ראש השנה","d":[],"b":[["t","האם מותר לנשים להתפלל מוסף של ראש השנה?"],["b","נשים רשאיות להתפלל מוסף של ראש השנה, הואיל ואין בברכות נוסח \"וציוונו\". ואדרבא, ראוי להן להתפלל מפני שיש בו הרבה פסוקים של רחמים ותחנונים. וכן בתפילת נעילה של יום הכיפורים: (שם סי\"ח מועדי ה' סי' ב' ס\"כ):"],["t","התוקע לאחרים, או לנשים, האם מברך להם?"],["b","מי שיצא ידי חובתו בתקיעת שופר וצריך לתקוע בשביל אחרים, יכול גם כן לברך את הברכות, אם הם אינם יודעים לברך. ונשים פטורות מתקיעת שופר, וכן המנהג, אבל יכולות הן לתקוע בלא ברכה, או יתקע להם אדם אחר בלא לברך. (שע\"ה סי' ק\"י סעיף י\"ח)"]]},{"h":"כט אלול יום שישי ערב ראש השנה","s":"הלכות תקיעת שופר ותפילות ראש השנה","d":[],"b":[["t","הרגשת האדם בצאתו מבית הכנסת אחר תפילת ראש השנה"],["b","כשיוצאין מבית הכנסת, יש ללכת בשובה ונחת, שמחים וטובי לב, בבטחון כי שמע ה' קול תפילותינו ותקיעותינו ברחמים. ואוכלין ושותין כיד ה' הטובה, ואין מתענין בראש השנה ולא בשבת בנתיים. ומכל מקום יזהרו שלא לאכול כל שבעם, למען לא יקלו ראשם ותהא יראת ה' על פניהם. (שע\"ה סי' ק\"י ס\"כ)"],["t","האם מותר להכין תבשילים ביו\"ט ראשון לצורך יו\"ט שני?"],["b","אסור לבשל או לחמם אוכל מיום טוב ראשון של ראש השנה לצורך יום טוב שני. והוא הדין שלא להכין שום דבר מיום ליום. ולכן יתחילו בבישול רק לאחר צאת הכוכבים. [מיהו בדיעבד שעברו ובשלו, לא נאסר המאכל]. (שם סכ\"ב)"]]}]};
